export const PSALTYR: MvBook[] = [{"u":"Як читати Псалтир","e":"How to read the Psalter","secs":[{"ps":["#Читання Псалтиря вдома","§Угамувавши в серці пристрасті і примирившись з усіма ближніми, стати перед іконами, неспішно перехрестившись, почати:","Молитви перед читанням Псалтиря.","#І починаємо читати свою кафизму","Там, де між псалмами написано: «Слава:» читаємо:","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Аллилу́я, аллилу́я, аллилу́я, сла́ва Тебі́, Бо́же. [Тричі]","Господи, помилуй. [Тричі]","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","§(Тут читаємо молитву з аркуша)","§Після третьої «Сла́ви» і молитви читаємо «Трисвяте» і далі, тобто:","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. [Тричі]","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас: Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. [Тричі]","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","А тоді далі молитви Псалтиря. Між молитвами «Сла́ва:» читаємо тільки:\nСла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","(а там де: «І ни́ні:»:)\nІ ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","§В кінці, після останньої молитви:","Молитви після завершення читання кількох кафизм, або всього Псалтиря і пісень.","§Якщо свою кафизму читаємо одразу ж після ранішніх чи вечірніх молитов, то молимося тільки молитвою:","«Прийді́те, поклоні́мся…» — і одразу ж читаємо свою кафизму."]}],"notes":[]},{"u":"Молитви перед читанням Псалтиря","e":"Prayers before reading the Psalter","secs":[{"ps":["§Про те, яким чином слід співати Псалтир, дотримуючись розумної послідовності.","Якщо священик, то виголошує: Благослове́н Бог наш всегда́, ни́ні, і при́сно, і во ві́ки віко́в.","Якщо мирянин, то промовляє зворушено: Моли́твами святи́х оте́ць на́ших, Го́споди Ісу́се Христе́ Бо́же наш, поми́луй нас, амі́нь.","Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша.","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. [Тричі]","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас: Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. [Тричі]","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Поми́луй нас, Го́споди, поми́луй нас; вся́каго бо отві́та недоумі́юще, сію́ Ті моли́тву я́ко Влади́ці грі́шнії прино́сим: поми́луй нас.","Сла́ва: Честно́є проро́ка Твоєго́ Го́споди, торжество́, не́бо Це́рков показа́, с челові́ки лику́ють а́нгели. Того́ моли́твами, Христе́ Бо́же, в ми́рі упра́ви живо́т наш, да поє́м Ті: аллилу́я.","І ни́ні: Мно́гая мно́жества мої́х, Богоро́дице, прегріше́ній, к Тебі́ прибіго́х, Чи́стая, спасе́нія тре́буя: посіти́ немощству́ющую мою́ ду́шу, і моли́ Си́на Твоєго́ і Бо́га на́шего да́ти мі оставле́ніє, я́же соді́ях лю́тих, єди́на Благослове́нная.","Го́споди, поми́луй. 40 разів.","§І поклонися скільки можеш.","Всесвята́я Тро́йце, Бо́же і Соді́телю всего́ ми́ра, поспіши́ і напра́ви се́рдце моє́ нача́ти с ра́зумом і конча́ти ді́ли благи́ми Богодухнове́нния сія́ кни́ги, я́же Святи́й Дух усти́ Дави́дови отри́гну, ї́хже ни́ні хощу́ глаго́лати аз, недосто́йний; разумі́я же своє́ неві́жество, припа́дая молю́ся Ті, і є́же от Тебе́ по́мощі прося́; Го́споди, упра́ви ум мой, і утверди́ се́рдце моє́, не о глаго́ланії усте́н стужа́ти си, но о ра́зумі глаго́лемих весели́тися, і пригото́витися на творе́ніє до́брих діл, я́же учу́ся, і глаго́лю; да до́брими ді́ли просвіще́н, на Суди́щі десни́я Ті страни́ прича́стник бу́ду со всі́ми ізбра́нними Твої́ми. І ни́ні, Влади́ко, благослови́, да воздохну́в от се́рдця, і язи́ком воспою́, глаго́ля си́це;","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему.","Також постій трохи, аж поки заспокояться усі почуття. А тоді — почни, але не одразу, без лінощів, зі зворушенням і смиренням у серці, і скажи так: Блаже́н муж: тихо і розумно, з увагою, не поспішаючи, не поквапом, а так, щоб розумом збагнути те, що говориться."]}],"notes":[]},{"u":"Кафизма 1","e":"Kathisma 1","secs":[{"h":"Псалом 1","ps":["§Псало́м Дави́ду, 1.","@1 Блаже́н муж, і́же не і́де на сові́т нечести́вих, і на путі́ грі́шних не ста, і на сіда́лищі губи́телей не сі́де;","@2 но в зако́ні Госпо́дні во́ля єго́, і в зако́ні Єго́ поучи́ться день і нощ.","@3 І бу́деть я́ко дре́во насажде́нноє при ісхо́дищих вод, є́же плод свой дасть во вре́м'я своє́, і лист єго́ не отпаде́ть, і вся, єли́ка а́ще твори́ть, успі́єть.","@4 Не та́ко нечести́вії, не та́ко: но я́ко прах, єго́же возмета́єть вітр от лиця́ землі́.","@5 Сего́ ра́ди не воскре́снуть нечести́вії на суд, ніже́ грі́шници в сові́т пра́ведних.","@6 Я́ко вість Госпо́дь путь пра́ведних, і путь нечести́вих поги́бнеть."]},{"h":"Псалом 2","ps":["§Псало́м Дави́ду, 2.","@1 Вску́ю шата́шася язи́ци, і лю́діє поучи́шася тще́тним?","@2 Предста́ша ца́ріє зе́мстії, і кня́зі собра́шася вку́пі на Го́спода і на Христа́ Єго́.","@3 Расто́ргнем⁽1⁾ у́зи їх і отве́ржем⁽2⁾ от нас і́го їх.","@4 Живи́й на небесі́х посміє́ться їм, і Госпо́дь поруга́ється їм.","@5 Тогда́ возглаго́леть к ним гні́вом Свої́м і я́ростію Своє́ю см'яте́ть я;","@6 Аз же поста́влен єсьм Цар от Него́ над Сіо́ном, горо́ю свято́ю Єго́,","@7 возвіща́яй повелі́ніє Госпо́днє. Госпо́дь рече́ ко Мні: Син Мой єси́ Ти, Аз днесь роди́х Тя;","@8 проси́ от Мене́, і дам Ті язи́ки достоя́ніє Твоє́, і одержа́ніє Твоє́ конці́ землі́;","@9 упасе́ши я жезло́м желі́зним, я́ко сосу́ди скуде́льничі сокруши́ши я.","@10 І ни́ні, ца́ріє, разумі́йте, накажі́теся⁽3⁾ всі судя́щії землі́.","@11 Рабо́тайте Го́сподеві со стра́хом і ра́дуйтеся Єму́ со тре́петом.","@12 Приймі́те наказа́ніє, да не когда́ прогні́вається Госпо́дь, і поги́бнете от путі́ пра́веднаго, єгда́ возгори́ться вско́рі я́рость Єго́; блаже́нні всі наді́ющіїся Нань."]},{"h":"Псалом 3","ps":["§Псало́м Дави́ду, внегда́ отбіга́ше от лиця́ Авессало́ма, си́на своєго́, 3.","@2 Го́споди, что ся умно́жиша стужа́ющії мі? Мно́зі востаю́ть на м'я,","@3 мно́зі глаго́лють душі́ моє́й: ність спаcе́нія єму́ в Бо́зі єго́.","@4 Ти же, Го́споди, засту́пник мой єси́, сла́ва моя́, і вознося́й главу́ мою́.","@5 Гла́сом мої́м ко Го́споду воззва́х, і усли́ша м'я от гори́ святи́я Своєя́.","@6 Аз усну́х, і спах, воста́х, я́ко Госпо́дь засту́пить м'я.","@7 Не убою́ся от тем люді́й, о́крест напа́дающих на м'я.","@8 Воскресни́, Го́споди, спаси́ м'я, Бо́же мой: я́ко Ти порази́л єси́ вся вражду́ющия мі всу́є, зу́би грі́шников сокруши́л єси́.","@9 Госпо́днє єсть спасе́ніє, і на лю́дех Твої́х благослове́ніє Твоє́.","§Сла́ва:"]},{"h":"Псалом 4","ps":["§В коне́ць, в пі́снех, псало́м Дави́ду, 4.","@2 Внегда́ призва́ти мі, усли́ша м'я Бог пра́вди моєя́; в ско́рбі распространи́л м'я єси́; уще́дри м'я і усли́ши моли́тву мою́.","@3 Си́нове челові́честії, доко́лі тяжкосе́рдії? Вску́ю лю́бите суєту́ і і́щете лжі?","@4 І уві́дите, я́ко удиви́ Госпо́дь преподо́бнаго Своєго́. Госпо́дь усли́шить м'я, внегда́ воззва́ти мі к Нему́.","@5 Гні́вайтеся, і не согріша́йте, я́же глаго́лете в сердця́х ва́ших, на ло́жах ва́ших умилі́теся;","@6 пожрі́те же́ртву пра́вди і упова́йте на Го́спода.","@7 Мно́зі глаго́лють: кто яви́ть нам блага́я? Зна́менася на нас світ лиця́ Твоєго́, Го́споди.","@8 Дал єси́ весе́ліє в се́рдці моє́м; от плода́ пшени́ці, вина́ і єле́я своєго́ умно́жишася;","@9 в ми́рі вку́пі усну́ і почи́ю, я́ко Ти, Го́споди, єди́наго на упова́нії всели́л м'я єси́."]},{"h":"Псалом 5","ps":["§О наслі́дствующем, псало́м Дави́ду, 5.","@2 Глаго́ли моя́ внуши́, Го́споди, разумі́й зва́ніє моє́.","@3 Воньми́ гла́су моле́нія моєго́, Царю́ мой і Бо́же мой, я́ко к Тебі́ помолю́ся, Го́споди.","@4 Зау́тра усли́ши глас мой, зау́тра предста́ну Ті, і у́зриши м'я;","@5 я́ко Бог не хотя́й беззако́нія Ти єси́, не присели́ться к Тебі́ лука́внуяй,","@6 ніже́ пребу́дуть беззако́нници пред очи́ма Твої́ма; возненави́діл єси́ вся ді́лающия беззако́ніє,","@7 погуби́ши вся глаго́лющия лжу; му́жа крове́й і льсти́ва гнуша́ється Госпо́дь.","@8 Аз же мно́жеством ми́лости Твоєя́ вни́ду в дом Твой, поклоню́ся ко хра́му свято́му Твоєму́, в стра́сі Твоє́м.","@9 Го́споди, наста́ви м'я пра́вдою Твоє́ю, враг мої́х ра́ди іспра́ви пред Тобо́ю путь мой.","@10 Я́ко ність во усті́х їх і́стини, се́рдце їх су́єтно, гроб отве́рст горта́нь їх, язи́ки свої́ми льща́ху.","@11 Суди́ їм, Бо́же, да отпаду́ть от ми́слей свої́х; по мно́жеству нече́стія їх ізри́ни я, я́ко преогорчи́ша Тя, Го́споди.","@12 І да возвеселя́ться всі упова́ющії на Тя, во вік возра́дуються, і всели́шися в них, і похва́ляться о Тебі́ лю́б'ящії і́м'я Твоє́.","@13 Я́ко Ти благослови́ши пра́ведника, Го́споди, я́ко ору́жієм благоволе́нія вінча́л єси́ нас."]},{"h":"Псалом 6","ps":["§В коне́ць, в пі́снех о осьмі́м, псало́м Дави́ду, 6.","@2 Го́споди, да не я́ростію Твоє́ю обличи́ши мене́, ніже́ гні́вом Твої́м нака́жеши мене́.","@3 Поми́луй м'я, Го́споди, я́ко не́мощен єсьм; ізціли́ м'я, Го́споди, я́ко см'ято́шася ко́сті моя́,","@4 і душа́ моя́ см'яте́ся зіло́; і Ти, Го́споди, доко́лі?","@5 Обрати́ся, Го́споди, ізба́ви ду́шу мою́, спаси́ м'я ра́ди ми́лости Твоєя́;","@6 я́ко ність в сме́рті помина́яй Тебе́, во а́ді же кто іспові́сться Тебі́?","@7 Утруди́хся воздиха́нієм мої́м, ізми́ю на вся́ку нощ ло́же моє́, слеза́ми мої́ми посте́лю мою́ омочу́.","@8 См'яте́ся от я́рости о́ко моє́, обетша́х во всіх вразі́х мої́х.","@9 Отступі́те от мене́, всі ді́лающії беззако́ніє, я́ко усли́ша Госпо́дь глас пла́ча моєго́,","@10 усли́ша Госпо́дь моле́ніє моє́, Госпо́дь моли́тву мою́ прия́т.","@11 Да постидя́ться і см'яту́ться всі вразі́ мої́, да возвратя́ться і устидя́ться зіло́ вско́рі.","§Сла́ва:"]},{"h":"Псалом 7","ps":["§Псало́м Дави́ду, єго́же воспі́т Го́сподеві о словесі́х Хусі́євих, си́на Іємені́їна, 7.","@2 Го́споди Бо́же мой, на Тя упова́х, спаси́ м'я от всіх гоня́щих м'я і ізба́ви м'я;","@3 да не когда́ похи́тить, я́ко лев, ду́шу мою́, не су́щу ізбавля́ющу, ніже́ спаса́ющу.","@4 Го́споди Бо́же мой, а́ще сотвори́х сіє́, а́ще єсть непра́вда в руку́ моє́ю,","@5 а́ще возда́х воздаю́щим мі зла, да отпаду́ у́бо от враг мої́х тощ;","@6 да пожене́ть у́бо враг ду́шу мою́, і да пости́гнеть, і попере́ть в зе́млю живо́т мой, і сла́ву мою́ в персть всели́ть.","@7 Воскресни́, Го́споди, гні́вом Твої́м, вознеси́ся в конця́х враг Твої́х, і воста́ни, Го́споди Бо́же мой, повелі́нієм, і́мже запові́дал єси́,","@8 і сонм люді́й оби́деть Тя, і о том на висоту́ обрати́ся.","@9 Госпо́дь су́дить лю́дем; суди́ мі, Го́споди, по пра́вді моє́й і по незло́бі моє́й на м'я.","@10 Да сконча́ється зло́ба грі́шних, і іспра́виши пра́веднаго, іспита́яй сердця́ і утро́би, Бо́же, пра́ведно.","@11 По́мощ моя́ от Бо́га, спаса́ющаго пра́вия се́рдцем.","@12 Бог суди́тель пра́веден, і крі́пок, і долготерпіли́в, і не гнів наводя́й на всяк день.","@13 А́ще не обратите́ся, ору́жіє своє́ очи́стить, лук Свой напряже́, і угото́ва ї,","@14 і в нем угото́ва сосу́ди сме́ртния, стрі́ли Своя́ сгара́ємим соді́ла.","@15 Се, болі́ непра́вдою, зача́т болі́знь і роди́ беззако́ніє;","@16 ров ізри́ і іскопа́ ї, і паде́ть в я́му, ю́же соді́ла.","@17 Обрати́ться болі́знь єго́ на главу́ єго́, і на верх єго́ непра́вда єго́ сни́деть.","@18 Іспові́мся Го́сподеві по пра́вді Єго́ і пою́ і́мені Го́спода Ви́шняго."]},{"h":"Псалом 8","ps":["§В коне́ць, о точи́ліх, псало́м Дави́ду, 8.","@2 Го́споди Госпо́дь наш, я́ко чу́дно і́м'я Твоє́ по всей землі́, я́ко взя́тся великолі́піє Твоє́ преви́ше небе́с.","@3 Із уст младе́нець і ссу́щих соверши́л єси́ хвалу́, враг Твої́х ра́ди, є́же разруши́ти врага́ і ме́стника.","@4 Я́ко узрю́ небеса́, діла́ перст Твої́х, луну́ і зві́зди, я́же Ти основа́л єси́;","@5 что єсть челові́к, я́ко по́мниши єго́? іли́ син челові́ч, я́ко посіща́єши єго́?","@6 Ума́лил єси́ єго́ ма́лим чим от а́нгел, сла́вою і че́стію вінча́л єси́ єго́;","@7 і поста́вил єси́ єго́ над ді́ли руку́ Твоє́ю, вся покори́л єси́ под но́зі єго́;","@8 о́вці і воли́ вся, єще́ же і скоти́ польські́я,","@9 пти́ці небе́сния і ри́би морські́я, преходя́щия стезі́ морські́я.","@10 Го́споди Госпо́дь наш, я́ко чу́дно і́м'я Твоє́ по всей землі́.","§Сла́ва:"]},{"h":"Після 1-ї кафизми Трисвято́є; і по О́тче наш: тропарі, глас 1:","ps":["В беззако́ніїх зача́вся аз, блу́дний, не дерза́ю взира́ти на висоту́ небе́сную, но дерза́я на человіколю́біє Твоє́, зову́: Бо́же, очи́сти м'я, грі́шнаго, і спаси́ м'я.","А́ще пра́ведник єдва́ спаса́ється, аз гді явлю́ся грі́шний? Тяготи́ і зно́я дневна́го не понесо́х, но с нає́мники єдинонадеся́таго часа́ сопричти́ м'я, Бо́же, і спаси́ м'я.","Сла́ва: Об'я́тія О́тча отве́рсти мі потщи́ся, блу́дно моє́ іжди́х житіє́, на бога́тство неіждива́ємоє взира́яй щедро́т Твої́х, Спа́се; ни́ні обнища́вшеє моє́ да не пре́зриши се́рдце, Тебі́ бо, Го́споди, умиле́нієм зову́: согріши́х на не́бо і пред Тобо́ю.","І ни́ні: Упова́ніє христия́н, Пресвята́я Ді́во, Єго́же родила́ єси́ Бо́га па́че ума́ же і сло́ва, непреста́нно моли́ с го́рними си́лами да́ти оставле́ніє гріхо́в нам всім і ісправле́ніє житія́, ві́рою і любо́вію при́сно Тя чту́щим.","Влади́ко Вседержи́телю, непостижи́ме, Нача́ло сві́та і преу́мная Си́ло, І́же іпоста́снаго Сло́ва Оте́ць, і Єдиноси́льнаго Твоєго́ Ду́ха іспусти́тель; милосе́рдния ра́ди ми́лости і неізрече́нния бла́гости, не презрі́вий челові́чеськаго єстества́, тьмо́ю гріха́ содержи́маго, но Боже́ственними сві́ти свяще́нних Твої́х уче́ній, Зако́ном і проро́ки світи́вий ми́ру, посліди́ же нам Того́ Єдиноро́днаго Твоєго́ Си́на благоволи́вий пло́тію возсія́ти і ко осія́нію нас Твоєго́ просвіще́нія наста́вити; да бу́дуть у́ші Твої́ вне́млющі гла́су моле́нія на́шего, і да́руй нам, Бо́же, во бді́нном і тре́звенном се́рдці всю настоя́щаго житія́ нощ прейти́, ожида́ющим прише́ствія Си́на Твоєго́ і Бо́га на́шего, Судії́ всіх, да не возлежа́ще і сп'я́ще, но бо́дрствующе і воздви́жені в ді́ланіє за́повідей Твої́х обря́щемся, і в ра́дость Єго́ совни́дем, іді́же пра́зднующих глас непреста́нний і неізрече́нная сла́дость зря́щих Твоєго́ лиця́ добро́ту неізглаго́ланную. Я́ко Благ і Человіколю́бець Бог єси́, і Тебі́ сла́ву возсила́єм, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[расто́ргним]</span>","<span class=''>[отве́ржим]</span>","навчіться"]},{"u":"Кафизма 2","e":"Kathisma 2","secs":[{"h":"Псалом 9","ps":["§В коне́ць, о та́йних си́на, псало́м Дави́ду, 9.","@2 Іспові́мся Тебі́, Го́споди, всім се́рдцем мої́м, пові́м вся чудеса́ Твоя́.","@3 Возвеселю́ся і возра́дуюся о Тебі́, пою́ і́мені Твоєму́, Ви́шній.","@4 Внегда́ возврати́тися врагу́ моєму́ всп'ять, ізнемо́гуть і поги́бнуть от лиця́ Твоєго́.","@5 Я́ко сотвори́л єси́ суд мой і прю мою́; сіл єси́ на Престо́лі, судя́й пра́вду.","@6 Запрети́л єси́ язи́ком, і поги́бе нечести́вий, і́м'я єго́ потреби́л єси́ в вік і в вік ві́ка.","@7 Врагу́ оскуді́ша ору́жія в коне́ць, і гра́ди разруши́л єси́; поги́бе па́м'ять єго́ с шу́мом.","@8 І Госпо́дь во вік пребива́єть, угото́ва на суд Престо́л Свой;","@9 і Той суди́ти і́мать вселе́нній в пра́вду, суди́ти і́мать лю́дем в правоті́.","@10 І бисть Госпо́дь прибі́жище убо́гому, помо́щник во благовре́меніїх, в ско́рбіх.","@11 І да упова́ють на Тя зна́ющії і́м'я Твоє́, я́ко не оста́вил єси́ взиска́ющих Тя, Го́споди.","@12 По́йте Го́сподеві, живу́щему в Сіо́ні, возвісті́те во язи́ціх начина́нія Єго́;","@13 я́ко взиска́яй кро́ви їх пом'яну́, не заби́ зва́нія убо́гих.","@14 Поми́луй м'я, Го́споди, виждь смире́ніє моє́ от враг мої́х, вознося́й м'я от врат сме́ртних;","@15 я́ко да возвіщу́ вся хвали́ Твоя́ во враті́х дще́ре Сіо́ні; возра́дуємся о спасе́нії Твоє́м.","@16 Углібо́ша язи́ци в па́губі, ю́же сотвори́ша; в сі́ті сей, ю́же скри́ша, ув'язе́ нога́ їх.","@17 Зна́єм єсть Госпо́дь судьби́ Творя́й; в ді́ліх руку́ своє́ю ув'язе́ грі́шник.","@18 Да возвратя́ться грі́шници во ад, всі язи́ци забива́ющії Бо́га.","@19 Я́ко не до конця́ забве́н бу́деть ни́щий, терпі́ніє убо́гих не поги́бнеть до конця́.","@20 Воскресни́, Го́споди, да не кріпи́ться челові́к, да су́дяться язи́ци пред Тобо́ю.","@21 Поста́ви, Го́споди, законоположи́теля над ни́ми, да разумі́ють язи́ци, я́ко челові́ци суть.","@22 Вску́ю, Го́споди, отстоя́ дале́че, презира́єши во благовре́меніїх, в ско́рбіх?","@23 Внегда́ горди́тися нечести́вому, возгара́ється ни́щий; ув'яза́ють в сові́тіх, я́же помишля́ють.","@24 Я́ко хвали́м єсть грі́шний в по́хотех душі́ своєя́, і оби́дяй благослови́м єсть.","@25 Раздражи́ Го́спода грі́шний; по мно́жеству гні́ва Своєго́ не взи́щеть; ність Бо́га пред ним.","@26 Оскверня́ються путіє́ єго́ на вся́ко вре́м'я; оте́млються судьби́ Твоя́ от лиця́ єго́; всі́ми враги́ свої́ми облада́єть.","@27 Рече́ бо в се́рдці своє́м: не подви́жуся от ро́да в род без зла;","@28 Єго́же кля́тви уста́ єго́ по́лна суть, і го́рести і льсти; под язи́ком єго́ труд і болі́знь.","@29 Присіди́ть в лови́тельстві с бога́тими в та́йних, є́же уби́ти непови́ннаго; о́чі єго́ на ни́щаго призира́єті.","@30 Лови́ть в та́йні, я́ко лев, во огра́ді своє́й, лови́ть є́же восхи́тити ни́щаго, восхи́тити ни́щаго, внегда́ привлещи́ ї в сі́ті своє́й.","@31 Смири́ть єго́, преклони́ться і паде́ть, внегда́ єму́ облада́ти убо́гими.","@32 Рече́ бо в се́рдці своє́м: заби́ Бог, отврати́ лице́ своє́, да не ви́дить до конця́.","@33 Воскресни́, Го́споди Бо́же мой, да вознесе́ться рука́ Твоя́, не забу́ди убо́гих Твої́х до конця́.","@34 Чесо́ ра́ди прогні́ва нечести́вий Бо́га; рече́ бо в се́рдці своє́м: не взи́щеть.","@35 Ви́диши, я́ко Ти болі́знь і я́рость смотря́єши, да пре́дан бу́деть в ру́ці Твої́; Тебі́ оста́влен єсть ни́щий, си́ру Ти бу́ди помо́щник.","@36 Сокруши́ ми́шцю грі́шному і лука́вому; взи́щеться гріх єго́ і не обря́щеться.","@37 Госпо́дь Цар во вік і в вік ві́ка; поги́бнете, язи́ци, от землі́ Єго́.","@38 Жела́ніє убо́гих усли́шал єси́, Го́споди, угото́ванію се́рдця їх внят у́хо Твоє́.","@39 Суди́ си́ру і смире́ну, да не приложи́ть ктому́ велича́тися челові́к на землі́."]},{"h":"Псалом 10","ps":["§В коне́ць, псало́м Дави́ду, 10.","@1 На Го́спода упова́х, ка́ко рече́те душі́ моє́й: превита́й по гора́м, я́ко пти́ця?","@2 Я́ко се, грі́шници наляко́ша лук, угото́ваша стрі́ли в ту́лі, состріля́ти во мра́ці пра́вия се́рдцем.","@3 Зане́ я́же Ти соверши́л єси́, они́ разруши́ша; пра́ведник же что сотвори́?","@4 Госпо́дь во хра́мі святі́м Своє́м. Госпо́дь, на небесі́ Престо́л Єго́; о́чі Єго́ на ни́щаго призира́єті, ві́жди Єго́ іспита́єті си́ни челові́чеськія.","@5 Госпо́дь іспита́єть пра́веднаго і нечести́ваго; люб'я́й же непра́вду ненави́дить свою́ ду́шу.","@6 Одожди́ть на грі́шники сі́ти; огнь і жу́пел, і дух бу́рен часть ча́ші їх.","@7 Я́ко пра́веден Госпо́дь і пра́вди возлюби́; правоти́ ви́ді лице́ Єго́."]},{"h":"Псалом 11","ps":["§В коне́ць, о осьмі́й, псало́м Дави́ду, 11.","@2 Спаси́ м'я, Го́споди, я́ко оскуді́ преподо́бний, я́ко ума́лишася і́стини от сино́в челові́чеських.","@3 Су́єтная глаго́ла ки́йждо ко і́скреннему своєму́; устні́ льсти́вия в се́рдці, і в се́рдці глаго́лаша зла́я.","@4 Потреби́ть Госпо́дь вся устни́ льсти́вия, язи́к велері́чивий,","@5 ре́кшия: язи́к наш возвели́чим, устни́ на́ша при нас суть, кто нам Госпо́дь єсть?","@6 Стра́сти ра́ди ни́щих і воздиха́нія убо́гих ни́ні воскресну́, — глаго́леть Госпо́дь, — положу́ся во спасе́ніє, не обиню́ся о нем.","@7 Словеса́ Госпо́дня — словеса́ чи́ста, сребро́ разжже́но, іскуше́но землі́, очище́но седмери́цею.","@8 Ти, Го́споди, сохрани́ши ни і соблюде́ши ни от ро́да сего́ і во вік.","@9 О́крест нечести́вії хо́дять; по висоті́ Твоє́й умно́жил єси́ си́ни челові́чеськія."]},{"h":"Псалом 12","ps":["§В коне́ць, псало́м Дави́ду, 12.","@2 Доко́лі, Го́споди, забу́деши м'я до конця́? Доко́лі отвраща́єши лице́ Твоє́ от мене́?","@3 Доко́лі положу́ сові́ти в душі́ моє́й, болі́зні в се́рдці моє́м день і нощ? Доко́лі вознесе́ться враг мой на м'я?","@4 При́зри, усли́ши м'я, Го́споди Бо́же мой, просвіти́ о́чі мої́, да не когда́ усну́ в смерть;","@5 да не когда́ рече́ть враг мой: укріпи́хся на него́.","@6 Стужа́ющії мі возра́дуються, а́ще подви́жуся.","@7 Аз же на ми́лость Твою́ упова́х; возра́дується се́рдце моє́ о спасе́нії Твоє́м; воспою́ Го́сподеві благоді́явшему мні і пою́ і́мені Го́спода Ви́шняго."]},{"h":"Псалом 13","ps":["§В коне́ць, псало́м Дави́ду, 13.","@1 Рече́ безу́мен в се́рдці своє́м: ність Бог. Растлі́ша і омерзи́шася в начина́ніїх; ність творя́й благости́ню.","@2 Госпо́дь с небесе́ прини́че на си́ни челові́чеськія, ви́діти, а́ще єсть разуміва́яй, іли́ взиска́яй Бо́га.","@3 Всі уклони́шася, вку́пі неключи́ми би́ша: ність творя́й благости́ню, ність до єди́наго.","@4 Ні ли разумі́ють всі ді́лающії беззако́ніє, сніда́ющії лю́ди моя́ в снідь хлі́ба? Го́спода не призва́ша.","@5 Та́мо убоя́шася стра́ха, іді́же не бі страх; я́ко Госпо́дь в ро́ді пра́ведних.","@6 Сові́т ни́щаго посрами́сте, Госпо́дь же упова́ніє єго́ єсть.","@7 Кто дасть от Сіо́на спасе́ніє Ізра́їлево?","@8 Внегда́ возврати́ть Госпо́дь пліне́ніє люді́й Свої́х, возра́дується Іа́ков і возвесели́ться Ізра́їль.","§Сла́ва:"]},{"h":"Псалом 14","ps":["§В коне́ць, псало́м Дави́ду, 14.","@1 Го́споди, кто обита́єть в жили́щі Твоє́м? Іли́ кто всели́ться во святу́ю го́ру Твою́?","@2 Ходя́й непоро́чен і ді́лаяй пра́вду, глаго́ляй і́стину в се́рдці своє́м;","@3 і́же не ульсти́ язи́ком свої́м і не сотвори́ і́скреннему своєму́ зла, і поноше́нія не прия́т на бли́жнія своя́;","@4 унічиже́н єсть пред ним лука́внуяй, боя́щияжеся Го́спода сла́вить; клени́йся і́скреннему своєму́ і не отмета́яся;","@5 сребра́ своєго́ не даде́ в ли́хву і мзди на непови́нних не прия́т. Творя́й сія́ не подви́житься во вік."]},{"h":"Псалом 15","ps":["§Столпописа́ніє, Дави́ду, 15.","@1 Сохрани́ м'я, Го́споди, я́ко на Тя упова́х.","@2 Ріх Го́сподеві: Госпо́дь мой єси́ Ти, я́ко благи́х мої́х не тре́буєши.","@3 Святи́м, і́же суть на землі́ Єго́, удиви́ Госпо́дь вся хоті́нія Своя́ в них.","@4 Умно́жишася не́мощі їх, по сих ускори́ша; не соберу́ собо́ри їх от крове́й, ні пом'яну́ же іме́н їх устна́ма мої́ма.","@5 Госпо́дь часть достоя́нія моєго́ і ча́ші моєя́; Ти єси́ устроя́яй достоя́ніє моє́ мні.","@6 У́жа нападо́ша мі в держа́вних мої́х, і́бо достоя́ніє моє́ держа́вно єсть мні.","@7 Благословлю́ Го́спода вразуми́вшаго м'я, єще́ же і до но́щі наказа́ша м'я утро́би моя́.","@8 Предзрі́х Го́спода пре́до мно́ю ви́ну, я́ко одесну́ю мене́ єсть, да не подви́жуся.","@9 Сего́ ра́ди возвесели́ся се́рдце моє́, і возра́довася язи́к мой, єще́ же і плоть моя́ всели́ться на упова́нії.","@10 Я́ко не оста́виши ду́шу мою́ во а́ді, ніже́ да́си преподо́бному Твоєму́ ви́діти істлі́нія.","@11 Сказа́л мі єси́ путі́ живота́; іспо́лниши м'я весе́лія с лице́м Твої́м; красота́⁽1⁾ в десни́ці Твоє́й в коне́ць."]},{"h":"Псалом 16","ps":["§Моли́тва Дави́ду, 16.","@1 Усли́ши, Го́споди, пра́вду мою́, воньми́ моле́нію моєму́, внуши́ моли́тву мою́ не во устна́х льсти́вих.","@2 От лиця́ Твоєго́ судьба́ моя́ ізи́деть; о́чі мої́ да ви́діта правоти́.","@3 Іскуси́л єси́ се́рдце моє́, посіти́л єси́ но́щію; іскуси́л м'я єси́, і не обрі́теся во мні непра́вда.","@4 Я́ко да не возглаго́лють уста́ моя́ діл челові́чеських, за словеса́ усте́н Твої́х аз сохрани́х путі́ же́стокі.","@5 Соверши́ стопи́ моя́ во стезя́х Твої́х, да не подви́жуться стопи́ моя́.","@6 Аз воззва́х, я́ко усли́шал м'я єси́, Бо́же; приклони́ у́хо Твоє́ мні і усли́ши глаго́ли моя́.","@7 Удиви́ ми́лості Твоя́, спаса́яй упова́ющия на Тя от проти́в'ящихся десни́ці Твоє́й;","@8 сохрани́ м'я, Го́споди, я́ко зі́ницю о́ка; в кро́ві крилу́ Твоє́ю покри́єши м'я","@9 от лиця́ нечести́вих остра́стших⁽2⁾ м'я; вразі́ мої́ ду́шу мою́ одержа́ша","@10 тук свой затвори́ша, уста́ їх глаго́лаша горди́ню.","@11 Ізгоня́щії м'я ни́ні обидо́ша м'я, о́чі свої́ возложи́ша уклони́ти на зе́млю.","@12 Об'я́ша м'я, я́ко лев гото́в на лов, і я́ко ски́мен обита́яй в та́йних.","@13 Воскресни́, Го́споди, предвари́ я і запни́ їм; ізба́ви ду́шу мою́ от нечести́ваго, ору́жіє Твоє́","@14 от враг руки́ Твоєя́, Го́споди, от ма́лих от землі́; разділи́ я в животі́ їх, і сокрове́нних Твої́х іспо́лнися чре́во їх; наси́тишася сино́в, і оста́виша оста́нки младе́нцем свої́м.","@15 Аз же пра́вдою явлю́ся лицю́ Твоєму́, наси́щуся, внегда́ яви́тимися сла́ві Твоє́й.","§Сла́ва:"]},{"h":"Після 2-ї кафизми Трисвято́є. І по О́тче наш: тропарі, глас 2:","ps":["Аз сий дре́во непло́дноє, Го́споди, умиле́нія плода́ не ношу́ отню́д, і посіче́нія страшу́ся і огня́ о́наго бою́ся негаси́маго. Ті́мже Тя молю́: пре́жде о́ния ну́жди обрати́ і спаси́ м'я.","Я́ко во́лни морські́я на м'я возста́ша беззако́нія моя́, я́ко корабле́ць в пучи́ні аз єди́н обурева́юся от прегріше́ній мно́гих; но в ти́хоє приста́нище наста́ви м'я, Го́споди, покая́нієм і спаси́ м'я.","Сла́ва: \"Поми́луй м'я\" — рече́ Дави́д, і аз Тебі́ зову́: согріши́х, Спа́се, гріхи́ моя́ очи́стив покая́нієм, поми́луй м'я.","І ни́ні: Предста́тельство те́плоє христия́н, Си́на Твоєго́ моли́, Богоро́дице, вся́каго злоді́йства і лю́тости ізба́вити нас ра́тника, і да́ти проще́ніє нам, о ни́хже согріши́хом, милосе́рдія ра́ди щедро́т, Твої́ми моли́твами, Ма́ти Ді́во."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Влади́ко Вседержи́телю, О́тче Го́спода на́шего Ісу́са Христа́, Єдиноро́днаго Твоєго́ Си́на, даждь мі ті́ло нескве́рноє, се́рдце чи́стоє, ум бодр, ра́зум незаблу́дний, Ду́ха Свята́го наше́ствіє, к стяжа́нію і дово́льству і́стини во Христі́ Твоє́м; с Ни́мже Тебі́ сла́ва подоба́єть, честь і поклоне́ніє, со Святи́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[сла́дость]</span>","<span class=''>[оби́дящих]</span>"]},{"u":"Кафизма 3","e":"Kathisma 3","secs":[{"h":"Псалом 17","ps":["§В коне́ць, о́троку Госпо́дню Дави́ду, я́же глаго́ла Го́сподеві словеса́ пі́сні сея́, в день, в о́ньже ізба́ви єго́ Госпо́дь от руки́ всіх враг єго́ і із руки́ Сау́ли; і рече́: 17.","@2 Возлюблю́ Тя, Го́споди, крі́посте моя́;","@3 Госпо́дь — утвержде́ніє моє́, і прибі́жище моє́, і ізба́витель мой, Бог мой, помо́щник мой, і упова́ю на Него́; защи́титель мой, і рог спаcе́нія моєго́, і засту́пник мой.","@4 Хваля́ призову́ Го́спода і от враг мої́х спасу́ся.","@5 Одержа́ша м'я болі́зні сме́ртния, і пото́ци беззако́нія см'ято́ша м'я;","@6 болі́зні а́дови обидо́ша м'я, предвари́ша м'я сі́ті сме́ртния.","@7 І внегда́ скорбі́ти мі, призва́х Го́спода і к Бо́гу моєму́ воззва́х; усли́ша от хра́ма свята́го Своєго́ глас мой, і вопль мой пред Ним вни́деть во у́ші Єго́.","@8 І подви́жеся і тре́петна бисть земля́, і основа́нія гор см'ято́шася і подвиго́шася, я́ко прогні́вася на ня Бог.","@9 Взи́де дим гні́вом Єго́, і огнь от лиця́ Єго́ воспла́мениться; у́гліє возгорі́ся от Него́.","@10 І приклони́ небеса́ і сни́де, і мрак под нога́ма Єго́.","@11 І взи́де на херуви́ми і леті́, леті́ на крилу́ ві́треню.","@12 І положи́ тьму закро́в Свой; о́крест Єго́ селе́ніє Єго́; темна́ вода́ во о́блаціх возду́шних.","@13 От облиста́нія пред Ним о́блаци пройдо́ша, град і у́гліє о́гненноє.","@14 І возгремі́ с небесе́ Госпо́дь, і Ви́шній даде́ глас Свой.","@15 Низпосла́ стрі́ли і разгна́ я, і мо́лнії умно́жи і см'яте́ я.","@16 І яви́шася істо́чници водні́ї, і откри́шася основа́нія вселе́нния от запреще́нія Твоєго́, Го́споди, от дохнове́нія ду́ха гні́ва Твоєго́.","@17 Низпосла́ с висоти́ і прия́т м'я, восприя́т м'я от вод мно́гих.","@18 Ізба́вить м'я от враго́в мої́х си́льних і от ненави́дящих м'я; я́ко утверди́шася па́че мене́.","@19 Предвари́ша м'я в день озлобле́нія моєго́; і бисть Госпо́дь утвержде́ніє моє́.","@20 І ізведе́ м'я на широту́; ізба́вить м'я, я́ко восхоті́ м'я.","@21 І возда́сть мі Госпо́дь по пра́вді моє́й, і по чистоті́ руку́ моє́ю возда́сть мі,","@22 я́ко сохрани́х путі́ Госпо́дні і не нече́ствовах от Бо́га моєго́.","@23 Я́ко вся судьби́ Єго́ пре́до мно́ю, і оправда́нія Єго́ не отступи́ша от мене́.","@24 І бу́ду непоро́чен с Ним і сохраню́ся от беззако́нія моєго́.","@25 І возда́сть мі Госпо́дь по пра́вді моє́й і по чистоті́ руку́ моє́ю пред очи́ма Єго́.","@26 С преподо́бним преподо́бен бу́деши, і с му́жем непови́нним непови́нен бу́деши,","@27 і со ізбра́нним ізбра́н бу́деши, і со стропти́вим разврати́шися.","@28 Я́ко Ти лю́ди смире́нния спасе́ши і о́чі го́рдих смири́ши.","@29 Я́ко Ти просвіти́ши світи́льник мой, Го́споди; Бо́же мой, просвіти́ши тьму мою́.","@30 Я́ко Тобо́ю ізба́влюся от іскуше́нія, і Бо́гом мої́м прейду́ сті́ну.","@31 Бог мой, непоро́чен путь Єго́: словеса́ Госпо́дня разжже́на. Защи́титель єсть всіх упова́ющих на Него́.","@32 Я́ко кто Бог, ра́зві Го́спода? Іли́ кто Бог, ра́зві Бо́га на́шего?","@33 Бог препоясу́яй м'я си́лою, і положи́ непоро́чен путь мой;","@34 соверша́яй но́зі мої́ я́ко єле́ні, і на висо́ких поставля́яй м'я;","@35 науча́яй ру́ці мої́ на брань, і положи́л єси́ лук мі́дян ми́шця моя́;","@36 і дал мі єси́ защище́ніє спаcе́нія, і десни́ця Твоя́ восприя́т м'я; і наказа́ніє Твоє́ іспра́вить м'я в коне́ць, і наказа́ніє Твоє́ то м'я научи́ть.","@37 Ушири́л єси́ стопи́ моя́ подо мно́ю, і не ізнемого́сті плесні́ мої́.","@38 Пожену́ враги́ моя́, і пости́гну я, і не возвращу́ся, до́ндеже сконча́ються;","@39 оскорблю́ їх, і не возмо́гуть ста́ти, паду́ть под нога́ма мої́ма.","@40 І препоя́сал м'я єси́ си́лою на брань, сп'ял єси́ вся востаю́щия на м'я под м'я.","@41 І враго́в мої́х дал мі єси́ хребе́т і ненави́дящия м'я потреби́л єси́.","@42 Воззва́ша, і не бі спаса́яй; ко Го́споду, і не усли́ша їх.","@43 І істню́ я я́ко прах пред лице́м ві́тра, я́ко бре́ніє путі́й погла́жду я.","@44 Ізба́виши м'я от преріка́нія люді́й; поста́виши м'я во главу́ язи́ков; лю́діє, ї́хже не ві́діх, рабо́таша мі,","@45 в слух у́ха послу́шаша м'я. Си́нове чужді́ї солга́ша мі,","@46 си́нове чужді́ї обетша́ша і охромо́ша от стезь свої́х.","@47 Жив Госпо́дь, і благослове́н Бог, і да вознесе́ться Бог спаcе́нія моєго́,","@48 Бог дая́й отмще́ніє мні і покори́вий лю́ди под м'я.","@49 Ізба́витель мой от враг мої́х гнівли́вих; от возстаю́щих на м'я вознесе́ши м'я, от му́жа непра́ведна ізба́виши м'я.","@50 Сего́ ра́ди іспові́мся Тебі́ во язи́ціх, Го́споди, і і́мені Твоєму́ пою́;","@51 велича́яй спасе́нія царе́ва і творя́й ми́лость христу́ Своєму́ Дави́ду і сі́мені єго́ до ві́ка.","§Сла́ва:"]},{"h":"Псалом 18","ps":["§В коне́ць, псало́м Дави́ду, 18.","@2 Небеса́ пові́дають сла́ву Бо́жию, творе́ніє же руку́ Єго́ возвіща́єть твердь.","@3 День дні отрига́єть глаго́л, і нощ но́щі возвіща́єть ра́зум.","@4 Не суть рі́чі, ніже́ словеса́, ї́хже не сли́шаться гла́си їх.","@5 Во всю зе́млю ізи́де віща́ніє їх, і в конці́ вселе́нния глаго́ли їх; в со́лнці положи́ селе́ніє Своє́;","@6 і той я́ко жени́х ісходя́й от черто́га своєго́, возра́дується я́ко ісполи́н тещи́ путь.","@7 От кра́я небесе́ ісхо́д єго́, і срі́теніє єго́ до кра́я небесе́; і ність, і́же укри́ється теплоти́ єго́.","@8 Зако́н Госпо́день непоро́чен, обраща́яй ду́ші; свиді́тельство Госпо́днє ві́рно, умудря́ющеє младе́нці.","@9 Оправда́нія Госпо́дня пра́ва, веселя́щая се́рдце; за́повідь Госпо́дня світла́, просвіща́ющая о́чі.","@10 Страх Госпо́день чист, пребива́яй в вік ві́ка; судьби́ Госпо́дні і́стинни, оправда́нни вку́пі,","@11 вожделі́нни па́че зла́та і ка́мене че́стна мно́га, і сла́ждша па́че ме́да і со́та.","@12 І́бо раб Твой храни́ть я; внегда́ сохрани́ти я, воздая́ніє мно́го.","@13 Гріхопаде́нія кто разумі́єть? От та́йних мої́х очи́сти м'я,","@14 і от чужди́х пощади́ раба́ Твоєго́; а́ще не облада́ють мно́ю, тогда́ непоро́чен бу́ду, і очи́щуся от гріха́ вели́ка.","@15 І бу́дуть во благоволе́ніє словеса́ уст мої́х, і поуче́ніє се́рдця моєго́ пред Тобо́ю ви́ну, Го́споди, Помо́щниче мой і Ізба́вителю мой."]},{"h":"Псалом 19","ps":["§В коне́ць, псало́м Дави́ду, 19.","@2 Усли́шить тя Госпо́дь в день печа́лі, защити́ть Тя і́м'я Бо́га Іа́ковля.","@3 По́слеть ті по́мощ от свята́го, і от Сіо́на засту́пить тя.","@4 Пом'яне́ть вся́ку же́ртву твою́, і всесожже́ніє твоє́ ту́чно бу́ди.","@5 Дасть ті Госпо́дь по се́рдцю твоєму́, і весь сові́т твой іспо́лнить.","@6 Возра́дуємся о спасе́нії твоє́м, і во і́м'я Го́спода Бо́га на́шего возвели́чимся; іспо́лнить Госпо́дь вся проше́нія твоя́.","@7 Ни́ні позна́х, я́ко спасе́ Госпо́дь Христа́ Своєго́; усли́шить Єго́ с небесе́ Свята́го Своєго́; в си́лах спасе́ніє десни́ці Єго́.","@8 Сі́ї на колесни́цях, і сі́ї на ко́нех; ми же во і́м'я Го́спода Бо́га на́шего призове́м.","@9 Ті́ї сп'я́ті би́ша і падо́ша; ми же воста́хом і іспра́вихомся.","@10 Го́споди, спаси́ царя́, і усли́ши ни, в о́ньже а́ще день призове́м Тя."]},{"h":"Псалом 20","ps":["§Псало́м Дави́ду, 20.","@2 Го́споди, си́лою Твоє́ю возвесели́ться цар, і о спасе́нії Твоє́м возра́дується зіло́.","@3 Жела́ніє се́рдця єго́ дал єси́ єму́, і хоті́нія устну́ єго́ ні́си лиши́л єго́.","@4 Я́ко предвари́л єси́ єго́ благослове́нієм благости́нним, положи́л єси́ на главі́ єго́ віне́ць от ка́мене че́стна.","@5 Живота́ проси́л єсть у Тебе́, і дал єси́ єму́ долготу́ дній во вік ві́ка.","@6 Ве́лія сла́ва єго́ спасе́нієм Твої́м; сла́ву і велелі́піє возложи́ши на него́.","@7 Я́ко да́си єму́ благослове́ніє во вік ві́ка; возвесели́ши єго́ ра́достію с лице́м Твої́м.","@8 Я́ко цар упова́єть на Го́спода, і ми́лостію Ви́шняго не подви́житься.","@9 Да обря́щеться рука́ Твоя́ всім враго́м Твої́м, десни́ця Твоя́ да обря́щеть вся ненави́дящия Тебе́.","@10 Я́ко положи́ши їх, я́ко пещ о́гненную во вре́м'я лиця́ Твоєго́; Госпо́дь гні́вом Свої́м см'яте́ть я, і сність їх огнь.","@11 Плод їх от землі́ погуби́ши, і сі́м'я їх от сино́в челові́чеських.","@12 Я́ко уклони́ша на Тя зла́я, поми́слиша сові́ти, ї́хже не возмо́гуть соста́вити.","@13 Я́ко положи́ши я хребе́т; во ізби́тціх Твої́х угото́виши лице́ їх.","@14 Вознеси́ся, Го́споди, си́лою Твоє́ю; воспоє́м і поє́м си́ли Твоя́.","§Сла́ва:"]},{"h":"Псалом 21","ps":["§В коне́ць, о заступле́нії у́треннем, псало́м Дави́ду, 21.","@2 Бо́же, Бо́же мой, воньми́ мі, вску́ю оста́вил м'я єси́? Дале́че от спаcе́нія моєго́ словеса́ гріхопаде́ній мої́х.","@3 Бо́же мой, воззову́ во дні, і не усли́шиши, і в нощі́, і не в безу́міє мні.","@4 Ти же во святі́м живе́ши, хвало́ Ізра́їлева.","@5 На Тя упова́ша отці́ на́ші; упова́ша, і ізба́вил єси́ я;","@6 к Тебі́ воззва́ша, і спасо́шася; на Тя упова́ша, і не постиді́шася.","@7 Аз же єсьм черв, а не челові́к, поноше́ніє челові́ков і унічиже́ніє люді́й.","@8 Всі ви́дящії м'я поруга́шамися, глаго́лаша устна́ми, покива́ша главо́ю;","@9 упова́ на Го́спода, да ізба́вить єго́, да спасе́ть єго́, я́ко хо́щеть єго́.","@10 Я́ко Ти єси́ істо́ргий м'я із чре́ва, упова́ніє моє́ от сосцю́ ма́тере моєя́.","@11 К Тебі́ приве́ржен єсьм от ложе́сн, от чре́ва ма́тере моєя́ Бог мой єси́ Ти.","@12 Да не отсту́пиши от мене́, я́ко скорб близ, я́ко ність помога́яй мі.","@13 Обидо́ша м'я тельці́ мно́зі, юнці́ ту́чнії одержа́ша м'я;","@14 отверзо́ша на м'я уста́ своя́, я́ко лев восхища́яй і рика́яй.","@15 Я́ко вода́ ізлія́хся, і разси́пашася вся ко́сті моя́; бисть се́рдце моє́ я́ко воск та́яй посреді́ чре́ва моєго́.","@16 І́зсше, я́ко скуде́ль, крі́пость моя́, і язи́к мой прильпе́ горта́ни моєму́, і в персть сме́рті свел м'я єси́.","@17 Я́ко обидо́ша м'я пси мно́зі, сонм лука́вих одержа́ша м'я; іскопа́ша ру́ці мої́ і но́зі мої́.","@18 Ісчето́ша вся ко́сті моя́; ті́ї же смотри́ша і презрі́ша м'я.","@19 Разділи́ша ри́зи моя́ себі́, і о оде́жді моє́й мета́ша жре́бій.","@20 Ти же, Го́споди, не удали́ по́мощ Твою́ от мене́; на заступле́ніє моє́ воньми́.","@21 Ізба́ви от ору́жія ду́шу мою́, і із руки́ пе́сії єдоноро́дную мою́.","@22 Спаси́ м'я от уст льво́вих, і от рог єдиноро́ж смире́ніє моє́.","@23 Пові́м і́м'я Твоє́ бра́тії моє́й, посреді́ це́ркве воспою́ Тя.","@24 Боя́щіїся Го́спода, восхвалі́те Єго́, все сі́м'я Іа́ковле, просла́віте Єго́, да убої́ться же от Него́ все сі́м'я Ізра́їлево;","@25 я́ко не унічижи́, ніже́ негодова́ моли́тви ни́щаго, ніже́ отврати́ лице́ Своє́ от мене́, і єгда́ воззва́х к Нему́, усли́ша м'я.","@26 От Тебе́ похвала́ моя́, в це́ркві вели́цій іспові́мся Тебі́; моли́тви моя́ возда́м пред боя́щимися Єго́.","@27 Ядя́ть убо́зії і наси́тяться, і восхва́лять Го́спода взиска́ющії Єго́; жива́ бу́дуть сердця́ їх в вік ві́ка.","@28 Пом'яну́ться і обратя́ться ко Го́споду всі конці́ землі́, і покло́няться пред ним вся оте́чествія язи́к;","@29 я́ко Госпо́днє єсть Ца́рствіє, і Той облада́єть язи́ки.","@30 Ядо́ша і поклони́шася всі ту́чнії землі́; пред Ним припаду́ть всі низходя́щії в зе́млю; і душа́ моя́ Тому́ живе́ть.","@31 І сі́м'я моє́ порабо́таєть Єму́; возвісти́ть Го́сподеві род гряду́щий;","@32 і возвістя́ть пра́вду Єго́ лю́дем ро́ждшимся⁽1⁾, я́же сотвори́ Госпо́дь."]},{"h":"Псалом 22","ps":["§Псало́м Дави́ду, 22.","@1 Госпо́дь пасе́ть м'я, і нічто́же м'я лиши́ть.","@2 На мі́сте зла́чні, та́мо всели́ м'я, на воді́ поко́йні воспита́ м'я.","@3 Ду́шу мою́ обрати́, наста́ви м'я на стезі́ пра́вди і́мене ра́ди Своєго́.","@4 А́ще бо і пойду́ посреді́ сі́ні сме́ртния, не убою́ся зла, я́ко Ти со мно́ю єси́; жезл Твой і па́лиця Твоя́, та м'я уті́шиста.","@5 Угото́вал єси́ пре́до мно́ю трапе́зу сопроти́в стужа́ющим мні; ума́стил єси́ єле́йом главу́ мою́, і ча́ша Твоя́ упоява́ющи м'я, я́ко держа́вна.","@6 І ми́лость Твоя́ пожене́ть м'я вся дні живота́ моєго́, і є́же всели́тимися в дом Госпо́день в долготу́ дній."]},{"h":"Псалом 23","ps":["§Псало́м Дави́ду, єди́ния от субо́т, 23.","@1 Госпо́дня земля́, і ісполне́ніє єя́, вселе́нная і всі живу́щії на ней.","@2 Той на моря́х основа́л ю єсть і на ріка́х угото́вал ю єсть.","@3 Кто взи́деть на го́ру Госпо́дню? Іли́ кто ста́неть на мі́сті святі́м Єго́?","@4 Непови́нен рука́ма і чист се́рдцем, І́же не прия́т всу́є ду́шу свою́ і не кля́тся ле́стію і́скреннему своєму́;","@5 сей при́йметь благослове́ніє от Го́спода і ми́лостиню от Бо́га Спа́са Своєго́.","@6 Сей род і́щущих Го́спода, і́щущих лице́ Бо́га Іа́ковля.","@7 Возьмі́те врата́ кня́зі ва́ша, і возьмі́теся врата́ ві́чная; і вни́деть Цар сла́ви.","@8 Кто єсть сей Цар сла́ви? Госпо́дь крі́пок і си́лен, Госпо́дь си́лен в бра́ні.","@9 Возьмі́те врата́ кня́зі ва́ша, і возьмі́теся врата́ ві́чная; і вни́деть Цар сла́ви.","@10 Кто єсть сей Цар сла́ви? Госпо́дь сил, Той єсть Цар сла́ви.","§Сла́ва:"]},{"h":"Після 3-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 3:","ps":["Живу́щи на землі́, душе́ моя́, пока́йся, персть во гро́бі не поє́ть, прегріше́ній не ізбавля́єть. Возопі́й Христу́ Бо́гу: Сердцеві́дче, согріши́х, пре́жде да́же не осу́диши м'я, поми́луй м'я.","Доко́лі, душе́ моя́, пребива́єши в прегріше́ніїх? Доко́лі приє́млеши покая́нія преложе́ніє? Прийми́ во умі́ суд гряду́щий і возопи́й Го́споду: Сердцеві́дче, согріши́х, пре́жде да́же не осу́диши м'я, поми́луй м'я.","Сла́ва: На Стра́шном Суди́щі без оглаго́льников облича́юся, без свиді́телей осужда́юся; кни́ги бо со́вістния разгиба́ються, і діла́ сокрове́нная открива́ються. Пре́жде не́же во о́ном всенаро́дном позо́рищі і́маши іспита́ти, я́же мно́ю соді́янная, Бо́же, очи́сти м'я, і спаси́ м'я.","І ни́ні: Недоразуміва́ємоє і непостижи́моє єсть, Влади́чице Богоблагода́тная, соді́янноє о Тебі́ стра́шноє та́їнство; Необ'є́млемаго бо заче́нши, родила́ єси́ пло́тію обложе́ннаго от чи́стих крове́й Твої́х. Єго́же, Чи́стая, я́ко Си́на Твоєго́, моли́ спасти́ вся пою́щия Тя."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Вседержи́телю, Сло́ве Пребезнача́льнаго Отця́, самосоверше́нний Бо́же Ісу́се Христе́, милосе́рдія ра́ди безприкла́днаго ми́лости Твоєя́ ніка́коже разлуча́яйся Твої́х рабо́в, но при́сно в них почива́яй, не оста́ви м'я, раба́ Твоєго́, Всесвяти́й Царю́; но даждь мні, недосто́йному, ра́дованіє спасе́нія Твоєго́, і просвіти́ мой ум сві́том позна́нія Єва́нгелія Твоєго́, ду́шу мою́ любо́вію Креста́ Твоєго́ об'яжи́, ті́ло же моє́ Твої́м безстра́стієм украси́, ми́слі умири́, і но́зі мої́ сохрани́ от поползнове́нія, і не погуби́ м'я со беззако́нньми мої́ми, благи́й Го́споди, но іскуси́ м'я, Бо́же, і вразуми́ се́рдце моє́; іспита́й м'я, і уві́ждь стезі́ моя́, і виждь, а́ще путь беззако́нія во мні, і отврати́ от него́, і наста́ви м'я на путь ві́чен. Ти бо єси́ Путь, і І́стина, і Живо́т, і Тебі́ сла́ву возсила́єм, со Безнача́льним Твої́м Отце́м і Пресвяти́м, і Благи́м, і Животворя́щим Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[роди́тися іму́щим]</span>"]},{"u":"Кафизма 4","e":"Kathisma 4","secs":[{"h":"Псалом 24","ps":["§Псало́м Дави́ду, 24.","@1 К Тебі́, Го́споди, воздвиго́х ду́шу мою́, Бо́же мой, на Тя упова́х, да не постижу́ся во вік, ніже́ да посмію́тьмися вразі́ мої́;","@2 і́бо всі терп'я́щії Тя не постидя́ться.","@3 Да постидя́ться беззако́ннующії вотще́.","@4 Путі́ Твоя́, Го́споди, скажи́ мі і стезя́м Твої́м научи́ м'я.","@5 Наста́ви м'я на і́стину Твою́ і научи́ м'я; я́ко Ти єси́ Бог спас мой, і Тебе́ терпі́х весь день.","@6 Пом'яни́ щедро́ти Твоя́, Го́споди, і ми́лості Твоя́, я́ко от ві́ка суть.","@7 Гріх ю́ности моєя́ і неві́дінія моєго́ не пом'яни́; по ми́лості Твоє́й пом'яни́ м'я Ти, ра́ди бла́гости Твоєя́, Го́споди.","@8 Благ і прав Госпо́дь, сего́ ра́ди законоположи́ть согріша́ющим на путі́.","@9 Наста́вить кро́ткия на суд, научи́ть кро́ткия путе́м Свої́м.","@10 Всі путіє́ Госпо́дні ми́лость і і́стина, взиска́ющим заві́та Єго́ і свиді́нія Єго́.","@11 Ра́ди і́мене Твоєго́, Го́споди, і очи́сти гріх мой, мног бо єсть.","@12 Кто єсть челові́к боя́йся Го́спода? Законоположи́ть єму́ на путі́, єго́же ізво́ли.","@13 Душа́ єго́ во благи́х водвори́ться, і сі́м'я єго́ наслі́дить зе́млю.","@14 Держа́ва Госпо́дь боя́щихся Єго́, і заві́т Єго́ яви́ть їм.","@15 О́чі мої́ ви́ну ко Го́споду, я́ко той істо́ргнеть от сі́ті но́зі мої́.","@16 При́зри на м'я і поми́луй м'я, я́ко єдиноро́д і нищ єсьм аз.","@17 Ско́рбі се́рдця моєго́ умно́жишася, от нужд мої́х ізведи́ м'я.","@18 Виждь смире́ніє моє́ і труд мой, і оста́ви вся гріхи́ моя́.","@19 Виждь враги́ моя́, я́ко умно́жишася, і ненавиді́нієм непра́ведним возненави́діша м'я.","@20 Сохрани́ ду́шу мою́ і ізба́ви м'я, да не постижу́ся, я́ко упова́х на Тя.","@21 Незло́бивії і пра́вії приліпля́хуся мні, я́ко потерпі́х Тя, Го́споди.","@22 Ізба́ви, Бо́же, Ізра́їля от всіх скорбе́й єго́."]},{"h":"Псалом 25","ps":["§Псало́м Дави́ду, 25.","@1 Суди́ мі, Го́споди, я́ко аз незло́бою моє́ю ходи́х; і на Го́спода упова́я не ізнемогу́.","@2 Іскуси́ м'я, Го́споди, і іспита́й м'я, разжжи́ утро́би моя́ і се́рдце моє́.","@3 Я́ко ми́лость Твоя́ пред очи́ма мої́ма єсть, і благоугоди́х во і́стині Твоє́й.","@4 Не сідо́х с со́ньмом су́єтним, і со законопресту́пними не вни́ду.","@5 Возненави́діх це́рков лука́внующих, і с нечести́вими не ся́ду.","@6 Уми́ю в непови́нних ру́ці мої́, і оби́ду же́ртвенник Твой, Го́споди,","@7 є́же усли́шати мі глас хвали́ Твоєя́ і пові́дати вся чудеса́ Твоя́.","@8 Го́споди, возлюби́х благолі́піє до́му Твоєго́ і мі́сто селе́нія сла́ви Твоєя́.","@9 Да не погуби́ши с нечести́вими ду́шу мою́ і с му́жі крове́й живо́т мой,","@10 ї́хже в руку́ беззако́нія, десни́ця їх іспо́лнися мзди.","@11 Аз же незло́бою моє́ю ходи́х; ізба́ви м'я, Го́споди, і поми́луй м'я.","@12 Нога́ моя́ ста на правоті́; в це́рквах благословлю́ Тя, Го́споди."]},{"h":"Псалом 26","ps":["§Псало́м Дави́ду, пре́жде пома́занія, 26.","@1 Госпо́дь — Просвіще́ніє моє́ і Спаси́тель мой, кого́ убою́ся? Госпо́дь — Защи́титель живота́ моєго́, от кого́ устрашу́ся?","@2 Внегда́ приближа́тися на м'я зло́бующим, є́же сні́сти пло́ті моя́, оскорбля́ющії м'я і вразі́ мої́, ті́ї ізнемого́ша і падо́ша.","@3 А́ще ополчи́ться на м'я полк, не убої́ться се́рдце моє́; а́ще воста́неть на м'я брань, на Него́ аз упова́ю.","@4 Єди́но проси́х от Го́спода, то взищу́: є́же жи́ти мі в дому́ Госпо́дні вся дні живота́ моєго́, зрі́ти мі красоту́ Госпо́дню і посіща́ти храм святи́й Єго́.","@5 Я́ко скри м'я в селе́нії Своє́м в день зол мої́х, покри́ м'я в та́йні селе́нія Своєго́, на ка́мень вознесе́ м'я.","@6 І ни́ні се, вознесе́ главу́ мою́ на враги́ моя́; обидо́х і пожро́х в селе́нії Єго́ же́ртву хвале́нія і воскликнове́нія; пою́ і воспою́ Го́сподеві.","@7 Усли́ши, Го́споди, глас мой, і́мже воззва́х, поми́луй м'я і усли́ши м'я.","@8 Тебі́ рече́ се́рдце моє́: Го́спода взищу́, взиска́ Тебе́ лице́ моє́, лиця́ Твоєго́, Го́споди, взищу́.","@9 Не отврати́ лиця́ Твоєго́ от мене́ і не уклони́ся гні́вом от раба́ Твоєго́; Помо́щник мой бу́ди, не отри́ни мене́ і не оста́ви мене́, Бо́же, Спаси́телю мой.","@10 Я́ко оте́ць мой і ма́ти моя́ оста́виста м'я, Госпо́дь же восприя́т м'я.","@11 Законоположи́ мі, Го́споди, в путі́ Твоє́м, і наста́ви м'я на стезю́ пра́вую враг мої́х ра́ди.","@12 Не преда́ждь мене́ в ду́ші стужа́ющих мі; я́ко воста́ша на м'я свиді́теле непра́веднії, і солга́ непра́вда себі́.","@13 Ві́рую ви́діти блага́я Госпо́дня на землі́ живи́х.","@14 Потерпи́ Го́спода, мужа́йся, і да кріпи́ться се́рдце Твоє́, і потерпи́ Го́спода.","§Сла́ва:"]},{"h":"Псалом 27","ps":["§Псало́м Дави́ду, 27.","@1 К Тебі́, Го́споди, воззову́, Бо́же мой! Да не премолчи́ши от мене́⁽1⁾; да не когда́ премолчи́ши от мене́⁽2⁾, і уподо́блюся низходя́щим в ров.","@2 Усли́ши, Го́споди, глас моле́нія моєго́, внегда́ моли́тимися к Тебі́, внегда́ возді́ти мі ру́ці мої́ ко хра́му свято́му Твоєму́.","@3 Не привлеци́ мене́ со грі́шники і с ді́лающими непра́вду не погуби́ мене́, глаго́лющими мир с бли́жніми свої́ми, зла́я же в сердця́х свої́х.","@4 Даждь їм, Го́споди, по діло́м їх і по лука́вству начина́ній їх, по діло́м руку́ їх даждь їм, возда́ждь воздая́ніє їх їм.","@5 Я́ко не разумі́ша в діла́ Госпо́дня і в діла́ руку́ Єго́; разори́ши я і не сози́ждеши я.","@6 Благоcлове́н Госпо́дь, я́ко усли́ша глас моле́нія моєго́.","@7 Госпо́дь — помо́щник мой і защи́титель мой; на Него́ упова́ се́рдце моє́, і помо́же мі, і процвіте́ плоть моя́; і во́лею моє́ю іспові́мся Єму́.","@8 Госпо́дь — утвержде́ніє люді́й Свої́х і защи́титель спасе́ній христа́ Своєго́ єсть.","@9 Спаси́ лю́ди Твоя́, і благослови́ достоя́ніє Твоє́, і упаси́ я, і возьми́⁽3⁾ я до ві́ка."]},{"h":"Псалом 28","ps":["§Псало́м Дави́ду, ісхо́да ски́нії, 28.","@1 Принесі́те Го́сподеві, си́нове Бо́жії, принесі́те Го́сподеві си́ни о́вні, принесі́те Го́сподеві сла́ву і честь;","@2 принесі́те Го́сподеві сла́ву і́мені Єго́; поклоні́теся Го́сподеві во дворі́ святі́м Єго́.","@3 Глас Госпо́день на вода́х, Бог сла́ви возгремі́, Госпо́дь на вода́х мно́гих.","@4 Глас Госпо́день в крі́пості, глас Госпо́день в великолі́пії.","@5 Глас Го́спода, сокруша́ющаго ке́дри; і стри́єть Госпо́дь ке́дри лива́нськія,","@6 і істни́ть я я́ко тельця́ лива́нська; і возлю́бленний я́ко син єдиноро́ж.","@7 Глас Го́спода, пресіца́ющаго пла́мень огня́.","@8 Глас Го́спода, стряса́ющаго пусти́ню; і стрясе́ть Госпо́дь пусти́ню Кадді́йскую.","@9 Глас Госпо́день, сверша́ющий єле́ні, і откри́єть дубра́ви; і в хра́мі Єго́ вся́кий глаго́леть сла́ву.","@10 Госпо́дь пото́п населя́єть, і ся́деть Госпо́дь Цар в вік.","@11 Госпо́дь крі́пость лю́дем Свої́м дасть, Госпо́дь благослови́ть лю́ди Своя́ ми́ром."]},{"h":"Псалом 29","ps":["§Псало́м пі́сні обновле́нія до́му Дави́дова, 29.","@2 Вознесу́ Тя, Го́споди, я́ко под'я́л м'я єси́, і не возвесели́л єси́ враго́в мої́х о мні.","@3 Го́споди Бо́же мой, воззва́х к Тебі́, і ізціли́л м'я єси́.","@4 Го́споди, возве́л єси́ от а́да ду́шу мою́, спасл м'я єси́ от низходя́щих в ров.","@5 По́йте Го́сподеві, преподо́бнії Єго́, і іспові́дайте па́м'ять святи́ні Єго́;","@6 я́ко гнів в я́рості Єго́, і живо́т в во́лі Єго́; ве́чер водвори́ться плач, і зау́тра ра́дость.","@7 Аз же ріх во оби́лії моє́м: не подви́жуся во вік.","@8 Го́споди, во́лею Твоє́ю пода́ждь добро́ті моє́й си́лу; отврати́л же єси́ лице́ Твоє́, і бих смуще́н.","@9 К Тебі́, Го́споди, воззову́, і к Бо́гу моєму́ помолю́ся.","@10 Ка́я по́льза в кро́ві моє́й, внегда́ сходи́ти мі во істлі́ніє? Єда́ іспові́сться Тебі́ персть? Іли́ возвісти́ть і́стину Твою́?","@11 Сли́ша Госпо́дь і поми́лова м'я; Госпо́дь бисть помо́щник мой.","@12 Обрати́л єси́ плач мой в ра́дость мні, растерза́л єси́ вре́тище моє́ і препоя́сал м'я єси́ весе́лієм,","@13 я́ко да воспоє́ть Тебі́ сла́ва моя́, і не умилю́ся. Го́споди Бо́же мой, во вік іспові́мся Тебі́.","§Сла́ва:"]},{"h":"Псалом 30","ps":["§В коне́ць, псало́м Дави́ду, ізступле́нія, 30.","@2 На Тя, Го́споди, упова́х, да не постижу́ся во вік; пра́вдою Твоє́ю ізба́ви м'я і ізми́ м'я.","@3 Приклони́ ко мні у́хо Твоє́, ускори́ із'я́ти м'я; бу́ди мі в Бо́га Защи́тителя і в Дом прибі́жища, є́же спасти́ м'я.","@4 Я́ко держа́ва моя́ і прибі́жище моє́ єси́ Ти; і і́мене Твоєго́ ра́ди наста́виши м'я і препита́єши м'я.","@5 Ізведе́ши м'я от сі́ті сея́, ю́же скри́ша мі; я́ко Ти єси́ Защи́титель мой, Го́споди.","@6 В ру́ці Твої́ предложу́ дух мой; ізба́вил м'я єси́, Го́споди Бо́же і́стини.","@7 Возненави́діл єси́ храня́щия суєти́ вотще́; аз же на Го́спода упова́х.","@8 Возра́дуюся і возвеселю́ся о ми́лості Твоє́й, я́ко призрі́л єси́ на смире́ніє моє́, спасл єси́ от нужд ду́шу мою́","@9 і ні́си мене́ затвори́л в рука́х вра́жіїх, поста́вил єси́ на простра́нні но́зі мої́.","@10 Поми́луй м'я, Го́споди, я́ко скорблю́; см'яте́ся я́ростію о́ко моє́, душа́ моя́ і утро́ба моя́.","@11 Я́ко ізчезе́ в болі́зні живо́т мой, і лі́та моя́ в воздиха́ніїх; ізнемо́же нището́ю крі́пость моя́, і ко́сті моя́ см'ято́шася.","@12 От всіх враг мої́х бих поноше́ніє, і сосі́дом мої́м зіло́, і страх зна́ємим мої́м; ви́дящії м'я вон біжа́ша от мене́.","@13 Забве́н бих я́ко мертв от се́рдця; бих я́ко сосу́д погубле́н.","@14 Я́ко сли́шах гажде́ніє⁽4⁾ мно́гих живу́щих о́крест, внегда́ собра́тися їм вку́пі на м'я, прия́ти ду́шу мою́ совіща́ша.","@15 Аз же на Тя, Го́споди, упова́х, ріх: Ти єси́ Бог мой.","@16 В руку́ Твоє́ю жре́бії мої́; ізба́ви м'я із руки́ враг мої́х і от гоня́щих м'я.","@17 Просвіти́ лице́ Твоє́ на раба́ Твоєго́; спаси́ м'я ми́лостію Твоє́ю.","@18 Го́споди, да не постижу́ся, я́ко призва́х Тя; да постидя́ться нечести́вії і сни́дуть во ад.","@19 Ні́ми да бу́дуть устни́ льсти́вия, глаго́лющия на пра́веднаго беззако́ніє, горди́нею і унічиже́нієм.","@20 Коль мно́гоє мно́жество бла́гости Твоєя́, Го́споди, ю́же скрил єси́ боя́щимся Тебе́, соді́лал єси́ упова́ющим на Тя, пред си́ни челові́чеськими!","@21 Скри́єши їх в та́йні лиця́ Твоєго́ от м'яте́жа челові́чеська, покри́єши їх в кро́ві от преріка́нія язи́к.","@22 Благослове́н Госпо́дь, я́ко удиви́ ми́лость Свою́ во гра́ді огражде́нія.","@23 Аз же ріх во ізступле́нії моє́м: отве́ржен єсьм от лиця́ о́чію Твоє́ю; сего́ ра́ди усли́шал єси́ глас моли́тви моєя́, внегда́ воззва́х к Тебі́.","@24 Возлюбі́те Го́спода, всі преподо́бнії Єго́; я́ко і́стини взиска́єть Госпо́дь і воздає́ть ізли́ше творя́щим горди́ню.","@25 Мужа́йтеся, і да кріпи́ться се́рдце ва́ше, всі упова́ющії на Го́спода."]},{"h":"Псалом 31","ps":["§Псало́м Дави́ду, ра́зума, 31.","@1 Блаже́нні, ї́хже оста́вишася беззако́нія, і ї́хже прикри́шася грісі́.","@2 Блаже́н муж, єму́же не вміни́ть Госпо́дь гріха́, ніже́ єсть во усті́х єго́ лесть.","@3 Я́ко умолча́х, обетша́ша ко́сті моя́, от є́же зва́ти мі весь день,","@4 я́ко день і нощ отяготі́ на мні рука́ Твоя́; возврати́хся на страсть, єгда́ уньзе́ мі терн.","@5 Беззако́ніє моє́ позна́х і гріха́ моєго́ не покри́х, ріх: іспові́м на м'я беззако́ніє моє́ Го́сподеві, і Ти оста́вил єси́ нече́стіє се́рдця моєго́.","@6 За то помо́литься к Тебі́ всяк преподо́бний во вре́м'я благопотре́бно; оба́че в пото́пі вод мно́гих к нему́ не прибли́жаться.","@7 Ти єси́ Прибі́жище моє́ от ско́рби обдержа́щия м'я; Ра́досте моя́, ізба́ви м'я от обише́дших м'я.","@8 Вразумлю́ тя, і наста́влю тя на путь сей, в о́ньже по́йдеши; утвержу́ на тя о́чі Мої́.","@9 Не бу́діте я́ко конь і меск, ї́мже ність ра́зума; брозда́ми і уздо́ю че́люсті їх востя́гнеши, не приближа́ющихся к тебі́.","@10 Мно́гі ра́ни грі́шному; упова́ющаго же на Го́спода ми́лость оби́деть.","@11 Веселі́теся о Го́споді і ра́дуйтеся, пра́веднії, і хвалі́теся, всі пра́вії се́рдцем.","§Сла́ва:"]},{"h":"Після 4-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 7:","ps":["Смире́нную мою́ ду́шу посіти́, Го́споди, во грісі́х все житіє́ іжди́вшую; і́мже о́бразом блудни́цю прийми́ і мене́, і спаси́ м'я.","Препла́вая пучи́ну настоя́щаго житія́, помишля́ю бе́здну мно́гих мої́х зол, і не імі́яй окорми́теля помишле́ній, Петро́в провіщава́ю Ті глас: спаси́ м'я, Христе́, спаси́ м'я, Бо́же, я́ко Человіколю́бець.","Сла́ва: Ско́ро совни́дем в неві́стник Христо́в, да всі усли́шим блаже́нний глас Христа́ Бо́га на́шего; прийді́те лю́б'ящії небе́сную сла́ву, соприча́стници би́вше му́дрих дів, уясни́вше свіщі́ на́ша ві́рою.","І ни́ні: Душе́, пока́йся пре́жде ісхо́да твоєго́, суд неуми́тен грі́шним єсть і нестерпи́мий, возопи́й Го́споду во умиле́нії се́рдця: согріши́х Ті в ві́дінії і не в ві́дінії. Ще́дрий, моли́твами Богоро́диці уще́дри і спаси́ м'я."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Тебі́ Го́споди, єди́ному благо́му і непам'ятозло́бному іспові́даю гріхи́ моя́, Тебі́ припа́даю вопія́ недосто́йний: согріши́х, Го́споди, согріши́х, і нісьм досто́їн воззрі́ти на висоту́ небе́сную от мно́жества непра́вд мої́х. Но, Го́споди мой, Го́споди, да́руй мі сле́зи умиле́нія, єди́ний Бла́же і Ми́лостивий, я́ко да ї́ми Тя умолю́, очи́ститися пре́жде конця́ от вся́каго гріха́; стра́шно бо і гро́зно мі́сто і́мам пройти́, ті́ла разлучи́вся, і мно́жество м'я мра́чноє і безчелові́чноє де́монов сря́щеть, і нікто́же в по́мощ спу́тствуяй, іли́ ізбавля́яй. Тім припа́даю Твоє́й бла́гості, не преда́ждь оби́дящим м'я, ніже́ да похва́ляться о мні вразі́ мої́, благи́й Го́споди, ніже́ да реку́ть: в ру́ки на́ша прише́л єси́, і нам пре́дан єси́. Ні, Го́споди, не забу́ди щедро́т Твої́х, і не возда́ждь мі по беззако́нієм мої́м, і не отврати́ лиця́ Твоєго́ от мене́, но Ти, Го́споди, накажи́ м'я, оба́че ми́лостію і щедро́тами; враг же мой да не возра́дується о мні, но угаси́ єго́ на м'я преще́нія, і все упраздни́ єго́ ді́йство, і даждь мі к Тебі́ путь неуко́рний, благи́й Го́споди; зане́же і согріши́в не прибіго́х ко іно́му врачу́, і не простро́х руки́ моєя́ к бо́гу чужде́му. Не отри́ни у́бо моле́нія моєго́, но усли́ши м'я Твоє́ю бла́гостію, і утверди́ моє́ се́рдце стра́хом Твої́м, і да бу́деть благода́ть Твоя́ на мні, Го́споди, я́ко огнь попаля́яй нечи́стия во мні по́мисли. Ти бо єси́, Го́споди, світ па́че вся́каго сві́та; ра́дость па́че вся́кия ра́дости, упокоє́ніє па́че вся́каго упокоє́нія; жизнь і́стинная, і спасе́ніє, пребива́ющеє во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[о мні]</span>","<span class=''>[о мні]</span>","<span class=''>[і вознеси́]</span>","<span class=''>[укоре́ніє]</span>"]},{"u":"Кафизма 5","e":"Kathisma 5","secs":[{"h":"Псалом 32","ps":["§Псало́м Дави́ду, не надпи́сан у євре́й, 32.","@1 Ра́дуйтеся, пра́веднії, о Го́споді; пра́вим подоба́єть похвала́.","@2 Іспові́дайтеся Го́сподеві в гу́слех, во псалти́рі десятостру́ннім по́йте Єму́;","@3 воспо́йте Єму́ піснь но́ву, до́брі по́йте Єму́ со восклица́нієм;","@4 я́ко пра́во сло́во Госпо́днє, і вся діла́ Єго́ в ві́рі.","@5 Лю́бить ми́лостиню і суд Госпо́дь, ми́лости Госпо́дні іспо́лнь земля́.","@6 Сло́вом Госпо́днім небеса́ утверди́шася, і Ду́хом уст Єго́ вся си́ла їх;","@7 собира́яй, я́ко міх, во́ди морські́я, полага́яй в сокро́вищих бе́здни.","@8 Да убої́ться Го́спода вся земля́, от Него́же да подви́жуться всі живу́щії по вселе́нній;","@9 я́ко Той рече́ — і би́ша; Той повелі́ — і созда́шася.","@10 Госпо́дь разоря́єть сові́ти язи́ков, отмета́єть же ми́слі люді́й і отмета́єть сові́ти князе́й.","@11 Сові́т же Госпо́день во вік пребива́єть, помишле́нія се́рдця Єго́ — в род і род.","@12 Блаже́н язи́к, єму́же єсть Госпо́дь Бог Єго́, — лю́діє, я́же ізбра́ в наслі́діє Себі́.","@13 С небесе́ призрі́ Госпо́дь, ви́ді вся си́ни челові́чеськія;","@14 от гото́ваго жили́ща Своєго́ призрі́ на вся живу́щия на землі́;","@15 созда́вий на єди́ні сердця́ їх, разуміва́яй на вся діла́ їх.","@16 Не спаса́ється цар мно́гою си́лою, і ісполи́н не спасе́ться мно́жеством крі́пости своєя́.","@17 Ложь конь во спасе́ніє, во мно́жестві же си́ли своєя́ не спасе́ться.","@18 Се, о́чі Госпо́дні на боя́щияся Єго́, упова́ющия на ми́лость Єго́;","@19 ізба́вити от сме́рти ду́ші їх, і препита́ти я в глад.","@20 Душа́ же на́ша ча́єть Го́спода, я́ко помо́щник і защи́титель наш єсть;","@21 я́ко о Нем возвесели́ться се́рдце на́ше, і во і́м'я свято́є Єго́ упова́хом.","@22 Бу́ди, Го́споди, ми́лость Твоя́ на нас, я́коже упова́хом на Тя."]},{"h":"Псалом 33","ps":["§Псало́м Дави́ду, внегда́ ізміни́ лице́ своє́ пред Авімеле́хом; і отпусти́ єго́, і оти́де, 33.","@2 Благословлю́ Го́спода на вся́коє вре́м'я, ви́ну хвала́ Єго́ во усті́х мої́х.","@3 О Го́споді похва́литься душа́ моя́; да усли́шать кро́тції і возвеселя́ться.","@4 Возвели́чіте Го́спода со мно́ю, і вознесе́м і́м'я Єго́ вку́пі.","@5 Взиска́х Го́спода, і усли́ша м'я, і от всіх скорбе́й мої́х ізба́ви м'я.","@6 Приступі́те к Нему́ і просвіті́теся, і ли́ця ва́ша не постидя́ться.","@7 Сей ни́щий воззва́, і Госпо́дь усли́ша ї, і от всіх скорбе́й єго́ спасе́ ї.","@8 Ополчи́ться а́нгел Госпо́день о́крест боя́щихся Єго́ і ізба́вить їх.","@9 Вкусі́те і ви́діте, я́ко Благ Госпо́дь; блаже́н муж, і́же упова́єть Нань.","@10 Бо́йтеся Го́спода, всі святі́ї Єго́, я́ко ність лише́нія боя́щимся Єго́.","@11 Бога́тії обнища́ша і взалка́ша; взиска́ющії же Го́спода не лиша́ться вся́каго бла́га.","@12 Прийді́те, ча́да, послу́шайте мене́, стра́ху Госпо́дню научу́ вас.","@13 Кто єсть челові́к хотя́й живо́т, люб'я́й дні ви́діти бла́гі?","@14 Удержи́ язи́к твой от зла і устні́ твої́, є́же не глаго́лати льсти.","@15 Уклони́ся от зла і сотвори́ бла́го; взищи́ ми́ра і пожени́ ї.","@16 О́чі Госпо́дні на пра́ведния, і у́ші Єго́ в моли́тву їх.","@17 Лице́ же Госпо́днє на творя́щия зла́я, є́же потреби́ти от землі́ па́м'ять їх.","@18 Воззва́ша пра́веднії, і Госпо́дь усли́ша їх, і от всіх скорбе́й їх ізба́ви їх.","@19 Близ Госпо́дь сокруше́нних се́рдцем, і смире́нния ду́хом спасе́ть.","@20 Мно́гі ско́рбі пра́ведним, і от всіх їх ізба́вить я Госпо́дь.","@21 Храни́ть Госпо́дь вся ко́сті їх, ні єди́на от них сокруши́ться.","@22 Смерть грі́шников люта́, і ненави́дящії пра́веднаго прегріша́ть.","@23 Ізба́вить Госпо́дь ду́ші раб свої́х, і не прегріша́ть всі упова́ющії на Него́.","§Сла́ва:"]},{"h":"Псалом 34","ps":["§Псало́м Дави́ду, 34.","@1 Суди́, Го́споди, оби́дящия м'я, побори́ борю́щия м'я.","@2 Прийми́ ору́жіє і щит і воста́ни в по́мощ мою́;","@3 ізсу́ни меч і заключи́ сопроти́в гоня́щих м'я; рци душі́ моє́й: спасе́ніє твоє́ єсьм Аз.","@4 Да постидя́ться і посра́м'яться і́щущії ду́шу мою́, да возвратя́ться всп'ять і постидя́ться ми́слящії мі зла́я.","@5 Да бу́дуть я́ко прах пред лице́м ві́тра, і а́нгел Госпо́день оскорбля́я їх;","@6 да бу́деть путь їх тьма і по́лзок, і а́нгел Госпо́день погоня́яй їх;","@7 я́ко ту́не скри́ша мі па́губу сі́ті своєя́, всу́є поноси́ша душі́ моє́й.","@8 Да при́йдеть єму́ сіть, ю́же не вість, і лови́тва, ю́же скри, да оби́меть ї, і в сіть да впаде́ть в ню.","@9 Душа́ же моя́ возра́дується о Го́споді, возвесели́ться о спасе́нії Єго́.","@10 Вся ко́сті моя́ реку́ть: Го́споди, Го́споди, кто подо́бен Тебі́? Ізбавля́яй ни́ща із руки́ крі́пльших єго́, і ни́ща, і убо́га от расхища́ющих єго́.","@11 Воста́вше на м'я свиді́теле непра́веднії, я́же не ві́дях, вопроша́ху м'я.","@12 Возда́ша мі лука́вая воз блага́я, і безча́діє душі́ моє́й.","@13 Аз же, внегда́ они́ стужа́ху мі, облача́хся во вре́тище і смиря́х посто́м ду́шу мою́, і моли́тва моя́ в ні́дро моє́ возврати́ться.","@14 Я́ко бли́жнему, я́ко бра́ту на́шему, та́ко угожда́х; я́ко пла́чя і сі́туя, та́ко смиря́хся.","@15 І на м'я возвесели́шася і собра́шася; собра́шася на м'я ра́ни, і не позна́х; разділи́шася, і не умили́шася.","@16 Іскуси́ша м'я, подражни́ша м'я подражне́нієм, поскрежета́ша на м'я зуби́ свої́ми.","@17 Го́споди, когда́ у́зриши? Устро́й ду́шу мою́ от злоді́йства їх, от лев єдоноро́дную мою́.","@18 Іспові́мся Тебі́ в це́ркві мно́зі, в лю́дех тя́жціх восхвалю́ Тя.","@19 Да не возра́дуються о мні вражду́ющії мі непра́ведно, ненави́дящії м'я ту́не і помиза́ющії очи́ма;","@20 я́ко мні у́бо ми́рная глаго́лаху, і на гнів ле́сти помишля́ху.","@21 Разшири́ша на м'я уста́ своя́, рі́ша: бла́гоже, бла́гоже, ви́діша о́чі на́ші.","@22 Ви́діл єси́, Го́споди, да не премолчи́ши; Го́споди, не отступи́ от мене́.","@23 Воста́ни, Го́споди, і воньми́ суду́ моєму́, Бо́же мой і Го́споди мой, на прю мою́.","@24 Суди́ мі, Го́споди, по пра́вді Твоє́й, Го́споди Бо́же мой, і да не возра́дуються о мні.","@25 Да не реку́ть в сердця́х свої́х: бла́гоже, бла́гоже душі́ на́шей; ніже́ да реку́ть: пожро́хом єго́.","@26 Да постидя́ться і посра́м'яться вку́пі ра́дующіїся злом мої́м; да облеку́ться в студ і срам велері́чующії на м'я.","@27 Да возра́дуються і возвеселя́ться хотя́щії пра́вди моєя́; і да реку́ть ви́ну: да возвели́читься Госпо́дь, хотя́щії ми́ра рабу́ Єго́.","@28 І язи́к мой поучи́ться пра́вді Твоє́й, весь день хвалі́ Твоє́й."]},{"h":"Псалом 35","ps":["§В коне́ць, о́троку Госпо́дню Дави́ду, 35.","@2 Глаго́лет пребеззако́нний согріша́ти в себі́; ність стра́ха Бо́жия пред очи́ма єго́;","@3 я́ко ульсти́ пред ним обрісти́ беззако́ніє своє́ і возненави́діти.","@4 Глаго́ли уст єго́ — беззако́ніє і лесть; не восхоті́ разумі́ти є́же ублажи́ти.","@5 Беззако́ніє поми́сли на ло́жі своє́м; предста́ вся́кому путі́ небла́гу, о зло́бі же не негодова́.","@6 Го́споди, на небесі́ ми́лость Твоя́, і і́стина Твоя́ до о́блак;","@7 пра́вда Твоя́ — я́ко го́ри Бо́жия, судьби́ Твоя́ — бе́здна мно́га; челові́ки і скоти́ спасе́ши, Го́споди.","@8 Я́ко умно́жил єси́ ми́лость Твою́, Бо́же; си́нове же челові́честії в кро́ві крилу́ Твоє́ю наді́ятися і́муть.","@9 Упію́ться от ту́ка до́му Твоєго́, і пото́ком сла́дости Твоєя́ напої́ши я.","@10 Я́ко у Тебе́ істо́чник живота́, во сві́ті Твоє́м у́зрим світ.","@11 Проба́ви ми́лость Твою́ ві́дущим Тя і пра́вду Твою́ пра́вим се́рдцем.","@12 Да не при́йдеть мні нога́ горди́ни, і рука́ грі́шнича да не подви́жить мене́.","@13 Та́мо падо́ша всі ді́лающії беззако́ніє; ізринове́ні би́ша і не возмо́гуть ста́ти.","§Сла́ва:"]},{"h":"Псалом 36","ps":["§Псало́м Дави́ду, 36.","@1 Не ревну́й лука́внующим, ніже́ зави́ди творя́щим беззако́ніє.","@2 Зане́ я́ко трава́ ско́ро і́зсшуть, і я́ко зе́ліє зла́ка ско́ро отпаду́ть.","@3 Упова́й на Го́спода і твори́ благости́ню; і насели́ зе́млю і упасе́шися в бога́тстві єя́.","@4 Наслади́ся Го́сподеві, і дасть ті проше́нія се́рдця твоєго́.","@5 Откри́й ко Го́споду путь твой і упова́й на Него́, і Той сотвори́ть.","@6 І ізведе́ть, я́ко світ, пра́вду твою́ і судьбу́ твою́, я́ко полу́дне.","@7 Повини́ся Го́сподеві і умоли́ Єго́. Не ревну́й спі́ющему в путі́ своє́м, челові́ку, творя́щему законопреступле́ніє.","@8 Преста́ни от гні́ва і оста́ви я́рость; не ревну́й, є́же лука́вновати,","@9 зане́ лука́внующії потреб'я́ться, терп'я́щії же Го́спода, ті́ї наслі́дять зе́млю.","@10 І єще́ ма́ло, і не бу́деть грі́шника; і взи́щеши мі́сто єго́ і не обря́щеши.","@11 Кро́тції же наслі́дять зе́млю і насладя́ться о мно́жестві ми́ра.","@12 Назира́єть грі́шний пра́веднаго і поскреже́щеть нань зуби́ свої́ми;","@13 Госпо́дь же посміє́ться єму́, зане́ прозира́єть, я́ко при́йдеть день єго́.","@14 Мечь ізвлеко́ша грі́шници, напряго́ша лук свой, низложи́ти убо́га і ни́ща, закла́ти пра́вия се́рдцем.","@15 Мечь їх да вни́деть в сердця́ їх, і лу́ці їх да сокруша́ться.","@16 Лу́чше ма́лоє пра́веднику, па́че бога́тства грі́шних мно́га.","@17 Зане́ ми́шці грі́шних сокруша́ться, утвержда́єть же пра́ведния Госпо́дь.","@18 Вість Госпо́дь путі́ непоро́чних, і достоя́ніє їх в вік бу́деть.","@19 Не постидя́ться во вре́м'я лю́тоє і во днех гла́да наси́тяться, я́ко грі́шници поги́бнуть.","@20 Вразі́ же Госпо́дні, ку́пно просла́витися їм і вознести́ся, ізчеза́юще, я́ко дим, ізчезо́ша.","@21 Зає́млеть грі́шний і не возврати́ть; пра́ведний же ще́дрить і дає́ть.","@22 Я́ко благословя́щії Єго́ наслі́дять зе́млю, клену́щії же Єго́ потреб'я́ться.","@23 От Го́спода стопи́ челові́ку ісправля́ються, і путі́ єго́ восхо́щеть зіло́.","@24 Єгда́ паде́ть, не разбіє́ться, я́ко Госпо́дь подкріпля́єть ру́ку єго́.","@25 Юні́йшій бих, і́бо состарі́хся, і не ви́діх пра́ведника оста́влена, ніже́ сі́мене єго́ прося́ща хлі́би.","@26 Весь день ми́луєть і взайм дає́ть пра́ведний, і сі́м'я єго́ во благослове́ніє бу́деть.","@27 Уклони́ся от зла і сотвори́ бла́го, і всели́ся в вік ві́ка.","@28 Я́ко Госпо́дь лю́бить суд і не оста́вить преподо́бних Свої́х; во вік сохраня́ться; беззако́нници же ізжену́ться, і сі́м'я нечести́вих потреби́ться.","@29 Пра́ведници же наслі́дять зе́млю і вселя́ться в вік ві́ка на ней.","@30 Уста́ пра́веднаго поуча́ться прему́дрости, і язи́к єго́ возглаго́леть суд.","@31 Зако́н Бо́га єго́ се́рдці єго́, і не за́пнуться стопи́ єго́.","@32 Сматря́єть грі́шний пра́веднаго і і́щеть, є́же умертви́ти єго́;","@33 Госпо́дь же не оста́вить єго́ в руку́ єго́, ніже́ осу́дить єго́, єгда́ су́дить єму́.","@34 Потерпи́ Го́спода і сохрани́ путь Єго́, і вознесе́ть Тя, є́же наслі́дити зе́млю; внегда́ потребля́тися грі́шником, у́зриши.","@35 Ви́діх нечести́ваго превознося́щася і ви́сящася, я́ко ке́дри лива́нськія;","@36 і ми́мо ідо́х, і се не бі, і взиска́х єго́, і не обрі́теся мі́сто єго́.","@37 Храни́ незло́біє і виждь правоту́, я́ко єсть оста́нок челові́ку ми́рну.","@38 Беззако́нници же потреб'я́ться вку́пі; оста́нци же нечести́вих потреб'я́ться.","@39 Спасе́ніє же пра́ведних от Го́спода, і Защи́титель їх єсть во вре́м'я ско́рби;","@40 і помо́жеть їм Госпо́дь, і ізба́вить їх, і і́зметь їх от грі́шник, і спасе́ть їх, я́ко упова́ша на Него́.","§Сла́ва:"]},{"h":"Після 5-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 5:","ps":["Стра́шний Твой престо́л, лука́воє моє́ житіє́, і кто м'я ізба́вить тогда́шнія ну́жди, а́ще не Ти поми́луєши м'я, Христе́ Бо́же, я́ко щедр і Человіколю́бець?","Сла́ва: Попече́ніє житія́ ізгна́ м'я рая́, і что сотворю́, отча́янний? Сего́ ра́ди толку́ во врата́ і зову́: Го́споди Го́споди, отве́рзи мі покая́нієм і спаси́ м'я.","І ни́ні: Кий нарече́м храм Твой, Богоро́дице: приста́нище ли духо́вноє? Іли́ рай сла́дости небе́сния, хода́тайствен жи́зні неконча́ємия? Вся бо і́маши до́брая. Всегда́ моли́ся Христу́ спасти́ся душа́м на́шим."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Бо́же пра́ведний і хва́льний, Бо́же вели́кий і крі́пкий, Бо́же преві́чний, усли́ши грі́шнаго му́жа моли́тву в час сей; усли́ши м'я, обіща́вий усли́шати во і́стині Тя призива́ющих, і не омерзи́ м'я нечи́стия устні́ іму́ща і во грісі́х содержи́ма, упова́ніє всіх конце́в землі́ і стра́нствующих дале́че. Прийми́ ору́жіє і щит, і воста́ни в по́мощ мою́, ізле́й меч і заключи́ сопроти́в гоня́щих м'я; запрети́ нечи́стим духово́м от лиця́ безу́мія моєго́, і да отлучи́ться от моєя́ ми́слі дух не́нависти і злопомні́нія, дух за́висти і ле́сти, дух боя́зні і уни́нія, дух го́рдости і вся́кия іни́я зло́би; і да уга́снеть вся́коє разжже́ніє і движе́ніє пло́ті моєя́, от дия́вольськаго ді́йства составля́ємоє, і да просвіти́ться моя́ душа́, і ті́ло, і дух сві́том Твоєго́ Боже́ственнаго позна́нія, да мно́жеством щедро́т Твої́х дости́гну соєдине́нія ві́ри, в му́жа соверше́нна, в мі́ру во́зраста, і просла́влю со а́нгели і всі́ми святи́ми Твої́ми всечестно́є і великолі́поє і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":[]},{"u":"Кафизма 6","e":"Kathisma 6","secs":[{"h":"Псалом 37","ps":["§Псало́м Дави́ду, в воспомина́ніє о субо́ті, 37.","@2 Го́споди, да не я́ростію Твоє́ю обличи́ши мене́, ніже́ гні́вом Твої́м нака́жеши мене́;","@3 я́ко стрі́ли Твоя́ уньзо́ша во мні, і утверди́л єси́ на мні ру́ку Твою́.","@4 Ність ізціле́нія в пло́ті моє́й от лиця́ гні́ва Твоєго́, ність ми́ра в косте́х мої́х от лиця́ гріх мої́х.","@5 Я́ко беззако́нія моя́ превзидо́ша главу́ мою́, я́ко бре́м'я тя́жкоє отяготі́ша на мні.","@6 Возсмерді́ша і согни́ша ра́ни моя́, от лиця́ безу́мія моєго́.","@7 Пострада́х і сляко́хся до конця́, весь день сі́туя хожда́х;","@8 я́ко ля́двія моя́ напо́лнишася поруга́ній, і ність ізціле́нія в пло́ті моє́й.","@9 Озло́блен бих і смири́хся до зіла́, рика́х от воздиха́нія се́рдця моєго́.","@10 Го́споди, пред Тобо́ю все жела́ніє моє́, і воздиха́ніє моє́ от Тебе́ не утаї́ся.","@11 Се́рдце моє́ см'яте́ся, оста́ви м'я си́ла моя́, і світ о́чію моє́ю — і той ність со мно́ю.","@12 Дру́зі мої́ і і́скреннії мої́ пря́мо мні прибли́жишася і ста́ша.","@13 І бли́жнії мої́ отдале́че мене́ ста́ша, і нужда́хуся і́щущії ду́шу мою́; і і́щущії зла́я мні глаго́лаху су́єтная, і льсти́вним весь день поуча́хуся.","@14 Аз же, я́ко глух, не сли́шах, і я́ко нім не отверза́яй уст свої́х;","@15 і бих я́ко челові́к не сли́шай і не іми́й во усті́х свої́х обличе́нія.","@16 Я́ко на Тя, Го́споди, упова́х, Ти усли́шиши, Го́споди, Бо́же мой.","@17 Я́ко ріх: да не когда́ пора́дуютьмися вразі́ мої́; і внегда́ подвижа́тися нога́м мої́м, на м'я велері́чеваша.","@18 Я́ко аз на ра́ни гото́в, і болі́знь моя́ пре́до мно́ю єсть ви́ну.","@19 Я́ко беззако́ніє моє́ аз возвіщу́ і попеку́ся о грісі́ моє́м.","@20 Вразі́ же мої́ живу́ть і укріпи́шася па́че мене́, і умно́жишася ненави́дящії м'я без пра́вди;","@21 воздаю́щії мі зла́я воз блага́я оболга́ху м'я, зане́ гоня́х благости́ню.","@22 Не оста́ви мене́, Го́споди Бо́же мой, не отступи́ от мене́;","@23 воньми́ в по́мощ мою́, Го́споди спасе́нія моєго́."]},{"h":"Псалом 38","ps":["§В коне́ць, Ідифу́му, піснь Дави́ду, 38.","@2 Ріх: сохраню́ путі́ моя́, є́же не согріша́ти мі язи́ком мої́м; положи́х усто́м мої́м храни́ло, внегда́ воста́ти грі́шному пре́до мно́ю.","@3 Онімі́х і смири́хся, і умолча́х от благ, і болі́знь моя́ обнови́ся.","@4 Согрі́яся се́рдце моє́ во мні, і в поуче́нії моє́м разгори́ться огнь; глаго́лах язи́ком мої́м:","@5 скажи́ мі, Го́споди, кончи́ну мою́ і число́ дній мої́х, ко́є єсть, да разумі́ю, что лиша́юся аз.","@6 Се, п'я́ді положи́л єси́ дні моя́, і соста́в мой — я́ко нічто́же пред Тобо́ю; оба́че вся́чеськая суєта́ всяк челові́к живи́й.","@7 У́бо о́бразом хо́дить челові́к, оба́че всу́є м'яте́ться; сокро́вищствуєть, і не вість, кому́ собере́ть я.","@8 І ни́ні кто терпі́ніє моє́? Не Госпо́дь ли? І соста́в мой от Тебе́ єсть.","@9 От всіх беззако́ній мої́х ізба́ви м'я; поноше́ніє безу́мному дал м'я єси́.","@10 Онімі́х і не отверзо́х уст мої́х, я́ко Ти сотвори́л єси́.","@11 Отста́ви от мене́ ра́ни Твоя́; от крі́пости бо руки́ Твоєя́ аз ізчезо́х.","@12 Во обличе́ніїх о беззако́нії наказа́л єси́ челові́ка, і іста́ял єси́, я́ко паучи́ну, ду́шу єго́; оба́че всу́є всяк челові́к.","@13 Усли́ши моли́тву мою́, Го́споди, і моле́ніє моє́ внуши́, слез мої́х не премолчи́; я́ко пресе́льник аз єсьм у Тебе́ і пришле́ць, я́коже всі отці́ мої́.","@14 Осла́би мі, да почи́ю, пре́жде да́же не отиду́, і ктому́ не бу́ду."]},{"h":"Псалом 39","ps":["§В коне́ць, псало́м Дави́ду, 39.","@2 Терп'я́ потерпі́х Го́спода, і внят мі і усли́ша моли́тву мою́;","@3 і возведе́ м'я от ро́ва страсте́й і от бре́нія ти́ни, і поста́ви на ка́мені но́зі мої́ і іспра́ви стопи́ моя́;","@4 і вложи́ во уста́ моя́ піснь но́ву, пі́ніє Бо́гу на́шему. ​У́зрять мно́зі і убоя́ться, і упова́ють на Го́спода.","@5 Блаже́н муж, єму́же єсть і́м'я Госпо́днє упова́ніє єго́, і не призрі́ в суєти́ і неістовле́нія ло́жная.","@6 Мно́га сотвори́л єси́ Ти, Го́споди Бо́же мой, чудеса́ Твоя́, і помишле́нієм Твої́м ність кто уподо́биться Тебі́; возвісти́х і глаго́лах; умно́жишася па́че числа́.","@7 Же́ртви і приноше́нія не восхоті́л єси́, ті́ло же сверши́л мі єси́; всесожже́ній і о грісі́ не взиска́л єси́.","@8 Тогда́ ріх: се, прийду́; в глави́зні кни́жні пи́сано єсть о мні;","@9 є́же сотвори́ти во́лю Твою́, Бо́же мой, восхоті́х, і зако́н Твой посреді́ чре́ва моєго́.","@10 Благовісти́х пра́вду в це́ркві вели́цій, се, устна́м мої́м не возбраню́; Го́споди, Ти разумі́л єси́.","@11 Пра́вду Твою́ не скрих в се́рдці моє́м, і́стину Твою́ і спасе́ніє Твоє́ ріх, не скрих ми́лость Твою́ і і́стину Твою́ от со́нма мно́га.","@12 Ти же, Го́споди, не удали́ щедро́т Твої́х от мене́; ми́лость Твоя́ і і́стина Твоя́ ви́ну да засту́питі м'я.","@13 Я́ко одержа́ша м'я зла́я, ї́мже ність числа́; постиго́ша м'я беззако́нія моя́, і не возмого́х зрі́ти; умно́жишася па́че влас глави́ моєя́, і се́рдце моє́ оста́ви м'я.","@14 Благоволи́, Го́споди, ізба́вити м'я; Го́споди, во є́же помощи́ мі, воньми́.","@15 Да постидя́ться і посра́м'яться вку́пі і́щущії ду́шу мою́, із'я́ти ю; да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я.","@16 Да при́ймуть а́біє студ свой глаго́лющії мі: бла́гоже, бла́гоже!","@17 Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебе́, Го́споди, і да реку́ть ви́ну «Да возвели́читься Госпо́дь!» лю́б'ящії спасе́ніє Твоє́.","@18 Аз же нищ єсьм і убо́г, Госпо́дь попече́ться о мні; Помо́щник мой і Защи́титель мой єси́ Ти, Бо́же мой, не закосни́.","§Сла́ва:"]},{"h":"Псалом 40","ps":["§В коне́ць, псало́м Дави́ду, 40.","@2 Блаже́н разуміва́яй на ни́ща і убо́га, в день лют ізба́вить єго́ Госпо́дь.","@3 Госпо́дь да сохрани́ть єго́ і живи́ть єго́, і да ублажи́ть єго́ на землі́, і да не преда́сть єго́ в ру́ки враго́в єго́.","@4 Госпо́дь да помо́жеть єму́ на одрі́ болі́зні єго́; все ло́же єго́ обрати́л єси́ в болі́зні єго́.","@5 Аз ріх: Го́споди, поми́луй м'я, ізціли́ ду́шу мою́, я́ко согріши́х Ті.","@6 Вразі́ мої́ рі́ша мні зла́я: когда́ у́мреть, і поги́бнеть і́м'я єго́?","@7 І вхожда́ше ви́діти, всу́є глаго́лаше се́рдце єго́; собра́ беззако́ніє себі́, ісхожда́ше вон і глаго́лаше вку́пі.","@8 На м'я шепта́ху всі вразі́ мої́, на м'я помишля́ху зла́я мні.","@9 Сло́во законопресту́пноє возложи́ша на м'я: єда́ сп'яй не приложи́ть воскресну́ти?","@10 І́бо челові́к ми́ра моєго́, на него́же упова́х, яди́й хлі́би моя́, возвели́чи на м'я запина́ніє.","@11 Ти же, Го́споди, поми́луй м'я і возста́ви м'я, і возда́м їм.","@13 Мене́ же за незло́біє прия́л і утверди́л м'я єси́ пред Тобо́ю в вік.","@14 Благослове́н Госпо́дь Бог Ізра́їлев от ві́ка і до ві́ка! Бу́ди, бу́ди.","@12 В сем позна́х, я́ко восхоті́л м'я єси́, я́ко не возра́дується враг мой о мні."]},{"h":"Псалом 41","ps":["§В коне́ць, в ра́зум сино́в Коре́йових, псало́м Дави́ду, 41.","@2 І́мже о́бразом жела́єть єле́нь на істо́чники водни́я, си́це жела́єть душа́ моя́ к Тебі́, Бо́же.","@3 Возжада́ душа́ моя́ к Бо́гу крі́пкому, живо́му; когда́ прийду́ і явлю́ся лицю́ Бо́жию?","@4 Би́ша сле́зи моя́ мні хліб день і нощ, внегда́ глаго́латися мні на всяк день: гді єсть Бог твой?","@5 Сія́ пом'яну́х і ізлія́х на м'я ду́шу мою́; я́ко пройду́ в мі́сто селе́нія ди́вна, да́же до до́му Бо́жия, во гла́сі ра́дованія і іспові́данія, шу́ма пра́зднующаго.","@6 Вску́ю приско́рбна єси́, душе́ моя́? І вску́ю смуща́єши м'я? Упова́й на Бо́га, я́ко іспові́мся Єму́, спасе́ніє лиця́ моєго́ і Бог мой.","@7 Ко мні самому́ душа́ моя́ см'яте́ся; сего́ ра́ди пом'яну́х Тя от землі́ іорда́нськи і єрмонії́мськи, от гори́ ма́лия.","@8 Бе́здна бе́здну призива́єть во гла́сі хля́бій Твої́х; вся висоти́ Твоя́ і во́лни Твоя́ на мні прейдо́ша.","@9 В день запові́сть Госпо́дь ми́лость Свою́, і но́щію піснь Єго́ от мене́⁽1⁾ — моли́тва Бо́гу живота́ моєго́.","@10 Реку́ Бо́гу: Засту́пник мой єси́, почто́ м'я заби́л єси́? І вску́ю сі́туя хожду́, внегда́ оскорбля́єть враг?","@11 Внегда́ сокруша́тися косте́м мої́м, поноша́ху мі вразі́ мої́, внегда́ глаго́лати їм мні на всяк день: гді єсть Бог Твой?","@12 Вску́ю приско́рбна єси́, душе́ моя́? І вску́ю смуща́єши м'я? Упова́й на Бо́га, я́ко іспові́мся Єму́, спасе́ніє лиця́ моєго́ і Бог мой."]},{"h":"Псалом 42","ps":["§Псало́м Дави́ду, не надпи́сан у євре́й, 42.","@1 Суди́ мі, Бо́же, і разсуди́ прю мою́; от язи́ка не преподо́бна, от челові́ка непра́ведна і льсти́ва ізба́ви м'я.","@2 Зане́ Ти єси́, Бо́же, крі́пость моя́, вску́ю отри́нул м'я єси́? І вску́ю сі́туя хожду́, внегда́ оскорбля́єть враг?","@3 Посли́ світ Твой і і́стину Твою́; та м'я наста́виста, і введо́ста м'я в го́ру святу́ю Твою́ і в селе́нія Твоя́.","@4 І вни́ду к же́ртвеннику Бо́жию, к Бо́гу веселя́щему ю́ность мою́; іспові́мся Тебі́ в гу́слех, Бо́же, Бо́же мой.","@5 Вску́ю приско́рбна єси́, душе́ моя́? І вску́ю смуща́єши м'я? Упова́й на Бо́га, я́ко іспові́мся Єму́, спасе́ніє лиця́ моєго́ і Бог мой.","§Сла́ва:"]},{"h":"Псалом 43","ps":["§В коне́ць, сино́в Коре́йових, в ра́зум, псало́м, 43.","@2 Бо́же, уши́ма на́шима усли́шахом, і отці́ на́ші возвісти́ша нам ді́ло, є́же соді́лал єси́ во днех їх, во днех дре́вніх.","@3 Рука́ Твоя́ язи́ки потреби́, і насади́л я єси́; озло́бил єси́ лю́ди і ізгна́л єси́ я.","@4 Не бо мече́м свої́м наслі́диша зе́млю, і ми́шця їх не спасе́ їх, но десни́ця Твоя́ і ми́шця Твоя́ і просвіще́ніє лиця́ Твоєго́, я́ко благоволи́л єси́ в них.","@5 Ти єси́ Сам Цар мой і Бог мой, запові́даяй спасе́нія Іа́ковля.","@6 О Тебі́ враги́ на́ша ізбоде́м ро́ги, і о і́мені Твоє́м уничижи́м востаю́щия на ни.","@7 Не на лук бо мой упова́ю, і меч мой не спасе́ть мене́;","@8 спасл бо єси́ нас от стужа́ющих нам, і ненави́дящих нас посрами́л єси́.","@9 О Бо́зі похва́лимся весь день, і о і́мені Твоє́м іспові́мися во вік.","@10 Ни́ні же отри́нул єси́ і посрами́л єси́ нас, і не ізи́деши, Бо́же, в си́лах на́ших.","@11 Возврати́л єси́ нас всп'ять при вразі́х на́ших, і ненави́дящії нас расхища́ху себі́.","@12 Дал єси́ нас, я́ко о́вці, сні́ди і во язи́ціх разсі́ял ни єси́.","@13 Отда́л єси́ лю́ди Твоя́ без ціни́, і не бі мно́жество в восклица́ніїх на́ших.","@14 Положи́л єси́ нас поноше́ніє сосі́дом на́шим, подражне́ніє і поруга́ніє су́щим о́крест нас.","@15 Положи́л єси́ нас в при́тчу во язи́ціх, покива́нію глави́ в лю́дех.","@16 Весь день срам мой пре́до мно́ю єсть, і студ лиця́ моєго́ покри́ м'я,","@17 от гла́са поноша́ющаго і оклевета́ющаго, от лиця́ вра́жия і ізгоня́щаго.","@18 Сія́ вся прийдо́ша на ни, і не заби́хом Тебе́, і не непра́вдовахом в заві́ті Твоє́м,","@19 і не отступи́ всп'ять се́рдце на́ше; і уклони́л єси́ стезі́ на́ша от путі́ Твоєго́,","@20 я́ко смири́л єси́ нас на мі́сті озлобле́нія, і прикри́ ни сінь сме́ртная.","@21 А́ще заби́хом і́м'я Бо́га на́шего, і а́ще возді́хом руки́ на́ша к бо́гу чужде́му,","@22 не Бог ли взи́щеть сих? Той бо вість та́йная се́рдця.","@23 Зане́ Тебе́ ра́ди умерщвля́ємся весь день, вміни́хомся, я́ко о́вці заколе́нія.","@24 Воста́ни, вску́ю спи́ши, Го́споди? воскресни́, і не отри́ни до конця́.","@25 Вску́ю лице́ Твоє́ отвраща́єши? Забива́єши нищету́ на́шу і скорб на́шу?","@26 Я́ко смири́ся в персть душа́ на́ша, прильпе́ землі́ утро́ба на́ша.","@27 Воскресни́, Го́споди, помози́ нам і ізба́ви нас і́мене ради Твоєго́."]},{"h":"Псалом 44","ps":["§В коне́ць, о ізміня́ємих сино́м коре́йовим в ра́зум, піснь о возлю́бленнім, 44.","@2 Отри́гну се́рдце моє́ сло́во бла́го, глаго́лю аз діла́ моя́ Царе́ві; язи́к мой — трость кни́жника скоропи́сця.","@3 Красе́н добро́тою па́че сино́в челові́чеських, ізлія́ся благода́ть во устна́х Твої́х; сего́ ра́ди благослови́ Тя Бог во вік.","@4 Препоя́ши меч Твой по бедрі́ Твоє́й, Си́льне,","@5 красото́ю Твоє́ю і добро́тою Твоє́ю; і наляци́, і успіва́й, і ца́рствуй і́стини ра́ди і кро́тости і пра́вди; і наста́вить Тя ди́вно десни́ця Твоя́.","@6 Стрі́ли Твоя́ ізощре́ни, Си́льне; лю́діє под Тобо́ю паду́ть в се́рдці враг Царе́вих.","@7 Престо́л Твой, Бо́же, в вік ві́ка; жезл пра́вости — жезл Ца́рствія Твоєго́.","@8 Возлюби́л єси́ пра́вду і возненави́діл єси́ беззако́ніє; сего́ ра́ди пома́за Тя, Бо́же, Бог Твой єле́єм ра́дости па́че прича́стник Твої́х.","@9 Сми́рна, і ста́кти, і касі́я от риз Твої́х, от тя́жестей слоно́вих⁽2⁾, із ни́хже возвесели́ша Тя.","@10 Дще́рі царе́й в че́сті Твоє́й; предста́ цари́ця одесну́ю Тебе́, в ри́зах позлаще́нних оді́яна преіспещре́на.","@11 Сли́ши, дщи, і виждь, і приклони́ у́хо твоє́, і забу́ди лю́ди твоя́ і дом отця́ твоєго́;","@12 і возжела́єть Цар добро́ти твоєя́, зане́ Той єсть Госпо́дь твой, і поклони́шися Єму́,","@13 і дщи Ти́рова с да́ри; лицю́ Твоєму́ помо́ляться бога́тії лю́дстії.","@14 Вся сла́ва дще́ре Царе́ві внутр; ря́сни злати́ми оді́яна і преіспещре́на.","@15 Приведу́ться Царю́ ді́ви вслід єя́, і́скреннія єя́ приведу́ться Тебі́;","@16 приведу́ться в весе́лії і ра́дованії, введу́ться в храм Царе́в.","@17 Вмі́сто оте́ць Твої́х би́ша си́нове Твої́; поста́виши я кня́зі по всей землі́.","@18 Пом'яну́ і́м'я Твоє́ во вся́ком ро́ді і ро́ді; сего́ ра́ди лю́діє іспові́дяться Тебі́ в вік і во вік ві́ка."]},{"h":"Псалом 45","ps":["§В коне́ць, о сині́х Коре́йових, о та́йних, псало́м, 45.","@2 Бог нам прибі́жище і си́ла, помо́щник в ско́рбіх обрі́тших ни зіло́.","@3 Сего́ ра́ди не убої́мся, внегда́ смуща́ється земля́, і прелага́ються го́ри в сердця́ морська́я.","@4 Возшумі́ша і см'ято́шася во́ди їх, см'ято́шася го́ри крі́постію Єго́.","@5 Рі́чная устремле́нія веселя́ть град Бо́жий; освяти́л єсть селе́ніє Своє́ Ви́шній.","@6 Бог посреді́ єго́, і не подви́житься; помо́жеть єму́ Бог у́тро зау́тра.","@7 См'ято́шася язи́ци, уклони́шася ца́рствія; даде́ глас Свой Ви́шній, подви́жеся земля́.","@8 Госпо́дь сил с на́ми, засту́пник наш Бог Іа́ковль.","@9 Прийді́те і ви́діте діла́ Бо́жія, я́же положи́ чудеса́ на землі́;","@10 оте́мля бра́ні до коне́ць землі́, лук сокруши́ть і сло́мить ору́жіє, і щити́ сожже́ть огне́м.","@11 Упраздні́теся і разумі́йте, я́ко Аз єсьм Бог; вознесу́ся во язи́ціх, вознесу́ся на землі́.","@12 Госпо́дь сил с на́ми, засту́пник наш Бог Іа́ковль.","§Сла́ва:"]},{"h":"Після 6-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 3:","ps":["Хвалу́ приношу́ Ті, Го́споди, прегріше́нія моя́ вся возвіща́ю Ті, Бо́же, обрати́в поми́луй м'я.","Сла́ва: Спаси́ м'я, Бо́же мой, я́коже іногда́ митаря́ спасл єси́; і блудни́ці слез не презрі́вий, і моє́ воздиха́ніє прийми́, Спа́се мой, і спаси́ м'я.","І ни́ні: Ра́бськи ни́ні притека́ю к покро́ву Твоєму́, Пренепоро́чная, ізба́ви м'я, Богороди́тельнице, слія́нія страсте́й, я́ко безстра́стія Вино́внаго Ро́ждшая."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Благодари́м Тя, Го́споди Бо́же наш, о всіх благодія́ніїх Твої́х, я́же от пе́рваго во́зраста до настоя́щаго в нас, недосто́йних, би́вших, о ї́хже ві́ми і не ві́ми, о явле́нних і неявле́нних, я́же ді́лом би́вших і сло́вом; возлюби́вий нас, я́коже і Єдиноро́днаго Твоєго́ Си́на о нас да́ти ізво́ливий, сподо́би і нас досто́йни би́ти Твоєя́ любве́. Даждь сло́вом Твої́м му́дрость, і стра́хом Твої́м вдохни́ крі́пость от Твоєя́ си́ли, і а́ще что хотя́ще, іли́ не хотя́ще согріши́хом, прости́ і не вміни́; і сохрани́ ду́шу на́шу святу, і предста́ви ю Твоєму́ престо́лу со́вість іму́щу чи́сту, і коне́ць досто́їн человіколю́бія Твоєго́. І пом'яни́, Го́споди, всіх призива́ющих і́м'я Твоє́ во і́стині, пом'яни́ всіх бла́га іли́ сопроти́вная нам хотя́щих, всі бо челові́ци єсьми́, і всу́є всяк челові́к. Ті́мже мо́лимся Тебі́, Го́споди: пода́ждь нам Твоєго́ благоутро́бія ве́лію ми́лость."]}],"notes":["<span class=''>[у мене́]</span>","<span class=''>[от хра́мов слоно́вих]</span>"]},{"u":"Кафизма 7","e":"Kathisma 7","secs":[{"h":"Псалом 46","ps":["§В коне́ць, о сині́х Коре́йових, псало́м, 46.","@2 Всі язи́ци, восплещі́те рука́ми, воскли́кніте Бо́гу гла́сом ра́дованія;","@3 я́ко Госпо́дь Ви́шній стра́шен, Цар ве́лій по всей землі́;","@4 покори́ лю́ди нам і язи́ки под но́ги на́ша;","@5 ізбра́ нам достоя́нія своє́, добро́ту Іа́ковлю, ю́же возлюби́.","@6 Взи́де Бог в воскликнове́нії, Госпо́дь во гла́сі тру́бні.","@7 По́йте Бо́гу на́шему, по́йте; по́йте Царе́ві на́шему, по́йте;","@8 я́ко Цар всея́ землі́ Бог, по́йте разу́мно.","@9 Воцари́ся Бог над язи́ки; Бог сіди́ть на Престо́лі святі́м Своє́м.","@10 Кня́зі лю́дстії собра́шася с Бо́гом Авраа́млим; я́ко Бо́жії держа́внії землі́ зіло́ вознесо́шася."]},{"h":"Псалом 47","ps":["§Псало́м пі́сні сино́в Коре́йових, втори́я субо́ти, 47.","@2 Ве́лій Госпо́дь і хва́лен зіло́ во гра́ді Бо́га на́шего, в горі́ святі́й Єго́,","@3 благокоре́нним ра́дованієм всея́ землі́; го́ри Сіо́нськия, ре́бра сі́верова, град Царя́ вели́каго.","@4 Бог в тя́жестіх⁽1⁾ Єго́ зна́єм єсть, єгда́ заступа́єть ї.","@5 Я́ко се, ца́ріє зе́мстії собра́шася, снидо́шася вку́пі;","@6 ті́ї ви́дівше та́ко, удиви́шася, см'ято́шася, подвиго́шася;","@7 тре́пет прия́т я та́мо, болі́зні я́ко ражда́ющия.","@8 Ду́хом бу́рним сокруши́ши кораблі́ Фарси́йськія.","@9 Я́коже сли́шахом, та́ко і ви́діхом во гра́ді Го́спода Сил, во гра́ді Бо́га на́шего; Бог основа́ і в вік.","@10 Прия́хом, Бо́же, ми́лость Твою́ посреді́ люді́й Твої́х.","@11 По і́мені Твоєму́, Бо́же, та́ко і хвала́ Твоя́ на конця́х землі́; пра́вди іспо́лнь десни́ця Твоя́.","@12 Да возвесели́ться гора́ Сіо́нськая, і да возра́дуються дще́рі Іуде́йськія, суде́б ра́ди Твої́х, Го́споди.","@13 Обиді́те Сіо́н і обимі́те єго́, пові́діте в столпі́х єго́;","@14 положі́те сердця́ ва́ша в си́лу єго́, і разділі́те до́ми єго́, я́ко да пові́сте в ро́ді іні́м.","@15 Я́ко Той єсть Бог наш во вік і в вік ві́ка; Той упасе́ть нас во ві́ки."]},{"h":"Псалом 48","ps":["§В коне́ць, сино́м Коре́йовим, псало́м, 48.","@2 Усли́шіте сія́, всі язи́ци, внуші́те, всі живу́щії по вселе́нній,","@3 земноро́днії же і си́нове челові́честії, вку́пі бога́т і убо́г.","@4 Уста́ моя́ возглаго́лють прему́дрость, і поуче́ніє се́рдця моєго́ — ра́зум.","@5 Приклоню́ в при́тчу у́хо моє́, отве́рзу во псалти́рі гана́ніє моє́.","@6 Вску́ю бою́ся в день лют? Беззако́ніє п'яти́ моєя́ оби́деть м'я.","@7 Наді́ющіїся на си́лу свою́ і о мно́жестві бога́тства своєго́ хва́лящіїся;","@8 брат не ізба́вить, ізба́вить ли челові́к? Не дасть Бо́гу ізмі́ни за ся,","@9 і ці́ну ізбавле́нія душі́ своєя́; і утруди́ся в вік,","@10 і жив бу́деть до конця́, не у́зрить па́губи.","@11 Єгда́ уви́дить прему́дрия умира́ющия, вку́пі безу́мен і несми́слен поги́бнуть, і оста́в'ять чужди́м бога́тство своє́.","@12 І гро́би їх жили́ща їх во вік, селе́нія їх в род і род, нареко́ша імена́ своя́ на земля́х.","@13 І челові́к в че́сті сий не ра́зумі, приложи́ся ското́м несми́сленним і уподо́бися їм.","@14 Сей путь їх собла́зн їм, і по сих во усті́х свої́х благоволя́ть.","@15 Я́ко о́вці во а́ді положе́ни суть, смерть упасе́ть я; і облада́ють ї́ми пра́вії зау́тра, і по́мощ їх обетша́єть во а́ді; от сла́ви своєя́ ізринове́ні би́ша.","@16 Оба́че Бог ізба́вить ду́шу мою́ із руки́ а́дови, єгда́ приє́млеть м'я.","@17 Не убо́йся, єгда́ разбогаті́єть челові́к, іли́ єгда́ умно́житься сла́ва до́му єго́;","@18 я́ко внегда́ умре́ти єму́, не во́зьметь вся, ніже́ сни́деть с ним сла́ва єго́.","@19 Я́ко душа́ єго́ в животі́ єго́ благослови́ться, іспові́сться Тебі́, єгда́ благосотвори́ши єму́.","@20 Вни́деть да́же до ро́да оте́ць свої́х, да́же до ві́ка не у́зрить сві́та.","@21 І челові́к в че́сті сий не ра́зумі, приложи́ся ското́м несми́сленним і уподо́бися їм.","§Сла́ва:"]},{"h":"Псалом 49","ps":["§Псало́м Аса́фу, 49.","@1 Бог бого́в Госпо́дь глаго́ла, і призва́ зе́млю от восто́к со́лнця до за́пад.","@2 От Сіо́на благолі́піє красоти́ Єго́;","@3 Бог я́ві при́йдеть, Бог наш, і не премолчи́ть; огнь пред Ним возгори́ться, і о́крест Єго́ бу́ря зі́льна.","@4 Призове́ть не́бо сви́ше, і зе́млю, разсуди́ти лю́ди Своя́.","@5 Собері́те Єму́ преподо́бния Єго́, завіща́ющия заві́т Єго́ о же́ртвах.","@6 І возвістя́ть небеса́ пра́вду Єго́; я́ко Бог Судія́ єсть.","@7 Усли́шіте, лю́діє Мої́, і возглаго́лю вам, Ізра́їлю, і засвиді́тельствую тебі́: Бог, Бог Твой єсьм Аз.","@8 Не о же́ртвах твої́х обличу́ тя, всесожже́нія же твоя́ пре́до Мно́ю суть ви́ну;","@9 не прийму́ от до́му твоєго́ тельце́в, ніже́ от стад твої́х козло́в.","@10 Я́ко мої́ суть всі зві́ріє дубра́внії, ско́ти в гора́х і воло́ве;","@11 позна́х вся пти́ці небе́сния, і красота́ се́льная со Мно́ю єсть.","@12 А́ще вза́лчу, не реку́ тебі́; Моя́ бо єсть вселе́нная і ісполне́ніє єя́.","@13 Єда́ ям м'яса́ ю́нча? Іли́ кров козло́в пію́?","@14 Пожри́ Бо́гові же́ртву хвали́ і возда́ждь Ви́шнему моли́тви твоя́;","@15 і призови́ М'я в день ско́рби твоєя́, і ізму́ тя, і просла́виши М'я.","@16 Грі́шнику же рече́ Бог: вску́ю ти пові́даєши оправда́нія Моя́ і восприє́млеши заві́т Мой усти́ твої́ми?","@17 Ти же возненави́діл єси́ наказа́ніє і отве́ргл єси́ словеса́ Моя́ всп'ять.","@18 А́ще ви́діл єси́ та́тя, текл єси́ с ним і с прелюбоді́єм уча́стіє твоє́ полага́л єси́;","@19 уста́ твоя́ умно́жиша зло́бу, і язи́к твой сплета́ше льще́нія;","@20 сідя́ на бра́та твоєго́ клевета́л єси́ і на си́на ма́тере твоєя́ полага́л єси́ собла́зн.","@21 Сія́ сотвори́л єси́ і умолча́х, вознепщева́л єси́ беззако́ніє, я́ко бу́ду тебі́ подо́бен; обличу́ тя і предста́влю пред лице́м твої́м гріхи́ твоя́.","@22 Разумі́йте у́бо сія́, забива́ющії Бо́га, да не когда́ похи́тить, і не бу́деть ізбавля́яй.","@23 Же́ртва хвали́ просла́вить М'я, і та́мо путь, і́мже явлю́ єму́ спасе́ніє Моє́."]},{"h":"Псалом 50","ps":["§В коне́ць, псало́м Дави́ду, внегда́ вни́ти к нему́ Нафа́ну проро́ку,","@2 єгда́ вни́де к Вирсаві́ї, жені́ Урі́єві, 50.","@3 Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́.","@4 Найпа́че оми́й м'я от беззако́нія моєго́ і от гріха́ моєго́ очи́сти м'я;","@5 я́ко беззако́ніє моє́ аз зна́ю, і гріх мой пре́до мно́ю єсть ви́ну.","@6 Тебі́ єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х; я́ко да оправди́шися во словесі́х Твої́х і побіди́ши, внегда́ суди́ти Ті.","@7 Се бо, в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́.","@8 Се бо, і́стину возлюби́л єси́, безві́стная і та́йная прему́дрости Твоєя́ яви́л мі єси́.","@9 Окропи́ши м'я іссо́пом, і очи́щуся; оми́єши м'я, і па́че сні́га убілю́ся.","@10 Слу́ху моєму́ да́си ра́дость і весе́ліє; возра́дуються ко́сті смире́нния.","@11 Отврати́ лице́ Твоє́ от гріх мої́х і вся беззако́нія моя́ очи́сти.","@12 Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й.","@13 Не отве́ржи мене́ от лиця́ Твоєго́ і Ду́ха Твоєго́ Свята́го не отими́ от мене́.","@14 Возда́ждь мі ра́дость спасе́нія Твоєго́ і ду́хом влади́чним утверди́ м'я.","@15 Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться.","@16 Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́; возра́дується язи́к мой пра́вді Твоє́й.","@17 Го́споди, устні́ мої́ отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́.","@18 Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо: всесожже́нія не благоволи́ши.","@19 Же́ртва Бо́гу — дух сокруше́н; се́рдце сокруше́нно і смире́нно Бог не унічижи́ть.","@20 Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія;","@21 тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая; тогда́ возложа́ть на олта́р Твой тельці́.","§Сла́ва:"]},{"h":"Псалом 51","ps":["§В коне́ць, ра́зума Дави́ду,","@2 внегда́ прийти́ Дої́ку Ідуме́йську, і возвісти́ти Сау́лу, і рещи́ єму́: при́йде Дави́д в дом Авімеле́хов, 51.","@3 Что хва́лишися во зло́бі, си́льне? Беззако́ніє весь день,","@4 непра́вду уми́сли язи́к твой; я́ко бри́тву ізощре́ну сотвори́л єси́ лесть.","@5 Возлюби́л єси́ зло́бу па́че благости́ні, непра́вду, не́же глаго́лати пра́вду;","@6 возлюби́л єси́ вся глаго́ли пото́пния, язи́к льстив.","@7 Сего́ ра́ди Бог разруши́ть тя до конця́; восто́ргнеть тя, і пресели́ть тя от селе́нія твоєго́ і ко́рень твой от землі́ живи́х.","@8 У́зрять пра́веднії і убоя́ться, і о нем возсмію́ться і реку́ть:","@9 се, челові́к, і́же не положи́ Бо́га помо́щника себі́, но упова́ на мно́жество бога́тства своєго́, і возмо́же суєто́ю своє́ю.","@10 Аз же, я́ко ма́слина плодови́та в дому́ Бо́жиї; упова́х на ми́лость Бо́жию во вік і в вік ві́ка.","@11 Іспові́мся Тебі́ в вік, я́ко сотвори́л єси́; і терплю́ і́м'я Твоє́, я́ко бла́го пред преподо́бними Твої́ми."]},{"h":"Псалом 52","ps":["§В коне́ць, о Маєле́фі, ра́зума Дави́ду, 52.","@2 Рече́ безу́мен в се́рдці своє́м: ність Бог. Растлі́ша і омерзи́шася в беззако́ніїх, ність творя́й благо́є.","@3 Бог с небесе́ прини́че на си́ни челові́чеськія, ви́діти, а́ще єсть разуміва́яй іли́ взиска́яй Бо́га.","@4 Всі уклони́шася, вку́пі непотре́бні би́ша; ність творя́й благо́є, ність до єди́наго.","@5 Ні ли разумі́ють всі ді́лающії беззако́ніє, сніда́ющії лю́ди моя́ в снідь хлі́ба? Го́спода не призва́ша.","@6 Та́мо устраши́шася стра́ха, іді́же не бі страх; я́ко Бог разси́па ко́сті человікоуго́дников; постиді́шася, я́ко Бог уничижи́ їх.","@7 Кто дасть от Сіо́на спасе́ніє Ізра́їлево? Внегда́ возврати́ть Бог пліне́ніє люді́й Свої́х, возра́дується Іа́ков і возвесели́ться Ізра́їль."]},{"h":"Псалом 53","ps":["§В коне́ць, в пі́снех ра́зума Дави́ду,","@2 внегда́ прийти́ Зіфе́єм і рещи́ Сау́лові: не се ли Дави́д скри́ся в нас? 53.","@3 Бо́же, во і́м'я Твоє́ спаси́ м'я і в си́лі Твоє́й суди́ мі.","@4 Бо́же, усли́ши моли́тву мою́, внуши́ глаго́ли уст мої́х;","@5 я́ко чу́ждії воста́ша на м'я, і крі́пції взиска́ша ду́шу мою́, і не предложи́ша Бо́га пред собо́ю.","@6 Се бо, Бог помога́єть мі, і Госпо́дь засту́пник душі́ моє́й;","@7 отврати́ть зла́я враго́м мої́м; і́стиною Твоє́ю потреби́ їх.","@8 Во́лею пожру́ Тебі́, іспові́мся і́мені Твоєму́, Го́споди, я́ко бла́го;","@9 я́ко от вся́кия печа́лі ізба́вил м'я єси́, і на враги́ моя́ воззрі́ о́ко моє́."]},{"h":"Псалом 54","ps":["§В коне́ць, в пі́снех ра́зума, Аса́фу, псало́м, 54.","@2 Внуши́, Бо́же, моли́тву мою́ і не пре́зри моле́нія моєго́;","@3 воньми́ мі і усли́ши м'я; возскорбі́х печа́лію моє́ю⁽2⁾, і см'ято́хся","@4 от гла́са вра́жия і от стуже́нія грі́шнича; я́ко уклони́ша на м'я беззако́ніє і во гні́ві враждова́ху мі.","@5 Се́рдце моє́ см'яте́ся во мні, і боя́знь сме́рти нападе́ на м'я;","@6 страх і тре́пет при́йде на м'я, і покри́ м'я тьма.","І ріх: кто дасть мі крилі́ я́ко голуби́ні? І полещу́, і почи́ю.","@8 Се, удали́хся бі́гая і водвори́хся в пусти́ні.","@9 Ча́ях Бо́га спаса́ющаго м'я от малоду́шія і от бу́рі.","@10 Потопи́, Го́споди, і разділи́ язи́ки їх; я́ко ви́діх беззако́ніє і преріка́ніє во гра́ді.","@11 Днем і но́щію оби́деть ї по стіна́м єго́; беззако́ніє і труд посреді́ єго́, і непра́вда;","@12 і не оскуді́ от стогн єго́ ли́хва і лесть.","@13 Я́ко а́ще би враг поноси́л мі, претерпі́л бих у́бо; і а́ще би ненави́дяй м'я на м'я велері́чевал, укри́лбихся от него́.","@14 Ти же, челові́че равноду́шне, влади́ко мой і зна́ємий мой,","@15 і́же ку́пно наслажда́лся єси́ со мно́ю бра́шен; в дому́ Бо́жиї ходи́хом єдиномишле́нієм.","@16 Да при́йдеть же смерть на ня, і да сни́дуть во ад жи́ві; я́ко лука́вство в жили́щих їх, посреді́ їх.","@17 Аз к Бо́гу воззва́х, і Госпо́дь усли́ша м'я.","@18 Ве́чер, і зау́тра, і полу́дне пові́м і возвіщу́, і усли́шить глас мой.","@19 Ізба́вить ми́ром ду́шу мою́ от приближа́ющихся мні; я́ко во мно́зі бя́ху со мно́ю.","@20 Усли́шить Бог, і смири́ть я Сий пре́жде вік; ність бо їм ізміне́нія, я́ко не убоя́шася Бо́га.","@21 Простре́ ру́ку свою́ на воздая́ніє; оскверни́ша заві́т Єго́.","@22 Разділи́шася от гні́ва лиця́ Єго́, і прибли́жишася сердця́ їх; ум'я́кнуша словеса́ їх па́че єле́я, і та суть стрі́ли.","@23 Возве́рзи на Го́спода печа́ль твою́, і Той тя препита́єть; не дасть в вік молви́ пра́веднику.","@24 Ти же, Бо́же, низведе́ши їх в студене́ць істлі́нія; му́жіє крове́й і льсти не преполов'я́ть дній свої́х. Аз же, Го́споди, упова́ю на Тя.","§Сла́ва:"]},{"h":"Після 7-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 5:","ps":["Судії́ сідя́щу і а́нгелом стоя́щим, трубі́ глася́щей, пла́мені горя́щу, что сотвори́ши, душе́ моя́, ведо́ма на суд? Тогда́ бо лю́тая твоя́ предста́нуть, і та́йная облича́ться согріше́нія. Ті́мже пре́жде конця́ возопи́й Судії́: Бо́же, очи́сти м'я і спаси́ м'я.","Сла́ва: Всі побди́м і Христа́ усря́щим со мно́жеством єле́я і свіща́ми сві́тлими, я́ко да черто́га внутр сподо́бимся. І́же бо вні двере́й пости́гнувий, безді́льно Бо́гові воззове́ть: поми́луй м'я.","І ни́ні: На одрі́ лежа́ согріше́ній мно́гих, окрада́єм єсьм в наде́жді спасе́нія моєго́; і́бо сон моєя́ лі́ности хода́тайствуєть душі́ моє́й му́ку. Но Ти, Бо́же, рожде́йся от Ді́ви, воздви́гни м'я к Твоєму́ пі́нію, да сла́влю Тя."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Бо́же мой, я́ко Благ і Человіколю́бець, мно́гія ми́лості сотвори́л єси́ со мно́ю, я́же не ча́ях ви́діти, і что возда́м Твоє́й бла́гості, Го́споди мой Го́споди? Благодарю́ Твоє́ многопі́тоє і́м'я; благодарю́ Твоє́ неісповіди́моє на мні благоутро́біє; благодарю́ безприкла́дноє Твоє́ долготерпі́ніє. І от ни́ні заступи́, і помози́ мні, і покри́й м'я, Влади́ко, от всіх, є́же не ктому́ согріша́ти пред Тобо́ю; Ти бо ві́си єстества́ моєго́ удобопоползнове́нноє, Ти ві́си безу́міє моє́, Ти ві́си мно́ю соді́янная, я́же в ві́дінії і не в ві́дінії, я́же во́льная і нево́льная, я́же в нощі́ і во дні, і во умі́ і ми́слі; я́ко Благ у́бо і Человіколю́бець Бог, очи́сти я росо́ю ми́лости Твоєя́, Преблаги́й Го́споди, і спаси́ нас і́мене ра́ди Твоєго́ Свята́го, ї́миже ві́си судьба́ми. Ти бо єси́ Світ, і І́стина, і Живо́т, і Тебі́ сла́ву возсила́єм, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[во хра́міх]</span>","<span class=''>[во іскуше́нії моє́м]</span>"]},{"u":"Кафизма 8","e":"Kathisma 8","secs":[{"h":"Псалом 55","ps":["§В коне́ць, о лю́дех от святи́х удале́нних, Дави́ду в столпописа́ніє, внегда́ удержа́ша ї іноплеме́нници в Ге́фі, псало́м, 55.","@2 Поми́луй м'я, Бо́же, я́ко попра́ м'я челові́к; весь день боря́ стужи́ мі.","@3 Попра́ша м'я вразі́ мої́ весь день; я́ко мно́зі борю́щії м'я с висоти́.","@4 В день не⁽1⁾ в ні́кіїх не імі́ється] убою́ся, аз же упова́ю на Тя.","@5 О Бо́зі похвалю́ словеса́ моя́; на Бо́га упова́х, не убою́ся; что сотвори́ть мні плоть?","@6 Весь день слове́с мої́х гнуша́хуся; на м'я вся помишле́нія їх на зло.","@7 Вселя́ться і скри́ють, ті́ї п'я́ту мою́ сохраня́ть, я́коже потерпі́ша ду́шу мою́⁽2⁾.","@8 Ні о чесо́мже отри́неши я, гні́вом лю́ди низведе́ши.","@9 Бо́же, живо́т мой возвісти́х Тебі́; положи́л єси́ сле́зи моя́ пред Тобо́ю, я́ко і во обітова́нії Твоє́м.","@10 Да возвратя́ться вразі́ мої́ всп'ять, в о́ньже а́ще день призову́ Тя; се позна́х, я́ко Бог мой єси́ Ти.","@11 О Бо́зі похвалю́ глаго́л, о Го́споді похвалю́ сло́во.","@12 На Бо́га упова́х, не убою́ся; что сотвори́ть мні челові́к?","@13 Во мні, Бо́же, моли́тви, я́же возда́м хвали́ Твоєя́;","@14 я́ко ізба́вил єси́ ду́шу мою́ от сме́рти, о́чі мої́ от слез і но́зі мої́ от поползнове́нія; благоугожду́ пред Го́сподем во сві́ті живи́х."]},{"h":"Псалом 56","ps":["§В коне́ць, да не растли́ши, Дави́ду в столпописа́ніє, внегда́ єму́ отбіга́ти от лиця́ Сау́лова в пеще́ру, 56.","@2 Поми́луй м'я, Бо́же, поми́луй м'я; я́ко на Тя упова́ душа́ моя́, і на сінь крилу́ Твоє́ю наді́юся, до́ндеже пре́йдеть беззако́ніє.","@3 Воззову́ к Бо́гу Ви́шнему, Бо́гу благоді́явшему мні.","@4 Посла́ с небесе́ і спасе́ м'я, даде́ в поноше́ніє попира́ющия м'я; посла́ Бог ми́лость Свою́ і і́стину Свою́,","@5 і ізба́ви ду́шу мою́ от среди́ ски́мнов. Поспа́х смуще́н; си́нове челові́честії, зу́би їх ору́жія і стрі́ли, і язи́к їх меч остр.","@6 Вознеси́ся на небеса́, Бо́же, і по всей землі́ сла́ва Твоя́.","@7 Сіть угото́ваша нога́м мої́м, і сляко́ша ду́шу мою́; іскопа́ша пред лице́м мої́м я́му, і впадо́ша в ню.","@8 Гото́во се́рдце моє́, Бо́же, гото́во се́рдце моє́; воспою́ і пою́ во сла́ві моє́й.","@9 Воста́ни, сла́ва моя́, воста́ни, псалти́рю і гу́слі; воста́ну ра́но.","@10 Іспові́мся Тебі́ в лю́дех, Го́споди, воспою́ Тебі́ во язи́ціх;","@11 я́ко возвели́чися до небе́с ми́лость Твоя́ і да́же до о́блак і́стина Твоя́.","@12 Вознеси́ся на небеса́, Бо́же, і по всей землі́ сла́ва Твоя́."]},{"h":"Псалом 57","ps":["§В коне́ць, да не растли́ши, Дави́ду в столпописа́ніє, 57.","@2 А́ще воі́стину у́бо пра́вду глаго́лете, пра́вая суді́те, си́нове челові́честії.","І́бо в се́рдці беззако́ніє ді́лаєте на землі́, непра́вду ру́ки ва́ша сплета́ють.","@4 Очужди́шася грі́шници от ложе́сн, заблуди́ша от чре́ва, глаго́лаша лжу.","@5 Я́рость їх по подо́бію зміїну́, я́ко а́спида глу́ха і затика́ющаго у́ші свої́,","@6 і́же не усли́шить гла́са обава́ющих⁽3⁾, обава́єм обава́ється от прему́дра.","@7 Бог сокруши́ть зу́би їх во усті́х їх; члено́вния⁽4⁾ львов сокруши́л єсть Госпо́дь.","@8 Унічижа́ться, я́ко вода́ мимотеку́щая; напряже́ть лук свой, до́ндеже ізнемо́гуть.","@9 Я́ко воск раста́яв оти́муться; паде́ огнь на них, і не ви́діша со́лнця.","@10 Пре́жде є́же разумі́ти те́рнія ва́шего ра́мна, я́ко жи́ви, я́ко во гні́ві пожре́ть я.","@11 Возвесели́ться пра́ведник, єгда́ уви́дить отмще́ніє; ру́ці свої́ уми́єть в кро́ві грі́шника.","@12 І рече́ть челові́к: а́ще у́бо єсть плод пра́веднику, у́бо єсть Бог судя́ їм на землі́.","§Сла́ва:"]},{"h":"Псалом 58","ps":["§В коне́ць, да не растли́ши, Дави́ду в столпописа́ніє, внегда́ посла́ Сау́л і стреже́ дом єго́, є́же умертви́ти єго́, 58.","@2 Ізми́ м'я от враг мої́х, Бо́же, і от возстаю́щих на м'я ізба́ви м'я;","@3 ізба́ви м'я от ді́лающих беззако́ніє, і от муж крове́й спаси́ м'я.","@4 Я́ко се, улови́ша ду́шу мою́, нападо́ша на м'я крі́пції; ніже́ беззако́ніє моє́, ніже́ гріх мой, Го́споди;","@5 без беззако́нія теко́х і іспра́вих; воста́ни в срі́теніє моє́ і виждь.","@6 І Ти, Го́споди Бо́же Сил, Бо́же Ізра́їлев, воньми́ посіти́ти вся язи́ки; да не уще́дриши вся ді́лающия беззако́ніє.","@7 Возвратя́ться на ве́чер, і вза́лчуть, я́ко пес, і оби́дуть град.","@8 Се, ті́ї отвіща́ють усти́ свої́ми, і меч во устна́х їх: я́ко кто сли́ша?","@9 І Ти, Го́споди, посміє́шися їм, уничижи́ши вся язи́ки.","@10 Держа́ву мою́ к Тебі́ сохраню́; я́ко Ти, Бо́же, Засту́пник мой єси́.","@11 Бог мой, ми́лость Єго́ предвари́ть м'я; Бог мой, яви́ть мні на вразі́х мої́х.","@12 Не убі́й їх, да не когда́ забу́дут зако́н Твой; расточи́ я си́лою Твоє́ю і низведи́ я, Защи́тниче мой, Го́споди,","@13 гріх уст їх, сло́во усте́н їх; і я́ти да бу́дуть в горди́ни своє́й, і от кля́тви і лжі возвістя́ться в кончи́ні,","@14 во гні́ві кончи́ни, і не бу́дуть; і уві́дять, я́ко Бог влади́чествуєть Іа́ковом і конці́ землі́.","@15 Возвратя́ться на ве́чер, і вза́лчуть, я́ко пес, і оби́дуть град;","@16 ті́ї рази́дуться я́сти; а́ще ли же не наси́тяться, і поро́пщуть.","@17 Аз же воспою́ си́лу Твою́ і возра́дуюся зау́тра о ми́лості Твоє́й; я́ко бил єси́ засту́пник мой і прибі́жище моє́ в день ско́рби моєя́.","@18 Помо́щник мой єси́, Тебі́ пою́; я́ко Бог Засту́пник мой єси́, Бо́же мой, ми́лость моя́."]},{"h":"Псалом 59","ps":["§В коне́ць, о ізміни́тися хотя́щих, в столпописа́ніє Дави́ду, в науче́ніє;","@2 внегда́ сожже́ Средорі́чіє Сирі́йськоє і Cирі́ю Cова́лськую, і возврати́ся Іоа́в і порази́ Едо́ма в де́брі соле́й двана́десять ти́сящ, 59.","@3 Бо́же, отри́нул ни єси́ і низложи́л єси́ нас, разгні́вался єси́ і уще́дрил єси́ нас.","@4 Стрясл єси́ зе́млю і смути́л єси́ ю; ізціли́ сокруше́ніє єя́, я́ко подви́жеся.","@5 Показа́л єси́ лю́дем Твої́м жесто́кая; напої́л єси́ нас вино́м умиле́нія.","@6 Дал єси́ боя́щимся Тебе́ зна́меніє, є́же убіжа́ти от лиця́ лу́ка.","@7 Я́ко да ізба́в'яться возлю́бленнії Твої́, спаси́ десни́цею Твоє́ю і усли́ши м'я.","@8 Бог возглаго́ла во святі́м Своє́м: возра́дуюся, і разділю́ Сики́му, і юдо́ль жили́щ размі́рю.","@9 Мой єсть Галаа́д, і Мой єсть Манассі́й, Єфре́м — крі́пость глави́ Моєя́, Іу́да — цар Мой.","@10 Моа́в — коно́б упова́нія Моєго́; на Ідуме́ю простру́ сапо́г Мой; Мні іноплеме́нници покори́шася.","@11 Кто введе́ть м'я во град огражде́нія? Іли́ кто наста́вить м'я до Ідуме́ї?","@12 Не Ти ли, Бо́же, отри́нувий нас? І не ізи́деши, Бо́же, в си́лах на́ших?","@13 Даждь нам по́мощ от ско́рби; і су́єтно спасе́ніє челові́чесько.","@14 О Бо́зі сотвори́м си́лу; і Той унічижи́ть стужа́ющия нам."]},{"h":"Псалом 60","ps":["§В коне́ць, в пі́снех, Дави́ду псало́м, 60.","@2 Усли́ши, Бо́же, моле́ніє моє́, воньми́ моли́тві моє́й;","@3 от коне́ць землі́ к Тебі́ воззва́х, внегда́ уни́ се́рдце моє́; на ка́мень возне́сл м'я єси́, наста́вил м'я єси́,","@4 я́ко бил єси́ упова́ніє моє́, столп крі́пости от лиця́ вра́жия.","@5 Вселю́ся в селе́нії Твоє́м во ві́ки, покри́юся в кро́ві крил Твої́х.","@6 Я́ко Ти, Бо́же, усли́шал єси́ моли́тви моя́, дал єси́ достоя́ніє боя́щимся і́мене Твоєго́.","@7 Дні на дні царе́ви приложи́ши, лі́та єго́ до дне ро́да і ро́да.","@8 Пребу́деть в вік пред Бо́гом; ми́лость і і́стину Єго́ кто взи́щеть?","@9 Та́ко воспою́ і́мені Твоєму́ во ві́ки, возда́ти мі моли́тви моя́ день от дне.","§Сла́ва:"]},{"h":"Псалом 61","ps":["§Псало́м","@1 В коне́ць, о Ідіфу́мі, псало́м Дави́ду, 61.","@2 Не Бо́гу ли повине́ться душа́ моя́? От Того́ бо спасе́ніє моє́.","@3 І́бо Той — Бог мой і Спас мой, Засту́пник мой; не подви́жуся найпа́че.","@4 Доко́лі належите́ на челові́ка? Убива́єте всі ви, я́ко стіні́ преклоне́ні і опло́ту возринове́ну.","@5 Оба́че ці́ну мою́ совіща́ша отри́нути, теко́ша в жа́жді; усти́ свої́ми благословля́ху, і се́рдцем свої́м кленя́ху.","@6 Оба́че Бо́гові повини́ся, душе́ моя́, я́ко от Того́ терпі́ніє моє́.","@7 І́бо Той — Бог мой і Спас мой, Засту́пник мой; не преселю́ся.","@8 О Бо́зі спасе́ніє моє́ і сла́ва моя́; Бог по́мощі моєя́, і упова́ніє моє́ на Бо́га.","@9 Упова́йте на Него́, весь сонм люді́й; ізлія́йте пред Ним сердця́ ва́ша, я́ко Бог помо́щник наш.","@10 Оба́че су́єтні си́нове челові́честії, лжи́ві си́нове челові́честії в мі́риліх є́же непра́вдовати; ті́ї от суєти́ вку́пі.","@11 Не упова́йте на непра́вду і на восхище́ніє не жела́йте; бога́тство а́ще тече́ть, не прилага́йте се́рдця.","@12 Єди́ною глаго́ла Бог, дво́я сія́ сли́шах, зане́ держа́ва Бо́жия,","@13 і Твоя́, Го́споди, ми́лость; я́ко Ти возда́си кому́ждо по діло́м єго́."]},{"h":"Псалом 62","ps":["§Псало́м Дави́ду, внегда́ би́ти єму́ в пусти́ні Іуде́йстій, 62.","@2 Бо́же, Бо́же мой, к Тебі́ у́тренюю; возжада́ Тебе́ душа́ моя́, коль мно́жицею Тебі́ плоть моя́, в землі́ пу́сті і непрохо́дні і безво́дні.","@3 Та́ко во святі́м яви́хся Тебі́ ви́діти си́лу Твою́ і сла́ву Твою́.","@4 Я́ко лу́чші ми́лость Твоя́ па́че живо́т; устні́ мої́ похвали́ті Тя.","@5 Та́ко благословлю́ Тя в животі́ моє́м і о і́мені Твоє́м воздіжу́ ру́ці мої́.","@6 Я́ко от ту́ка і ма́сти да іспо́лниться душа́ моя́, і устна́ма ра́дости восхва́лять Тя уста́ моя́.","@7 А́ще помина́х Тя на посте́лі моє́й, на у́тренніх поуча́хся в Тя;","@8 я́ко бил єси́ Помо́щник мой, і в кро́ві крилу́ Твоє́ю возра́дуюся.","@9 Прильпе́ душа́ моя́ по Тебі́; мене́ же прия́т десни́ця Твоя́.","@10 Ті́ї же всу́є іска́ша ду́шу мою́; вни́дуть в преіспо́дняя землі́;","@11 предадя́ться в ру́ки ору́жія, ча́сті ли́совом бу́дуть.","@12 Цар же возвесели́ться о Бо́зі; похва́литься всяк клени́йся Ім, я́ко загради́шася уста́ глаго́лющих непра́ведная."]},{"h":"Псалом 63","ps":["§В коне́ць, псало́м Дави́ду, 63.","@2 Усли́ши, Бо́же, глас мой, внегда́ моли́тимися к Тебі́; от стра́ха вра́жия ізми́ ду́шу мою́.","@3 Покри́й м'я от со́ньма лука́внующих, от мно́жества ді́лающих непра́вду;","@4 і́же ізостри́ша я́ко меч язи́ки своя́, напряго́ша лук свой, вещ го́рку,","@5 состріля́ти в та́йних непоро́чна; внеза́пу состріля́ють єго́, і не убоя́ться.","@6 Утверди́ша себі́ сло́во лука́воє; пові́даша скри́ти сіть, рі́ша: кто у́зрить їх?","@7 Іспита́ша беззако́ніє; ізчезо́ша іспита́ющії іспита́нія; присту́пить челові́к, і се́рдце глубоко́.","@8 І вознесе́ться Бог; стрі́ли младе́нець би́ша я́зви їх,","@9 і ізнемого́ша на ня язи́ци їх; смути́шася всі ви́дящії їх.","@10 І убоя́ся всяк челові́к; і возвісти́ша діла́ Бо́жія, і творе́нія Єго́ разумі́ша.","@11 Возвесели́ться пра́ведник о Го́споді і упова́єть на Него́; і похва́ляться всі пра́вії се́рдцем.","§Сла́ва:"]},{"h":"Після 8-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 5:","ps":["Во глубини́ м'я гріха́ попо́лзшася, треволне́ніє обурева́єть отча́янія; но предвари́, Христе́, я́ко Всеси́лен упра́вителю всіх, і ко приста́нищу ти́хому устреми́ безстра́стія, за благоутро́біє, Спа́се, і спаси́ м'я.","Сла́ва: Душе́, я́же зді привре́менна, та́мо же ві́чна; зрю суди́лище, і на престо́лі Судію́, і трепе́щу ізрече́нія. Про́чеє, душе́, обрати́ся, суд непроща́єм.","І ни́ні: Наде́жде ненаді́ємих, По́моще безпомо́щних, Заступле́ніє на Тя упова́ющих, свята́я Влади́чице Богоро́дице, по́мощ Твою́ низпосли́ нам."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди ще́дрий і ми́лостивий, долготерпіли́ве і многоми́лостиве, внуши́ моли́тву і воньми́ гла́су моле́нія моєго́, сотвори́ со мно́ю зна́меніє во бла́го, наста́ви м'я на путь Твой, є́же ходи́ти во і́стині Твоє́й; возвесели́ се́рдце моє́, во є́же боя́тися і́мене Твоєго́ свята́го. Зане́же ве́лій єси́ і творя́й чудеса́, Ти єси́ Бог єди́н, і ність подо́бен Тебі́ в бозі́х, Го́споди, си́льний в ми́лості, і благи́й в крі́пості, во є́же помога́ти, і утіша́ти, і спаса́ти вся упова́ющия на і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[<em>сей рі́чи [не]</span>","<span class=''>[ті́ї п'я́ту мою́ наблюда́ти бу́дуть, я́коже жда́ху душі́ моєя́]</span>","",""]},{"u":"Кафизма 9","e":"Kathisma 9","secs":[{"h":"Псалом 64","ps":["§В коне́ць, псало́м пі́сні Дави́ду, піснь Ієремі́єва і Ієзекі́їлева, люді́й преселе́нія, єгда́ хотя́ху ісходи́ти, 64.","@2 Тебі́ подоба́єть піснь, Бо́же, в Сіо́ні, і Тебі́ возда́сться моли́тва во Ієрусали́мі.","@3 Усли́ши моли́тву мою́; к Тебі́ вся́ка плоть при́йдеть.","@4 Словеса́ беззако́нник премого́ша нас; і нече́стія на́ша Ти очи́стиши.","@5 Блаже́н, єго́же ізбра́л єси́ і прия́л, всели́ться во дво́ріх Твої́х. Іспо́лнимся во благи́х до́му Твоєго́; свят храм Твой.","@6 Ди́вен в пра́вді, усли́ши ни, Бо́же, Спаси́телю наш, упова́ніє всіх конце́й землі́ і су́щих в мо́рі дале́че;","@7 уготовля́яй го́ри крі́постію Своє́ю, препоя́сан си́лою;","@8 смуща́яй глубину́ морську́ю, шу́му волн Єго́ кто постої́ть? См'яту́ться язи́ци,","@9 і убоя́ться живу́щії в конця́х от зна́меній Твої́х; ісхо́ди у́тра і ве́чера украси́ши.","@10 Посіти́л єси́ зе́млю і упої́л єси́ ю, умно́жил єси́ обогати́ти ю; ріка́ Бо́жия напо́лнися вод; угото́вал єси́ пи́щу їм, я́ко та́ко (єсть) угото́ваніє.","@11 Бразди́ єя́ упо́й, умно́жи жи́та єя́; в ка́плях єя́ возвесели́ться возсія́ющи⁽1⁾.","@12 Благослови́ши віне́ць лі́та бла́гости Твоєя́, і поля́ Твоя́ іспо́лняться ту́ка;","@13 разботі́ють кра́сная пусти́ні, і ра́достію хо́лми препоя́шуться.","@14 Оді́яшася о́вні о́вчії, і удо́лія умно́жать пшени́цю; воззову́ть, і́бо воспою́ть."]},{"h":"Псалом 65","ps":["§В коне́ць, піснь псалма́ воскресе́нія, 65.","@2 Воскли́кніте Го́сподеві вся земля́, по́йте же і́мені Єго́, даді́те сла́ву хвалі́ Єго́.","@3 Рці́те Бо́гу: коль стра́шна діла́ Твоя́? Во мно́жестві си́ли Твоєя́ со́лжуть Тебі́ вразі́ Твої́.","@4 Вся земля́ да покло́ниться Тебі́ і поє́ть Тебі́, да поє́ть же і́мені Твоєму́, Ви́шній.","@5 Прийді́те і ви́діте діла́ Бо́жія, коль стра́шен в сові́тіх па́че сино́в челові́чеських.","@6 Обраща́яй мо́ре в су́шу, в ріці́ про́йдуть нога́ми; та́мо возвеселі́мся о Нем,","@7 влади́чествующем си́лою Своє́ю ві́ком; о́чі Єго́ на язи́ки призира́єті; преогорчева́ющії да не возно́сяться в себі́.","@8 Благослові́те, язи́ци, Бо́га на́шего, і усли́шан сотворі́те глас хвали́ Єго́,","@9 поло́жшаго ду́шу мою́ в живо́т, і не да́вшаго во см'яте́ніє ног мої́х.","@10 Я́ко іскуси́л ни єси́, Бо́же, разже́гл ни єси́, я́коже разжиза́ється сребро́.","@11 Ввел ни єси́ в сіть, положи́л єси́ ско́рбі на хребті́ на́шем.","@12 Возве́л єси́ челові́ки на глави́ на́ша; пройдо́хом сквозі́ огнь і во́ду, і ізве́л єси́ ни в поко́й.","@13 Вни́ду в дом Твой со всесожже́нієм, возда́м Тебі́ моли́тви моя́,","@14 я́же ізреко́сті устні́ мої́, і глаго́лаша уста́ моя́ в ско́рбі моє́й.","@15 Всесожже́нія ту́чна вознесу́ Тебі́ с кади́лом, і овни́, вознесу́ Тебі́ воли́ с козли́.","@16 Прийді́те, усли́шіте, і пові́м вам, всі боя́щіїся Бо́га, єли́ка сотвори́ душі́ моє́й.","@17 К Нему́ усти́ мої́ми воззва́х, і вознесо́х под язи́ком мої́м.","@18 Непра́вду а́ще узрі́х в се́рдці моє́м, да не усли́шить мене́ Госпо́дь.","@19 Сего́ ра́ди усли́ша м'я Бог, внят гла́су моле́нія моєго́.","@20 Благослове́н Бог, І́же не отста́ви моли́тву мою́ і ми́лость Свою́ от мене́."]},{"h":"Псалом 66","ps":["§В коне́ць, в пі́снех, псало́м пі́сні Дави́ду, 66.","@2 Бо́же, уще́дри ни і благослови́ ни, просвіти́ лице́ Твоє́ на ни і поми́луй ни;","@3 позна́ти на землі́ путь Твой, во всіх язи́ціх спасе́ніє Твоє́.","@4 Да іспові́дяться Тебі́ лю́діє, Бо́же, да іспові́дяться Тебі́ лю́діє всі.","@5 Да возвеселя́ться і да возра́дуються язи́ци; я́ко су́диши лю́дем правото́ю і язи́ки на землі́ наста́виши.","@6 Да іспові́дяться Тебі́ лю́діє, Бо́же, да іспові́дяться Тебі́ лю́діє всі.","@7 Земля́ даде́ плод Свой; благослови́ ни, Бо́же, Бо́же наш,","@8 благослови́ ни, Бо́же; і да убоя́ться Єго́ всі конці́ землі́.","§Сла́ва:"]},{"h":"Псалом 67","ps":["§В коне́ць, псало́м пі́сні Дави́ду, 67.","@2 Да воскре́снеть Бог, і расточа́ться вразі́ Єго́, і да біжа́ть от лиця́ Єго́ ненави́дящії Єго́.","@3 Я́ко ізчеза́єть дим, да ізче́знуть; я́ко та́єть воск от лиця́ огня́, та́ко да поги́бнуть грі́шници от лиця́ Бо́жия;","@4 а пра́ведници да возвеселя́ться, да возра́дуються пред Бо́гом, да насладя́ться в весе́лії.","@5 Воспо́йте Бо́гу, по́йте і́мені Єго́; путесотворі́те возше́дшему на за́пади, Госпо́дь — і́м'я Єму́; і ра́дуйтеся пред Ним.","@6 Да см'яту́ться от лиця́ Єго́, Отця́ си́рих і Судії́ вдови́ць; Бог в мі́сті святі́м Своє́м.","@7 Бог вселя́єть єдиноми́сленния в дом, ізводя́ окова́нния му́жеством, тако́жде преогорчева́ющия живу́щия во гробі́х.","@8 Бо́же, внегда́ ісходи́ти Тебі́ пред людьми́ Твої́ми, внегда́ мимоходи́ти Тебі́ в пусти́ні,","@9 земля́ потрясе́ся, і́бо небеса́ ка́нуша от лиця́ Бо́га Сина́їна, от лиця́ Бо́га Ізра́їлева.","@10 Дождь во́лен отлучи́ши, Бо́же, достоя́нію Твоєму́, і ізнемо́же, Ти же соверши́л єси́ є.","@11 Живо́тная Твоя́ живу́ть на ней; угото́вал єси́ бла́гостію Твоє́ю ни́щему, Бо́же.","@12 Госпо́дь дасть глаго́л благовіству́ющим си́лою мно́гою;","@13 Цар Сил возлю́бленнаго, красото́ю⁽2⁾ до́му разділи́ти кори́сти.","@14 А́ще поспите́ посреді́ преді́л, крилі́ голуби́ні посре́брені, і междора́мія єя́ в блеща́нії зла́та;","@15 внегда́ ра́знствить Небе́сний царі́ на ней, осніжа́ться в Селмо́ні.","@16 Гора́ Бо́жия, гора́ ту́чная, гора́ усире́нная, гора́ ту́чная.","@17 Вску́ю непщу́єте, го́ри усире́нния? Гора́, ю́же благоволи́ Бог жи́ти в ней; і́бо Госпо́дь всели́ться до конця́.","@18 Колесни́ця Бо́жия тьма́ми тем, ти́сяща гобзу́ющих; Госпо́дь в них в Сина́ї во святі́м.","@19 Возше́л єси́ на висоту́, пліни́л єси́ плін; прия́л єси́ дая́нія в челові́ціх, і́бо не покаря́ющияся, є́же всели́тися.","@20 Госпо́дь Бог благослове́н, благослове́н Госпо́дь день дне; поспіши́ть нам Бог спаcе́ній на́ших.","@21 Бог наш — Бог, є́же спаса́ти; і Госпо́дня, Госпо́дня ісхо́дища сме́ртная.","@22 Оба́че Бог сокруши́ть глави́ враго́в Свої́х, верх влас преходя́щих в прегріше́ніїх свої́х.","@23 Рече́ Госпо́дь: от Васа́на обращу́, обращу́ во глубина́х морськи́х;","@24 я́ко да омо́читься нога́ твоя́ в кро́ві, язи́к пес твої́х от враг от него́.","@25 Ви́діна би́ша ше́ствія Твоя́, Бо́же, ше́ствія Бо́га моєго́ Царя́, І́же во святі́м.","@26 Предвари́ша кня́зі близ пою́щих, посреді́ дів тимпа́нниць.","@27 В це́рквах благослові́те Бо́га — Го́спода от істо́чник Ізра́їлевих.","@28 Та́мо Веніамі́н юні́йшій во у́жасі, кня́зі Іу́дови влади́ки їх, кня́зі Завуло́ні, кня́зі Неффали́млі.","@29 Запові́ждь, Бо́же, си́лою Твоє́ю; укріпи́, Бо́же, сіє́, є́же соді́лал єси́ в нас.","@30 От хра́ма Твоєго́ во Ієрусали́м Тебі́ принесу́ть ца́ріє да́ри.","@31 Запрети́ звіре́м тро́стним; сонм юне́ць в ю́ницях людськи́х, є́же затвори́ти іскуше́нния сребро́м; расточи́ язи́ки, хотя́щия бра́нем.","@32 При́йдут моли́твенници от Єги́пта; Ефіо́пія предвари́ть ру́ку свою́ к Бо́гу.","@33 Ца́рства земна́я, по́йте Бо́гу, воспо́йте Го́сподеві,","@34 возше́дшему на Не́бо небесе́ на восто́ки; се, дасть гла́су Своєму́ глас си́ли.","@35 Даді́те сла́ву Бо́гові; на Ізра́їлі велелі́пота Єго́, і си́ла Єго́ на о́блаціх.","@36 Ди́вен Бог во святи́х свої́х; Бог Ізра́їлев, той дасть си́лу і держа́ву лю́дем Свої́м. Благослове́н Бог.","§Сла́ва:"]},{"h":"Псалом 68","ps":["§В коне́ць, о ізмі́ншихся⁽3⁾, псало́м Дави́ду, 68.","@2 Спаси́ м'я, Бо́же, я́ко внидо́ша во́ди до душі́ моєя́.","@3 Углібо́х в тимі́нії глубини́, і ність постоя́нія; прийдо́х во глубини́ морські́я, і бу́ря потопи́ м'я.","@4 Утруди́хся зови́й, ізмолче́ горта́нь мой; ісчезо́сті о́чі мої́, от є́же упова́ти мі на Бо́га моєго́.","@5 Умно́жишася па́че влас глави́ моєя́ ненави́дящії м'я ту́не; укріпи́шася вразі́ мої́, ізгоня́щії м'я непра́ведно; я́же не восхища́х, тогда́ воздая́х.","@6 Бо́же, Ти уві́діл єси́ безу́міє моє́, і прегріше́нія моя́ от Тебе́ не утаї́шася.","@7 Да не постидя́ться о мні терп'я́щії Тебе́, Го́споди, Го́споди Сил; ніже́ да посра́м'яться о мні і́щущії Тебе́, Бо́же Ізра́їлев.","@8 Я́ко Тебе́ ра́ди претерпі́х поноше́ніє, покри́ срамота́ лице́ моє́.","@9 Чуждь бих бра́тії моє́й і стра́нен синово́м ма́тере моєя́;","@10 я́ко ре́вность до́му Твоєго́ сніде́ м'я, і поноше́нія понося́щих Ті нападо́ша на м'я.","@11 І покри́х посто́м ду́шу мою́, і бисть в поноше́ніє мні;","@12 і положи́х одія́ніє моє́ вре́тище, і бих їм в при́тчу.","@13 О мні глумля́хуся сідя́щії во враті́х, і о мні поя́ху пію́щії вино́.","@14 Аз же моли́твою моє́ю к Тебі́, Бо́же; вре́м'я благоволе́нія, Бо́же; во мно́жестві ми́лости Твоєя́ усли́ши м'я, во і́стині спаcе́нія Твоєго́.","@15 Спаси́ м'я от бре́нія, да не углі́бну; да ізба́влюся от ненави́дящих м'я і от глубо́ких вод.","@16 Да не потопи́ть мене́ бу́ря водна́я, ніже́ да пожре́ть мене́ глубина́, ніже́ сведе́ть о мні рове́нник уст свої́х.","@17 Усли́ши м'я, Го́споди, я́ко бла́га ми́лость Твоя́; по мно́жеству щедро́т Твої́х при́зри на м'я.","@18 Не отврати́ лиця́ Твоєго́ от о́трока Твоєго́, я́ко скорблю́; ско́ро усли́ши м'я.","@19 Воньми́ душі́ моє́й і ізба́ви ю; враг мої́х ра́ди ізба́ви м'я.","@20 Ти бо ві́си поноше́ніє моє́, і студ мой, і срамоту́ мою́; пред Тобо́ю всі оскорбля́ющії м'я.","@21 Поноше́ніє ча́яше душа́ моя́ і страсть; і ждах соскорб'я́щаго, і не бі, і утіша́ющих, і не обріто́х.","@22 І да́ша в снідь мою́ желчь, і в жа́жду мою́ напої́ша м'я о́цта.","@23 Да бу́деть трапе́за їх пред ни́ми в сіть, і в воздая́ніє, і в собла́зн.","@24 Да помрача́ться о́чі їх, є́же не ви́діти, і хребе́т їх ви́ну сляци́.","@25 Проли́й на ня гнів Твой, і я́рость гні́ва Твоєго́ да пости́гнеть їх.","@26 Да бу́деть двор їх пуст, і в жили́щих їх да не бу́деть живи́й.","@27 Зане́ єго́же Ти порази́л єси́, ті́ї погна́ша, і к болі́зні язв мої́х приложи́ша.","@28 Приложи́ беззако́ніє к беззако́нію їх, і да не вни́дуть в пра́вду Твою́.","@29 Да потреб'я́ться от кни́ги живи́х, і с пра́ведними да не напи́шуться.","@30 Нищ і боля́й єсьм аз; спасе́ніє Твоє́, Бо́же, да при́йметь м'я.","@31 Восхвалю́ і́м'я Бо́га моєго́ с пі́снію, возвели́чу Єго́ во хвале́нії;","@32 і уго́дно бу́деть Бо́гу па́че тельця́ ю́на, ро́ги ізнося́ща і па́знокти.","@33 Да у́зрять ни́щії і возвеселя́ться; взищі́те Бо́га, і жива́ бу́деть душа́ ва́ша.","@34 Я́ко усли́ша убо́гія Госпо́дь, і окова́нния Своя́ не унічижи́.","@35 Да восхва́лять Єго́ небеса́ і земля́, мо́ре і вся живу́щая в нем.","@36 Я́ко Бог спасе́ть Сіо́на, і сози́ждуться гра́ди Іуде́йстії, і вселя́ться та́мо і наслі́дять ї;","@37 і сі́м'я рабо́в Твої́х удержи́ть ї, і лю́б'ящії і́м'я Твоє́ вселя́ться в нем."]},{"h":"Псалом 69","ps":["§В коне́ць Дави́ду, в воспомина́ніє, во є́же спасти́ м'я Го́споду, 69.","@2 Бо́же, в по́мощ мою́ воньми́; Го́споди, помощи́ мі потщи́ся.","@3 Да постидя́ться і посра́м'яться і́щущії ду́шу мою́, да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я;","@4 да возратя́ться а́біє стидя́щеся глаго́лющії мі: бла́гоже, бла́гоже!","@5 Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебе́, Бо́же; і да глаго́лють ви́ну: «Да возвели́читься Госпо́дь!», лю́б'ящії спасе́ніє Твоє́.","@6 Аз же нищ єсьм і убо́г, Бо́же, помози́ мі; Помо́щник мой і Ізба́витель мой єси́ Ти, Го́споди, не закосни́.","§Сла́ва:"]},{"h":"Після 9-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 6:","ps":["Помишля́ю день стра́шний і пла́чу дія́ній мої́х лука́вих; ка́ко отвіща́ю Безсме́ртному Царю́, іли́ ко́їм дерзнове́нієм воззрю́ на Судію́, блу́дний аз? Благоутро́бний О́тче, Си́не Єдиноро́дний, Ду́ше Святи́й, поми́луй м'я.","Сла́ва: Во удо́лі плаче́вні, на мі́сті є́же завіща́л єси́, єгда́ ся́деши, Ми́лостиве, сотвори́ти пра́ведний суд, не обличи́ моя́ сокрове́нная, ніже́ посрами́ мене́ пред а́нгели; но пощади́ м'я, Бо́же, і поми́луй м'я.","І ни́ні: Упова́ніє і покро́в держа́вний к Тебі́ притека́ющих, Богороди́тельнице, благо́є предста́тельство ми́ра, моли́ со безпло́тними прилі́жно, Єго́же родила́ єси́ человіколю́бнійшаго Бо́га, ізба́витися душа́м на́шим от вся́каго преще́нія, єди́на Благослове́нная."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Влади́ко Го́споди Бо́же наш, І́же єди́н окая́нния моєя́ душі́ неду́г і сея́ ісціле́ніє ві́дий, ісціли́ ю, я́коже ві́си ра́ди мно́жества ми́лости Твоєя́ і щедро́т Твої́х; поне́же от діл мої́х ність пла́стиря приложи́ти єй, ніже́ єле́я, ні об'яза́нія, но Ти прише́дий не пра́ведния призва́ти, но грі́шния в покая́ніє, поми́луй, уще́дри, прости́ ю, раздери́ рукописа́ніє мно́гих мої́х і сту́дних дія́ній, і наста́ви м'я на пра́вий путь Твой, да ходя́й во і́стині Твоє́й, возмогу́ ізбіжа́ти стріл лука́ваго і си́це предста́ну неосужде́нно пред стра́шним престо́лом Твої́м, сла́в'я і воспіва́я пресвято́є Твоє́ і́м'я во ві́ки, амі́нь."]}],"notes":["<span class=''>[прозяба́ющи]</span>","<span class=''>[ра́ди красоти́]</span>","<span class=''>[о іму́щих ізміни́тися]</span>"]},{"u":"Кафизма 10","e":"Kathisma 10","secs":[{"h":"Псалом 70","ps":["§Дави́ду псало́м, сино́в Іонада́вових і пе́рвих плі́ншихся, не надпи́сан у євре́й, 70.","@1 На Тя, Го́споди, упова́х, да не постижу́ся во вік.","@2 Пра́вдою Твоє́ю ізба́ви м'я і ізми́ м'я; приклони́ ко мні у́хо Твоє́ і спаси́ м'я.","@3 Бу́ди мі в Бо́га Защи́тителя і в мі́сто крі́пко спасти́ м'я, я́ко утвержде́ніє моє́ і прибі́жище моє́ єси́ Ти.","@4 Бо́же мой, ізба́ви м'я із руки́ грі́шнаго, із руки́ законопресту́пнаго і оби́дящаго.","@5 Я́ко Ти єси́ терпі́ніє моє́, Го́споди, Го́споди, упова́ніє моє́ от ю́ности моєя́.","@6 В Тебі́ утверди́хся от утро́би, от чре́ва ма́тере моєя́ Ти єси́ мой покрови́тель, о Тебі́ пі́ніє моє́ ви́ну.","@7 Я́ко чу́до бих мно́гим, і Ти помо́щник мой крі́пок.","@8 Да іспо́лняться уста́ моя́ хвале́нія, я́ко да воспою́ сла́ву Твою́, весь день великолі́піє Твоє́.","@9 Не отве́ржи мене́ во вре́м'я ста́рости, внегда́ оскудіва́ти крі́пості моє́й, не оста́ви мене́.","@10 Я́ко рі́ша вразі́ мої́ мні, і стрегу́щії ду́шу мою́ совіща́ша вку́пі,","@11 глаго́люще: Бог оста́вил єсть єго́, пожені́те і імі́те єго́, я́ко ність ізбавля́яй.","@12 Бо́же мой, не удали́ся от мене́; Бо́же мой, в по́мощ мою́ воньми́.","@13 Да постидя́ться і ізче́знуть оклевета́ющії ду́шу мою́, да облеку́ться в студ і срам і́щущії зла́я мні.","@14 Аз же всегда́ возупова́ю на Тя, і приложу́ на вся́ку похвалу́ Твою́.","@15 Уста́ моя́ возвістя́ть пра́вду Твою́, весь день — спасе́ніє Твоє́, я́ко не позна́х кни́жная.","@16 Вни́ду в си́лі Госпо́дні; Го́споди, пом'яну́ пра́вду Тебе́ єди́наго.","@17 Бо́же мой, ї́мже научи́л м'я єси́ от ю́ности моєя́, і дони́ні возвіщу́ чудеса́ Твоя́.","@18 І да́же до ста́рости і престарі́нія, Бо́же мой, не оста́ви мене́, до́ндеже возвіщу́ ми́шцю Твою́ ро́ду всему́ гряду́щему,","@19 си́лу Твою́ і пра́вду Твою́, Бо́же, да́же до ви́шніх, я́же сотвори́л мі єси́ вели́чія; Бо́же, кто подо́бен Тебі́?","@20 Єли́ки яви́л мі єси́ ско́рбі мно́гі і зли? І обра́щся оживотвори́л м'я єси́ і от бездн землі́ возве́л м'я єси́.","@21 Умно́жил єси́ на мні вели́чествіє Твоє́, і обра́щся уті́шил м'я єси́, і от бездн землі́ па́ки возве́л м'я єси́.","@22 І́бо аз іспові́мся Тебі́ в лю́дех, Го́споди, в сосу́діх псало́мських і́стину Твою́, Бо́же. Воспою́ Тебі́ в гу́слех, Святи́й Ізра́їлев.","@23 Возра́дуєтіся устні́ мої́, єгда́ воспою́ Тебі́, і душа́ моя́, ю́же єси́ ізба́вил.","@24 Єще́ же і язи́к мой весь день поучи́ться пра́вді Твоє́й, єгда́ постидя́ться і посра́м'яться і́щущий зла́я мні."]},{"h":"Псалом 71","ps":["§О Соломо́ні, псало́м Дави́ду, 71.","@1 Бо́же, суд Твой царе́ві даждь, і пра́вду Твою́ си́ну царе́ву;","@2 суди́ти лю́дем Твої́м в пра́вді і ни́щим Твої́м в суді́.","@3 Да воспри́ймуть го́ри мир лю́дем і хо́лми пра́вду.","@4 Су́дить ни́щим людськи́м, і спасе́ть си́ни убо́гих, і смири́ть клеветника́.","@5 І пребу́деть с со́лнцем, і пре́жде луни́ ро́да родо́в.","@6 Сни́деть, я́ко дождь на руно́, і я́ко ка́пля ка́плющая на зе́млю.","@7 Возсія́єть во днех єго́ пра́вда і мно́жество ми́ра, до́ндеже оти́меться луна́.","@8 І облада́єть от мо́ря до мо́ря, і от рік до коне́ць вселе́нния.","@9 Пред ним припаду́ть ефіо́пляне, і вразі́ єго́ персть поли́жуть.","@10 Ца́ріє Фарсі́йстії і о́строві да́ри принесу́ть, ца́ріє Ара́встії і Сава́ да́ри приведу́ть;","@11 і покло́няться єму́ всі ца́ріє зе́мстії, всі язи́ци порабо́тають єму́.","@12 Я́ко ізба́ви ни́ща от си́льна, і убо́га, єму́же не бі помо́щника.","@13 Пощади́ть ни́ща і убо́га, і ду́ші убо́гих спасе́ть;","@14 от ли́хви і от непра́вди ізба́вить ду́ші їх, і че́стно і́м'я єго́ пред ни́ми.","@15 І жив бу́деть, і да́сться єму́ от зла́та араві́йська; і помо́ляться о нем ви́ну, весь день благослов'я́ть єго́.","@16 Бу́деть утвержде́ніє на землі́ на версі́х гор; превознесе́ться па́че Лива́на плод єго́, і процвіту́ть от гра́да, я́ко трава́ земна́я.","@17 Бу́деть і́м'я єго́ благослове́но во ві́ки, пре́жде со́лнця пребива́єть і́м'я єго́; і благослов'я́ться в нем вся колі́на земна́я, всі язи́ци ублажа́ть єго́.","@18 Благослове́н Госпо́дь, Бог Ізра́їлев, творя́й чудеса́ єди́н,","@19 і благослове́нно і́м'я сла́ви Єго́ во вік і в вік ві́ка; і іспо́лниться сла́ви Єго́ вся земля́. Бу́ди, бу́ди.","§Сла́ва:"]},{"h":"Псалом 72","ps":["§Оконча́шася пі́сні Дави́да, си́на Ієссе́йова. Псало́м Аса́фу, 72.","@1 Коль благ Бог Ізра́їлев пра́вим се́рдцем.","@2 Мої́ же вма́лі не подвижа́стіся но́зі; вма́лі не пролія́шася стопи́ моя́;","@3 я́ко возревнова́х на беззако́нния, мир грі́шников зря;","@4 я́ко ність восклоне́нія в сме́рті їх і утвержде́нія в ра́ні їх;","@5 в труді́х челові́чеських не суть, і с челові́ки не при́ймуть ран.","@6 Сего́ ра́ди удержа́ я горди́ня їх до конця́; оді́яшася непра́вдою і нече́стієм свої́м.","@7 Ізи́деть, я́ко із ту́ка, непра́вда їх; прейдо́ша в любо́в се́рдця.","@8 Поми́слиша і глаго́лаша в лука́встві, непра́вду в висоту́ глаго́лаша;","@9 положи́ша на небесі́ уста́ своя́, і язи́к їх пре́йде по землі́.","@10 Сего́ ра́ди обратя́ться лю́діє мої́ сі́мо, і дні́є іспо́лнені обря́щуться в них.","@11 І рі́ша: ка́ко уві́ді Бог? І а́ще єсть ра́зум в ви́шнім?","@12 Се, сі́ї грі́шници і гобзу́ющії в вік удержа́ша бога́тство.","@13 І ріх: єда́⁽1⁾ всу́є оправди́х се́рдце моє́ і уми́х в непови́нних ру́ці мої́,","@14 і бих я́звен весь день, і обличе́ніє моє́ на у́треніх?","@15 А́ще глаго́лах, пові́м та́ко: се, ро́ду сино́в Твої́х, єму́же обіща́хся⁽2⁾;","@16 і непщева́х разумі́ти; сіє́ труд єсть пре́до мно́ю,","@17 до́ндеже вни́ду во святи́ло Бо́жиє і разумі́ю в послі́дняя їх.","@18 Оба́че за льще́нія їх положи́л єси́ їм зла́я, низложи́л єси́ я, внегда́ разгорди́шася.","@19 Ка́ко би́ша в запусті́ніє? Внеза́пу ізчезо́ша, погибо́ша за беззако́ніє своє́.","@20 Я́ко со́ніє востаю́щаго, Го́споди, во гра́ді Твоє́м о́браз їх уничижи́ши.","@21 Я́ко разжже́ся се́рдце моє́, і утро́би моя́ ізміни́шася;","@22 і аз унічиже́н, і не разумі́х, ско́тен бих у Тебе́.","@23 І аз ви́ну с Тобо́ю; удержа́л єси́ ру́ку десну́ю мою́,","@24 і сові́том Твої́м наста́вил м'я єси́, і со сла́вою прия́л м'я єси́.","@25 Что бо мі єсть на небесі́? І от Тебе́ что восхоті́х на землі́?","@26 Ізчезе́ се́рдце моє́ і плоть моя́, Бо́же се́рдця моєго́, і часть моя́, Бо́же, во вік.","@27 Я́ко се, удаля́ющії себе́ от Тебе́ поги́бнуть; потреби́л єси́ вся́каго любоді́ющаго от Тебе́.","@28 Мні же приліпля́тися Бо́гові бла́го єсть, полага́ти на Го́спода упова́ніє моє́, возвісти́ти мі вся хвали́ Твоя́, во враті́х дще́ре Сіо́ні."]},{"h":"Псалом 73","ps":["§Ра́зума Аса́фу, 73.","@1 Вску́ю, Бо́же, отри́нул єси́ до конця́? Разгні́вася я́рость Твоя́ на о́вці па́житі Твоєя́?","@2 Пом'яни́ сонм Твой, єго́же стяжа́л єси́ іспе́рва, ізба́вил єси́ жезло́м достоя́нія Твоєго́, гора́ Сіо́н сія́⁽3⁾, в не́йже всели́лся єси́.","@3 Воздви́гни ру́ці Твої́ на горди́ні їх в коне́ць, єли́ка лука́внова враг во святі́м Твоє́м.","@4 І восхвали́шася ненави́дящії Тя посреді́ пра́здника Твоєго́; положи́ша зна́менія своя́ зна́менія, і не позна́ша,","@5 я́ко во ісхо́ді преви́ше; я́ко в дубра́ві дре́в'яні сіки́рами разсіко́ша","@6 две́рі єго́ вку́пі, сі́чивом і оско́рдом разруши́ша ї.","@7 Возжго́ша огне́м святи́ло Твоє́; на землі́ оскверни́ша жили́ще і́мене Твоєго́.","@8 Рі́ша в се́рдці своє́м ю́жики їх вку́пі: прийді́те, і отста́вим вся пра́здники Бо́жия от землі́.","@9 Зна́мєнія їх⁽4⁾ не ви́діхом; ність ктому́ проро́ка, і нас не позна́єть ктому́.","@10 Доко́лі, Бо́же, поно́сить враг? Раздражи́ть проти́вний і́м'я Твоє́ до конця́?","@11 Вску́ю отвраща́єши ру́ку Твою́ і десни́цю Твою́ от среди́ ні́дра Твоєго́ в коне́ць?","@12 Бог же, Цар наш, пре́жде ві́ка соді́ла спасе́ніє посреді́ землі́.","@13 Ти утверди́л єси́ си́лою Твоє́ю мо́ре; Ти стерл єси́ глави́ зміє́в в воді́;","@14 Ти сокруши́л єси́ главу́ змі́єву, дал єси́ того́ бра́шно лю́дем ефіо́пським.","@15 Ти расто́ргл єси́ істо́чники і пото́ки; Ти ізсуши́л єси́ рі́ки Іфа́мськия.","@16 Твой єсть день, і Твоя́ єсть нощ; Ти соверши́л єси́ зарю́ і со́лнце.","@17 Ти сотвори́л єси́ вся преді́ли землі́; жа́тву і ве́сну Ти созда́л єси́ я.","@18 Пом'яни́ сія́; враг поноси́ Го́сподеві, і лю́діє безу́мнії раздражи́ша і́м'я Твоє́.","@19 Не преда́ждь звіре́м ду́шу іспові́дающуюся Тебі́; душ убо́гих Твої́х не забу́ди до конця́.","@20 При́зри на заві́т Твой; я́ко іспо́лнишася помраче́ннії землі́ домо́в беззако́ній.","@21 Да не возврати́ться смире́нний посра́млен; нищ і убо́г восхвали́та і́м'я Твоє́.","@22 Воста́ни, Бо́же, суди́ прю Твою́; пом'яни́ поноше́ніє Твоє́, є́же от безу́мнаго весь день.","@23 Не забу́ди гла́са моли́твенник Твої́х; горди́ня ненави́дящих Тя взи́де ви́ну⁽5⁾.","§Сла́ва:"]},{"h":"Псалом 74","ps":["§В коне́ць, да не растли́ши, псало́м пі́сні Аса́фу, 74.","@2 Іспові́мися Тебі́, Бо́же, іспові́мися Тебі́ і призове́м і́м'я Твоє́; пові́м вся чудеса́ Твоя́.","@3 Єгда́ прийму́ вре́м'я, аз правоти́ возсужду́.","@4 Раста́яся земля́ і всі живу́щії на ней, аз утверди́х столпи́ єя́.","@5 Ріх беззако́ннующим: не беззако́ннуйте! І согріша́ющим: не возносі́те ро́га.","@6 Не воздвиза́йте на висоту́ ро́га ва́шего і не глаго́літе на Бо́га непра́вду;","@7 я́ко ніже́ от ісхо́д, ніже́ і за́пад, ніже́ от пусти́х гор.","@8 Я́ко Бог Судія́ єсть; cего́ смиря́єть, і cего́ возно́сить.","@9 Я́ко ча́ша в руці́ Госпо́дні, вина́ нерастворе́на іспо́лнь растворе́нія, і уклони́ от сея́ в сію́; оба́че дро́ждіє Єго́ не істощи́ся, іспію́ть всі грі́шнії землі́.","@10 Аз же возра́дуюся в вік, воспою́ Бо́гу Іа́ковлю;","@11 і вся ро́ги грі́шних сломлю́, і вознесе́ться рог пра́веднаго."]},{"h":"Псалом 75","ps":["§В коне́ць, в пі́снех, псало́м Аса́фу, піснь ко ассирі́анину, 75.","@2 Ві́дом во Іуде́ї Бог; во Ізра́їлі ве́ліє і́м'я Єго́.","@3 І бисть в ми́рі мі́сто Єго́, і жили́ще Єго́ в Сіо́ні.","@4 Та́мо сокруши́ крі́пості луко́в, ору́жіє і меч і брань.","@5 Просвіща́єши Ти ди́вно от гор ві́чних.","@6 См'ято́шася всі неразу́мнії се́рдцем; усну́ша сном свої́м, і нічто́же обріто́ша всі му́жіє бога́тства в рука́х свої́х.","@7 От запреще́нія Твоєго́, Бо́же Іа́ковль, воздрема́ша всі́дшії на ко́ні.","@8 Ти стра́шен єси́, і кто противоста́неть Тебі́? Отто́лі гнів Твой.","@9 С небесе́ сли́шан сотвори́л єси́ суд; земля́ убоя́ся і умолча́,","@10 внегда́ воста́ти на суд Бо́гу, спасти́ вся кро́ткия землі́.","@11 Я́ко помишле́ніє челові́чеськоє іспові́сться Тебі́, і оста́нок помишле́нія пра́зднуєть Ті.","@12 Помолі́теся і воздаді́те Го́сподеві Бо́гу на́шему; всі, і́же о́крест Єго́, принесу́ть да́ри","@13 Стра́шному і от'ємлющему ду́хи князе́й, стра́шному па́че царе́й земни́х."]},{"h":"Псалом 76","ps":["§В коне́ць, о Ідіфу́мі, псало́м Аса́фу, 76.","@2 Гла́сом мої́м ко Го́споду воззва́х, гла́сом мої́м к Бо́гу, і внят мі.","@3 В день ско́рби моєя́ Бо́га взиска́х рука́ма мої́ма, но́щію пред Ним, і не прельще́н бих; отве́ржеся уті́шитися душа́ моя́.","@4 Пом'яну́х Бо́га і возвесели́хся, поглумля́хся⁽6⁾, і малоду́шствоваше дух мой.","@5 Предвари́сті стражби́ о́чі мої́; см'ято́хся і не глаго́лах.","@6 Поми́слих дні пе́рвия, і лі́та ві́чная пом'яну́х, і поуча́хся;","@7 но́щію се́рдцем мої́м глумля́хся, і тужа́ше⁽7⁾ дух мой;","@8 єда́ во ві́ки отри́неть Госпо́дь і не приложи́ть благоволи́ти па́ки?","@9 іли́ до конця́ ми́лость Свою́ отсіче́ть, сконча́ глаго́л от ро́да в род?","@10 єда́ забу́деть уще́дрити Бог? Іли́ удержи́ть во гні́ві Своє́м щедро́ти Своя́?","@11 І ріх: ни́ні нача́х, сія́ ізмі́на десни́ці Ви́шняго.","@12 Пом'яну́х діла́ Госпо́дня; я́ко пом'яну́ от нача́ла чудеса́ Твоя́,","@13 і поучу́ся во всіх ді́ліх Твої́х, і в начина́ніїх Твої́х поглумлю́ся⁽8⁾.","@14 Бо́же, во святі́м путь Твой; кто Бог ве́лій, я́ко Бог наш?","@15 Ти єси́ Бог творя́й чудеса́; сказа́л єси́ в лю́дех си́лу Твою́,","@16 ізба́вил єси́ ми́шцею Твоє́ю лю́ди Твоя́, си́ни Іа́ковлі і Іо́сифови.","@17 Ви́діша Тя во́ди, Бо́же, ви́діша Тя во́ди і убоя́шася; см'ято́шася бе́здни.","@18 Мно́жество шу́ма вод; глас да́ша о́блаци, і́бо стрі́ли Твоя́ прехо́дять.","@19 Глас гро́ма Твоєго́ в колесі́, освіти́ша мо́лнія Твоя́ вселе́нную; подви́жеся і тре́петна бисть земля́.","@20 В мо́рі путіє́ Твої́, і стезі́ Твоя́ в вода́х мно́гих, і сліди́ Твої́ не позна́ються.","@21 Наста́вил єси́, я́ко о́вці, лю́ди Твоя́ руко́ю Моїсе́йовою і Ааро́нею.","§Сла́ва:"]},{"h":"Після 10-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 6:","ps":["Стра́шнаго дне прише́ствія Твоєго́ ужаса́юся, Христе́, і неуми́тнаго суди́лища боя́ся, Го́споди, ужаса́юся і трепе́щу, я́ко іми́й мно́жество согріше́ній; но пре́жде конця́ я́ко ми́лостив Бог обрати́ і спаси́ м'я, Спа́се мой Многоми́лостиве.","Сла́ва: Єгда́ престо́ли на суд поста́в'яться, Го́споди, і суди́лищу Твоєму́ предста́нуть челові́ци, не предпочте́ться цар во́їна, не преіму́ществить влади́ка раба́; ки́йждо бо от свої́х діл іли́ просла́виться, іли́ постиди́ться.","І ни́ні: Вели́ких дарова́ній, Чи́стая Ді́во Богома́ти, Ти сподо́билася єси́, я́ко родила́ єси́ пло́тію Єди́наго от Тро́йці, Христа́ Жизнода́вця, во спасе́ніє душ на́ших."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Бо́же наш, в ми́лості бога́тий і в щедро́тах непостижи́мий, єди́не по єстеству́ безгрі́шен, і нас ра́ди кромі́ гріха́ бив челові́к, усли́ши в час сей болі́зненноє моє́ сіє́ моле́ніє, я́ко нищ і убо́г єсьм от діл благи́х, і се́рдце моє́ см'яте́ся внутр мене́. Ти бо ві́си, Ви́шній Царю́, Го́споди небесе́ і землі́, я́ко всю мою́ ю́ность во грісі́х іжди́х; і в слід похоте́й пло́ті моєя́ ходи́в, весь сміх де́моном бих, весь дия́волу послі́довах ви́ну, в тимі́нії сласте́й валя́яйся. Омрачи́вся бо помишле́нієм от младе́нства да́же і до ни́ні, нікогда́же восхоті́х сотвори́ти во́лю Твою́ святу́ю; но весь от наві́тующих м'я страсте́й пліни́вся, сміх і поруга́ніє де́моном бих, ніка́коже во умі́ помишля́яй, я́ко нестерпи́мий гнів є́же на грі́шники преще́нія Твоєго́, і лежа́щую геє́нну о́гненную. Я́коже отсю́ду во отча́яніє впади́й і ніка́коже в чу́встві обраще́нія бив, пуст і наг є́же от Твоєя́ дру́жби бих. Кий бо вид гріха́ не соді́лах? Ко́є ді́ло де́монськоє не соді́ях? Ко́є дія́ніє сту́дноє і блу́дноє не с преіму́ществом і тща́нієм соверши́х? Ум воспомина́ньми плотськи́ми оскверни́х, ті́ло сміше́ньми окаля́х, дух сосложе́нієм оскверни́х; всяк уд окая́нния моєя́ пло́ті служи́ти і рабо́тати гріхо́м возлюби́х. І кто про́чеє не возрида́єть м'я, окая́ннаго? Кто не воспла́четь м'я, осужде́ннаго? Аз бо єди́н, Влади́ко, я́рость Твою́ прогні́вах; аз єди́н гнів Твой на м'я разжего́х; аз єди́н лука́воє пред Тобо́ю сотвори́х, превозше́д і препобіди́в вся от ві́ка грі́шники, несравне́нно погріши́вий і непроще́нно. Но поне́же многоми́лостивий і благоутро́бний єси́, Человіколю́бче, і ожида́єши челові́чеськаго обраще́нія; се і аз вверга́ю себе́ пред стра́шноє і нестерпи́моє Твоє́ суди́ще, і я́коже Пречи́стим Твої́м нога́м каса́яйся, із глубини́ душі́ взива́ю Ті: очи́сти, Го́споди, прости́, Благопреміни́телю, поми́луй не́мощ мою́, приклони́ся недоумі́нію моєму́, воньми́ моле́нію моєму́ і слез мої́х не премолчи́. Прийми́ м'я ка́ющагося, і заблу́ждшаго обрати́; обраща́ющагося обими́, і моля́щагося прости́. Не бо положи́л єси́ покая́ніє пра́ведним, не положи́л єси́ проще́ніє несогріша́ющим; но положи́л єси́ покая́ніє мні, грі́шному, в ни́хже в негодова́ніє Твоє́ соді́ях. Наг і обнаже́н пред Тобо́ю предстою́, Сердцеві́дче Го́споди, іспові́даяй моя́ гріхи́; не бо могу́ воззрі́ти і ви́діти висоту́ небе́сную, от тя́жести гріхо́в мої́х сляца́єм. Просвіти́ у́бо о́чі се́рдця моєго́ і даждь мі умиле́ніє к покая́нію і сокруше́ніє се́рдця ко ісправле́нію; да со благо́ю наде́ждею і і́стинним увіре́нієм к та́мошнему ми́ру пойду́, хваля́ і благослов'я́ ви́ну всесвято́є і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[у́бо]</span>","<span class=''>[се, ро́ду сино́в Твої́х преступи́х]</span>","<span class=''>[жезл достоя́нія Твоєго́, го́ру Сіо́н сію́]</span>","<span class=''>[зна́меній на́ших]</span>","<span class=''>[да восхо́дить ви́ну к Тебі́]</span>","<span class=''>[размишля́х]</span>","<span class=''>[размишля́х, і іспи́товаше]</span>","<span class=''>[размишля́ти бу́ду]</span>"]},{"u":"Кафизма 11","e":"Kathisma 11","secs":[{"h":"Псалом 77","ps":["§Ра́зума Аса́фу, 77.","@1 Внемлі́те, лю́діє мої́, зако́ну моєму́, приклоні́те у́хо ва́ше во глаго́ли уст мої́х.","@2 Отве́рзу в при́тчах уста́ моя́, провіща́ю гана́нія іспе́рва.","@3 Єли́ка сли́шахом і позна́хом я, і отці́ на́ші пові́даша нам;","@4 не утаї́шася от чад їх в род ін, возвіща́юще хвали́ Госпо́дні, і си́ли Єго́, і чудеса́ Єго́, я́же сотвори́.","@5 І воздви́же свиді́ніє во Іа́кові, і зако́н положи́ во Ізра́їлі, єли́ка запові́да отце́м на́шим сказа́ти я синово́м свої́м,","@6 я́ко да позна́єть род ін, си́нове родя́щіїся, і воста́нуть, і пові́дять я синово́м свої́м;","@7 да положа́ть на Бо́га упова́ніє своє́, і не забу́дуть діл Бо́жиїх, і за́повіді Єго́ взи́щуть;","@8 да не бу́дуть я́коже отці́ їх, род стропти́в і преогорчева́яй, род і́же не іспра́ви се́рдця своєго́ і не уві́ри с Бо́гом ду́ха своєго́.","@9 Си́нове Єфре́млі, наляца́юще і стріля́юще лу́ки, возврати́шася в день бра́ні;","@10 не сохрани́ша заві́та Бо́жия, і в зако́ні Єго́ не восхоті́ша ходи́ти.","@11 І заби́ша благодія́нія Єго́ і чудеса́ Єго́, я́же показа́ їм","@12 пред отці́ їх, я́же сотвори́ чудеса́ в землі́ Єги́петстій, на по́лі Танео́сі;","@13 разве́рзе мо́ре і проведе́ їх; предста́ви во́ди, я́ко міх,","@14 і наста́ви я о́блаком во дні і всю нощ просвіще́нієм огня́.","@15 Разве́рзе ка́мень в пусти́ні і напої́ я, я́ко в бе́здні мно́зі;","@16 і ізведе́ во́ду із ка́мене, і низведе́, я́ко рі́ки, во́ди.","@17 І приложи́ша єще́ согріша́ти Єму́, преогорчи́ша Ви́шняго в безво́дній;","@18 і іскуси́ша Бо́га в сердця́х свої́х, воспроси́ти бра́шна душа́м свої́м.","@19 І клевета́ша на Бо́га і рі́ша: єда́ возмо́жеть Бог угото́вати трапе́зу в пусти́ні?","@20 Поне́же порази́ ка́мень, і потеко́ша во́ди, і пото́ци наводни́шася; єда́ і хліб мо́жеть да́ти? Іли́ угото́вати трапе́зу лю́дем Свої́м?","@21 Сего́ ра́ди сли́ша Госпо́дь і презрі́, і огнь возгорі́ся во Іа́кові, і гнів взи́де на Ізра́їля;","@22 я́ко не ві́роваша Бо́гові, ніже́ упова́ша на спасе́ніє Єго́.","@23 І запові́да облако́м сви́ше, і две́рі небесе́ отве́рзе;","@24 і одожди́ їм ма́нну я́сти, і хліб небе́сний даде́ їм.","@25 Хліб а́нгелський яде́ челові́к; бра́шно посла́ їм до си́тости.","@26 Воздви́же юг с небесе́, і наведе́ си́лою Своє́ю ли́ва;","@27 і одожди́ на ня, я́ко прах, пло́ті, і, я́ко песо́к морськи́й, пти́ці перна́ти.","@28 І нападо́ша посреді́ ста́на їх, о́крест жили́щ їх.","@29 І ядо́ша і наси́тишася зіло́, і жела́ніє їх пренесе́ їм.","@30 Не лиши́шася от жела́нія своєго́; єще́ бра́шну су́щу во усті́х їх,","@31 і гнів Бо́жий взи́де на ня, і уби́ мно́жайшая їх, і ізбра́нним Ізра́їлевим зап'я́т.","@32 Во всіх сих согріши́ша єще́ і не ві́роваша чудесе́м Єго́;","@33 і ізчезо́ша в суєті́ дні́є їх, і лі́та їх со тща́нієм.","@34 Єгда́ убива́ше я, тогда́ взиска́ху Єго́ і обраща́хуся і у́треневаху к Бо́гу;","@35 і пом'яну́ша, я́ко Бог Помо́щник їм єсть, і Бог Ви́шній Ізба́витель їм єсть;","@36 і возлюби́ша Єго́ усти́ свої́ми, і язи́ком свої́м солга́ша Єму́;","@37 се́рдце же їх не бі пра́во с Ним, ніже́ уві́ришася в заві́ті Єго́.","@38 Той же єсть щедр, і очи́стить гріхи́ їх, і не растли́ть; і умно́жить отврати́ти я́рость Свою́, і не разжже́ть всего́ гні́ва Своєго́.","@39 І пом'яну́, я́ко плоть суть, дух ходя́й і не обраща́яйся;","@40 колькра́ти преогорчи́ша Єго́ в пусти́ні, прогні́ваша Єго́ в землі́ безво́дній?","@41 і обрати́шася, і іскуси́ша Бо́га, і Свята́го Ізра́їлева раздражи́ша;","@42 і не пом'яну́ша руки́ Єго́ в день, в о́ньже ізба́ви я із руки́ оскорбля́ющаго;","@43 я́коже положи́ во Єги́пті зна́менія Своя́, і чудеса́ Своя́ на по́лі Танео́сі;","@44 і преложи́ в кров рі́ки їх і істо́чники їх, я́ко да не пію́ть.","@45 Посла́ на ня пе́сія му́хи, і поядо́ша я, і жа́би, і растли́ я;","@46 і даде́ ржі плоди́ їх, і труди́ їх пруго́м.","@47 Уби́ гра́дом виногра́ди їх і черни́чіє їх сла́ною;","@48 і предаде́ гра́ду скоти́ їх, і імі́ніє їх огню́.","@49 Посла́ на ня гнів я́рости Своєя́, я́рость, і гнів, і скорб, посла́ніє а́ггели лю́тими.","@50 Путесотвори́ стезю́ гні́ву Своєму́, і не пощаді́ от сме́рти душ їх, і скоти́ їх в сме́рті заключи́;","@51 і порази́ вся́коє перворо́дноє в землі́ Єги́петстій, нача́ток вся́каго труда́ їх в селе́ніїх Ха́мових.","@52 І воздви́же, я́ко о́вці, лю́ди Своя́, і возведе́ я, я́ко ста́до, в пусти́ні;","@53 і наста́ви я на упова́ніє, і не убоя́шася; і враги́ їх покри́ мо́ре.","@54 І введе́ я в го́ру святи́ні Своєя́, го́ру сію́, ю́же стяжа́ десни́ця Єго́.","@55 І ізгна́ от лиця́ їх язи́ки, і по жре́бію даде́ їм (зе́млю) у́жем жребодая́нія, і всели́ в селе́ніїх їх колі́на Ізра́їлєва.","@56 І іскуси́ша і преогорчи́ша Бо́га Ви́шняго, і свиді́ній Єго́ не сохрани́ша;","@57 і отврати́шася і отверго́шася, я́коже і отці́ їх; преврати́шася в лук развраще́н;","@58 і прогні́ваша Єго́ в хо́лміх свої́х, і во істука́нних свої́х раздражи́ша Єго́.","@59 Сли́ша Бог і презрі́, і унічижи́ зіло́ Ізра́їля;","@60 і отри́ну ски́нію Сило́мськую, селе́ніє є́же⁽1⁾ всели́ся в челові́ціх;","@61 і предаде́ в плін крі́пость їх, і добро́ту їх в ру́ки враго́в;","@62 і затвори́ во ору́жії лю́ди Своя́ і достоя́ніє Своє́ презрі́.","@63 Ю́ноші їх пояде́ огнь, і ді́ви їх не осі́товани би́ша;","@64 свяще́нници їх мече́м падо́ша, і вдови́ці їх не опла́кани бу́дуть.","@65 І воста́, я́ко сп'я, Госпо́дь, я́ко си́лен і шу́мен от вина́;","@66 і порази́ враги́ Своя́ всп'ять, поноше́ніє ві́чноє даде́ їм;","@67 і отри́ну селе́ніє Іо́сифово, і колі́но Єфре́мово не ізбра́;","@68 і ізбра́ колі́но Іу́дово, го́ру Сіо́ню, ю́же возлюби́;","@69 і созда́, я́ко єдиноро́га, святи́лище Своє́; на землі́ основа́ ї в вік.","@70 І ізбра́ Дави́да раба́ Своєго́, і восприя́т єго́ от стад о́вчих;","@71 от дої́лиць поя́т єго́ пасти́ Іа́кова — раба́ Своєго́, і Ізра́їля — достоя́ніє Своє́.","@72 І упасе́ я в незло́бії се́рдця своєго́, і в ра́зуміх руку́ своє́ю наста́вил я єсть.","§Сла́ва:"]},{"h":"Псалом 78","ps":["§Псало́м Аса́фу, 78.","@1 Бо́же, прийдо́ша язи́ци в достоя́ніє Твоє́, оскверни́ша храм святи́й Твой,","@2 положи́ша Ієрусали́м, я́ко ово́щноє храни́лище; положи́ша тру́пія раб Твої́х бра́шно пти́цям небе́сним, пло́ти преподо́бних Твої́х звіре́м земни́м;","@3 пролія́ша кров їх, я́ко во́ду, о́крест Ієрусали́ма, і не бі погреба́яй.","@4 Би́хом поноше́ніє сосі́дом на́шим, подражне́ніє і поруга́ніє су́щим о́крест нас.","@5 Доко́лі, Го́споди, прогні́ваєшися до конця́? Разжже́ться, я́ко огнь, рве́ніє Твоє́?","@6 Проли́й гнів Твой на язи́ки, незна́ющия Тебе́, і на ца́рствія, я́же і́мене Твоєго́ не призва́ша;","@7 я́ко поядо́ша Іа́кова і мі́сто єго́ опустоши́ша.","@8 Не пом'яни́ на́ших беззако́ній пе́рвих; ско́ро да предваря́ть ни щедро́ти Твоя́, Го́споди, я́ко обнища́хом зіло́.","@9 Помози́ нам, Бо́же, Спаси́телю наш, сла́ви ра́ди і́мене Твоєго́; Го́споди, ізба́ви ни і очи́сти гріхи́ на́ша і́мене ра́ди Твоєго́.","@10 Да не когда́ реку́ть язи́ци: гді єсть Бог їх? І да уві́сться во язи́ціх пред очи́ма на́шима отмще́ніє кро́ве раб Твої́х пролити́я.","@11 Да вни́деть пред Тя воздиха́ніє окова́нних; по вели́чію ми́шці Твоєя́ снабди́ си́ни умерщвле́нних.","@12 Возда́ждь сосі́дом на́шим седмери́цею в ні́дро їх поноше́ніє їх, і́мже поноси́ша Тя, Го́споди.","@13 Ми же, лю́діє Твої́ і о́вці па́житі Твоєя́, іспові́мися Тебі́, Бо́же, во вік, в род і род возвісти́м хвалу́ Твою́.","§Сла́ва:"]},{"h":"Псалом 79","ps":["§В коне́ць, о ізмі́ншихся, свиді́ніє Аса́фу, псало́м 79.","@2 Паси́й Ізра́їля, воньми́! Наставля́яй, я́ко овча́, Іо́сифа, сідя́й на херуви́міх, яви́ся;","@3 пред Єфре́мом, і Веніамі́ном, і Манассі́єм воздви́гни си́лу Твою́, і прийди́, во є́же спасти́ нас.","@4 Бо́же, обрати́ ни і просвіти́ лице́ Твоє́, і спасе́мся.","@5 Го́споди, Бо́же Сил, доко́лі гні́ваєшися на моли́тву раб Твої́х?","@6 Напита́єши нас хлі́бом сле́зним і напої́ши нас слеза́ми в мі́ру.","@7 Положи́л єси́ нас в преріка́ніє сосі́дом на́шим, і вразі́ на́ші подражни́ша ни.","@8 Го́споди, Бо́же Сил, обрати́ ни і просвіти́ лице́ Твоє́, і спасе́мся.","@9 Виногра́д із Єги́пта прене́сл єси́; ізгна́л єси́ язи́ки і насади́л єси́ ї;","@10 путесотвори́л єси́ пред ним, і насади́л єси́ коре́нія єго́, і іспо́лни зе́млю.","@11 Покри́ го́ри сінь єго́, і ві́твія єго́ ке́дри Бо́жия;","@12 простре́ ро́зги єго́⁽2⁾ до мо́ря і да́же до рік отра́сли єго́⁽3⁾.","@13 Вску́ю низложи́л єси́ опло́т єго́, і обима́ють ї всі мимоходя́щії путе́м?","@14 Озоба́ ї вепр от дубра́ви, і уєдине́нний ди́вій пояде́ ї.","@15 Бо́же Сил, обрати́ся у́бо і при́зри с небесе́ і виждь, і посіти́ виногра́д сей;","@16 і соверши́ ї, єго́же насади́ десни́ця Твоя́, і на си́на челові́чеськаго, єго́же укрепи́л єси́ Себі́.","@17 Пожже́н огне́м і раско́пан; от запреще́нія лиця́ Твоєго́ поги́бнуть.","@18 Да бу́деть рука́ Твоя́ на му́жа десни́ці Твоєя́ і на си́на челові́чеськаго, єго́же укріпи́л єси́ Себі́,","@19 і не отсту́пим от Тебе́; оживи́ши ни, і і́м'я Твоє́ призове́м.","@20 Го́споди, Бо́же Сил, обрати́ ни і просвіти́ лице́ Твоє́, і спасе́мся."]},{"h":"Псалом 80","ps":["§В коне́ць, о точи́ліх, псало́м Аса́фу, 80.","@2 Ра́дуйтеся Бо́гу — Помо́щнику на́шему, воскли́кніте Бо́гу Іа́ковлю;","@3 приймі́те псало́м і даді́те тимпа́н, псалти́р красе́н с гу́сльми;","@4 вострубі́те в новомісячії трубо́ю, во благознамени́тий день пра́здника ва́шего;","@5 я́ко повелі́ніє Ізра́їлеві єсть, і судьба́ Бо́гу Іа́ковлю.","@6 Свиді́ніє во Іо́сифі положи́ є, внегда́ ізи́ти єму́ от землі́ єги́петськия; язи́ка, єго́же не ві́дяше, усли́ша.","@7 От'я́т от бре́мене хребе́т єго́; ру́ці єго́ в коші́ порабо́тасті.","@8 В ско́рбі призва́л М'я єси́, і ізба́вих тя; усли́шах тя в та́йні бу́рні; іскуси́х тя на воді́ преріка́нія.","@9 Сли́шіте, лю́діє мої́, і засвиді́тельствую вам, Ізра́їлю, а́ще послу́шаєши Мене́;","@10 не бу́деть тебі́ бог нов, ніже́ поклони́шися бо́гу чужде́му.","@11 Аз бо єсьм Госпо́дь, Бог твой, ізведи́й тя от землі́ Єги́петськия; разшири́ уста́ твоя́, і іспо́лню я.","@12 І не послу́шаша лю́діє Мої́ гла́са Моєго́, і Ізра́їль не внят Мі;","@13 і отпусти́х я по начина́нієм серде́ць їх, по́йдуть в начина́ніїх свої́х.","@14 А́ще би́ша лю́діє Мої́ послу́шали Мене́, Ізра́їль а́ще би в путі́ Моя́ ходи́л;","@15 ні о чесо́мже у́бо враги́ єго́ смири́л бих, і на оскорбля́ющия їх возложи́л бих ру́ку Мою́.","@16 Вразі́ Госпо́дні солга́ша Єму́, і бу́деть вре́м'я їх в вік;","@17 і напита́ їх от ту́ка пшени́чна, і от ка́мене ме́да наси́ти їх."]},{"h":"Псалом 81","ps":["§Псало́м Аса́фу, 81.","@1 Бог ста в со́нмі бого́в, посреді́ же бо́ги разсу́дить.","@2 Доко́лі су́дите непра́вду і ли́ця грі́шников приє́млете?","@3 Суді́те си́ру і убо́гу, смире́на і ни́ща оправда́йте;","@4 ізмі́те ни́ща і убо́га, із руки́ грі́шничі ізба́віте єго́.","@5 Не позна́ша, ніже́ уразумі́ша, во тьмі хо́дять; да подви́жаться вся основа́нія землі́.","@6 Аз ріх: бо́зі єсте́, і си́нове Ви́шняго всі;","@7 ви же, я́ко челові́ци, умира́єте, і, я́ко єди́н от князе́й, па́даєте.","@8 Воскресни́, Бо́же, суди́ землі́; я́ко Ти наслі́диши во всіх язи́ціх."]},{"h":"Псалом 82","ps":["§Піснь псалма́ Аса́фу, 82.","@2 Бо́же, кто уподо́биться Тебі́? Не премолчи́, ніже́ укроти́⁽4⁾, Бо́же;","@3 я́ко се, вразі́ Твої́ возшумі́ша, і ненави́дящії Тя воздвиго́ша главу́.","@4 На лю́ди Твоя́ лука́вноваша во́лею, і совіща́ша на святи́я Твоя́.","@5 Рі́ша: прийді́те і потреби́м я от язи́к, і не пом'яне́ться і́м'я Ізра́їлево ктому́.","@6 Я́ко совіща́ша єдиномишле́нієм вку́пі, на Тя заві́т завіща́ша;","@7 селе́нія Ідуме́йська і Ісма́їліте, Моа́в і ага́ряне,","@8 Гева́л і Аммо́н і Амали́к, іноплеме́нници с живу́щими в Ти́рі;","@9 і́бо і Ассу́р при́йде с ни́ми, би́ша в заступле́ніє синово́м Ло́товим;","@10 сотвори́ їм, я́ко Мадіа́му і Сиса́рі, я́ко Іави́му в пото́ці Ки́ссові;","@11 потреби́шася во Аендо́рі, би́ша, я́ко гной земни́й.","@12 Положи́ кня́зі їх, я́ко Ори́ва і Зи́ва, і Зеве́я і Салма́на, вся кня́зі їх,","@13 і́же рі́ша: да наслі́дим себі́ святи́лище Бо́жиє.","@14 Бо́же мой, положи́ я я́ко ко́ло, я́ко трость пред лице́м ві́тра.","@15 Я́ко огнь попаля́яй дубра́ви, я́ко пла́мень пожига́яй го́ри;","@16 та́ко пожене́ши я бу́рею Твоє́ю і гні́вом Твої́м см'яте́ши я.","@17 Іспо́лни ли́ця їх безче́стія, і взи́щуть і́мене Твоєго́, Го́споди.","@18 Да постидя́ться і см'яту́ться в вік ві́ка, і посра́м'яться і поги́бнуть.","@19 І да позна́ють, я́ко і́м'я Тебі́ — Госпо́дь, Ти єди́н Ви́шній по всей землі́."]},{"h":"Псалом 83","ps":["§В коне́ць, о точи́ліх, сино́м Коре́йовим, псало́м, 83.","@2 Коль возлю́бленна селе́нія Твоя́, Го́споди Сил.","@3 Жела́єть і скончава́ється душа́ моя́ во двори́ Госпо́дні; се́рдце моє́ і плоть моя́ возра́довастася о Бо́зі жи́ві.","@4 І́бо пти́ця обрі́те себі́ хра́мину, і го́рлиця гніздо́ себі́, іді́же положи́ть птенці́ своя́, олтарі́ Твоя́, Го́споди Сил, Царю́ мой і Бо́же мой.","@5 Блаже́нні живу́щії в дому́ Твоє́м; в ві́ки віко́в восхва́лять Тя.","@6 Блаже́н муж, єму́же єсть заступле́ніє єго́ у Тебе́; восхожде́нія в се́рдці своє́м положи́,","@7 во юдо́ль плаче́вную, в мі́сто є́же положи́⁽5⁾; і́бо благослове́ніє дасть законополага́яй.","@8 По́йдуть от си́ли в си́лу; яви́ться Бог бого́в в Сіо́ні.","@9 Го́споди, Бо́же Сил, усли́ши моли́тву мою́, внуши́, Бо́же Іа́ковль.","@10 Защи́тниче наш, виждь, Бо́же, і при́зри на лице́ христа́ Твоєго́.","@11 Я́ко лу́чше день єди́н во дво́ріх Твої́х па́че ти́сящ; ізво́лих примета́тися в дому́ Бо́га моєго́ па́че, не́же жи́ти мі в селе́ніїх грі́шничих.","@12 Я́ко ми́лость і і́стину лю́бить Госпо́дь, Бог благода́ть і сла́ву дасть; Госпо́дь не лиши́ть благи́х ходя́щих незло́бієм.","@13 Го́споди, Бо́же сил, блаже́н челові́к упова́яй на Тя."]},{"h":"Псалом 84","ps":["§В коне́ць, сино́м Коре́йовим, псало́м, 84.","@2 Благоволи́л єси́, Го́споди, зе́млю Твою́, возврати́л єси́ плін Іа́ковль.","@3 Оста́вил єси́ беззако́нія люді́й Твої́х, покри́л єси́ вся гріхи́ їх.","@4 Укроти́л єси́ весь гнів Твой, возврати́лся єси́ от гні́ва я́рости Твоєя́.","@5 Возврати́ нас, Бо́же спасе́ній на́ших, і отврати́ я́рость Твою́ от нас.","@6 Єда́ во ві́ки прогні́ваєшися на ни? Іли́ простре́ши гнів Твой от ро́да в род?","@7 Бо́же, Ти обра́щся оживи́ши ни, і лю́діє Твої́ возвеселя́ться о Тебі́.","@8 Яви́ нам, Го́споди, ми́лость Твою́, і спасе́ніє Твоє́ даждь нам.","@9 Усли́шу, что рече́ть о мні Госпо́дь Бог; я́ко рече́ть мир на лю́ди Своя́, і на преподо́бния Своя́, і на обраща́ющия сердця́ к Нему́.","@10 Оба́че близ боя́щихся Єго́ спасе́ніє Єго́, всели́ти сла́ву в зе́млю на́шу.","@11 Ми́лость і і́стина сріто́стіся, пра́вда і мир облобиза́стася;","@12 і́стина от землі́ возсія́, і пра́вда с небесе́ прини́че;","@13 і́бо Госпо́дь дасть бла́гость, і земля́ на́ша дасть плод свой.","@14 Пра́вда пред Ним преди́деть, і положи́ть в путь стопи́ своя́.","§Сла́ва:"]},{"h":"Після 11-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 7:","ps":["Іму́щи, душе́ моя́, врачевство́ покая́нія, приступи́, слезя́щи, воздиха́нієм вопію́щи: Врачу́ душ і тіле́с, свободи́ м'я, Человіколю́бче, от мно́гих согріше́ній. Сопричти́ м'я блудни́ці, і разбо́йнику, і митарю́; і да́руй мі, Бо́же, беззако́ній мої́х проще́ніє, і спаси́ м'я.","Сла́ва: Митаре́ву покая́нію не поревнова́х, і блудни́ці слез не стяжа́х; недоумі́юся бо от осліпле́нія о таково́м ісправле́нії; но Твої́м благоутро́бієм спаси́ м'я, Христе́ Бо́же, я́ко Человіколю́бець.","І ни́ні: Богоро́дице Ді́во нескве́рная, Си́на Твоєго́ моли́ с Го́рними Си́лами, проще́ніє прегріше́ній нам пре́жде конця́ дарова́ти і ве́лію ми́лость."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Возсія́й в сердця́х на́ших, Человіколю́бче Го́споди, Твоєго́ Богові́дінія нетлі́нний світ, і ми́сленния на́ша отве́рзи о́чі, во єва́нгельських Твої́х пропові́даній разумі́ніє; вложи́ в нас і блаже́нних Твої́х за́повідей страх, да плотські́я по́хоті вся попра́вше, духо́вноє жи́тельство про́йдем, вся я́же ко благоугожде́нію Твоєму́ і му́дрствующе і ді́юще. Ти бо єси́ просвіще́ніє душ і тіле́с на́ших, Христе́ Бо́же, і Тебі́ сла́ву возсила́єм со Безнача́льним Твої́м Отце́м, і Всесвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні, і при́сно і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[селе́ніє Своє́, іді́же]</span>","<span class=''>[своя́]</span>","<span class=''>[своя́]</span>","<span class=''>[ніже́ укроти́ся]</span>","<span class=''>[во юдо́лі плаче́вній, в мі́сті, є́же положи́]</span>"]},{"u":"Кафизма 12","e":"Kathisma 12","secs":[{"h":"Псалом 85","ps":["§Моли́тва Дави́ду, 85.","@1 Приклони́, Го́споди, у́хо Твоє́, і усли́ши м'я, я́ко нищ і убо́г єсьм аз.","@2 Сохрани́ ду́шу мою́, я́ко преподо́бен єсьм; спаси́ раба́ Твоєго́, Бо́же мой, упова́ющаго на Тя.","@3 Поми́луй м'я, Го́споди, я́ко к Тебі́ воззову́ весь день.","@4 Возвесели́ ду́шу раба́ Твоєго́, я́ко к Тебі́ взях ду́шу мою́.","@5 Я́ко Ти, Го́споди, благ і кро́ток і многоми́лостив всім призива́ющим Тя.","@6 Внуши́, Го́споди, моли́тву мою́ і воньми́ гла́су моле́нія моєго́.","@7 В день ско́рби моєя́ воззва́х к Тебі́, я́ко усли́шал м'я єси́.","@8 Ність подо́бен Тебі́ в бозі́х, Го́споди, і ність по діло́м Твої́м.","@9 Всі язи́ци, єли́кі сотвори́л єси́, при́йдуть і покло́няться пред Тобо́ю, Го́споди, і просла́в'ять і́м'я Твоє́;","@10 я́ко ве́лій єси́ Ти і творя́й чудеса́, Ти єси́ Бог єди́н.","@11 Наста́ви м'я, Го́споди, на путь Твой, і пойду́ во і́стині Твоє́й; да возвесели́ться се́рдце моє́ боя́тися і́мене Твоєго́.","@12 Іспові́мся Тебі́, Го́споди Бо́же мой, всім се́рдцем мої́м і просла́влю і́м'я Твоє́ в вік;","@13 я́ко ми́лость Твоя́ ве́лія на мні, і ізба́вил єси́ ду́шу мою́ от а́да преіспо́днійшаго.","@14 Бо́же, законопресту́пници воста́ша на м'я, і сонм держа́вних взиска́ша ду́шу мою́, і не предложи́ша Тебе́ пред собо́ю.","@15 І Ти, Го́споди Бо́же мой, ще́дрий і ми́лостивий, долготерпіли́вий і многоми́лостивий і і́стинний,","@16 при́зри на м'я і поми́луй м'я; даждь держа́ву Твою́ о́троку Твоєму́ і спаси́ си́на раби́ Твоєя́.","@17 Сотвори́ со мно́ю зна́меніє во бла́го; і да ви́дять ненави́дящії м'я, і постидя́ться, я́ко Ти, Го́споди, помо́гл мі і уті́шил м'я єси́."]},{"h":"Псалом 86","ps":["§Сино́м коре́йовим, псало́м пі́сні, 86.","@2 Основа́нія Єго́ на гора́х святи́х; лю́бить Госпо́дь врата́ Сіо́ня па́че всіх селе́ній Іа́ковлих.","@3 Пресла́вная глаго́лашася о Тебі́, гра́де Бо́жий.","@4 Пом'яну́ Раа́в і Вавило́на ві́дущим м'я; і се, іноплеме́нници і Тир і лю́діє Ефіо́пстії, сі́ї би́ша та́мо.","@5 Ма́ти Сіо́н рече́ть: челові́к і челові́к роди́ся в нем, і Той основа́ ї Ви́шній.","@6 Госпо́дь пові́сть в писа́нії люді́й і князе́й, сих би́вших в нем.","@7 Я́ко веселя́щихся всіх жили́ще в Тебі́."]},{"h":"Псалом 87","ps":["§Піснь псалма́ сино́м Коре́йовим, в коне́ць, о Маєле́фі⁽1⁾ є́же отвіща́ти, ра́зума Ема́ну Ізра́їльтянину, 87.","@2 Го́споди Бо́же спаcе́нія моєго́, во дні воззва́х і в нощі́ пред Тобо́ю;","@3 да вни́деть пред Тя моли́тва моя́, приклони́ у́хо Твоє́ к моле́нію моєму́.","@4 Я́ко іспо́лнися зол душа́ моя́, і живо́т мой а́ду прибли́жися.","@5 Привміне́н бих с низходя́щими в ров; бих я́ко челові́к без по́мощі,","@6 в ме́ртвих свобо́дь; я́ко я́звеннії сп'я́щії во гро́бі, ї́хже не пом'яну́л єси́ ктому́, і ті́ї от руки́ Твоєя́ отринове́ні би́ша.","@7 Положи́ша м'я в ро́ві преіспо́днім, в те́мних і сі́ні сме́ртній.","@8 На мні утверди́ся я́рость Твоя́, і вся во́лни Твоя́ наве́л єси́ на м'я.","@9 Уда́лил єси́ зна́ємих мої́х от мене́; положи́ша м'я ме́рзость себі́; пре́дан бих і не ісхожда́х.","@10 О́чі мої́ ізнемого́сті от нищети́; воззва́х к Тебі́, Го́споди, весь день, возді́х к Тебі́ ру́ці мої́.","@11 Єда́ ме́ртвими твори́ши чудеса́? Іли́ вра́чеве воскреся́ть, і іспові́дяться Тебі́?","@12 Єда́ пові́сть кто во гро́бі ми́лость Твою́ і і́стину Твою́ в поги́белі?","@13 Єда́ позна́на бу́дуть во тьмі чудеса́ Твоя́ і пра́вда Твоя́ в землі́ забве́нній?","@14 І аз к Тебі́, Го́споди, воззва́х, і у́тро моли́тва моя́ предвари́ть Тя.","@15 Вску́ю, Го́споди, отрі́єши ду́шу мою́? Отвраща́єши лице́ Твоє́ от мене́?","@16 Нищ єсьм аз і в труді́х от ю́ности моєя́; возне́сжеся смири́хся і ізнемого́х.","@17 На мні прейдо́ша гні́ви Твої́, устраше́нія Твоя́ возмути́ша м'я;","@18 обидо́ша м'я я́ко вода́ весь день, одержа́ша м'я вку́пі.","@19 Уда́лил єси́ от мене́ дру́га і і́скренняго, і зна́ємих мої́х от страсте́й.","§Сла́ва:"]},{"h":"Псалом 88","ps":["§Ра́зума Ефа́ма Ізра́їльтянина, 88.","@2 Ми́лості Твоя́, Го́споди, во вік воспою́, в род і род возвіщу́ і́стину Твою́ усти́ мої́ми.","@3 Зане́ рекл єси́: в вік ми́лость сози́ждеться, на небесі́х угото́виться і́стина Твоя́.","@4 Завіща́х заві́т ізбра́нним Мої́м, кля́хся Дави́ду, рабу́ Моєму́:","@5 до ві́ка угото́ваю сі́м'я твоє́, і сози́жду в род і род престо́л твой.","@6 Іспові́дять небеса́ чудеса́ Твоя́, Го́споди, і́бо і́стину Твою́ в Це́ркві святи́х.","@7 Я́ко кто во о́блаціх уравни́ться Го́сподеві? Уподо́биться Го́сподеві в сині́х Бо́жиїх?","@8 Бог прославля́єм в сові́ті святи́х, ве́лій і стра́шен єсть над всі́ми окре́стними Єго́.","@9 Го́споди Бо́же сил, кто подо́бен Тебі́? Си́лен єси́, Го́споди, і і́стина Твоя́ о́крест Тебе́.","@10 Ти влади́чествуєши держа́вою морсько́ю, возмуще́ніє же волн єго́ Ти укроча́єши.","@11 Ти смири́л, єси́, я́ко я́звена, го́рдаго, ми́шцею си́ли Твоєя́ расточи́л єси́ враги́ Твоя́.","@12 Твоя́ суть небеса́, і Твоя́ єсть земля́; вселе́нную і ісполне́ніє єя́ Ти основа́л єси́.","@13 Сі́вер і мо́ре Ти созда́л єси́; Фаво́р і Єрмо́н о і́мені Твоє́м возра́дуєтася.","@14 Твоя́ ми́шця с си́лою, да укріпи́ться рука́ Твоя́, і вознесе́ться десни́ця Твоя́.","@15 Пра́вда і судьба́ — угото́ваніє Престо́ла Твоєго́; ми́лость і і́стина преди́деті пред лице́м Твої́м.","@16 Блаже́нні лю́діє ві́дущії воскликнове́ніє: Го́споди, во сві́ті лиця́ Твоєго́ по́йдуть,","@17 і о і́мені Твоє́м возра́дуються весь день, і пра́вдою Твоє́ю вознесу́ться.","@18 Я́ко похвала́ си́ли їх Ти єси́, і во благоволе́нії Твоє́м вознесе́ться рог наш.","@19 Я́ко Госпо́днє єсть заступле́ніє і Свята́го Ізра́їлева Царя́ на́шего.","@20 Тогда́ глаго́лал єси́ в виді́нії синово́м Твої́м і рекл єси́: положи́х по́мощ на си́льнаго, вознесо́х ізбра́ннаго от люді́й Мої́х;","@21 обріто́х Дави́да, раба́ Моєго́, єле́єм святи́м Мої́м пома́зах єго́.","@22 І́бо рука́ моя́ засту́пить єго́, і ми́шця моя́ укріпи́ть єго́;","@23 нічто́же успі́єть враг на него́, і син беззако́нія не приложи́ть озло́бити єго́.","@24 І ссіку́ от лиця́ єго́ враги́ єго́, і ненави́дящия єго́ побіжду́;","@25 і і́стина Моя́ і ми́лость Моя́ с ним, і о і́мені Моє́м вознесе́ться рог єго́;","@26 і положу́ на мо́рі ру́ку єго́, і на ріка́х десни́цю єго́.","@27 Той призове́ть М'я: Оте́ць мой єси́ Ти, Бог мой і засту́пник спаcе́нія моєго́.","@28 І Аз пе́рвенця положу́ єго́, висока́ па́че царе́й земни́х;","@29 в вік сохраню́ єму́ ми́лость Мою́, і заві́т Мой ві́рен єму́;","@30 і положу́ в вік ві́ка сі́м'я єго́, і престо́л єго́ я́ко дні́є не́ба.","@31 А́ще оста́в'ять си́нове єго́ зако́н Мой і в судьба́х Мої́х не по́йдуть,","@32 а́ще оправда́нія Моя́ оскверня́ть і за́повідій Мої́х не сохраня́ть,","@33 посіщу́ жезло́м беззако́нія їх і ра́нами непра́вди їх,","@34 ми́лость же Мою́ не разорю́ от них, ні преврежду́ во і́стині Моє́й;","@35 ніже́ оскверню́ заві́та Моєго́ і ісходя́щих от уст Мої́х не отве́ргуся.","@36 Єди́ною кля́хся о святі́м Моє́м: а́ще Дави́ду солжу́?","@37 Сі́м'я єго́ во вік пребу́деть, і престо́л єго́ — я́ко со́лнце пре́до Мно́ю,","@38 і я́ко луна́ соверше́на в вік, і свиді́тель на небесі́ ві́рен.","@39 Ти же отри́нул єси́ і унічижи́л, негодова́л єси́ пома́заннаго Твоєго́;","@40 разори́л єси́ заві́т раба́ Твоєго́, оскверни́л єси́ на землі́ святи́ню єго́;","@41 разори́л єси́ вся опло́ти єго́, положи́л єси́ тве́рдая єго́ страх.","@42 Расхища́ху єго́ всі мимоходя́щії путе́м, бисть поноше́ніє сосі́дом свої́м.","@43 Возви́сил єси́ десни́цю стужа́ющих єму́, возвесели́л єси́ вся враги́ єго́;","@44 отврати́л єси́ по́мощ меча́ єго́ і не заступи́л єси́ єго́ во бра́ні;","@45 разори́л єси́ от очище́нія єго́, престо́л єго́ на зе́млю пове́ргл єси́:","@46 Ума́лил єси́ дні вре́мене єго́, облія́л єси́ єго́ студо́м.","@47 Доко́лі, Го́споди, отвраща́єшися в коне́ць, разжже́ться я́ко огнь гнів Твой?","@48 Пом'яни́, кий мой соста́в: єда́ бо всу́є созда́л єси́ вся си́ни челові́чеськія?","@49 Кто єсть челові́к, і́же поживе́ть і не у́зрить сме́рти, ізба́вить ду́шу свою́ із руки́ а́дови?","@50 Гді суть ми́лості Твоя́ дре́внія, Го́споди, ї́миже кля́лся єси́ Дави́ду во і́стині Твоє́й?","@51 Пом'яни́, Го́споди, поноше́ніє раб Твої́х, є́же удержа́х в ні́дрі моє́м мно́гих язи́к;","@52 і́мже поноси́ша вразі́ Твої́, Го́споди, і́мже поноси́ша ізміне́нію христа́ Твоєго́.","@53 Благослове́н Госпо́дь во вік! Бу́ди, бу́ди.","§Сла́ва:"]},{"h":"Псалом 89","ps":["§Моли́тва Моїсе́я, челові́ка Бо́жия, 89.","@2 Го́споди, прибі́жище бил єси́ нам в род і род.","@3 Пре́жде да́же гора́м не би́ти і созда́тися землі́ і вселе́нній, і от ві́ка і до ві́ка Ти єси́.","@4 Не отврати́ челові́ка во смире́ніє, і рекл єси́: обраті́теся, си́нове челові́честії.","@5 Я́ко ти́сяща літ пред очи́ма Твої́ма, Го́споди, я́ко день вчера́шній, і́же ми́мо і́де, і стра́жа нощна́я.","@6 Уничиже́нія їх лі́та бу́дуть; у́тро я́ко трава́ ми́мо і́деть, у́тро процвіте́ть і пре́йдеть; на ве́чер отпаде́ть, ожесті́єть і і́зсхнеть;","@7 я́ко ізчезо́хом гні́вом Твої́м, і я́ростію Твоє́ю смути́хомся.","@8 Положи́л єси́ беззако́нія на́ша пред Тобо́ю, вік наш в просвіще́ніє лиця́ Твоєго́.","@9 Я́ко всі дні́є на́ші оскуді́ша, і гні́вом Твої́м ізчезо́хом;","@10 лі́та на́ша я́ко паучи́на поуча́хуся; дні́є літ на́ших в ни́хже се́дьмдесят літ, а́ще же в си́лах — о́сьмдесят літ, і мно́жає їх труд і болі́знь: я́ко при́йде кро́тость на ни, і нака́жемся.","@11 Кто вість держа́ву гні́ва Твоєго́, і от стра́ха Твоєго́ я́рость Твою́ ізчести́?","@12 Десни́цю Твою́ та́ко скажи́ мі, і окова́нния⁽2⁾ се́рдцем в му́дрості.","@13 Обрати́ся, Го́споди, доко́лі? І умоле́н бу́ди на раби́ Твоя́.","@14 Іспо́лнихомся зау́тра ми́лости Твоєя́, Го́споди, і возра́довахомся і возвесели́хомся;","@15 во вся дні на́ша возвесели́хомся, за дні, в ня́же смири́л ни єси́, лі́та, в ня́же ви́діхом зла́я.","@16 І при́зри на раби́ Твоя́ і на діла́ Твоя́, і наста́ви си́ни їх.","@17 І бу́ди сві́тлость Го́спода Бо́га на́шего на нас, і діла́ рук на́ших іспра́ви на нас, і ді́ло рук на́ших іспра́ви."]},{"h":"Псалом 90","ps":["§Хвала́ пі́сні Дави́дови, не надпи́сан у євре́й, 90.","@1 Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га Небе́снаго водвори́ться,","@2 рече́ть Го́сподеві: засту́пник мой єси́ і прибі́жище моє́, Бог мой, і упова́ю на Него́.","@3 Я́ко Той ізба́вить тя от сі́ті ло́вчі і от словесе́ м'яте́жна;","@4 Плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися; ору́жієм оби́деть тя і́стина Єго́.","@5 Не убої́шися от стра́ха нощна́го, от стріли́ летя́щия во дні,","@6 от ве́щі во тьмі преходя́щия, от сря́ща⁽3⁾ і бі́са полу́деннаго.","@7 Паде́ть от страни́ твоєя́ ти́сяща і тьма одесну́ю тебе́, к тебі́ же не прибли́житься;","@8 оба́че очи́ма твої́ма смо́триши і воздая́ніє грі́шников у́зриши.","@9 Я́ко Ти, Го́споди, упова́ніє моє́; Ви́шняго положи́л єси́ прибі́жище твоє́.","@10 Не при́йдеть к тебі́ зло, і ра́на не прибли́житься тілесі́ твоєму́⁽4⁾;","@11 я́ко а́нгелом Свої́м запові́сть о тебі́ сохрани́ти тя во всіх путе́х твої́х.","@12 На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́;","@13 на а́спида і васили́ска насту́пиши і попере́ши льва і змі́я.","@14 Я́ко на М'я упова́, і ізба́влю ї; покри́ю ї, я́ко позна́ і́м'я Моє́.","@15 Воззове́ть ко Мні, і усли́шу єго́; с ним єсьм в ско́рбі, ізму́ єго́ і просла́влю єго́;","@16 Долгото́ю дній іспо́лню єго́ і явлю́ єму́ спасе́ніє Моє́.","§Сла́ва:"]},{"h":"Після 12-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 7:","ps":["Блудни́ці сле́зи і Петро́ви приє́мий, Го́споди, і митаря́ оправда́вий, із глубини́ воздохну́вша; і мене́ во умиле́нії припа́дающа уще́дри, Спа́се, і поми́луй м'я.","Сла́ва: Прийми́, я́ко митаря́, Го́споди, я́ко блудни́цю, очи́сти м'я, Влади́ко, я́ко ханане́ю, поми́луй, по вели́цій Твоє́й ми́лості.","І ни́ні: Ма́ти Сві́та, благослове́нная Богоро́дице, моли́ся Христу́ Бо́гу совозсія́ти у́тро, і ве́лію ми́лость душа́м на́шим."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Бо́же мой, єди́н благи́й і человіколюби́вий, єди́н ми́лостивий і кро́ткий, єди́н і́стинний і пра́ведний, єди́н ще́дрий і ми́лостивий Бо́же наш; да при́йдеть си́ла Твоя́ на м'я, грі́шнаго і непотре́бнаго раба́ Твоєго́, і да укріпи́ть мой храм Єва́нгелієм Боже́ственнаго уче́нія Твоєго́. Влади́ко і Человіколю́бче, Любоблаже, Любоблагоутро́бне, просвіти́ моя́ утро́би і вся у́ди Твоє́ю во́лею; очи́сти м'я от вся́кия зло́би і гріха́, соблюди́ м'я нескве́рна і непоро́чна от вся́каго наї́тія і ді́йства дия́воля, і да́руй мі по Твоє́й бла́гості Твоя́ разумі́ти, Твоя́ му́дрствовати і в Твої́х хоті́ніїх жи́ти, Твоєго́ стра́ха страши́тися, є́же твори́ти Тебі́ благоуго́дная до послі́дняго моєго́ іздиха́нія, я́ко да по неісповіди́мой Твоє́й ми́лості соблюде́ши моє́ ті́ло і ду́шу, ум же і ми́слі, неіскуше́н вся́кия сопротиволежа́щия сі́ті храм. Го́споди мой, Го́споди, покри́й м'я Твої́м благоутро́бієм і не оста́ви м'я, грі́шнаго, і нечи́стаго, і недосто́йнаго раба́ Твоєго́; я́ко Ти єси́ Защи́титель мой, Го́споди, і о Тебі́ пі́ніє моє́ ви́ну, і Тебі́ сла́ву возсила́єм, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["","<span class=''>[і нака́занния]</span>","<span class=''>[от нападе́нія]</span>","<span class=''>[селе́нію твоєму́]</span>"]},{"u":"Кафизма 13","e":"Kathisma 13","secs":[{"h":"Псалом 91","ps":["§Псало́м пі́сні, в день субо́тний, 91.","@2 Благо єсть іспові́датися Го́сподеві і пі́ти і́мені Твоєму́, Ви́шній;","@3 возвіща́ти зау́тра ми́лость Твою́ і і́стину Твою́ на вся́ку нощ,","@4 в десятостру́ннім псалти́рі с пі́снію в гу́слех.","@5 Я́ко возвесели́л м'я єси́, Го́споди, в творе́нії Твоє́м, і в ді́ліх руку́ Твоє́ю возра́дуюся.","@6 Я́ко возвели́чишася діла́ Твоя́, Го́споди; зіло́ углуби́шася помишле́нія Твоя́.","@7 Муж безу́мен не позна́єть, і неразуми́в не разумі́єть сих.","@8 Внегда́ прозябо́ща грі́шници я́ко трава́, і пронико́ша всі ді́лающії беззако́ніє, я́ко да потреб'я́ться в вік ві́ка;","@9 Ти же Ви́шній во вік, Го́споди.","@10 Я́ко се вразі́ Твої́, Го́споди, я́ко се вразі́ Твої́ поги́бнуть і рази́дуться всі ді́лающії беззако́ніє.","@11 І вознесе́ться я́ко єдиноро́га рог мой, і ста́рость моя́ в єле́ї масти́ті;","@12 і воззрі́ о́ко моє́ на враги́ моя́, і востаю́щия на м'я лука́внующия усли́шить у́хо моє́.","@13 Пра́ведник, я́ко фі́ніx процвіте́ть, я́ко кедр, і́же в Лива́ні, умно́житься.","@14 Насажде́ні в дому́ Госпо́дні во дво́ріх Бо́га на́шего процвіту́ть;","@15 єще́ умно́жаться в ста́рості масти́ті, і благоприє́млюще бу́дуть.","@16 Да возвістя́ть, я́ко прав Госпо́дь Бог наш, і ність непра́вди в Нем."]},{"h":"Псалом 92","ps":["§В день предсубо́тний, внегда́ насели́ся земля́, хвала́ пі́сні Дави́ду, 92.","@1 Госпо́дь воцари́ся, в лі́поту облече́ся; облече́ся Госпо́дь в си́лу і препоя́сася; і́бо утверди́ вселе́нную, я́же не подви́житься.","@2 Гото́в престо́л Твой отто́лі; от ві́ка Ти єси́.","@3 Воздвиго́ша рі́ки, Го́споди, воздвиго́ша рі́ки гла́си своя́;","@4 во́зьмуть рі́ки сотре́нія своя́, от гласо́в вод мно́гих.","@5 Ди́вни висоти́ морські́я; ди́вен в висо́ких Госпо́дь.","@6 Свиді́нія Твоя́ уві́ришася зіло́. До́му Твоєму́ подоба́єть святи́ня, Го́споди, в долготу́ дній."]},{"h":"Псалом 93","ps":["§Псало́м Дави́ду, в четве́ртий субо́ти, 93.","@1 Бог отмще́ній Госпо́дь, Бог отмще́ній не обину́лся єсть.","@2 Вознеси́ся, судя́й землі́, возда́ждь воздая́ніє го́рдим.","@3 Доко́лі грі́шници, Го́споди, доко́лі грі́шници восхва́ляться?","@4 Провіща́ють і возглаго́лють непра́вду, возглаго́лють всі ді́лающії беззако́ніє?","@5 Лю́ди Твоя́, Го́споди, смири́ша, і достоя́ніє Твоє́ озло́биша:","@6 вдови́цю і си́ра умори́ша, і прише́лця уби́ша,","@7 і рі́ша: не у́зрить Госпо́дь, ніже́ уразумі́єть Бог Іа́ковль.","@8 Разумі́йте же, безу́мнії в лю́дех, і бу́її ні́когда, умудрі́теся;","@9 насажде́й у́хо, не сли́шить ли? Іли́ созда́вий о́ко, не сматря́єть ли?","@10 Наказу́яй язи́ки, не обличи́ть ли, уча́й челові́ка ра́зуму?","@11 Госпо́дь вість помишле́нія челові́чеськая, я́ко суть су́єтна.","@12 Блаже́н челові́к, єго́же а́ще нака́жеши, Го́споди, і от зако́на Твоєго́ научи́ши єго́;","@13 укроти́ти єго́ от дній лю́тих, до́ндеже ізри́ється грі́шному я́ма.","@14 Я́ко не отри́неть Госпо́дь люді́й Свої́х, і достоя́нія Своєго́ не оста́вить;","@15 до́ндеже пра́вда обрати́ться на суд, і держа́щіїся єя́ всі пра́вії се́рдцем.","@16 Кто воста́неть мі на лука́внующия? Іли́ кто спредста́неть мі на ді́лающия беззако́ніє?","@17 А́ще не Госпо́дь помо́гл би мі, вма́лі всели́лася би во ад душа́ моя́.","@18 А́ще глаго́лах: подви́жеся нога́ моя́, ми́лость Твоя́, Го́споди, помога́ше мі:","@19 по мно́жеству болі́зней мої́х в се́рдці моє́м, утіше́нія Твоя́ возвесели́ша ду́шу мою́.","@20 Да не пребу́деть Тебі́ престо́л беззако́нія, созида́яй труд на повелі́ніє.","@21 Улов'я́ть на ду́шу пра́ведничу, і кров непови́нную осу́дять.","@22 І бисть мні Госпо́дь в прибі́жище, і Бог мой в по́мощ упова́нія моєго́;","@23 і возда́сть їм Госпо́дь беззако́ніє їх, і по лука́вствію їх погуби́ть я Госпо́дь Бог наш.","§Сла́ва:"]},{"h":"Псалом 94","ps":["§Хвала́ пі́сні Дави́ду, не надпи́сан у євре́й, 94.","@1 Прийді́те, возра́дуємся Го́сподеві, воскли́кнем Бо́гу Спаси́телю на́шему;","@2 предвари́м лице́ Єго́ во іспові́данії, і во псалмі́х воскли́кнем Єму́;","@3 я́ко Бог ве́лій Госпо́дь, і Цар ве́лій по всей землі́;","@4 я́ко в руці́ Єго́ всі конці́ землі́, і висоти́ гор Того́ суть.","@5 Я́ко Того́ єсть мо́ре, і Той сотвори́ є, і су́шу ру́ці Єго́ созда́сті.","@6 Прийді́те, поклоні́мся і припаде́м Єму́, і воспла́чемся пред Го́сподем сотво́ршим нас;","@7 я́ко Той єсть Бог наш, і ми лю́діє па́житі Єго́ і о́вці руки́ Єго́. Днесь а́ще глас Єго́ усли́шіте,","@8 не ожесточі́те серде́ць ва́ших, я́ко в прогні́ванії, по дні іскуше́нія в пусти́ні;","@9 в о́ньже⁽1⁾ іскуси́ша М'я отці́ ва́ші, іскуси́ша М'я, і ви́діша діла́ Моя́.","@10 Чети́редесять літ негодова́х ро́да того́, і ріх: при́сно заблужда́ють се́рдцем, ті́ї же не позна́ша путі́й Мої́х;","@11 я́ко кля́хся во гні́ві Моє́м, а́ще вни́дуть в поко́й Мой."]},{"h":"Псалом 95","ps":["§Хвала́ пі́сні Дави́ду, внегда́ дом созида́шеся по пліне́нії, не надпи́сан у євре́й, 95.","@1 Воспо́йте Го́сподеві піснь но́ву, воспо́йте Го́сподеві вся земля́;","@2 воспо́йте Го́сподеві, благослові́те і́м'я Єго́; благовісті́те день от дне спасе́ніє Єго́.","@3 Возвісті́те во язи́ціх сла́ву Єго́, во всіх лю́дех чудеса́ Єго́.","@4 Я́ко ве́лій Госпо́дь і хва́лен зіло́, стра́шен єсть над всі́ми бо́ги.","@5 Я́ко всі бо́зі — язи́к бі́сове; Госпо́дь же небеса́ сотвори́.","@6 Іспові́даніє і красота́ пред Ним, святи́ня і великолі́піє во святи́лі Єго́.","@7 Принесі́те Го́сподеві, оте́чествія язи́к, принесі́те Го́сподеві сла́ву і честь.","@8 принесі́те Го́сподеві сла́ву і́мені Єго́; возьмі́те же́ртви і вході́те во двори́ Єго́.","@9 Поклоні́теся Го́сподеві во дворі́ святі́м Єго́. Да подви́житься от лиця́ Єго́ вся земля́.","@10 Рці́те во язи́ціх, я́ко Госпо́дь воцари́ся; і́бо іспра́ви вселе́нную, я́же не подви́житься; су́дить лю́дем пра́востію.","@11 Да возвеселя́ться небеса́, і ра́дується земля́; да подви́житься мо́ре і ісполне́ніє єго́;","@12 возра́дуються поля́ і вся я́же на них; тогда́ возра́дуються вся древа́ дубра́вная","@13 от лиця́ Госпо́дня, я́ко гряде́ть, я́ко гряде́ть суди́ти землі́; суди́ти вселе́нній в пра́вду і лю́дем і́стиною Своє́ю."]},{"h":"Псалом 96","ps":["§Псало́м Дави́ду, єгда́ земля́ єго́ устроя́шеся, не надпи́сан у євре́й, 96.","@1 Госпо́дь воцари́ся, да ра́дується земля́, да веселя́ться о́строві мно́зі.","@2 О́блак і мрак о́крест Єго́; пра́вда і судьба́ — ісправле́ніє Престо́ла Єго́.","@3 Огнь пред Ним преди́деть і попали́ть о́крест враги́ Єго́.","@4 Освіти́ша мо́лнія Єго́ вселе́нную; ви́ді і подви́жеся земля́.","@5 Го́ри, я́ко воск, раста́яша от лиця́ Госпо́дня, от лиця́ Го́спода всея́ землі́.","@6 Возвісти́ша небеса́ пра́вду Єго́, і ви́діша всі лю́діє сла́ву Єго́.","@7 Да постидя́ться всі кла́няющіїся істука́нним, хва́лящіїся о і́доліх свої́х; поклоні́теся Єму́, всі а́нгели Єго́.","@8 Сли́ша і возвесели́ся Сіо́н, і возра́довашася дще́рі іуде́йськия, суде́б ра́ди Твої́х, Го́споди;","@9 я́ко Ти Госпо́дь Ви́шній над все́ю земле́ю, зіло́ превозне́слся єси́ над всі́ми бо́ги.","@10 Лю́б'ящії Го́спода, ненави́діте зла́я; храни́ть Госпо́дь ду́ші преподо́бних Свої́х, із руки́ грі́шничі ізба́вить я.","@11 Світ возсія́ пра́веднику, і пра́вим се́рдцем весе́ліє.","@12 Веселі́теся, пра́веднії, о Го́споді, і іспові́дайте па́м'ять святи́ні Єго́.","§Сла́ва:"]},{"h":"Псалом 97","ps":["§Псало́м Дави́ду, 97.","@1 Воспо́йте Го́сподеві піснь но́ву, я́ко ди́вна сотвори́ Госпо́дь; спасе́ Єго́ десни́ця Єго́ і ми́шця свята́я Єго́.","@2 Сказа́ Госпо́дь спасе́ніє Своє́, пред язи́ки откри́ пра́вду Свою́.","@3 Пом'яну́ ми́лость Свою́ Іа́кову і і́стину Свою́ до́му Ізра́їлеву; ви́діша всі конці́ землі́ спасе́ніє Бо́га на́шего.","@4 Воскли́кніте Бо́гові, вся земля́, воспо́йте і ра́дуйтеся і по́йте.","@5 По́йте Го́сподеві в гу́слех, в гу́слех і гла́сі псало́мсті,","@6 в труба́х ко́ваних і гла́сом труби́ ро́жани; вострубі́те пред Царе́м Го́сподем.","@7 Да подви́житься мо́ре і ісполне́ніє єго́, вселе́нная і всі живу́щії на ней.","@8 Рі́ки воспле́щуть руко́ю вку́пі, го́ри возра́дуються","@9 от лиця́ Госпо́дня, я́ко гряде́ть, я́ко і́деть суди́ти землі́; суди́ти вселе́нній в пра́вду, і лю́дем пра́востію."]},{"h":"Псалом 98","ps":["§Псало́м Дави́ду, 98.","@1 Госпо́дь воцари́ся — да гні́ваються лю́діє; сідя́й на херуви́міх — да подви́житься земля́.","@2 Госпо́дь в Сіо́ні вели́к і висо́к єсть над всі́ми людьми́.","@3 Да іспові́дяться і́мені Твоєму́ вели́кому, я́ко стра́шно і свя́то єсть.","@4 І честь царе́ва суд лю́бить; Ти угото́вал єси́ правоти́, суд і пра́вду во Іа́кові Ти сотвори́л єси́.","@5 Возносі́те Го́спода Бо́га на́шего і покланя́йтеся подно́жію но́гу Єго́, я́ко свя́то єсть.","@6 Моїсе́й і Ааро́н во ієре́ех Єго́, і Самуї́л в призива́ющих і́м'я Єго́; призива́ху Го́спода, і Той послу́шаше їх.","@7 В столпі́ о́блачні глаго́лаше к ним, я́ко храня́ху свиді́нія Єго́ і повелі́нія Єго́, я́же даде́ їм.","@8 Го́споди Бо́же наш, Ти послу́шал єси́ їх; Бо́же, Ти ми́лостив бива́л єси́ їм і мща́я на вся начина́нія їх.","@9 Возносі́те Го́спода Бо́га на́шего і покланя́йтеся в горі́ святі́й Єго́; я́ко Свят Госпо́дь Бог наш."]},{"h":"Псалом 99","ps":["§Псало́м Дави́ду во іспові́даніє, 99.","@1 Воскли́кніте Бо́гові, вся земля́;","@2 рабо́тайте Го́сподеві в весе́лії, вни́діте пред Ним в ра́дості.","@3 Уві́діте, я́ко Госпо́дь — Той єсть Бог наш; Той сотвори́ нас, а не ми; ми же лю́діє Єго́ і о́вці па́житі Єго́.","@4 Вни́діте во врата́ Єго́ во іспові́данії, во двори́ Єго́ в пі́ніїх; іспові́дайтеся Єму́, хвалі́те і́м'я Єго́.","@5 Я́ко Благ Госпо́дь, в вік ми́лость Єго́, і да́же до ро́да і ро́да і́стина Єго́."]},{"h":"Псалом 100","ps":["§Псало́м Дави́ду, 100.","@1 Ми́лость і суд воспою́ Тебі́, Го́споди;","@2 пою́ і разумі́ю в путі́ непоро́чні; когда́ при́йдеши ко мні? Прехожда́х в незло́бії се́рдця моєго́ посреді́ до́му моєго́.","@3 Не предлага́х пред очи́ма мої́ма вещ законопресту́пную; творя́щия преступле́ніє возненави́діх;","@4 не прильпе́ мні се́рдце стропти́во; уклоня́ющагося от мене́ лука́ваго не позна́х.","@5 Оклевета́ющаго тай і́скренняго своєго́, cего́ ізгоня́х; го́рдим о́ком і неси́тим се́рдцем, с сим не ядя́х.","@6 О́чі мої́ на ві́рния землі́, посажда́ти я со мно́ю; ходя́й по путі́ непоро́чну, сей мі служа́ше.","@7 Не живя́ше посреді́ до́му моєго́ творя́й горди́ню; глаго́ляй непра́ведная не ісправля́ше пред очи́ма мої́ма.","@8 Воу́трія ізбива́х вся грі́шния землі́, є́же потреби́ти от гра́да Госпо́дня вся ді́лающия беззако́ніє.","§Сла́ва:"]},{"h":"Після 13-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 8:","ps":["О́ком благоутро́бним, Го́споди, виждь моє́ смире́ніє, я́ко пома́лі жизнь моя́ іждива́ється, і от діл ність мні спасе́нія. Сего́ ра́ди молю́ся: о́ком благоутро́бним, Го́споди, виждь моє́ смире́ніє, і спаси́ м'я.","Сла́ва: Я́ко Судії́ предстоя́щу, попеци́ся душе́, і стра́шнаго дне час помишля́й; суд бо неми́лостив єсть не сотво́ршим ми́лости. Возопи́й у́бо Христу́ Бо́гу; Сердцеві́дче, согріши́х, пре́жде да́же не осу́диши, поми́луй м'я.","І ни́ні: Стра́шнаго Твоєго́ і гро́знаго і неуми́тнаго Суда́, Христе́, во умі́ приє́м день і час трепе́щу, я́ко злоді́й, студа́ діла́ і дія́нія імі́я лю́тая, я́же єди́н аз соді́ях прилі́жно. Ті́мже стра́хом припа́даю Тебі́, вопія́ болі́зненно: моли́твами Ро́ждшия Тя, Многоми́лостиве, спаси́ м'я."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Святи́й, І́же в ви́шніх живи́й і всеви́дящим Твої́м о́ком призира́яй на всю твар, Тебі́ приклони́хом ви́ю душі́ і тілесе́, і Тебі́ мо́лимся, Святи́й святи́х: простри́ ру́ку Твою́ неви́димую от Свята́го жили́ща Твоєго́ і благослови́ вся ни. І а́ще что к Тебі́ согріши́хом во́лею і нево́лею, я́ко Благ і Человіколю́бець Бог прости́, да́руяй нам і ми́рная блага́я Твоя́. Твоє́ бо єсть є́же ми́ловати і спаса́ти, Бо́же наш, і Тебі́ сла́ву возсила́єм, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[іді́же]</span>"]},{"u":"Кафизма 14","e":"Kathisma 14","secs":[{"h":"Псалом 101","ps":["§Моли́тва ни́щаго, єгда́ уни́єть і пред Го́сподем проліє́ть моле́ніє своє́, 101.","@2 Го́споди, усли́ши моли́тву мою́, і вопль мой к Тебі́ да при́йдеть.","@3 Не отврати́ лиця́ Твоєго́ от мене́; в о́ньже а́ще день скорблю́, приклони́ ко мні у́хо Твоє́; в о́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я.","@4 Я́ко ізчезо́ша, я́ко дим, дні́є мої́, і ко́сті моя́, я́ко суши́ло, сосхо́шася.","@5 Уя́звлен бих, я́ко трава́, і і́зсше се́рдце моє́, я́ко заби́х сні́сти хліб мой.","@6 От гла́са воздиха́нія моєго́ прильпе́ кость моя́ пло́ті моє́й.","@7 Уподо́бихся нея́сити пусти́нній, бих, я́ко нощни́й вран на ни́рищі⁽1⁾.","@8 Бдіх і бих, я́ко пти́ця осо́б'ящаяся на зді⁽2⁾.","@9 Весь день поноша́ху мі вразі́ мої́, і хва́лящії м'я мно́ю⁽3⁾ кленя́хуся.","@10 Зане́ пе́пел, я́ко хліб, ядя́х і питіє́ моє́ с пла́чем растворя́х,","@11 от лиця́ гні́ва Твоєго́ і я́рости Твоєя́ — я́ко возне́с низве́ргл м'я єси́.","@12 Дні́є мої́ я́ко сінь уклони́шася, і аз я́ко сі́но ізсхо́х.","@13 Ти же, Го́споди, во вік пребива́єши, і па́м'ять Твоя́ в род і род.","@14 Ти воскре́с уще́дриши Сіо́на; я́ко вре́м'я уще́дрити єго́, я́ко при́йде вре́м'я.","@15 Я́ко благоволи́ша раби́ Твої́ ка́меніє⁽4⁾ єго́, і персть єго́ уще́дрять.","@16 І убоя́ться язи́ци і́мене Госпо́дня, і всі ца́ріє зе́мстії сла́ви Твоєя́;","@17 я́ко сози́ждеть Госпо́дь Сіо́на і яви́ться во сла́ві Своє́й.","@18 Призрі́ на моли́тву смире́нних і не унічижи́ моле́нія їх.","@19 Да напи́шеться сіє́ в род ін, і лю́діє зи́ждемії восхва́лять Го́спода;","@20 я́ко прини́че с висоти́ святи́я Своєя́, Госпо́дь с небесе́ на зе́млю призрі́,","@21 усли́шати воздиха́ніє окова́нних, разріши́ти си́ни умерщвле́нних;","@22 возвісти́ти в Сіо́ні і́м'я Госпо́днє і хвалу́ Єго́ во Ієрусали́мі,","@23 внегда́ собра́тися лю́дем вку́пі і царе́м, є́же рабо́тати Го́сподеві.","@24 Отвіща́ Єму́ на путі́ крі́пости Єго́; умале́ніє дній мої́х возвісти́ мі;","@25 не возведи́ мене́ во преполове́ніє дній мої́х; в ро́ді родо́в лі́та Твоя́.","@26 В нача́ліх Ти, Го́споди, зе́млю основа́л єси́, і діла́ руку́ Твоє́ю суть небеса́.","@27 Та поги́бнуть, Ти же пребива́єши; і вся, я́ко ри́за, обетша́ють, і, я́ко оде́жду, свіє́ши я, і ізміня́ться.","@28 Ти же То́йжде єси́, і лі́та Твоя́ не оскуді́ють.","@29 Си́нове раб Твої́х вселя́ться, і сі́м'я їх во вік іспра́виться."]},{"h":"Псалом 102","ps":["§Псало́м Дави́ду, 102.","@1 Благослови́, душе́ моя́, Го́спода, і, вся вну́тренняя моя́, і́м'я свято́є Єго́;","@2 благослови́, душе́ моя́, Го́спода, і не забива́й всіх воздая́ній Єго́;","@3 очища́ющаго вся беззако́нія твоя́, ізціля́ющаго вся неду́ги твоя́,","@4 ізбавля́ющаго от істлі́нія живо́т твой, вінча́ющаго тя ми́лостію і щедро́тами,","@5 ісполня́ющаго во благи́х жела́ніє твоє́; обнови́ться, я́ко о́рля, ю́ность твоя́.","@6 Творя́й ми́лостині Госпо́дь і судьбу́ всім оби́димим.","@7 Сказа́ путі́ Своя́ Моїсе́йові, синово́м Ізра́їлевим хоті́нія Своя́.","@8 Щедр і ми́лостив Госпо́дь, долготерпіли́в і многоми́лостив.","@9 Не до конця́ прогні́вається, ніже́ во вік вражду́єть;","@10 не по беззако́нієм на́шим сотвори́л єсть нам, ніже́ по гріхо́м на́шим возда́л єсть нам.","@11 Я́ко по висоті́ небе́сній от землі́, утверди́л єсть Госпо́дь ми́лость Свою́ на боя́щихся Єго́;","@12 єли́ко отстоя́ть восто́ци от за́пад, уда́лил єсть от нас беззако́нія на́ша.","@13 Я́коже ще́дрить оте́ць си́ни, уще́дри Госпо́дь боя́щихся Єго́.","@14 Я́ко Той позна́ созда́ніє на́ше, пом'яну́, я́ко персть єсьми́.","@15 Челові́к — я́ко трава́, дні́є єго́ — я́ко цвіт се́льний, та́ко оцвіте́ть;","@16 я́ко дух про́йде в нем, і не бу́деть, і не позна́єть ктому́ мі́ста своєго́.","@17 Ми́лость же Госпо́дня от ві́ка і до ві́ка на боя́щихся Єго́,","@18 і пра́вда Єго́ на сині́х сино́в, храня́щих заві́т Єго́ і по́мнящих за́повіді Єго́ твори́ти я.","@19 Госпо́дь на небесі́ угото́ва Престо́л Свой, і Ца́рство Єго́ всі́ми облада́єть.","@20 Благослові́те Го́спода, всі а́нгели Єго́, си́льнії крі́постію, творя́щії сло́во Єго́, усли́шати глас слове́с Єго́.","@21 Благослові́те Го́спода, вся си́ли Єго́, слуги́ Єго́, творя́щії во́лю Єго́.","@22 Благослові́те Го́спода, вся діла́ Єго́ на вся́ком мі́сті влади́чества Єго́; благослови́, душе́ моя́, Го́спода."]},{"h":"Псалом 103","ps":["§Псало́м Дави́ду, о мирсті́м битії́, 103.","@1 Благослови́, душе́ моя́, Го́спода. Го́споди Бо́же мой, возвели́чился єси́ зіло́; во іспові́даніє і в велелі́поту обле́клся єси́;","@2 одія́йся сві́том, я́ко ри́зою, простира́яй не́бо, я́ко ко́жу;","@3 покрива́яй вода́ми преви́спренняя Своя́, полага́яй о́блаки на восхожде́ніє Своє́, ходя́й на крилу́ ві́треню;","@4 творя́й а́нгели Своя́ ду́хи, і слуги́ Своя́ — пла́мень о́гненний;","@5 основа́яй зе́млю на тве́рді єя́; не преклони́ться в вік ві́ка.","@6 Бе́здна, я́ко ри́за, одія́ніє єя́, на гора́х ста́нуть во́ди;","@7 от запреще́нія Твоєго́ побі́гнуть, от гла́са гро́ма Твоєго́ убоя́ться.","@8 Восхо́дять го́ри, і низхо́дять поля́, в мі́сто, є́же основа́л єси́ їм.","@9 Преді́л положи́л єси́, єго́же не пре́йдуть, ніже́ обратя́ться покри́ти зе́млю.","@10 Посила́яй істо́чники в де́брех, посреді́ гор про́йдуть во́ди.","@11 Напая́ють вся зві́рі се́льния, ждуть⁽5⁾ она́гри⁽6⁾ в жа́жду свою́.","@12 На тих пти́ці небе́сния привита́ють; от среди́ ка́менія дадя́ть глас.","@13 Напая́яй го́ри от преви́спренних Свої́х; от плода́ діл Твої́х наси́титься земля́.","@14 Прозяба́яй траву́ ското́м, і злак на слу́жбу челові́ком, ізвести́ хліб от землі́;","@15 і вино́ весели́ть се́рдце челові́ка, ума́стити лице́ єле́єм; і хліб се́рдце челові́ка укріпи́ть.","@16 Наси́тяться древа́ польська́я, ке́дри лива́нстії, ї́хже єси́ насади́л;","@17 та́мо пти́ці вогніздя́ться, єроді́єво⁽7⁾ жили́ще предводи́тельствуєть ї́ми.","@18 Го́ри висо́кия єле́нем, ка́мень — прибі́жище за́яцем.","@19 Сотвори́л єсть луну́ во времена́; со́лнце позна́ за́пад свой.","@20 Положи́л єси́ тьму, і бисть нощ, в не́йже про́йдуть всі зві́ріє дубра́внії,","@21 ски́мні рика́ющії восхи́тити і взиска́ти от Бо́га пи́щу себі́.","@22 Возсія́ со́лнце, і собра́шася, і в ло́жах свої́х ля́гуть.","@23 Ізи́деть челові́к на ді́ло своє́ і на ді́ланіє своє́ до ве́чера.","@24 Я́ко возвели́чишася діла́ Твоя́, Го́споди; вся прему́дростію сотвори́л єси́; іспо́лнися земля́ тва́рі Твоєя́.","@25 Сіє́ мо́ре вели́коє і простра́нноє; та́мо га́ди, ї́хже ність числа́, живо́тная ма́лая с вели́кими;","@26 та́мо кораблі́ препла́вають, змій сей, єго́же созда́л єси́ руга́тися єму́.","@27 Вся к Тебі́ ча́ють, да́ти пи́щу їм во бла́го вре́м'я.","@28 Да́вшу Тебі́ їм, соберу́ть; отве́рзшу Тебі́ ру́ку, вся́чеськая іспо́лняться бла́гости;","@29 отвра́щшу же Тебі́ лице́, возм'яту́ться; оти́меши дух їх, і ізче́знуть і в персть свою́ возвратя́ться;","@30 по́слеши Ду́ха Твоєго́, і сози́ждуться, і обнови́ши лице́ землі́.","@31 Бу́ди сла́ва Госпо́дня во ві́ки; возвесели́ться Госпо́дь о ді́ліх Свої́х;","@32 призира́яй на зе́млю і творя́й ю трясти́ся; прикаса́яйся гора́м, і дим'я́ться.","@33 Воспою́ Го́сподеві в животі́ моє́м, пою́ Бо́гу моєму́, до́ндеже єсьм;","@34 да услади́ться Єму́ бесі́да моя́, аз же возвеселю́ся о Го́споді.","@35 Да ізче́знуть грі́шници от землі́, і беззако́нници, я́коже не би́ти їм. Благослови́, душе́ моя́, Го́спода.","§Сла́ва:"]},{"h":"Псалом 104","ps":["§Аллилу́я, 104.","@1 Іспові́дайтеся Го́сподеві і призива́йте і́м'я Єго́, возвісті́те во язи́ціх діла́ Єго́;","@2 воспо́йте Єму́ і по́йте Єму́, пові́діте вся чудеса́ Єго́.","@3 Хвалі́теся о і́мені святі́м Єго́; да возвесели́ться се́рдце і́щущих Го́спода;","@4 взищі́те Го́спода і утверді́теся, взищі́те лиця́ Єго́ ви́ну.","@5 Пом'яні́те чудеса́ Єго́, я́же сотвори́, чудеса́ Єго́ і судьби́ уст Єго́,","сі́м'я Авраа́мле, раби́ Єго́, си́нове Іа́ковлі — ізбра́ннії Єго́.","@7 Той — Госпо́дь Бог наш: по всей землі́ судьби́ Єго́.","@8 Пом'яну́ в вік заві́т Свой, сло́во, є́же запові́да в ти́сящі родо́в,","@9 є́же завіща́ Авраа́му, і кля́тву Свою́ Ісаа́ку;","@10 і поста́ви ю Іа́кову в повелі́ніє і Ізра́їлю в заві́т ві́чен,","@11 глаго́ля: тебі́ дам зе́млю Ханаа́ню, у́же достоя́нія ва́шего.","@12 Внегда́ би́ти їм ма́лим число́м, малі́йшим і прише́льцем в ней,","@13 і прейдо́ша от язи́ка в язи́к і от ца́рствія в лю́ди і́ни;","@14 не оста́ви челові́ка оби́діти їх і обличи́ о них царі́;","@15 не прикаса́йтеся пома́занним Мої́м, і во проро́ціх Мої́х не лука́внуйте.","@16 І призва́ глад на зе́млю, вся́ко утвержде́ніє хлі́бноє сотри́.","@17 Посла́ пред ни́ми челові́ка; в раба́ про́дан бисть Іо́сиф.","@18 Смири́ша во око́вах но́зі єго́, желі́зо про́йде душа́ єго́,","@19 до́ндеже при́йде сло́во Єго́; сло́во Госпо́днє разжже́ єго́.","@20 Посла́ цар і разріши́ єго́, князь люді́й, і оста́ви⁽8⁾ єго́.","@21 Поста́ви єго́ господи́на до́му своєму́ і кня́зя всему́ стяжа́нію своєму́,","@22 наказа́ти кня́зі єго́, я́ко себе́, і ста́рці єго́ умудри́ти.","@23 І вни́де Ізра́їль во Єги́пет, і Іа́ков прише́льствова в зе́млю Ха́мову.","@24 І возрасти́ лю́ди Своя́ зіло́ і укріпи́ я па́че враго́в їх.","@25 Преврати́ се́рдце їх возненави́діти лю́ди Єго́, лесть сотвори́ти в рабі́х Єго́.","@26 Посла́ Моїсе́я, раба́ Своєго́, Ааро́на, єго́же ізбра́ Себі́;","@27 положи́ в них словеса́ зна́меній Свої́х і чуде́с Свої́х в землі́ Ха́мові.","@28 Посла́ тьму і помрачи́, я́ко преогорчи́ша словеса́ Єго́.","@29 Преложи́ во́ди їх в кров і ізмори́ ри́би їх.","@30 Воскипі́ земля́ їх жа́бами в сокро́вищницях царе́й їх.","@31 Рече́, і прийдо́ша пе́сія му́хи і скни́пи во вся преді́ли їх.","@32 Положи́ дожди́ їх гра́ди, огнь попаля́ющ в землі́ їх;","@33 і порази́ виногра́ди їх і смо́кви їх, і сотри́ вся́коє дре́во преді́л їх.","@34 Рече́, і прийдо́ша пру́зі і гу́сениці, ї́мже не бі числа́,","@35 і снідо́ша вся́ку траву́ в землі́ їх, і поядо́ша всяк плод землі́ їх.","@36 І порази́ вся́каго пе́рвенця в землі́ їх, нача́ток вся́каго труда́ їх;","@37 і ізведе́ я с сребро́м і зла́том; і не бі в колі́ніх їх боля́й.","@38 Возвесели́ся Єги́пет во ісхожде́нії їх; я́ко нападе́ страх їх на ня.","@39 Распростре́ о́блак в покро́в їм, і огнь, є́же просвіти́ти їм но́щію.","@40 Проси́ша, і прийдо́ша кра́стелі⁽9⁾, і хлі́ба небе́снаго наси́ти я;","@41 разве́рзе ка́мень, і потеко́ша во́ди, потеко́ша в безво́дних рі́ки;","@42 я́ко пом'яну́ сло́во свято́є Своє́, є́же ко Авраа́му, рабу́ Своєму́.","@43 І ізведе́ лю́ди Своя́ в ра́дості і ізбра́нния Своя́ в весе́лії.","@44 І даде́ їм страни́ язи́к, і труди́ люді́й наслі́доваша;","@45 я́ко да сохраня́ть оправда́нія Єго́ і зако́на Єго́ взи́щуть.","§Сла́ва:"]},{"h":"Після 14-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 8:","ps":["Я́ко блудни́ця, припа́даю Ті, да прийму́ оставле́ніє, і вмі́сто ми́ра сле́зи от се́рдця приношу́ Ті, Христе́ Бо́же; да, я́ко о́ную, уще́дриши м'я, Спа́се, і пода́си очище́ніє гріхо́в. Я́ко о́ная бо зову́ Ті: ізба́ви м'я от тимі́нія діл мої́х.","Сла́ва: Почто́ не помишля́єши, душе́ моя́, сме́рти? Почто́ не обраща́єшися про́чеє ко ісправле́нію, пре́жде труби́ глаше́нія на суді́? Тогда́ ність вре́м'я покая́нія. Прийми́ во умі́ митаря́ і блудни́цю, зову́щия: согріши́х Ті, Го́споди, поми́луй м'я.","І ни́ні: Я́ко превосходя́щая воі́стину Рождество́м Твої́м Си́ли Небе́сния, Присноді́во Богоро́дице, і́же Тобо́ю Бо́жество́м обогати́вшеся, непреста́нно Тя велича́єм."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Благодари́м Тя, Го́споди, Бо́же наш спасе́ній на́ших, я́ко вся твори́ши во благодія́нія жи́зні на́шея; я́ко упоко́їл єси́ нас в преше́дшем нощно́м вре́мені, і воздви́гл єси́ нас от ло́жей на́ших, і поста́вил єси́ нас в поклоне́ніє честна́го і сла́внаго і́мене Твоєго́. Ті́мже мо́лимся Тебі́ Го́споди: даждь нам благода́ть і си́лу, да сподо́бимся Тебі́ пі́ти разу́мно, і моли́тися непреста́нно, і ви́ну к Тебі́ зрі́ти, Спаси́телю і Благоді́телю на́ших душ, стра́хом і тре́петом своє́ спасе́ніє ді́йствующе. Усли́ши у́бо і поми́луй, Благоутро́бне, нас, сокруши́ под но́ги на́ша неви́димия ра́тники і враги́; прийми́ я́же по си́лі на́шей благодаре́нія; даждь нам благода́ть і си́лу во отверзе́ніє уст на́ших і научи́ нас оправда́нієм Твої́м, я́ко что помо́лимся, я́коже подоба́єть, не ві́ми, а́ще не Ти, Го́споди, Ду́хом Твої́м Святи́м наста́виши ни. А́ще же что согріши́хом да́же до настоя́щаго часа́, сло́вом, іли́ ді́лом, іли́ помишле́нієм, во́лею, іли́ нево́лею, осла́би, оста́ви, прости́. А́ще бо беззако́нія на́зриши, Го́споди, Го́споди, кто постої́ть? Я́ко у Тебе́ очище́ніє єсть, у Тебе́ ізбавле́ніє. Ти єси́ єди́н Свят, Помо́щник крі́пкий і Защи́титель жи́зні на́шея, і Тя благослови́м во вся ві́ки, амі́нь."]}],"notes":["<span class=''>[на разва́лині]</span>","<span class=''>[на кро́ві]</span>","<span class=''>[на м'я]</span>","<span class=''>[о ка́менії]</span>","<span class=''>[воспри́ймуть]</span>","","","<span class=''>[отпусти́]</span>",""]},{"u":"Кафизма 15","e":"Kathisma 15","secs":[{"h":"Псалом 105","ps":["§Аллилу́я, 105.","@1 Іспові́дайтеся Го́сподеві, я́ко благ, я́ко во вік ми́лость Єго́.","@2 Кто возглаго́леть си́ли Госпо́дні, сли́шани сотвори́ть вся хвали́ Єго́?","@3 Блаже́нні храня́щії суд і творя́щії пра́вду во вся́коє вре́м'я.","@4 Пом'яни́ нас, Го́споди, во благоволе́нії люді́й Твої́х, посіти́ нас спасе́нієм Твої́м,","@5 ви́діти во бла́гості ізбра́нния Твоя́, возвесели́тися в весе́лії язи́ка Твоєго́, хвали́тися с достоя́нієм Твої́м.","@6 Согріши́хом со отці́ на́шими, беззако́нновахом, непра́вдовахом;","@7 отці́ на́ші во Єги́пті не разумі́ша чуде́с Твої́х, ні пом'яну́ша мно́жества ми́лости Твоєя́; і преогорчи́ша восходя́ще в Чермно́є мо́ре.","@8 І спасе́ їх і́мене Своєго́ ра́ди, сказа́ти си́лу Свою́;","@9 і запрети́ Чермно́му мо́рю, і ізся́че; і наста́ви⁽1⁾ я в бе́здні я́ко в пусти́ні.","@10 І спасе́ я із руки́ ненави́дящих і ізба́ви я із руки́ враго́в.","@11 Покри́ вода́ стужа́ющия їм; ні єди́н от них ізби́сть.","@12 І ві́роваша словесі́ Єго́ і воспі́ша хвалу́ Єго́.","@13 Ускори́ша, заби́ша діла́ Єго́, не стерпі́ша сові́та Єго́;","@14 і похоті́ша жела́нію в пусти́ні і іскуси́ша Бо́га в безво́дній.","@15 І даде́ їм проше́ніє їх, посла́ си́тость в ду́ші їх.","@16 І прогні́ваша Моїсе́я в стану́, Ааро́на, свята́го Госпо́дня.","@17 Отве́рзеся земля́ і пожре́ Дафа́на і покри́ на со́нмищи Авиро́на;","@18 і разжже́ся огнь в со́нмі їх, пла́мень попали́ грі́шники.","@19 І сотвори́ша тельця́ в Хори́ві і поклони́шася істука́нному;","@20 і ізміни́ша сла́ву Єго́ в подо́біє тельця́ яду́щаго траву́.","@21 І заби́ша Бо́га спаса́ющаго їх, сотво́ршаго ве́лія во Єги́пті,","@22 чудеса́ в землі́ Ха́мові, стра́шная в мо́рі Чермні́м.","@23 І рече́ потреби́ти їх, а́ще не би Моїсе́й ізбра́нний Єго́ стал в сокруше́нії пред Ним, возврати́ти я́рость Єго́, да не погуби́ть їх.","@24 І унічижи́ша зе́млю жела́нную, не я́ша ві́ри словесі́ Єго́;","@25 і поропта́ша в селе́ніїх свої́х, не усли́шаша гла́са Госпо́дня.","@26 І воздви́же ру́ку Свою́ на ня, низложи́ти я в пусти́ні,","@27 і низложи́ти сі́м'я їх во язи́ціх, і расточи́ти я в страни́.","@28 І причасти́шася Веєльфего́ру і снідо́ша же́ртви ме́ртвих;","@29 і раздражи́ша Єго́ в начина́ніїх свої́х, і умно́жися в них паде́ніє.","@30 І ста Фінеє́с і уми́лостиви, і преста́ січ;","@31 і вміни́ся єму́ в пра́вду, в род і род до ві́ка.","@32 І прогні́ваша єго́ на воді́ преріка́нія, і озло́блен бисть Моїсе́й їх ра́ди;","@33 я́ко преогорчи́ша дух єго́ і ра́знствова устна́ма свої́ма.","@34 Не потреби́ша язи́ки, я́же рече́ Госпо́дь їм.","@35 І сміси́шася во язи́ціх і навико́ша діло́м їх;","@36 і порабо́таша істука́нним їх, і бисть їм в собла́зн.","@37 І пожро́ша си́ни своя́ і дще́рі своя́ бісово́м,","@38 і пролія́ша кров непови́нную, кров сино́в свої́х і дще́рей, я́же пожро́ша істука́нним ханаа́нським; і убіє́на бисть земля́ їх кровми́","@39 і оскверни́ся в ді́ліх їх; і соблуди́ша в начина́ніїх свої́х.","@40 І разгні́вася я́ростію Госпо́дь на лю́ди Своя́ і омерзи́ достоя́ніє Своє́;","@41 і предаде́ я в ру́ки враго́в, і облада́ша ї́ми ненави́дящії їх.","@42 І стужи́ша їм вразі́ їх; і смири́шася под рука́ми їх.","@43 Мно́жицею ізба́ви я; ті́ї же преогорчи́ша Єго́ сові́том свої́м, і смири́шася в беззако́ніїх свої́х.","@44 І ви́ді Госпо́дь, внегда́ скорбі́ти їм, внегда́ усли́шаше моле́ніє їх;","@45 і пом'яну́ заві́т Свой, і раска́яся по мно́жеству ми́лости Своєя́;","@46 і даде́ я в щедро́ти пред всі́ми пліни́вшими я.","@47 Спаси́ ни, Го́споди, Бо́же наш, і собери́ ни от язи́к, іспові́датися і́мені Твоєму́ свято́му, хвали́тися во хвалі́ Твоє́й.","@48 Благослове́н Госпо́дь Бог Ізра́їлев от ві́ка і до ві́ка. І реку́ть всі лю́діє: бу́ди, бу́ди!","§Сла́ва:"]},{"h":"Псалом 106","ps":["§Аллилу́я, 106.","@1 Іспові́дайтеся Го́сподеві, я́ко благ, я́ко во вік ми́лость Єго́.","@2 Да реку́ть ізба́вленнії Го́сподем, ї́хже ізба́ви із руки́ врага́,","@3 і от стран собра́ їх, от восто́к і за́пад, і сі́вера і мо́ря;","@4 заблуди́ша в пусти́ні безво́дній, путі́ гра́да оби́тельнаго не обріто́ша;","@5 а́лчуще і жа́ждуще, душа́ їх в них ізчезе́.","@6 І воззва́ша ко Го́споду, внегда́ скорбі́ти їм, і от нужд їх ізба́ви я;","@7 і наста́ви я на путь прав, вни́ти во град оби́тельний.","@8 Да іспові́дяться⁽2⁾ Го́сподеві ми́лості Єго́ і чудеса́ Єго́ синово́м челові́чеським;","@9 я́ко наси́тил єсть ду́шу тщу, і ду́шу а́лчущу іспо́лни благ;","@10 сідя́щия во тьмі і сі́ні сме́ртній, окова́нния нището́ю і желі́зом,","@11 я́ко преогорчи́ша словеса́ Бо́жія, і сові́т Ви́шняго раздражи́ша.","@12 І смири́ся в труді́х се́рдце їх, і ізнемого́ша, і не бі помага́яй.","@13 І воззва́ша ко Го́споду, внегда́ скорбі́ти їм, і от нужд їх спасе́ я;","@14 і ізведе́ я із тьми і сі́ні сме́ртния, і у́зи їх растерза́.","@15 Да іспові́дяться⁽3⁾ Го́сподеві ми́лості Єго́ і чудеса́ Єго́ синово́м челові́чеським;","@16 я́ко сокруши́ врата́ мі́дная, і вереї́ желі́зния сломи́.","@17 Восприя́т я от путі́ беззако́нія їх; беззако́ній бо ра́ди свої́х смири́шася.","@18 Вся́каго бра́шна возгнуша́ся душа́ їх, і прибли́жишася до врат сме́ртних.","@19 І воззва́ша ко Го́споду, внегда́ скорбі́ти їм, і от нужд їх спасе́ я;","@20 посла́ сло́во своє́, і ізціли́ я, і ізба́ви я от растлі́ній їх.","@21 Да іспові́дяться⁽4⁾ Го́сподеві ми́лості Єго́ і чудеса́ Єго́ синово́м челові́чеським;","@22 і да пожру́ть Єму́ же́ртву хвали́ і да возвістя́ть діла́ Єго́ в ра́дості.","@23 Сходя́щії в мо́ре в корабле́х, творя́щії ді́ланія в вода́х мно́гих,","@24 ті́ї ви́діша діла́ Госпо́дня і чудеса́ Єго́ во глубині́.","@25 Рече́ — і ста дух бу́рен, і вознесо́шася во́лни єго́;","@26 восхо́дять до небе́с і низхо́дять до бездн; душа́ їх в злих та́яше;","@27 см'ято́шася, подвиго́шася, я́ко пія́ний, і вся му́дрость їх поглощена́ бисть.","@28 І воззва́ша ко Го́споду, внегда́ скорбі́ти їм, і от нужд їх ізведе́ я;","@29 і повелі́ бу́рі, і ста в тишину́, і умолко́ша во́лни єго́.","@30 І возвесели́шася, я́ко умолко́ша, і наста́ви я в приста́нище хоті́нія Своєго́.","@31 Да іспові́дяться⁽5⁾ Го́сподеві ми́лості Єго́ і чудеса́ Єго́ синово́м челові́чеським;","@32 да вознесу́ть єго́ в Це́ркві людсті́й, і на сіда́лищі ста́рець восхва́лять Єго́.","@33 Положи́л єсть рі́ки в пусти́ню і ісхо́диша водна́я в жа́жду,","@34 зе́млю плодоно́сную в сла́ность, от зло́би живу́щих на ней.","@35 Положи́л єсть пусти́ню во єзе́ра водна́я і зе́млю безво́дную во ісхо́дища водна́я.","@36 І насели́ та́мо а́лчущия, і соста́виша гра́ди оби́тельни;","@37 і насі́яша се́ла, і насади́ша виногра́ди, і сотвори́ша плод жи́тен.","@38 І благослови́ я, і умно́жишася зіло́; і скоти́ їх не ума́ли.","@39 І ума́лишася і озло́бишася от ско́рби зол і болі́зні;","@40 ізлія́ся унічиже́ніє на кня́зі їх, і облазни́⁽6⁾ я по непрохо́дній, а не по путі́.","@41 І помо́же убо́гу от нищети́ і положи́, я́ко о́вці, оте́чествія.","@42 У́зрять пра́вії і возвеселя́ться, і вся́коє беззако́ніє загради́ть уста́ своя́.","@43 Кто прему́др і сохрани́ть сія́? І разумі́ють ми́лості Госпо́дні.","§Сла́ва:"]},{"h":"Псалом 107","ps":["§Піснь, псало́м Дави́ду, 107.","@2 Гото́во се́рдце моє́, Бо́же, гото́во се́рдце моє́; воспою́ і пою́ во сла́ві моє́й.","@3 Воста́ни, сла́ва моя́, воста́ни, псалти́рю і гу́слі; воста́ну ра́но.","@4 Іспові́мся Тебі́ в лю́дех, Го́споди, пою́ Тебі́ во язи́ціх;","@5 я́ко ве́лія верху́ небе́с ми́лость Твоя́ і до о́блак і́стина Твоя́.","@6 Вознеси́ся на небеса́, Бо́же, і по всей землі́ сла́ва Твоя́.","@7 я́ко да ізба́в'яться возлю́бленнії Твої́; спаси́ десни́цею Твоє́ю і усли́ши м'я.","@8 Бог возглаго́ла во святі́м Своє́м: вознесу́ся і разділю́ Сики́му, і удо́ль селе́ній размі́рю.","@9 Мой єсть Галаа́д, і Мой єсть Манассі́й, і Єфре́м — заступле́ніє глави́ Моєя́; Іу́да — цар Мой,","@10 Моа́в — коно́б упова́нія Моєго́; на Ідуме́ю наложу́ сапо́г Мой; Мні іноплеме́нници покори́шася.","@11 Кто введе́ть м'я во град огражде́нія? Іли́ кто наста́вить м'я до Ідуме́ї?","@12 Не Ти ли, Бо́же, отри́нувий нас, і не ізи́деши, Бо́же, в си́лах на́ших?","@13 Даждь нам по́мощ от ско́рби, і су́єтно спасе́ніє челові́чесько.","@14 О Бо́зі сотвори́м си́лу, і Той унічижи́ть враги́ на́ша."]},{"h":"Псалом 108","ps":["§В коне́ць, псало́м Дави́ду, 108.","@1 Бо́же, хвали́ моєя́ не премолчи́;","@2 я́ко уста́ грі́шнича і уста́ льсти́ваго на м'я отверзо́шася, глаго́лаша на м'я язи́ком льсти́вим,","@3 і словеси́ ненави́стними обидо́ша м'я, і бра́шася со мно́ю ту́не.","@4 Вмі́сто є́же люби́ти м'я, оболга́ху м'я, аз же моля́хся;","@5 і положи́ша на м'я зла́я за блага́я, і не́нависть за возлюбле́ніє моє́.","@6 Поста́ви на него́ грі́шника, і дия́вол да ста́неть одесну́ю єго́;","@7 внегда́ суди́тися єму́, да ізи́деть осужде́н, і моли́тва єго́ да бу́деть в гріх.","@8 Да бу́дуть дні́є єго́ ма́лі, і єпи́скопство єго́ да при́йметь ін;","@9 да бу́дуть си́нове єго́ си́рі, і жена́ єго́ — вдова́;","@10 дви́жущеся да преселя́ться си́нове єго́ і воспро́сять, да ізгна́ні бу́дуть із домо́в свої́х.","@11 Да взи́щеть займода́вець вся, єли́ка суть єго́; і да восхи́тять чужді́ї труди́ єго́.","@12 Да не бу́деть єму́ засту́пника, ніже́ да бу́деть ущедря́яй сироти́ єго́;","@13 да бу́дуть ча́да єго́ в погубле́ніє, в ро́ді єди́нім да потреби́ться і́м'я єго́.","@14 Да воспом'яне́ться беззако́ніє оте́ць єго́ пред Го́сподем, і гріх ма́тере єго́ да не очи́ститься;","@15 да бу́дуть пред Го́сподем ви́ну, і да потреби́ться от землі́ па́м'ять їх;","@16 зане́же не пом'яну́ сотвори́ти ми́лость, і погна́ челові́ка ни́ща і убо́га, і умиле́на се́рдцем умертви́ти.","@17 І возлюби́ кля́тву, і при́йдеть єму́; і не восхоті́ благослове́нія, і удали́ться от него́.","@18 І облече́ся в кля́тву, я́ко в ри́зу, і вни́де, я́ко вода́, во утро́бу єго́ і, я́ко єле́й, в ко́сті єго́;","@19 да бу́деть єму́, я́ко ри́за, в ню́же облачи́ться, і, я́ко по́яс, і́мже ви́ну опоясу́ється.","@20 Сіє́ ді́ло оболга́ющих м'я у Го́спода і глаго́лющих лука́вая на ду́шу мою́.","@21 І Ти, Го́споди, Го́споди, сотвори́ со мно́ю і́мене ра́ди Твоєго́, я́ко бла́га ми́лость Твоя́;","@22 ізба́ви м'я, я́ко нищ і убо́г єсьм аз, і се́рдце моє́ см'яте́ся внутр мене́.","@23 Я́ко сінь, внегда́ уклони́тися єй, отя́хся; стрясо́хся, я́ко пру́зи.","@24 Колі́на моя́ ізнемо́госта от посту, і плоть моя́ ізміни́ся єле́я ра́ди.","@25 І аз бих поноше́ніє їм; ви́діша м'я, покива́ша глава́ми свої́ми.","@26 Помози́ мі, Го́споди Бо́же мой, і спаси́ м'я по ми́лості Твоє́й;","@27 і да разумі́ють, я́ко рука́ Твоя́ сія́, і Ти, Го́споди, сотвори́л єси́ ю.","@28 Проклену́ть ті́ї, і Ти благослови́ши; востаю́щії на м'я да постидя́ться, раб же Твой возвесели́ться.","@29 Да облеку́ться оболга́ющії м'я в срамоту́ і оде́ждуться, я́ко оде́ждою, студо́м свої́м.","@30 Іспові́мся Го́сподеві зіло́ усти́ мої́ми і посреді́ мно́гих восхвалю́ Єго́;","@31 я́ко преста́ одесну́ю убо́гаго, є́же спасти́ от гоня́щих ду́шу мою́.","§Сла́ва:"]},{"h":"Після 15-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 1:","ps":["Я́ко пучи́на мно́га прегріше́ній мої́х, Спа́се, і лю́ті погрузи́хся согріше́ньми мої́ми; даждь мі ру́ку, я́ко Петро́ві, і спаси́ м'я, Бо́же, і поми́луй м'я.","Сла́ва: Я́ко помишле́нії лука́вими і ді́ли осуди́хся, Спа́се, мисль мі да́руй обраще́нія, Бо́же, да зову́: спаси́ м'я, Благоді́телю Благи́й, і поми́луй м'я.","І ни́ні: Богоблаже́нная Отрокови́це і Пренепоро́чная, скве́рна м'я су́ща і окаля́нна, от дія́ній безмі́стних і скве́рних помишле́ній очи́сти м'я, окая́ннаго, нескве́рная і чи́стая, всесвята́я Ма́ти Ді́во."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Влади́ко Го́споди Ісу́се Христе́, Ти єси́ Помо́щник мой, в рука́х Твої́х єсьм аз, помози́ мі, не оста́ви мене́ согріши́ти к Тебі́, я́ко заблужде́н єсьм. Не оста́ви м'я послі́довати во́лі пло́ті моєя́; не пре́зри м'я? Го́споди, я́ко не́мощен єсьм. Ти ві́си поле́зноє мні, не оста́ви м'я поги́бнути гріхи́ мої́ми; не оста́ви м'я, Го́споди, не отступи́ от мене́, я́ко к Тебі́ прибіго́х, научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой. Ісціли́ ду́шу мою́, я́ко согріши́х Ті, спаси́ м'я ра́ди ми́лости Твоєя́, я́ко пред Тобо́ю суть всі стужа́ющії мі; і ність мні іно́є прибі́жище, то́кмо Ти, Го́споди. Да постидя́ться у́бо всі востаю́щії на м'я і і́щущії ду́шу мою́, є́же потреби́ти ю; я́ко Ти єси́ єди́н си́льний, Го́споди, во всіх, і Твоя́ єсть сла́ва во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[преведе́]</span>","<span class=''>[да іспові́дять]</span>","<span class=''>[да іспові́дять]</span>","<span class=''>[да іспові́дять]</span>","<span class=''>[да іспові́дять]</span>","<span class=''>[заблужда́ти сотвори́]</span>"]},{"u":"Кафизма 16","e":"Kathisma 16","secs":[{"h":"Псалом 109","ps":["§Псало́м Дави́ду, 109.","@1 Рече́ Госпо́дь Го́сподеві моєму́: сіди́ одесну́ю Мене́, до́ндеже положу́ враги́ Твоя́ подно́жіє ног Твої́х.","@2 Жезл си́ли по́слеть Ті Госпо́дь от Сіо́на, і Госпо́дствуй посреді́ враго́в Твої́х.","@3 С Тобо́ю нача́ло в день си́ли Твоєя́, во сві́тлостех святи́х Твої́х; із чре́ва пре́жде денни́ці роди́х Тя.","@4 Кля́тся Госпо́дь і не раска́ється: Ти ієре́й во вік по чи́ну Мелхіседе́кову.","@5 Госпо́дь одесну́ю Тебе́ сокруши́л єсть в день гні́ва Своєго́ царі́;","@6 су́дить во язи́ціх, іспо́лнить паде́нія, сокруши́ть глави́ на землі́ мно́гих.","@7 От пото́ка на путі́ піє́ть; сего́ ра́ди вознесе́ть главу́."]},{"h":"Псалом 110","ps":["§Аллилу́я, 110.","@1 Іспові́мся Тебі́, Го́споди, всім се́рдцем мої́м в сові́ті пра́вих і со́нмі.","@2 Ве́лія діла́ Госпо́дня, ізи́скана во всіх во́лях Єго́;","@3 іспові́даніє і великолі́піє — ді́ло Єго́, і пра́вда Єго́ пребива́єть в вік ві́ка.","@4 Па́м'ять сотвори́л єсть чуде́с Свої́х; ми́лостив і щедр Госпо́дь.","@5 Пи́щу даде́ боя́щимся Єго́; пом'яне́ть в вік заві́т Свой.","@6 Крі́пость діл Свої́х возвісти́ лю́дем Свої́м, да́ти їм достоя́ніє язи́к.","@7 Діла́ рук Єго́ — і́стина і суд, ві́рни вся за́повіді Єго́,","@8 утверже́ни в вік ві́ка, сотворе́ни во і́стині і правоті́.","@9 Ізбавле́ніє посла́ лю́дем Свої́м; запові́да в вік заві́т Свой; свя́то і стра́шно і́м'я Єго́.","@10 Нача́ло прему́дрости — страх Госпо́день, ра́зум же благ всім творя́щим ї; хвала́ Єго́ пребива́єть в вік ві́ка."]},{"h":"Псалом 111","ps":["§Аллилу́я, псало́м, 111","@1 Блаже́н муж боя́йся Го́спода, в за́повідех Єго́ восхо́щеть зіло́.","@2 Си́льно на землі́ бу́деть сі́м'я єго́, род пра́вих благослови́ться;","@3 сла́ва і бога́тство в дому́ єго́, і пра́вда єго́ пребива́єть в вік ві́ка.","@4 Возсія́ во тьмі світ пра́вим; ми́лостив, і щедр, і пра́веден.","@5 Благ муж ще́дря і дая́; устро́їть словеса́ своя́ на суді́, я́ко в вік не подви́житься.","@6 В па́м'ять ві́чную бу́деть пра́ведник.","@7 От слу́ха зла не убої́ться;","@8 гото́во се́рдце єго́ упова́ти на Го́спода; утверди́ся се́рдце єго́, не убої́ться, до́ндеже воззри́ть на враги́ своя́.","@9 Расточи́, даде́ убо́гим; пра́вда єго́ пребива́єть во вік ві́ка: рог єго́ вознесе́ться в сла́ві.","@10 Грі́шник у́зрить і прогні́вається, зуби́ свої́ми поскреже́щеть і раста́єть; жела́ніє грі́шника поги́бнеть.","§Сла́ва:"]},{"h":"Псалом 112","ps":["§Аллилу́я, 112.","@1 Хвалі́те, о́троци, Го́спода, хвалі́те і́м'я Госпо́днє.","@2 Бу́ди і́м'я Госпо́днє благослове́но отни́ні і до ві́ка.","@3 От восто́к со́лнця до за́пад хва́льно і́м'я Госпо́днє.","@4 Висо́к над всі́ми язи́ки Госпо́дь; над небесі́ сла́ва Єго́.","@5 Кто — я́ко Госпо́дь Бог наш? На висо́ких живи́й,","@6 і на смире́нния призира́яй на небесі́ і на землі́;","@7 воздвиза́яй от землі́ ни́ща і от гно́їща возвиша́яй убо́га;","@8 посади́ти єго́ с кня́зі, с кня́зі люді́й Свої́х;","@9 вселя́я непло́дов в дом, ма́тер о ча́діх веселя́щуся."]},{"h":"Псалом 113","ps":["§Аллилу́я, 113.","@1 Во ісхо́ді Ізра́їлеві от Єги́пта, до́му Іа́ковля із люді́й ва́рвар,","@2 бисть Іуде́я святи́ня Єго́, Ізра́їль — о́бласть Єго́.","@3 Мо́ре ви́ді і побіже́, Іорда́н возврати́ся всп'ять;","@4 го́ри взигра́шася, я́ко овні́, і хо́лми, я́ко а́гнці о́вчії.","@5 Что ті єсть, мо́ре, я́ко побі́гло єси́? І тебі́, Іорда́не, я́ко возврати́лся єси́ всп'ять?","@6 го́ри, я́ко взигра́стеся, я́ко овні́, і хо́лми, я́ко а́гнці о́вчії.","@7 От лиця́ Госпо́дня подви́жеся земля́, от лиця́ Бо́га Іа́ковля;","@8 обра́щшаго ка́мень во єзе́ра водна́я і несіко́мий во істо́чники водни́я.","@9 Не нам, Го́споди, не нам, но і́мені Твоєму́ даждь сла́ву о ми́лості Твоє́й і і́стині Твоє́й;","@10 Да не когда́ реку́ть язи́ци: гді єсть Бог їх?","@11 Бог же наш на небесі́ і на землі́, вся єли́ка восхоті́, сотвори́.","@12 І́доли язи́к — сребро́ і зла́то, діла́ рук челові́чеських;","@13 уста́ і́муть і не возглаго́лють; о́чі і́муть і не у́зрять;","@14 у́ші і́муть, і не усли́шать; но́здри і́муть, і не обоня́ють;","@15 ру́ці і́муть, і не ося́жуть; но́зі і́муть, і не по́йдуть; не возглася́ть горта́нем свої́м.","@16 Подо́бні їм да бу́дуть творя́щії я і всі наді́ющіїся на ня.","@17 Дом Ізра́їлев упова́ на Го́спода: Помо́щник і Защи́титель їм єсть.","@18 Дом Ааро́нь упова́ на Го́спода: Помо́щник і Защи́титель їм єсть.","@19 Боя́щіїся Го́спода упова́ша на Го́спода: Помо́щник і Защи́титель їм єсть.","@20 Госпо́дь пом'яну́в ни благослови́л єсть нас, благослови́л єсть дом Ізра́їлев, благослови́л єсть дом Ааро́нь,","@21 благослови́л єсть боя́щияся Го́спода, ма́лия с вели́кими.","@22 Да приложи́ть Госпо́дь на ви, на ви і на си́ни ва́ша;","@23 благослове́нні ви Го́сподеві, сотво́ршему не́бо і зе́млю.","@24 Не́бо небесе́ — Го́сподеві, зе́млю же даде́ синово́м челові́чеським.","@25 Не ме́ртвії восхва́лять Тя, Го́споди, ніже́ всі низходя́щії во ад;","@26 но ми живі́ї благослови́м Го́спода отни́ні і до ві́ка."]},{"h":"Псалом 114","ps":["§Аллилу́я, 114.","@1 Возлюби́х, я́ко усли́шить Госпо́дь глас моле́нія моєго́,","@2 я́ко приклони́ у́хо Своє́ мні; і во дні моя́ призову́.","@3 Об'я́ша м'я болі́зні сме́ртния, біди́ а́дови обріто́ша м'я; скорб і болі́знь обріто́х і і́м'я Госпо́днє призва́х.","@4 О Го́споди, ізба́ви ду́шу мою́; ми́лостив Госпо́дь і пра́веден, і Бог наш ми́луєть.","@5 Храня́й младе́нці Госпо́дь; смири́хся, і спасе́ м'я.","@6 Обрати́ся, душе́ моя́, в поко́й твой, я́ко Госпо́дь благоді́йствова тя.","@7 я́ко із'я́т ду́шу мою́ от сме́рти, о́чі мої́ от слез і но́зі мої́ от поползнове́нія.","@8 Благоугожду́ пред Го́сподем во страні́ живи́х.","§Сла́ва:"]},{"h":"Псалом 115","ps":["§Аллилу́я, 115.","@1 Ві́ровах, ті́мже возглаго́лах: аз же смири́хся зіло́.","@2 Аз же ріх во ізступле́нії моє́м: всяк челові́к лож.","@3 Что возда́м Го́сподеві о всіх, Я́же воздаде́ мі?","@4 Ча́шу спаcе́нія прийму́ і і́м'я Госпо́днє призову́;","@5 моли́тви моя́ Го́сподеві возда́м пред всі́ми людьми́ Єго́.","@6 Честна́ пред Го́сподем смерть преподо́бних Єго́.","@7 О Го́споди, аз раб Твой, аз раб Твой і син раби́ні Твоєя́. Растерза́л єси́ у́зи моя́.","@8 Тебі́ пожру́ же́ртву хвали́ і во і́м'я Госпо́днє призову́.","@9 Моли́тви моя́ Го́сподеві возда́м пред всі́ми людьми́ Єго́,","@10 во дво́ріх до́му Госпо́дня, посреді́ тебе́, Ієрусали́ме."]},{"h":"Псалом 116","ps":["§Аллилу́я, 116.","@1 Хвалі́те Го́спода, всі язи́ци, похвалі́те Єго́, всі лю́діє;","@2 я́ко утверди́ся ми́лость Єго́ на нас, і і́стина Госпо́дня пребива́єть во вік."]},{"h":"Псалом 117","ps":["§Сей день, єго́же сотвори́ Госпо́дь, возра́дуємся і возвеселі́мся в онь.","Аллилу́я, 117.","@1 Іспові́дайтеся Го́сподеві, я́ко благ, я́ко во вік ми́лость Єго́.","@2 Да рече́ть у́бо дом Ізра́їлев: я́ко благ, я́ко в вік ми́лость Єго́.","@3 Да рече́ть у́бо дом Ааро́нь: я́ко благ, я́ко в вік ми́лость Єго́.","@4 Да реку́ть у́бо всі боя́щіїся Го́спода: я́ко благ, я́ко в вік ми́лость Єго́.","@5 От ско́рби призва́х Го́спода, і усли́ша м'я в простра́нство.","@6 Госпо́дь мні помо́щник, і не убою́ся; что сотвори́ть мні челові́к?","@7 Госпо́дь мні помо́щник, і аз воззрю́ на враги́ моя́.","@8 Благо єсть наді́ятися на Го́спода, не́жели наді́ятися на челові́ка;","@9 бла́го єсть упова́ти на Го́спода, не́жели упова́ти на кня́зі.","@10 Всі язи́ци обидо́ша м'я, і і́менем Госпо́днім противля́хся їм;","@11 Обише́дше обидо́ша м'я, і і́менем Госпо́днім противля́хся їм.","@12 обидо́ша м'я, я́ко пче́ли сот, і разгорі́шася, я́ко огнь в те́рнії; і і́менем Госпо́днім противля́хся їм.","@13 Отринове́н преврати́хся па́сти, і Госпо́дь прия́т м'я.","@14 Крі́пость моя́ і пі́ніє моє́ — Госпо́дь, і бисть мі во спасе́ніє.","@15 Глас ра́дости і спаcе́нія в селе́ніїх пра́ведних; десни́ця Госпо́дня сотвори́ си́лу.","@16 Десни́ця Госпо́дня вознесе́ м'я, десни́ця Госпо́дня сотвори́ си́лу.","@17 Не умру́, но жив бу́ду і пові́м діла́ Госпо́дня.","@18 Наказу́я наказа́ м'я Госпо́дь, сме́рті же не предаде́ м'я.","@19 Отве́рзіте мні врата́ пра́вди; вшед в ня, іспові́мся Го́сподеві.","@20 Сія́ врата́ Госпо́дня; пра́веднії вни́дуть в ня.","@21 Іспові́мся Тебі́, я́ко усли́шал м'я єси́ і бил єси́ мні во спасе́ніє.","@22 Ка́мень, єго́же небрего́ша зи́ждущії, сей бисть во главу́ у́гла.","@23 От Го́спода бисть сей, і єсть ди́вен во очесі́х на́ших.","@25 О, Го́споди, спаси́ же, о, Го́споди, поспіши́ же.","@26 Благослове́н Гряди́й во і́м'я Госпо́днє; благослови́хом ви із до́му Госпо́дня.","@27 Бог Госпо́дь, і яви́ся нам; соста́віте пра́здник во учаща́ющих до рог олтаре́вих.","@28 Бог мой єси́ Ти, і іспові́мся Тебі́; Бог мой єси́ Ти, і вознесу́ Тя; іспові́мся Тебі́, я́ко усли́шал м'я єси́ і бил єси́ мні во спасе́ніє.","@29 Іспові́дайтеся Го́сподеві, я́ко благ, я́ко во вік ми́лость Єго́.","§Сла́ва:"]},{"h":"Після 16-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 1:","ps":["І́н мир тебе́, душе́, ожида́єть, і Судія́ хо́щеть твоя́ обличи́ти та́йная і лю́тая. Не пребу́ди у́бо в зді́шних, но предвари́ вопію́щи Судії́: Бо́же, очи́сти м'я і спаси́ м'я.","Сла́ва: Я́ко прегріше́ньми мно́гими і я́звами безмі́рними облежи́м єсьм, Спа́се, согріша́яй молю́ Твоє́ благоутро́біє, Христе́: Врачу́ неду́гующих, посіти́, і ісціли́, і спаси́ м'я.","І ни́ні: Душе́ моя́, что неради́во живе́ши ліня́щися? Что не пече́шися о злих, ї́хже соді́яла єси́ в житії́? Потщи́ся іспра́витися, пре́жде да́же двер не заключи́ть тебі́ Госпо́дь. Богоро́диці притеци́, припади́ і возопи́й: упова́ніє ненаді́ємих, спаси́ м'я, мно́го к Тебі́ прегріши́вша, Влади́чице Пречи́стая."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Святи́й, в ви́шніх живи́й і всеви́дящим Твої́м о́ком призира́яй на всю твар, Тебі́ приклоня́єм ви́ю душі́ і тілесе́, і Тебі́ мо́лимся, Святи́й святи́х: простри́ ру́ку Твою́ неви́димую от Свята́го жили́ща Твоєго́, і благослови́ вся ни, і прости́ нам вся́коє согріше́ніє, во́льноє же і нево́льноє, сло́вом, іли́ ді́лом. Да́руй нам, Го́споди, умиле́ніє, да́руй сле́зи духо́вния от душі́ во очище́ніє мно́гих на́ших гріхо́в; да́руй ве́лію Твою́ ми́лость на мир Твой і на ни, недосто́йния раби́ Твоя́; я́ко благослове́нно і препросла́вленно єсть і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":[]},{"u":"Кафизма 17","e":"Kathisma 17","secs":[{"h":"Псалом 118","ps":["§Аллилу́я, 118.","@1 Блаже́нні непоро́чнії в путь⁽1⁾, ходя́щії в зако́ні Госпо́дні.","@2 Блаже́нні іспита́ющії свиді́нія Єго́, всім се́рдцем взи́щуть Єго́.","@3 Не ді́лающії бо беззако́нія в путе́х Єго́ ходи́ша.","@4 Ти запові́дал єси́ за́повіді Твоя́ сохрани́ти зіло́;","@5 даби́ іспра́вилися путіє́ мої́, сохрани́ти оправда́нія Твоя́.","@6 Тогда́ не постижу́ся, внегда́ призрі́ти мі на вся за́повіді Твоя́.","@7 Іспові́мся Тебі́ в пра́вості се́рдця, внегда́ научи́тимися судьба́м пра́вди Твоєя́.","@8 Оправда́нія Твоя́ сохраню́; не оста́ви мене́ до зіла́.","@9 В чесо́м іспра́вить юні́йшій путь свой? Внегда́ сохрани́ти словеса́ Твоя́.","@10 Всім се́рдцем мої́м взиска́х Тебе́; не отри́ни мене́ от за́повідій Твої́х.","@11 В се́рдці моє́м скрих словеса́ Твоя́, я́ко да не согрішу́ Тебі́.","@12 Благослове́н єси́, Го́споди; научи́ м'я оправда́нієм Твої́м.","@13 Устна́ма мої́ма возвісти́х вся судьби́ уст Твої́х.","@14 На путі́ свиді́ній Твої́х наслади́хся, я́ко о вся́ком бога́тстві.","@15 В за́повідех Твої́х поглумлю́ся, і уразумі́ю путі́ Твоя́.","@16 Во оправда́ніїх Твої́х поучу́ся; не забу́ду слове́с Твої́х.","@17 Возда́ждь рабу́ Твоєму́; живи́ м'я, і сохраню́ словеса́ Твоя́.","@18 Откри́й о́чі мої́, і уразумі́ю чудеса́ от зако́на Твоєго́.","@19 Пришле́ць аз єсьм на землі́; не скрий от мене́ за́повіді Твоя́.","@20 Возлюби́ душа́ моя́ возжела́ти судьби́ Твоя́ на вся́коє вре́м'я.","@21 Запрети́л єси́ го́рдим; про́кляті уклоня́ющіїся от за́повідій Твої́х.","@22 Отими́ от мене́ поно́с⁽2⁾ і унічиже́ніє, я́ко свиді́ній Твої́х взиска́х.","@23 І́бо сідо́ша кня́зі і на м'я клевета́ху, раб же Твой глумля́шеся во оправда́ніїх Твої́х;","@24 і́бо свиді́нія Твоя́ — поуче́ніє моє́ єсть, і сові́ти мої́ — оправда́нія Твоя́.","@25 Прильпе́ землі́ душа́ моя́; живи́ м'я по словесі́ Твоєму́.","@26 Путі́ моя́ возвісти́х, і усли́шал м'я єси́; научи́ м'я оправда́нієм Твої́м.","@27 Путь оправда́ній Твої́х вразуми́ мі, і поглумлю́ся в чудесі́х Твої́х.","@28 Воздрема́ душа́ моя́ от уни́нія; утверди́ м'я в словесі́х Твої́х.","@29 Путь непра́вди отста́ви от мене́ і зако́ном Твої́м поми́луй м'я.","@30 Путь і́стини ізво́лих і судьби́ Твоя́ не заби́х.","@31 Приліпи́хся свиді́нієм Твої́м, Го́споди, не посрами́ мене́.","@32 Путь за́повідій Твої́х теко́х, єгда́ разшири́л єси́ се́рдце моє́.","@33 Законоположи́ мні, Го́споди, путь оправда́ній Твої́х, і взищу́ ї ви́ну;","@34 Вразуми́ м'я, і іспита́ю зако́н Твой, і сохраню́ ї всім се́рдцем мої́м.","@35 Наста́ви м'я на стезю́ за́повідій Твої́х, я́ко ту́ю восхоті́х.","@36 Приклони́ се́рдце моє́ во свиді́нія Твоя́, а не в лихої́мство.","@37 Отврати́ о́чі мої́, є́же не ви́діти суєти́; в путі́ Твоє́м живи́ м'я.","@38 Поста́ви рабу́ Твоєму́ сло́во Твоє́ в страх Твой.","@39 Отими́ поноше́ніє моє́, є́же непщева́х; я́ко судьби́ Твоя́ бла́гі.","@40 Се, возжела́х за́повіді Твоя́; в пра́вді Твоє́й живи́ м'я.","@41 І да при́йдеть на м'я ми́лость Твоя́, Го́споди, спасе́ніє Твоє́ по словесі́ Твоєму́;","@42 і отвіща́ю поноша́ющим мі сло́во, я́ко упова́х на словеса́ Твоя́.","@43 І не отими́ от уст мої́х словесе́ і́стинна до зіла́, я́ко на судьби́ Твоя́ упова́х;","@44 і сохраню́ зако́н Твой ви́ну, в вік і в вік ві́ка.","@45 І хожда́х в широті́, я́ко за́повіді Твоя́ взиска́х;","@46 і глаго́лах о свиді́ніїх Твої́х пред царі́ і не стидя́хся;","@47 і поуча́хся в за́повідех Твої́х, я́же возлюби́х зіло́;","@48 і воздвиго́х ру́ці мої́ к за́повідем Твої́м, я́же возлюби́х, і глумля́хся во оправда́ніїх Твої́х.","@49 Пом'яни́ словеса́ Твоя́ рабу́ Твоєму́, ї́хже упова́ніє дал мі єси́.","@50 То м'я уті́ши во смире́нії моє́м, я́ко сло́во Твоє́ живи́ м'я.","@51 Го́рдії законопреступова́ху до зіла́; от зако́на же Твоєго́ не уклони́хся.","@52 Пом'яну́х судьби́ Твоя́ от ві́ка, Го́споди, і уті́шихся.","@53 Печа́ль прия́т м'я от грі́шник, оставля́ющих зако́н Твой.","@54 Пі́та бя́ху мні оправда́нія Твоя́ на мі́сті прише́льствія моєго́.","@55 Пом'яну́х в нощі́ і́м'я Твоє́, Го́споди, і сохрани́х зако́н Твой.","@56 Сей бисть мні, я́ко оправда́ній Твої́х взиска́х.","@57 Часть моя́ єси́, Го́споди; ріх сохрани́ти зако́н Твой.","@58 Помоли́хся лицю́ Твоєму́ всім се́рдцем мої́м; поми́луй м'я по словесі́ Твоєму́.","@59 Поми́слих путі́ Твоя́ і возврати́х но́зі мої́ во свиді́нія Твоя́.","@60 Угото́вихся і не смути́хся сохрани́ти за́повіді Твоя́.","@61 У́жя грі́шник об'яза́шася мні, і зако́на Твоєго́ не заби́х.","@62 Полу́нощі воста́х іспові́датися Тебі́ о судьба́х пра́вди Твоєя́.","@63 Прича́стник аз єсьм всім боя́щимся Тебе́ і храня́щим за́повіді Твоя́.","@64 Ми́лости Твоєя́, Го́споди, іспо́лнь земля́; оправда́нієм Твої́м научи́ м'я.","@65 Благость сотвори́л єси́ с рабо́м Твої́м, Го́споди, по словесі́ Твоєму́;","@66 бла́гості, і наказа́нію, і ра́зуму научи́ м'я, я́ко за́повідем Твої́м ві́ровах.","@67 Пре́жде да́же не смири́тимися, аз прегріши́х; сего́ ра́ди сло́во Твоє́ сохрани́х.","@68 Благ єси́ Ти, Го́споди; і бла́гостію Твоє́ю научи́ м'я оправда́нієм Твої́м.","@69 Умно́жися на м'я непра́вда го́рдих; аз же всім се́рдцем мої́м іспита́ю за́повіді Твоя́.","@70 Усири́ся, я́ко млеко́, се́рдце їх; аз же зако́ну Твоєму́ поучи́хся.","@71 Благо мні, я́ко смири́л м'я єси́, я́ко да научу́ся оправда́нієм Твої́м.","@72 Благ мні зако́н уст Твої́х па́че ти́сящ зла́та і сребра́.","§Сла́ва:","@73 Ру́це Твої́ сотвори́сті м'я і созда́сті м'я; вразуми́ м'я, і научу́ся за́повідем Твої́м.","@74 Боя́щіїся Тебе́ у́зрять м'я і возвеселя́ться, я́ко на словеса́ Твоя́ упова́х.","@75 Разумі́х, Го́споди, я́ко пра́вда судьби́ Твоя́, і воі́стину смири́л м'я єси́.","@76 Бу́ди же ми́лость Твоя́, да уті́шить м'я, по словесі́ Твоєму́ рабу́ Твоєму́;","@77 да при́йдуть мні щедро́ти Твоя́, і жив бу́ду, я́ко зако́н Твой поуче́ніє моє́ єсть.","@78 Да постидя́ться го́рдії, я́ко непра́ведно беззако́нноваша на м'я; аз же поглумлю́ся⁽3⁾ в за́повідех Твої́х.","@79 Да обратя́ть м'я боя́щіїся Тебе́ і ві́дящії свиді́нія Твоя́.","@80 Бу́ди се́рдце моє́ непоро́чно во оправда́ніїх Твої́х, я́ко да не постижу́ся.","@81 Ізчеза́єть во спасе́ніє Твоє́ душа́ моя́, на словеса́ Твоя́ упова́х;","@82 ізчезо́ша о́чі мої́ в сло́во Твоє́, глаго́люще: когда́ уті́шиши м'я?","@83 зане́ бих я́ко міх на сла́ні; оправда́ній Твої́х не заби́х.","@84 Коли́ко єсть дній раба́ Твоєго́? Когда́ сотвори́ши мі от гоня́щих м'я суд?","@85 Пові́даша мні законопресту́пници глумле́нія, но не я́ко зако́н Твой, Го́споди.","@86 Вся за́повіді Твоя́ — і́стина; непра́ведно погна́ша м'я, помози́ мі.","@87 Вма́лі не сконча́ша мене́ на землі́; аз же не оста́вих за́повідій Твої́х.","@88 По ми́лості Твоє́й живи́ м'я, і сохраню́ свиді́нія уст Твої́х.","@89 Во вік, Го́споди, сло́во Твоє́ пребива́єть на небесі́.","@90 В род і род і́стина Твоя́; основа́л єси́ зе́млю, і пребива́єть.","@91 Учине́нієм Твої́м пребива́єть день; я́ко вся́чеськая рабо́тна Тебі́.","@92 Я́ко а́ще би не зако́н Твой поуче́ніє моє́ бил, тогда́ у́бо поги́бл бих во смире́нії моє́м;","@93 во вік не забу́ду оправда́ній Твої́х, я́ко в них оживи́л м'я єси́.","@94 Твой єсьм аз, спаси́ м'я; я́ко оправда́ній Твої́х взиска́х.","@95 Мене́ жда́ша грі́шници погуби́ти м'я; свиді́нія Твоя́ разумі́х.","@96 Вся́кия кончи́ни ви́діх коне́ць; широка́ за́повідь Твоя́ зіло́.","@97 Коль возлюби́х зако́н Твой, Го́споди; весь день поуче́ніє моє́ єсть.","@98 па́че враг мої́х умудри́л м'я єси́ за́повідію Твоє́ю, я́ко в вік моя́ єсть.","@99 па́че всіх уча́щих м'я разумі́х, я́ко свиді́нія Твоя́ поуче́ніє моє́ єсть.","@100 па́че ста́рець разумі́х, я́ко за́повіді Твоя́ взиска́х.","@101 От вся́каго путі́ лука́ва возбрани́х нога́м мої́м, я́ко да сохраню́ словеса́ Твоя́;","@102 от суде́б Твої́х не уклони́хся, я́ко Ти законоположи́л мі єси́.","@103 Коль сладка́ горта́ні моєму́ словеса́ Твоя́; па́че ме́да усто́м мої́м.","@104 От за́повідій Твої́х разумі́х; сего́ ра́ди возненави́діх всяк путь непра́вди.","@105 Світи́льник нога́ма мої́ма зако́н Твой, і світ стезя́м мої́м.","@106 Кля́хся і поста́вих сохрани́ти судьби́ пра́вди Твоєя́.","@107 Смири́хся до зіла́; Го́споди, живи́ м'я по словесі́ Твоєму́.","@108 Во́льная уст мої́х благоволи́ же, Го́споди, і судьба́м Твої́м научи́ м'я.","@109 Душа́ моя́ в руку́ Твоє́ю⁽4⁾ ви́ну, і зако́на Твоєго́ не заби́х.","@110 Положи́ша грі́шници сіть мні; і от за́повідій Твої́х не заблуди́х.","@111 Наслі́довах свиді́нія Твоя́ во вік, я́ко ра́дованіє се́рдця моєго́ суть;","@112 приклони́х се́рдце моє́ сотвори́ти оправда́нія Твоя́ в вік за воздая́ніє.","@113 Законопресту́пния возненави́діх, зако́н же Твой возлюби́х.","@114 Помо́щник мой і Засту́пник мой єси́ Ти; на словеса́ Твоя́ упова́х.","@115 Уклоні́теся от мене́, лука́внующії, і іспита́ю за́повіді Бо́га моєго́.","@116 Заступи́ м'я по словесі́ Твоєму́, і жив бу́ду; і не посрами́ мене́ от ча́янія моєго́;","@117 помози́ мі, і спасу́ся, і поучу́ся во оправда́ніїх Твої́х ви́ну.","@118 Уничижи́л єси́ вся отступа́ющия от оправда́ній Твої́х; я́ко непра́ведно помишле́ніє їх.","@119 Преступа́ющия непщева́х вся грі́шния землі́; сего́ ра́ди возлюби́х свиді́нія Твоя́.","@120 Пригвозди́ стра́ху Твоєму́ пло́ті моя́; от суде́б бо Твої́х убоя́хся.","@121 Сотвори́х суд і пра́вду; не преда́ждь мене́ оби́дящим м'я.","@122 Восприйми́ раба́ Твоєго́ во бла́го, да не оклевета́ють мене́ го́рдії.","@123 О́чі мої́ ізчезо́сті во спасе́ніє Твоє́ і в сло́во пра́вди Твоєя́;","@124 сотвори́ с рабо́м Твої́м по ми́лості Твоє́й і оправда́нієм Твої́м научи́ м'я.","@125 Раб Твой єсьм аз; вразуми́ м'я, і уві́м свиді́нія Твоя́.","@126 Вре́м'я сотвори́ти Го́сподеві; разори́ша зако́н Твой.","@127 Сего́ ра́ди возлюби́х за́повіді Твоя́ па́че зла́та і топа́зія.","@128 Сего́ ра́ди ко всім за́повідем Твої́м направля́хся, всяк путь непра́вди возненави́діх.","@129 Ди́вна свиді́нія Твоя́; сего́ ра́ди іспита́ я душа́ моя́.","@130 Явле́ніє слове́с Твої́х просвіща́єть і вразумля́єть младе́нці.","@131 Уста́ моя́ отверзо́х і привлеко́х дух, я́ко за́повідій Твої́х жела́х.","§Сла́ва:","@132 При́зри на м'я і поми́луй м'я, по суду́ лю́б’ящих і́м'я Твоє́.","@133 Стопи́ моя́ напра́ви по словесі́ Твоєму́, і да не облада́єть мно́ю вся́коє беззако́ніє;","@134 ізба́ви м'я от клевети́ челові́чеськия, і сохраню́ за́повіді Твоя́.","@135 Лице́ Твоє́ просвіти́ на раба́ Твоєго́ і научи́ м'я оправда́нієм Твої́м.","@136 Ісхо́дища водна́я ізведо́сті о́чі мої́, поне́же не сохрани́х зако́на Твоєго́.","@137 Пра́веден єси́, Го́споди, і пра́ві суди́ Твої́;","@138 запові́дал єси́ пра́вду свиді́нія Твоя́, і і́стину зіло́.","@139 Іста́яла м'я єсть ре́вность Твоя́, я́ко заби́ша словеса́ Твоя́ вразі́ мої́.","@140 Разжже́но сло́во Твоє́ зіло́, і раб Твой возлюби́ є.","@141 Юні́йшій аз єсьм і унічиже́н; оправда́ній Твої́х не заби́х.","@142 Пра́вда Твоя́ — пра́вда во вік, і зако́н Твой — і́стина.","@143 Ско́рбі і ну́жди обріто́ша м'я; за́повіді Твоя́ — поуче́ніє моє́.","@144 Пра́вда свиді́нія Твоя́ — в вік; вразуми́ м'я, і жив бу́ду.","@145 Воззва́х всім се́рдцем мої́м, усли́ши м'я, Го́споди; оправда́нія Твоя́ взищу́.","@146 Воззва́х Ті, спаси́ м'я, і сохраню́ свиді́нія Твоя́.","@147 Предвари́х в безго́дії і воззва́х; на словеса́ Твоя́ упова́х.","@148 Предвари́сті о́чі мої́ ко у́тру поучи́тися словесе́м Твої́м.","@149 Глас мой усли́ши, Го́споди, по ми́лості Твоє́й; по судьбі́ Твоє́й живи́ м'я.","@150 Прибли́жишася гоня́щії м'я беззако́нієм; от зако́на же Твоєго́ удали́шася.","@151 Близ єси́ Ти, Го́споди, і всі путіє́ Твої́ — і́стина.","@152 Іспе́рва позна́х от свиді́ній Твої́х, я́ко в вік основа́л я єси́.","@153 Виждь смире́ніє моє́ і ізми́ м'я, я́ко зако́на Твоєго́ не заби́х.","@154 Суди́ суд мой і ізба́ви м'я; словесе́ ра́ди Твоєго́ живи́ м'я.","@155 Дале́че от грі́шник спасе́ніє, я́ко оправда́ній Твої́х не взиска́ша.","@156 Щедро́ти Твоя́ мно́гі, Го́споди; по судьбі́ Твоє́й живи́ м'я.","@157 Мно́зі ізгоня́щії м'я і стужа́ющії мі; от свиді́ній Твої́х не уклони́хся.","@158 Ви́діх неразуміва́ющия і іста́ях, я́ко слове́с Твої́х не сохрани́ша.","@159 Виждь, я́ко за́повіді Твоя́ возлюби́х; Го́споди, по ми́лості Твоє́й живи́ м'я.","@160 Нача́ло слове́с Твої́х — і́стина, і во вік вся судьби́ пра́вди Твоєя́.","@161 Кня́зі погна́ша м'я ту́не; і от слове́с Твої́х убоя́ся се́рдце моє́.","@162 Возра́дуюся аз о словесі́х Твої́х, я́ко обріта́яй кори́сть мно́гу.","@163 Непра́вду возненави́діх і омерзи́х; зако́н же Твой возлюби́х.","@164 Седмери́цею днем хвали́х Тя о судьба́х пра́вди Твоєя́.","@165 Мир мног лю́б'ящим зако́н Твой, і ність їм собла́зна.","@166 Ча́ях спаcе́нія Твоєго́, Го́споди, і за́повіді Твоя́ возлюби́х.","@167 Сохрани́ душа́ моя́ свиді́нія Твоя́ і возлюби́ я зіло́.","@168 Сохрани́х за́повіді Твоя́ і свиді́нія Твоя́, я́ко всі путіє́ мої́ пред Тобо́ю, Го́споди.","@169 Да прибли́житься моле́ніє моє́ пред Тя, Го́споди; по словесі́ Твоєму́ вразуми́ м'я.","@170 Да вни́деть проше́ніє моє́ пред Тя; Го́споди, по словесі́ Твоєму́ ізба́ви м'я.","@171 Отри́гнуть устні́ мої́ пі́ніє, єгда́ научи́ши м'я оправда́нієм Твої́м.","@172 Провіща́єть язи́к мой словеса́ Твоя́, я́ко вся за́повіді Твоя́ — пра́вда.","@173 Да бу́деть рука́ Твоя́ є́же спасти́ м'я, я́ко за́повіді Твоя́ ізво́лих.","@174 Возжела́х спасе́ніє Твоє́, Го́споди, і зако́н Твой поуче́ніє моє́ єсть.","@175 Жива́ бу́деть душа́ моя́ і восхва́лить Тя; і судьби́ Твоя́ помо́гуть мні.","@176 Заблуди́х, я́ко овча́ поги́бшеє; взищи́ раба́ Твоєго́, я́ко за́повідій Твої́х не заби́х.","§Сла́ва:"]},{"h":"Після 17-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 2:","ps":["Согріши́х к Тебі́, Спа́се, я́ко блу́дний син, прийми́ м'я, О́тче, ка́ющагося, і поми́луй м'я, Бо́же.","Сла́ва: Зову́ к Тебі́, Христе́ Спа́се, митаре́вим гла́сом: очи́сти м'я, я́коже о́наго, і поми́луй м'я, Бо́же.","І ни́ні: Богоро́дице, не пре́зри м'я, тре́бующа заступле́нія Твоєго́; на Тя бо упова́ душа́ моя́, поми́луй м'я."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Влади́ко Го́споди Вседержи́телю і Тво́рче всіх, щедро́т Оте́ць, і ми́лости Бог, от землі́ созда́вий челові́ка і показа́вий єго́ по о́бразу Твоєму́ і по подо́бію, да і тім просла́виться великолі́поє і́м'я Твоє́ на землі́, і істо́ргнена у́бо преступле́нієм Твої́х за́повідей, па́ки на лу́чшеє возсозда́вий єго́ во Христі́ Твоє́м, і возведи́й на Небеса́; благодарю́ Тя, я́ко умно́жил єси́ на мні вели́чіє Твоє́ і не пре́дал м'я єси́ враго́м мої́м в коне́ць істо́ргнути м'я і́щущим в про́пасть а́дову, ніже́ оста́вил м'я єси́ поги́бнути со беззако́ньми мої́ми. Ни́ні у́бо, многоми́лостиве і любоблаже Го́споди, не хотя́й сме́рти грі́шнаго, но обраще́нія ожида́яй, і приє́мляй, І́же низве́рженния ісправля́яй, сокруше́нния ісціля́яй, обрати́ і мене́ к покая́нію, і низве́рженнаго іспра́ви, і сокруше́ннаго ісціли́; пом'яни́ Твоя́ щедро́ти і є́же от ві́ка Твою́ непостижи́мую бла́гость, і моя́ безмі́рная забу́ди беззако́нія, я́же ді́лом, і сло́вом, і ми́слію соверши́х, разріши́ осліпле́ніє се́рдця моєго́ і даждь мі сле́зи умиле́нія на очище́ніє скве́рни ми́слі моєя́. Усли́ши, Го́споди, воньми́, Человіколю́бче, очи́сти, Благоутро́бне, і от мучи́тельства во мні ца́рствующих страсте́й окая́нную мою́ ду́шу свободи́; і не ктому́ да содержи́ть м'я гріх, ніже́ да возмо́жеть на м'я бори́тель де́мон, ніже́ к своєму́ хоті́нію да веде́ть м'я, но держа́вною Твоє́ю руко́ю, єго́ влади́чества ісхи́тивий м'я, Ти ца́рствуй во мні, благи́й і человіколюби́вий Го́споди, і всего́ Твоєго́ би́ти, і жи́ти мні про́чеє по Твоє́й благоволи́ во́лі. І пода́ждь мі неізрече́нною бла́гостію се́рдця очище́ніє, уст хране́ніє, правоту́ дія́ній, мудрова́ніє смире́нноє, мир помисло́в, тишину́ душе́вних мої́х сил, ра́дость духо́вную, любо́в і́стинную, долготерпі́ніє, бла́гость, кро́тость, ві́ру нелицемі́рну, воздержа́ніє обдержа́тельноє і всіх м'я благи́х плодо́в іспо́лни дарова́нієм Свята́го Твоєго́ Ду́ха. І не возведи́ мене́ в преполове́ніє дній мої́х, ніже́ неіспра́влену і негото́ву ду́шу мою́ восхи́тиши; но соверши́ м'я Твої́м соверше́нством, і та́ко м'я настоя́щаго житія́ ізведи́, я́ко да невозбра́нно проше́д нача́ла і вла́сті тьми, Твоє́ю благода́тію узрю́ і аз непристу́пния Твоєя́ сла́ви добро́ту неізрече́нную, со всі́ми святи́ми Твої́ми; в ни́хже освяти́ся, і просла́вися всечестно́є і великолі́поє і́м'я Твоє́, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[в путі́]</span>","<span class=''>[поноше́ніє]</span>","<span class=''>[размишля́ти бу́ду]</span>","<span class=''>[<em>Алекс.:</em> моє́ю]</span>"]},{"u":"Кафизма 18","e":"Kathisma 18","secs":[{"h":"Псалом 119","ps":["§Піснь степе́ней, 119.","@1 Ко Го́споду, внегда́ скорбі́ти мі, воззва́х, і усли́ша м'я.","@2 Го́споди, ізба́ви ду́шу мою́ от усте́н непра́ведних і от язи́ка льсти́ва.","@3 Что да́сться Тебі́ іли́ что приложи́ться Тебі́ к язи́ку льсти́ву?","@4 Стрі́ли си́льнаго ізощре́ни со у́гльми пусти́нними.","@5 Уви мні, я́ко прише́льствіє моє́ продолжи́ся, всели́хся с селе́нії кида́рськими;","@6 мно́го прише́льствова душа́ моя́; с ненави́дящими ми́ра біх ми́рен;","@7 єгда́ глаго́лах їм, боря́ху м'я ту́не."]},{"h":"Псалом 120","ps":["§Піснь степе́ней, 120.","@1 Возведо́х о́чі мої́ в го́ри, отню́дуже при́йдеть по́мощ моя́.","@2 По́мощ моя́ от Го́спода, сотво́ршаго не́бо і зе́млю.","@3 Не даждь во см'яте́ніє ноги́ твоєя́, ніже́ воздре́млеть храня́й тя;","@4 се, не воздре́млеть, ніже́ у́снеть храня́й Ізра́їля.","@5 Госпо́дь сохрани́ть тя, Госпо́дь — покро́в твой на ру́ку десну́ю твою́.","@6 Во дні со́лнце не ожже́ть тебе́, ніже́ луна́ но́щію.","@7 Госпо́дь сохрани́ть тя от вся́каго зла, сохрани́ть ду́шу твою́ Госпо́дь;","@8 Госпо́дь сохрани́ть вхожде́ніє твоє́ і ісхожде́ніє твоє́, отни́ні і до ві́ка."]},{"h":"Псалом 121","ps":["§Піснь степе́ней, 121.","@1 Возвесели́хся о ре́кших мні: в дом Госпо́день по́йдем.","@2 Стоя́ще бя́ху но́ги на́ша во дво́ріх твої́х, Ієрусали́ме.","@3 Ієрусали́м зи́ждемий я́ко град, єму́же прича́стіє єго́ вку́пі.","@4 Та́мо бо взидо́ша колі́на, колі́на Госпо́дня, свиді́ніє Ізра́їлево, іспові́датися і́мені Госпо́дню;","@5 я́ко та́мо сідо́ша престо́ли на суд, престо́ли в дому́ Дави́дові.","@6 Вопросі́те же я́же о ми́рі Ієрусали́ма, і оби́ліє лю́б'ящим тя.","@7 Бу́ди же мир в си́лі твоє́й, і оби́ліє в столпостіна́х твої́х.","@8 Ра́ди бра́тій мої́х і бли́жніх мої́х глаго́лах у́бо мир о тебі́.","@9 До́му ра́ди Го́спода Бо́га на́шего взиска́х блага́я тебі́."]},{"h":"Псалом 122","ps":["§Піснь степе́ней, 122.","@1 К Тебі́ возведо́х о́чі мої́, живу́щему на небесі́.","@2 Се, я́ко о́чі раб в руку́ госпо́дій свої́х, я́ко о́чі раби́ні в руку́ госпожі́ своєя́, та́ко о́чі на́ші ко Го́споду Бо́гу на́шему, до́ндеже уще́дрить ни.","@3 Поми́луй нас, Го́споди, поми́луй нас, я́ко помно́гу іспо́лнихомся унічиже́нія;","@4 найпа́че напо́лнися душа́ на́ша поноше́нія гобзу́ющих і унічиже́нія го́рдих."]},{"h":"Псалом 123","ps":["§Піснь степе́ней, 123.","@1 Я́ко а́ще не Госпо́дь би бил в нас, — да рече́ть у́бо Ізра́їль,","@2 я́ко а́ще не Госпо́дь би бил в нас, внегда́ воста́ти челові́ком на ни, — у́бо живи́х поже́рли би́ша нас;","@3 внегда́ прогні́ватися я́рості їх на ни, у́бо вода́ потопи́ла би нас.","@4 Пото́к пре́йде душа́ на́ша;","@5 у́бо пре́йде душа́ на́ша во́ду непостоя́нную.","@6 Благослове́н Госпо́дь, І́же не даде́ нас в лови́тву зубо́м їх.","@7 Душа́ на́ша, я́ко пти́ця ізба́вися от сі́ті ловя́щих; сіть сокруши́ся, і ми ізба́влені би́хом.","@8 По́мощ на́ша во і́м'я Го́спода, сотво́ршаго не́бо і зе́млю.","§Сла́ва:"]},{"h":"Псалом 124","ps":["§Піснь степе́ней, 124.","@1 Наді́ющіїся на Го́спода, я́ко гора́ Сіо́н; не подви́житься в вік живи́й во Ієрусали́мі.","@2 Го́ри о́крест єго́, і Госпо́дь о́крест люді́й Свої́х, отни́ні і до ві́ка.","@3 Я́ко не оста́вить Госпо́дь жезла́ грі́шних на жре́бій пра́ведних, я́ко да не про́струть пра́веднії в беззако́нія рук свої́х.","@4 Ублажи́, Го́споди, благі́я і пра́вия се́рдцем.","@5 Уклоня́ющияся же в развраще́нія отведе́ть Госпо́дь с ді́лающими беззако́ніє; мир на Ізра́їля!"]},{"h":"Псалом 125","ps":["§Піснь степе́ней, 125.","@1 Внегда́ возврати́ти Го́споду плін Сіо́нь, би́хом я́ко уті́шені.","@2 Тогда́ іспо́лнишася ра́дости уста́ на́ша, і язи́к наш весе́лія; тогда́ реку́ть во язи́ціх: возвели́чил єсть Госпо́дь сотвори́ти с ни́ми.","@3 Возвели́чил єсть Госпо́дь сотвори́ти с на́ми; би́хом веселя́щеся.","@4 Возврати́, Го́споди, пліне́ніє на́ше, я́ко пото́ки ю́гом.","@5 Сі́ющії слеза́ми ра́достію по́жнуть.","@6 Ходя́щії хожда́ху і пла́кахуся, мета́юще сі́мена своя́; гряду́ще же при́йдуть ра́достію, взе́млюще рукоя́ті своя́."]},{"h":"Псалом 126","ps":["§Піснь степе́ней, 126.","@1 А́ще не Госпо́дь сози́ждеть дом, всу́є труди́шася зи́ждущії; а́ще не Госпо́дь сохрани́ть град, всу́є бді стреги́й.","@2 Всу́є вам єсть у́треневати; воста́нете по сіді́нії яду́щії хліб болі́зні, єгда́ дасть возлю́бленним Свої́м сон.","@3 Се, достоя́ніє Госпо́днє — си́нове, мзда — плода́ чре́вняго.","@4 Я́ко стрі́ли в руці́ си́льнаго, та́ко си́нове оттрясе́нних.","@5 Блаже́н, і́же іспо́лнить жела́ніє своє́ от них; не постидя́ться, єгда́ глаго́лють враго́м свої́м во враті́х."]},{"h":"Псалом 127","ps":["§Піснь степе́ней, 127.","@1 Блаже́нні всі боя́щіїся Го́спода, ходя́щії в путе́х Єго́;","@2 труди́ плодо́в⁽1⁾ твої́х сні́си; блаже́н єси́, і добро́ тебі́ бу́деть.","@3 Жена́ Твоя́, я́ко лоза́ плодови́та, в страна́х до́му твоєго́;","@4 си́нове твої́, я́ко новосажде́нія ма́сличная, о́крест трапе́зи твоєя́.","@5 Се, та́ко благослови́ться челові́к боя́йся Го́спода.","@6 Благослови́ть тя Госпо́дь от Сіо́на, і у́зриши блага́я Ієрусали́ма вся дні живота́ твоєго́,","@7 і у́зриши си́ни сино́в твої́х; мир на Ізра́їля!"]},{"h":"Псалом 128","ps":["§Піснь степе́ней, 128.","@1 Мно́жицею бра́шася со мно́ю от ю́ности моєя́, — да рече́ть у́бо Ізра́їль;","@2 мно́жицею бра́шася со мно́ю от ю́ности моєя́, і́бо не премого́ша м'я.","@3 На хребті́ моє́м ді́лаша грі́шници, продолжи́ша беззако́ніє своє́.","@4 Госпо́дь пра́веден ссіче́ ви́я грі́шников.","@5 Да постидя́ться і возвратя́ться всп'ять всі ненави́дящії Сіо́на;","@6 да бу́дуть, я́ко трава́ на здіх⁽2⁾, я́же пре́жде восторже́нія і́зсше;","@7 Є́юже не іспо́лни руки́ своєя́ жняй, і ні́дра своєго́ рукоя́ті собира́яй;","@8 і не рі́ша мимоходя́щії; благослове́ніє Госпо́днє на ви, благослови́хом ви во і́м'я Госпо́днє.","§Сла́ва:"]},{"h":"Псалом 129","ps":["§Піснь степе́ней, 129.","@1 Із глубини́ воззва́х к Тебі́, Го́споди; Го́споди, усли́ши глас мой.","@2 Да бу́дуть у́ші Твої́ вне́млющі гла́су моле́нія моєго́.","@3 А́ще беззако́нія на́зриши, Го́споди, Го́споди, кто постої́ть? Я́ко у Тебе́ очище́ніє єсть.","@4 І́мене ра́ди Твоєго́ потерпі́х⁽3⁾ Тя, Го́споди, потерпі́ душа́ моя́ в сло́во Твоє́; упова́ душа́ моя́ на Го́спода.","@5 От стра́жі у́треннія до но́щі, от стра́жі у́треннія да упова́єть Ізра́їль на Го́спода;","@6 я́ко у Го́спода ми́лость, і мно́гоє у Него́ ізбавле́ніє; і Той ізба́вить Ізра́їля от всіх беззако́ній єго́."]},{"h":"Псалом 130","ps":["§Піснь степе́ней, 130.","@1 Го́споди, не вознесе́ся се́рдце моє́, ніже́ вознесо́стіся о́чі мої́; ніже́ ходи́х в вели́ких, ніже́ в ди́вних па́че мене́.","@2 А́ще не смиреному́дрствовах, но вознесо́х ду́шу мою́, я́ко отдоє́ноє на ма́тер свою́, та́ко возда́си на ду́шу мою́.","@3 Да упова́єть Ізра́їль на Го́спода отни́ні і до ві́ка."]},{"h":"Псалом 131","ps":["§Піснь степе́ней, 131.","@1 Пом'яни́, Го́споди, Дави́да і всю кро́тость єго́;","@2 я́ко кля́тся Го́сподеві, обіща́ся Бо́гу Іа́ковлю;","@3 а́ще вни́ду в селе́ніє до́му моєго́, іли́ взи́ду на одр посте́лі моєя́;","@4 а́ще дам сон очи́ма мої́ма, і ві́ждома⁽4⁾ мої́ма дрема́ніє, і поко́й скранія́ма⁽5⁾ мої́ма;","@5 до́ндеже обря́щу мі́сто Го́сподеві, селе́ніє Бо́гу Іа́ковлю.","@6 Се, сли́шахом я во Євфра́фі, обріто́хом я в поля́х дубра́ви;","@7 вни́дем в селе́нія Єго́, поклоні́мся на мі́сто, іді́же стоя́сті но́зі Єго́.","@8 Воскrни́, Го́споди, в поко́й Твой, Ти і ківо́т святи́ні Твоєя́.","@9 Свяще́нници Твої́ облеку́ться пра́вдою, і преподо́бнії Твої́ возра́дуються.","@10 Дави́да ра́ди, раба́ Твоєго́, не отврати́ лице́ пома́заннаго Твоєго́.","@11 Кля́тся Госпо́дь Дави́ду і́стиною, і не отве́ржеться єя́: от плода́ чре́ва твоєго́ посажду́ на престо́лі твоє́м.","@12 А́ще сохраня́ть си́нове твої́ заві́т Мой і свиді́нія Моя́ сія́, ї́мже научу́ я, і си́нове їх до ві́ка ся́дуть на престо́лі твоє́м.","@13 Я́ко ізбра́ Госпо́дь Сіо́на, ізво́ли ї в жили́ще Себі́.","@14 Сей поко́й Мой во вік ві́ка, зді вселю́ся, я́ко Ізво́лих ї.","@15 Лови́тву єго́ благословля́яй благословлю́, ни́щия єго́ наси́щу хлі́би;","@16 свяще́нники єго́ облеку́ во спасе́ніє, і преподо́бнії єго́ ра́достію возра́дуються.","@17 Та́мо возращу́ рог Дави́дові, угото́вах світи́льник пома́занному моєму́.","@18 Враги́ єго́ облеку́ студо́м, на нем же процвіте́ть святи́ня Моя́."]},{"h":"Псалом 132","ps":["§Піснь степе́ней, 132.","@1 Се, что добро́, іли́ что красно́, но є́же жи́ти бра́тії вку́пі?","@2 Я́ко ми́ро на главі́, сходя́щеє на браду́, браду́ Ааро́ню, сходя́щеє на оме́ти оде́жди єго́;","@3 я́ко роса́ аєрмо́нськая сходя́щая на го́ри Сіо́нськія; я́ко та́мо запові́да Госпо́дь благослове́ніє і живо́т до ві́ка."]},{"h":"Псалом 133","ps":["§Піснь степе́ней, 133.","@1 Се, ни́ні благослові́те Го́спода, всі раби́ Госпо́дні, стоя́щії в хра́мі Госпо́дні, во дво́ріх до́му Бо́га на́шего.","@2 В но́щех воздіжі́те ру́ки ва́ша во свята́я і благослові́те Го́спода.","@3 Благослови́ть Тя Госпо́дь от Сіо́на, сотвори́вий не́бо і зе́млю.","§Сла́ва:"]},{"h":"Після 18-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 2:","ps":["Пре́жде да́же не осу́диши м'я, Го́споди мой, Го́споди, даждь мі обраще́ніє і ісправле́ніє мно́гих мої́х гріхо́в; даждь мі умиле́ніє духо́вноє, я́ко да возопію́ к Тебі́: Благоутро́бне, Человіколю́бче Бо́же мой, спаси́ м'я.","Сла́ва: Несми́сленним ското́м уподо́бивийся аз, блу́дний, приложи́хся їм; обраще́ніє мі да́руй, Христе́, я́ко да прийму́ у Тебе́ ве́лію ми́лость.","І ни́ні: Не отврати́, Влади́чице, лиця́ Твоєго́ от мене́, моля́щагося Тебі́; но, я́ко благоутро́бная Ма́ти ще́драго Бо́га, потщи́ся пре́жде конця́ обраще́ніє мні дарова́ти, я́ко да спа́сся Тобо́ю, воспою́ Тя я́ко спасе́ніє і упова́ніє моє́ непосра́мленноє, Госпоже́ моя́."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди, да не я́ростію Твоє́ю обличи́ши мене́, ніже́ гні́вом Твої́м нака́жеши м'я. Влади́ко Го́споди Ісу́се Христе́, Си́не Бо́га Жива́го, поми́луй м'я, грі́шнаго, ни́щаго, обнаже́ннаго, ліни́ваго, неради́ваго, прекосло́внаго, окая́ннаго, блудника́, прелюбоді́я, малакі́я, мужело́жника, скве́рнаго, блу́днаго, неблагода́рнаго, неми́лостиваго, жесто́каго, пія́ницю, сожже́ннаго со́вістію, безли́чнаго, бездерзнове́ннаго, безотві́тнаго, недосто́йнаго Твоєго́ человіколю́бія і досто́йна вся́каго муче́нія, і геє́нни, і му́ки; і не ра́ди мно́жества толи́ких мої́х согріше́ній, мно́жеству подложи́ши, Ізба́вителю, мук, но поми́луй м'я, я́ко не́мощен єсьм, і душе́ю і пло́тію, і ра́зумом і помишле́нієм; і ї́миже ві́си судьба́ми, спаси́ м'я, недосто́йнаго раба́ Твоєго́, моли́твами Пречи́стия Влади́чиці на́шея Богоро́диці і всіх святи́х, от ві́ка Тебі́ благоуго́ждших; я́ко Благослове́н єси́ во ві́ки віко́в, амі́нь."]}],"notes":["<span class=''>[рук]</span>","<span class=''>[на кро́віх]</span>","","Вѣ́жда — повіки.","Скра́нїй — скроня."]},{"u":"Кафизма 19","e":"Kathisma 19","secs":[{"h":"Псалом 134","ps":["§Аллилу́я, 134.","@1 Хвалі́те і́м'я Госпо́днє, хвалі́те, раби́ Го́спода,","@2 стоя́щії во хра́мі Госпо́дні, во дво́ріх до́му Бо́га на́шего.","@3 Хвалі́те Го́спода, я́ко благ Госпо́дь; по́йте і́мені Єго́, я́ко добро́;","@4 я́ко Іа́кова ізбра́ Себі́ Госпо́дь, Ізра́їля в достоя́ніє Себі́;","@5 я́ко аз позна́х, я́ко ве́лій Госпо́дь, і Госпо́дь наш над всі́ми бо́ги;","@6 вся, єли́ка восхоті́ Госпо́дь, сотвори́ на небесі́ і на землі́, в моря́х і во всіх бе́зднах.","@7 Возводя́ о́блаки от послі́дніх землі́, мо́лнії в дождь сотвори́, ізводя́й ві́три от сокро́вищ Свої́х.","@8 І́же порази́ пе́рвенці єги́петськия от челові́ка до скота́;","@9 посла́ зна́менія і чудеса́ посреді́ тебе́, Єги́пте, на фарао́на і на вся раби́ єго́.","@10 І́же порази́ язи́ки мно́гі і ізби́ царі́ крі́пкі;","@11 Сіо́на, царя́ Аморре́йська, і О́га, царя́ Васа́нська, і вся ца́рствія Ханаа́нська;","@12 і даде́ зе́млю їх достоя́ніє, достоя́ніє Ізра́їлю лю́дем Свої́м.","@13 Го́споди, і́м'я Твоє́ в вік, і па́м'ять Твоя́ в род і род;","@14 я́ко суди́ти і́мать Госпо́дь лю́дем Свої́м, і о рабі́х Свої́х умо́литься.","@15 І́доли язи́к — сребро́ і зла́то, діла́ рук челові́чеських;","@16 уста́ і́муть і не возглаго́лють; о́чі і́муть і не у́зрять;","@17 у́ші і́муть і не усли́шать; ніже́ бо єсть дух во усті́х їх.","@18 Подо́бні їм да бу́дуть творя́щії я і всі наді́ющіїся на ня.","@19 До́ме Ізра́їлев, благослові́те Го́спода; до́ме Ааро́нь, благослові́те Го́спода; до́ме Леві́їн, благослові́те Го́спода;","@20 боя́щіїся Го́спода, благослові́те Го́спода.","@21 Благослове́н Госпо́дь от Сіо́на, живи́й во Ієрусали́мі."]},{"h":"Псалом 135","ps":["§Аллилу́я, 135.","@1 Іспові́дайтеся Го́сподеві, я́ко Благ; я́ко в вік ми́лость Єго́.","@2 Іспові́дайтеся Бо́гу бого́в; я́ко в вік ми́лость Єго́.","@3 Іспові́дайтеся Го́сподеві господе́й; я́ко в вік ми́лость Єго́.","@4 Сотво́ршему чудеса́ ве́лія Єди́ному; я́ко в вік ми́лость Єго́.","@5 Сотво́ршему небеса́ ра́зумом; я́ко в вік ми́лость Єго́.","@6 Утверди́вшему зе́млю на вода́х; я́ко в вік ми́лость Єго́.","@7 Сотво́ршему світи́ла ве́лія Єди́ному; я́ко в вік ми́лость Єго́;","@8 со́лнце во о́бласть дне; я́ко в вік ми́лость Єго́;","@9 луну́ і зві́зди во о́бласть но́щі; я́ко в вік ми́лость Єго́.","@10 Порази́вшему Єги́пта с пе́рвенці єго́; я́ко в вік ми́лость Єго́;","@11 і ізве́дшему Ізра́їля от среди́ їх; я́ко в вік ми́лость Єго́;","@12 руко́ю крі́пкою і ми́шцею висо́кою; я́ко в вік ми́лость Єго́.","@13 Разді́льшему Чермно́є мо́ре в разділе́нія; я́ко в вік ми́лость Єго́;","@14 і прове́дшему Ізра́їля посреді́ єго́; я́ко в вік ми́лость Єго́;","@15 і істря́сшему фарао́на і си́лу єго́ в мо́ре Чермно́є; я́ко в вік ми́лость Єго́.","@16 Прове́дшему лю́ди Своя́ в пусти́ні; я́ко в вік ми́лость Єго́.","@17 Порази́вшему царі́ ве́лія; я́ко в вік ми́лость Єго́.","@18 І уби́вшему царі́ крі́пкія; я́ко в вік ми́лость Єго́;","@19 Сіо́на, царя́ Аморре́йська; я́ко в вік ми́лость Єго́;","@20 і О́га, царя́ Васа́нська; я́ко в вік ми́лость Єго́.","@21 І да́вшему зе́млю їх достоя́ніє; я́ко в вік ми́лость Єго́;","@22 достоя́ніє Ізра́їлю, рабу́ Своєму́; я́ко в вік ми́лость Єго́.","@23 Я́ко во смире́нії на́шем пом'яну́ ни Госпо́дь; я́ко в вік ми́лость Єго́.","@24 І ізба́вил ни єсть от враго́в на́ших; я́ко в вік ми́лость Єго́;","@25 дая́й пи́щу вся́кой пло́ті; я́ко в вік ми́лость Єго́.","@26 Іспові́дайтеся Бо́гу Небе́сному; я́ко в вік ми́лость Єго́."]},{"h":"Псалом 136","ps":["§Дави́ду Ієремі́єм, 136.","@1 На ріка́х Вавило́нських, та́мо сідо́хом і пла́кахом, внегда́ пом'яну́ти нам Сіо́на;","@2 на ве́рбіїх посреді́ єго́ обі́сихом орга́ни на́ша.","@3 Я́ко та́мо вопроси́ша ни плі́ншії нас о словесі́х пі́сней, і ве́дшії нас о пі́нії; воспо́йте нам от пі́сней сіо́нських.","@4 Ка́ко воспоє́м піснь Госпо́дню на землі́ чужде́й?","@5 А́ще забу́ду тебе́, Ієрусали́ме, забве́нна бу́ди десни́ця моя́.","@6 Прильпни́ язи́к мой горта́ні моєму́, а́ще не пом'яну́ тебе́, а́ще не предложу́ Ієрусали́ма, я́ко в нача́лі весе́лія моєго́.","@7 Пом'яни́, Го́споди, си́ни Едо́мськія в день Ієрусали́мль глаго́лющия: істоща́йте, істоща́йте до основа́ній єго́.","@8 Дщи Вавило́ня окая́нная, блаже́н, і́же возда́сть тебі́ воздая́ніє твоє́, є́же воздала́ єси́ нам;","@9 блаже́н, і́же і́меть і разбіє́ть младе́нці твоя́ о ка́мень.","§Сла́ва:"]},{"h":"Псалом 137","ps":["§Псало́м Дави́ду, Агге́я і Заха́рії, 137.","@1 Іспові́мся Тебі́, Го́споди, всім се́рдцем мої́м, і пред а́нгели воспою́ Тебі́, я́ко усли́шал єси́ вся глаго́ли уст мої́х;","@2 поклоню́ся ко хра́му свято́му Твоєму́ і іспові́мся і́мені Твоєму́ о ми́лості Твоє́й і і́стині Твоє́й, я́ко возвели́чил єси́ над всім і́м'я Твоє́ свято́є.","@3 В о́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я; умно́жиши м'я в душі́ моє́й си́лою Твоє́ю.","@4 Да іспові́дяться Тебі́, Го́споди, всі ца́ріє зе́мстії, я́ко усли́шаша вся глаго́ли уст Твої́х;","@5 і да воспою́ть в путе́х Госпо́дніх, я́ко ве́лія сла́ва Госпо́дня;","@6 я́ко висо́к Госпо́дь, і смире́нния призира́єть, і висо́кая іздале́ча вість.","@7 А́ще пойду́ посреді́ ско́рби, живи́ши м'я; на гнів враг мої́х просте́рл єси́ ру́ку Твою́, і спасе́ м'я десни́ця Твоя́.","@8 Госпо́дь возда́сть за м'я; Го́споди, ми́лость Твоя́ во вік; діл руку́ Твоє́ю не пре́зри."]},{"h":"Псалом 138","ps":["§В коне́ць Дави́ду, псало́м Заха́ріїн, в разсі́янії, 138.","@1 Го́споди, іскуси́л м'я єси́ і позна́л м'я єси́; Ти позна́л єси́ сіда́ніє моє́ і воста́ніє моє́.","@2 Ти разумі́л єси́ помишле́нія моя́ іздале́ча;","@3 стезю́ мою́ і у́же моє́ Ти єси́ ізслі́довал і вся путі́ моя́ прови́діл єси́.","@4 Я́ко ність льсти в язи́ці моє́м; се, Го́споди, Ти позна́л єси́","@5 вся послі́дняя і дре́вняя; Ти созда́л єси́ м'я і положи́л єси́ на мні ру́ку Твою́.","@6 Удиви́ся ра́зум Твой от мене́, утверди́ся, не возмогу́ к Нему́.","@7 Ка́мо пойду́ от Ду́ха Твоєго́? І от лиця́ Твоєго́ ка́мо біжу́?","@8 А́ще взи́ду на не́бо, Ти та́мо єси́; а́ще сни́ду во ад, та́мо єси́.","@9 А́ще возьму́ крилі́ мої́ ра́но і вселю́ся в послі́дніх мо́ря,","@10 і та́мо бо рука́ Твоя́ наста́вить м'я, і удержи́ть м'я десни́ця Твоя́.","@11 І ріх: єда́ тьма попере́ть м'я? І нощ просвіще́ніє в сла́дості моє́й.","@12 Я́ко тьма не помрачи́ться от Тебе́, і нощ я́ко день просвіти́ться; я́ко тьма єя́, та́ко і світ єя́.","@13 Я́ко Ти созда́л⁽1⁾ єси́ утро́би моя́, восприя́л м'я єси́ із чре́ва ма́тере моєя́.","@14 Іспові́мся Тебі́, я́ко стра́шно удиви́лся єси́; чу́дна діла́ Твоя́, і душа́ моя́ зна́єть зіло́.","@15 Не утаї́ся кость моя́ от Тебе́, ю́же сотвори́л єси́ в та́йні, і соста́в мой в преіспо́дніх землі́.","@16 Несоді́ланноє моє́ ви́дісті о́чі Твої́, і в кни́зі Твоє́й всі напи́шуться; во днех сози́ждуться, і нікто́же в них.","@17 Мні же зіло́ че́стні би́ша дру́зі Твої́, Бо́же, зіло́ утверди́шася влади́чествія їх;","@18 ізочту́ їх, і па́че піска́ умно́жаться; воста́х, і єще́ єсьм с Тобо́ю.","@19 А́ще ізбіє́ши грі́шники, Бо́же; му́жіє крове́й, уклоні́теся от мене́.","@20 Я́ко ревни́ві єсте́ в помишле́ніїх, при́ймуть в суєту́ гра́ди Твоя́.","@21 Не ненави́дящия ли Тя, Го́споди, возненави́діх, і о вразі́х Твої́х іста́ях?","@22 Соверше́нною не́навистію возненави́діх я; во враги́ би́ша мі.","@23 Іскуси́ м'я, Бо́же, і уві́ждь се́рдце моє́; істяжи́ м'я і разумі́й стезі́ моя́;","@24 і виждь, а́ще путь беззако́нія во мні, і наста́ви м'я на путь ві́чен."]},{"h":"Псалом 139","ps":["§В коне́ць, псало́м Дави́ду, 139.","@1 Ізми́ м'я, Го́споди, от челові́ка лука́ва, от му́жа непра́ведна ізба́ви м'я;","@2 і́же поми́слиша непра́вду в се́рдці, весь день ополча́ху бра́ні;","@3 ізостри́ша язи́к свой, я́ко змії́н; яд а́спідов под устна́ми їх.","@4 Сохрани́ м'я, Го́споди, із руки́ грі́шничі, от челові́к непра́ведних ізми́ м'я, і́же поми́слиша зап'я́ті стопи́ моя́.","@5 Скри́ша го́рдії сіть мні і у́жи, преп'я́ша сіть нога́ма мої́ма;","@6 при стезі́ собла́зни положи́ша мі.","@7 Ріх Го́сподеві: Бог мой єси́ Ти, внуши́, Го́споди, глас моле́нія моєго́.","@8 Го́споди, Го́споди! Си́ло спаcе́нія моєго́, осіни́л єси́ над главо́ю моє́ю в день бра́ні.","@9 Не преда́ждь мене́, Го́споди, от жела́нія моєго́ грі́шнику; поми́слиша на м'я, не оста́ви мене́, да не когда́ вознесу́ться.","@10 Псало́м окруже́нія їх, труд усте́н їх покри́єть я.","@11 Паду́ть на них у́глія о́гненная, низложи́ши я во страсте́х, і не постоя́ть.","@12 Муж язи́чен не іспра́виться на землі́; му́жа непра́ведна зла́я улов'я́ть во істлі́ніє.","@13 Позна́х, я́ко сотвори́ть Госпо́дь суд ни́щим і месть убо́гим.","@14 Оба́че пра́веднії іспові́дяться і́мені Твоєму́, і вселя́ться пра́вії с лице́м Твої́м.","§Сла́ва:"]},{"h":"Псалом 140","ps":["§Псало́м Дави́ду, 140.","@1 Го́споди, воззва́х к Тебі́, усли́ши м'я; воньми́ гла́су моле́нія моєго́, внегда́ воззва́ти мі к Тебі́.","@2 Да іспра́виться моли́тва моя́, я́ко кади́ло пред Тобо́ю; воздія́ніє руку́ моє́ю — же́ртва вече́рняя.","@3 Положи́, Го́споди, хране́ніє усто́м мої́м і двер огражде́нія о устна́х мої́х.","@4 Не уклони́ се́рдце моє́ в словеса́ лука́вствія — непщева́ти вини́ о грісі́х с челові́ки, ді́лающими беззако́ніє; і не сочту́ся со ізбра́нними їх.","@5 Нака́жеть м'я пра́ведник ми́лостію і обличи́ть м'я, єле́й же грі́шнаго да не нама́стить глави́ моєя́; я́ко єще́ і моли́тва моя́ во благоволе́ніїх їх.","@6 Поже́рти би́ша при ка́мені судії́ їх; усли́шаться глаго́ли мої́, я́ко возмого́ша⁽2⁾.","@7 Я́ко то́лща землі́ просі́деся на землі́, расточи́шася ко́сті їх при а́ді.","@8 Я́ко к Тебі́, Го́споди, Го́споди, о́чі мої́; на Тя упова́х, не отими́ ду́шу мою́;","@9 сохрани́ м'я от сі́ті, ю́же соста́виша мі, і от собла́зн ді́лающих беззако́ніє.","@10 Паду́ть во мре́жу свою́ грі́шници; єди́н єсьм аз, до́ндеже прейду́."]},{"h":"Псалом 141","ps":["§Ра́зума Дави́ду, внегда́ би́ти єму́ в верте́пі моля́щемуся, 141.","@2 Гла́сом мої́м ко Го́споду воззва́х, гла́сом мої́м ко Го́споду помоли́хся.","@3 Пролію́ пред Ним моле́ніє моє́, печа́ль мою́ пред Ним возвіщу́.","@4 Внегда́ ізчеза́ти от мене́ ду́ху моєму́, і Ти позна́л єси́ стезі́ моя́; на путі́ сем, по нему́же хожда́х, скри́ша сіть мні.","@5 Сматря́х одесну́ю і возгля́дах, і не бі зна́яй мене́; поги́бе бі́гство от мене́, і ність взиска́яй ду́шу мою́.","@6 Воззва́х к Тебі́, Го́споди, ріх: Ти єси́ упова́ніє моє́, часть моя́ єси́ на землі́ живи́х.","@7 Воньми́ моле́нію моєму́, я́ко смири́хся зіло́; ізба́ви м'я от гоня́щих м'я, я́ко укріпи́шася па́че мене́.","@8 Ізведи́ із темни́ці ду́шу мою́, іспові́датися і́мені Твоєму́; мене́ ждуть пра́ведници, до́ндеже возда́си мні."]},{"h":"Псалом 142","ps":["§Псало́м Дави́ду, єгда́ гоня́ше єго́ Авессало́м, син єго́, 142.","@1 Го́споди, усли́ши моли́тву мою́, внуши́ моле́ніє моє́ во і́стині Твоє́й, усли́ши м'я в пра́вді Твоє́й;","@2 і не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й.","@3 Я́ко погна́ враг ду́шу мою́; смири́л єсть в зе́млю живо́т мой; посади́л м'я єсть в те́мних, я́ко ме́ртвия ві́ка.","@4 І уни́ во мні дух мой, во мні см'яте́ся се́рдце моє́.","@5 Пом'яну́х дні дре́внія, поучи́хся во всіх ді́ліх Твої́х, в творе́ніїх руку́ Твоє́ю поуча́хся.","@6 Возді́х к Тебі́ ру́ці мої́; душа́ моя́, я́ко земля́ безво́дная, Тебі́.","@7 Ско́ро усли́ши м'я, Го́споди, ізчезе́ дух мой; не отврати́ лиця́ Твоєго́ от мене́, і уподо́блюся низходя́щим в ров.","@8 Сли́шану сотвори́ мні зау́тра ми́лость Твою́, я́ко на Тя упова́х; скажи́ мні, Го́споди, путь, в о́ньже пойду́, я́ко к Тебі́ взях ду́шу мою́.","@9 Ізми́ м'я от враг мої́х, Го́споди, к Тебі́ прибіго́х.","@10 Научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой; Дух Твой Благи́й наста́вить м'я на зе́млю пра́ву.","@11 І́мене Твоєго́ ра́ди, Го́споди, живи́ши м'я пра́вдою Твоє́ю; ізведе́ши от печа́лі ду́шу мою́;","@12 і ми́лостію Твоє́ю потреби́ши враги́ моя́ і погуби́ши вся стужа́ющия душі́ моє́й; я́ко аз раб Твой єсьм.","§Сла́ва:"]},{"h":"Після 19-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 7:","ps":["Благодаря́ сла́влю Тя, Бо́же мой, я́ко всім дал єси́ грі́шником покая́ніє; Спа́се, не посрами́ мене́, єгда́ при́йдеши суди́ти ми́ру всему́, сра́мная діла́ сотво́ршаго.","Сла́ва: Безмі́рная Тебі́ прегріши́в і безмі́рних муче́ній ожида́ю; Бо́же мой, уще́дрив спаси́ м'я.","І ни́ні: Ко мно́жеству ми́лости Твоєя́ ни́ні прибіга́ю, разріши́ вери́ги, Богоро́дице, согріше́ній мої́х."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Влади́ко Христе́ Бо́же, І́же Страстьми́ Твої́ми стра́сті моя́ ісціли́вий і я́звами Твої́ми я́зви моя́ уврачева́вий; да́руй мні, мно́го Тебі́ прегріши́вшему, сле́зи умиле́нія. Сраствори́ моєму́ ті́лу от обоня́нія Животворя́щаго Ті́ла Твоєго́, і наслади́ ду́шу мою́ Твоє́ю Честно́ю Кро́вію от го́рести, є́юже м'я сопроти́вник напої́, возви́си мой ум к Тебі́, до́лу привле́кшийся, і возведи́ от про́пасти поги́белі; я́ко не і́мам покая́нія, не і́мам умиле́нія, не і́мам слези́ уті́шительния, возводя́щия ча́да ко своєму́ наслі́дію. Омрачи́хся умо́м в жите́йських страсте́х, не могу́ воззрі́ти к Тебі́ в болі́зні, не могу́ согрі́тися слеза́ми, я́же к Тебі́ любве́; но, Влади́ко Го́споди Ісу́се Христе́, Сокро́вище благи́х, да́руй мні покая́ніє всеці́лоє і се́рдце люботру́дноє во взиска́ніє Твоє́, да́руй мні благода́ть Твою́ і обнови́ во мні зра́ки Твоєго́ о́браза. Оста́вих Тя, не оста́ви мене́, ізи́ди на взиска́ніє моє́. Возведи́ к па́житі Твоє́й і сопричти́ м'я овця́м ізбра́ннаго Твоєго́ ста́да, воспита́й м'я с ни́ми от зла́ка Боже́ственних Твої́х Та́їнств, моли́твами Пречи́стия Твоєя́ Ма́тере і всіх святи́х Твої́х, амі́нь."]}],"notes":["<span class=''>[стяжа́л]</span>","<span class=''>[услади́шася]</span>"]},{"u":"Кафизма 20","e":"Kathisma 20","secs":[{"h":"Псалом 143","ps":["§Псало́м Дави́ду, к Голіа́фу, 143.","@1 Благоcлове́н Госпо́дь Бог мой, науча́яй ру́ці мої́ на ополче́ніє, пе́рсти моя́ на брань.","@2 Ми́лость моя́ і прибі́жище моє́, Засту́пник мой і Ізба́витель мой, Защи́титель мой, і на Него́ упова́х; повину́яй лю́ди моя́ под м'я.","@3 Го́споди, что єсть челові́к, я́ко позна́лся єси́ єму́? Іли́ син челові́ч, я́ко вміня́єши єго́?","@4 Челові́к суєті́ уподо́бися; дні́є єго́ — я́ко сінь прехо́дять.","@5 Го́споди, преклони́ небеса́ і сни́ди; косни́ся гора́м — і воздим'я́ться;","@6 блесни́ мо́лнію — і разжене́ши я; посли́ стрі́ли Твоя́ — і см'яте́ши я.","@7 Посли́ ру́ку Твою́ с висоти́, ізми́ м'я і ізба́ви м'я от вод мно́гих, із руки́ сино́в чужди́х,","@8 ї́хже уста́ глаго́лаша суєту́, і десни́ця їх — десни́ця непра́вди.","@9 Бо́же, піснь но́ву воспою́ Тебі́, во псалти́рі десятостру́ннім пою́ Тебі́;","@10 даю́щему спасе́ніє царе́м, ізбавля́ющему Дави́да, раба́ Своєго́, от меча́ лю́та.","@11 Ізба́ви м'я і ізми́ м'я із руки́ сино́в чужди́х, ї́хже уста́ глаго́лаша суєту́, і десни́ця їх — десни́ця непра́вди;","@12 ї́хже си́нове їх — я́ко новосажде́нія водруже́ная в ю́ності своє́й, дще́рі їх удо́брени, преукра́шени, я́ко подо́біє хра́ма;","@13 храни́лища їх іспо́лнена, отрига́ющая от сего́ в сіє́; о́вці їх многопло́дни, мно́жащияся во ісхо́дищих свої́х; воло́ве їх то́лсті;","@14 ність паде́нія опло́ту, ніже́ прохо́да, ніже́ во́пля в сто́гнах їх.","@15 Ублажи́ша лю́ди, ї́мже сія́ суть; блаже́нні лю́діє, ї́мже Госпо́дь Бог їх."]},{"h":"Псалом 144","ps":["§Хвала́ Дави́ду, 144.","@1 Вознесу́ Тя, Бо́же мой, Царю́ мой, і благословлю́ і́м'я Твоє́ в вік і в вік ві́ка.","@2 На всяк день благословлю́ Тя, і восхвалю́ і́м'я Твоє́ в вік і в вік ві́ка.","@3 Ве́лій Госпо́дь і хва́лен зіло́, і вели́чію Єго́ ність конця́.","@4 Род і род восхва́лять діла́ Твоя́ і си́лу Твою́ возвістя́ть;","@5 великолі́піє сла́ви святи́ні Твоєя́ возглаго́лють і чудеса́ Твоя́ пові́дять;","@6 і си́лу стра́шних Твої́х реку́ть і вели́чіє Твоє́ пові́дять;","@7 па́м'ять мно́жества бла́гости Твоєя́ отри́гнуть і пра́вдою Твоє́ю возра́дуються.","@8 Щедр і ми́лостив Госпо́дь, долготерпіли́в і многоми́лостив.","@9 Благ Госпо́дь вся́чеським, і щедро́ти Єго́ на всіх ді́ліх Єго́.","@10 Да іспові́дяться Тебі́, Го́споди, вся діла́ Твоя́, і преподо́бнії Твої́ да благослов'я́ть Тя;","@11 сла́ву Ца́рствія Твоєго́ реку́ть і си́лу Твою́ возглаго́лють,","@12 сказа́ти синово́м челові́чеським си́лу Твою́ і сла́ву великолі́пія Ца́рствія Твоєго́.","@13 Ца́рство Твоє́ — Ца́рство всіх віко́в, і влади́чество Твоє́ во вся́ком ро́ді і ро́ді. Ві́рен Госпо́дь во всіх словесі́х Свої́х і преподо́бен во всіх ді́ліх Свої́х.","@14 Утвержда́єть Госпо́дь вся низпа́дающия і возставля́єть вся низве́рженния.","@15 О́чі всіх на Тя упова́ють, і Ти дає́ши їм пи́щу во благовре́менії;","@16 отверза́єши Ти ру́ку Твою́ і ісполня́єши вся́коє живо́тно благоволе́нія.","@17 Пра́веден Госпо́дь во всіх путе́х Свої́х і преподо́бен во всіх ді́ліх Свої́х.","@18 Близ Госпо́дь всім призива́ющим Єго́, всім призива́ющим Єго́ во і́стині;","@19 во́лю боя́щихся Єго́ сотвори́ть, і моли́тву їх усли́шить, і спасе́ть я.","@20 Храни́ть Госпо́дь вся лю́б'ящия Єго́, і вся грі́шники потреби́ть.","@21 Хвалу́ Госпо́дню возглаго́лють уста́ моя́; і да благослови́ть вся́ка плоть і́м'я свято́є Єго́ в вік і в вік ві́ка.","§Сла́ва:"]},{"h":"Псалом 145","ps":["§Аллилу́я, Агге́я і Заха́рії, 145.","@1 Хвали́, душе́ моя́, Го́спода;","@2 восхвалю́ Го́спода в животі́ моє́м, пою́ Бо́гу моєму́, до́ндеже єсьм.","@3 Не наді́йтеся на кня́зі, на си́ни челові́чеськія, в ни́хже ність спаcе́нія.","@4 Ізи́деть дух єго́, і возврати́ться в зе́млю свою́; в той день поги́бнуть вся помишле́нія єго́.","@5 Блаже́н, єму́же Бог Іа́ковль помо́щник єго́, упова́ніє єго́ на Го́спода Бо́га своєго́,","@6 сотво́ршаго не́бо і зе́млю, мо́ре і вся, я́же в них; храня́щаго і́стину в вік,","@7 творя́щаго суд оби́димим, даю́щаго пи́щу а́лчущим. Госпо́дь ріши́ть окова́нния;","@8 Госпо́дь умудря́єть сліпці́; Госпо́дь возво́дить низве́рженния; Госпо́дь лю́бить пра́ведники.","@9 Госпо́дь храни́ть прише́лці, си́ра і вдову́ при́йметь, і путь грі́шних погуби́ть.","@10 Воцари́ться Госпо́дь во вік, Бог Твой, Сіо́не, в род і род."]},{"h":"Псалом 146","ps":["§Аллилу́я, 146.","@1 Хвалі́те Го́спода, я́ко благ псало́м; Бо́гові на́шему да услади́ться хвале́ніє.","@2 Зи́ждай Ієрусали́ма Госпо́дь; разсі́янія Ізра́їлєва собере́ть;","@3 ізціля́яй сокруше́нния се́рдцем і об'язу́яй сокруше́нія їх;","@4 ізчита́яй мно́жество звізд, і всім їм імена́ нарица́яй.","@5 Ве́лій Госпо́дь наш, і ве́лія крі́пость Єго́, і ра́зума Єго́ ність числа́.","@6 Приє́мляй кро́ткия Госпо́дь, смиря́яй же грі́шники до землі́.","@7 Начні́те Го́сподеві во іспові́данії, по́йте Бо́гові на́шему в гу́слех;","@8 одіва́ющему не́бо о́блаки, уготовля́ющему землі́ дождь; прозяба́ющему на гора́х траву́ і злак на слу́жбу челові́ком;","@9 даю́щему ското́м пи́щу їх і птенце́м вра́новим, призива́ющим Єго́.","@10 Не в си́лі ко́нстій восхо́щеть, ніже́ в ли́стіх му́жеських благоволи́ть;","@11 благоволи́ть Госпо́дь в боя́щихся Єго́ і во упова́ющих на ми́лость Єго́."]},{"h":"Псалом 147","ps":["§Аллилу́я, Агге́я і Заха́рії, 147.","@1 Похвали́, Ієрусали́ме, Го́спода, хвали́ Бо́га Твоєго́, Сіо́не;","@2 я́ко укріпи́ вереї́ врат Твої́х, благослови́ си́ни Твоя́ в Тебі́.","@3 Полага́яй преді́ли Твоя́ мир, і ту́ка пшени́чна насища́яй Тя;","@4 посила́яй сло́во Своє́ землі́, до ско́рости тече́ть сло́во Єго́,","@5 даю́щаго сніг Свой, я́ко во́лну⁽1⁾, мглу — я́ко пе́пел посипа́ющаго,","@6 мета́ющаго го́лоть⁽2⁾ Свой, я́ко хлі́би; проти́ву лиця́ мра́за⁽3⁾ Єго́ кто постої́ть?","@7 По́слеть сло́во Своє́, і іста́єть я; дхнеть дух Єго́, і потеку́ть во́ди.","@8 Возвіща́яй сло́во Своє́ Іа́кову, оправда́нія і судьби́ Своя́ Ізра́їлеві;","@9 не сотвори́ та́ко вся́кому язи́ку, і судьби́ Своя́ не яви́ їм.","§Сла́ва:"]},{"h":"Псалом 148","ps":["§Аллилу́я, Агге́я і Заха́рії, 148.","@1 Хвалі́те Го́спода с небе́с, хвалі́те Єго́ в ви́шніх.","@2 Хвалі́те Єго́ всі а́нгели Єго́; хвалі́те Єго́, вся си́ли Єго́.","@3 Хвалі́те Єго́, со́лнце і луна́; хвалі́те Єго́ вся зві́зди і світ.","@4 Хвалі́те Єго́, небеса́ небе́с, і вода́, я́же преви́ше небе́с.","@5 Да восхва́лять і́м'я Госпо́днє; я́ко Той рече́ — і би́ша; Той повелі́ — і созда́шася.","@6 Поста́ви я в вік і в вік ві́ка; повелі́ніє положи́, і не ми́мо і́деть.","@7 Хвалі́те Го́спода от землі́, змі́єве і вся бе́здни;","@8 огнь, град, сніг, го́лоть, дух бу́рен, творя́щая сло́во Єго́;","@9 го́ри і всі хо́лми, древа́ плодоно́сна і всі ке́дри;","@10 зві́ріє і всі ско́ти, га́ди і пти́ці перна́ти;","@11 ца́ріє зе́мстії і всі лю́діє, кня́зі і всі судії́ зе́мстії;","@12 ю́ноші і ді́ви, ста́рці с ю́нотами.","@13 Да восхва́лять і́м'я Госпо́днє; я́ко вознесе́ся і́м'я Того́ Єди́наго, іспові́даніє Єго́ на землі́ і на небесі́.","@14 І вознесе́ть рог люді́й Свої́х; піснь всім преподо́бним Єго́, синово́м Ізра́їлевим, лю́дем приближа́ющимся Єму́."]},{"h":"Псалом 149","ps":["§Аллилу́я, 149.","@1 Воспо́йте Го́сподеві піснь но́ву; хвале́ніє Єго́ в це́ркві преподо́бних.","@2 Да возвесели́ться Ізра́їль о сотво́ршем Єго́, і си́нове Сіо́ні возра́дуються о Царі́ своє́м.","@3 Да восхва́лять і́м'я Єго́ в ли́ці, в тимпа́ні і псалти́рі да пою́ть Єму́.","@4 Я́ко благоволи́ть Госпо́дь в лю́дех Свої́х, і вознесе́ть кро́ткия во спасе́ніє.","@5 Восхва́ляться преподо́бнії во сла́ві і возра́дуються на ло́жах свої́х.","@6 Возноше́нія Бо́жия в горта́ні їх, і мечі́ обою́ду остри́ в рука́х їх;","@7 сотвори́ти отмще́ніє во язи́ціх, обличе́нія в лю́дех;","@8 св'яза́ти царі́ їх пу́ти, і сла́вния їх ручни́ми око́ви желі́зними;","@9 сотвори́ти в них суд напи́сан. Сла́ва сія́ бу́деть всім преподо́бним Єго́."]},{"h":"Псалом 150","ps":["§Аллилу́я, 150.","@1 Хвалі́те Бо́га во святи́х Єго́, хвалі́те Єго́ во утверже́нії си́ли Єго́;","@2 хвалі́те Єго́ на си́лах⁽4⁾ Єго́, хвалі́те єго́ по мно́жеству вели́чествія Єго́;","@3 хвалі́те Єго́ во гла́сі тру́бнім, хвалі́те Єго́ во псалти́рі і гу́слех;","@4 хвалі́те Єго́ в тимпа́ні і ли́ці, хвалі́те Єго́ во стру́нах і орга́ні;","@5 хвалі́те Єго́ в кимва́ліх доброгла́сних, хвалі́те Єго́ в кимва́ліх восклица́нія.","@6 Вся́коє диха́ніє да хва́лить Го́спода.","§Сла́ва:"]},{"h":"Псалом 151","ps":["§Сей псало́м осо́б пи́сан, Дави́дов, і вні числа́ 150 псалмо́в, внегда́ єдинобо́рствоваше на Голіа́фа","@1 Мал біх в бра́тії моє́й і ю́нший в дому́ отця́ моєго́; пасо́х о́вці отця́ моєго́.","@2 Ру́ці мої́ сотвори́сті орга́н, і пе́рсти мої́ соста́виша псалти́р.","@3 І кто возвісти́ть Го́сподеві моєму́? Сам Госпо́дь, Сам усли́шить;","@4 Сам посла́ а́нгела Своєго́, і взят м'я от ове́ць отця́ моєго́, і пома́за м'я єле́єм пома́занія Своєго́.","@5 Бра́тія моя́ добрі́ і вели́ці; і не благоволи́ в них Госпо́дь.","@6 Ізидо́х в срі́теніє іноплеме́ннику, і прокля́т м'я і́доли свої́ми.","@7 Аз же істо́ргнув меч от него́, обезгла́вих єго́ і от'я́х поноше́ніє от сино́в Ізра́їлевих."]},{"h":"Після 20-ї кафизми, Трисвято́є. І по О́тче наш: тропарі, глас 8:","ps":["Ісполне́ніє всіх благи́х Ти єси́, Христе́ мой, іспо́лни ра́дости і весе́лія ду́шу мою́ і спаси́ м'я, я́ко єди́н многоми́лостив.","Сла́ва: А́ще і согріши́х, Христе́ Спа́се мой, пред Тобо́ю, іно́го Бо́га ра́зві Тебе́ не вім; дерза́ю же на Твоє́ благоутро́біє; обраща́ющагося прийми́ м'я, Благоутро́бне О́тче, і Си́не Єдоноро́дне, і Ду́ше Святи́й, я́ко блу́днаго си́на, і спаси́ м'я.","І ни́ні: Іно́го прибі́жища і те́плаго предста́тельства, ра́зві Тебе́ не вім; я́ко дерзнове́ніє іму́щи ко із Тебе́ Рожде́нному, Влади́чице, помози́, і спаси́ м'я, раба́ Твоєго́."]},{"h":"Го́споди поми́луй, 40 разів. І молитва:","ps":["Го́споди Ісу́се Христе́, Бо́же мой, поми́луй м'я, грі́шнаго, і прости́ мі, недосто́йному рабу́ Твоєму́, єли́ка Ті согріши́х чрез все живота́ моєго́ вре́м'я і да́же до днесь, і а́ще что я́ко челові́к согріши́х, во́льная моя́ прегріше́нія і нево́льная, ді́лом і сло́вом, я́же умо́м і ми́слію, я́же от совосхище́нія і невнима́нія, і мно́гия моєя́ лі́ности і небреже́нія. А́ще же і́менем Твої́м кля́хся, а́ще же лжекля́хся, іли́ ху́лих ми́слію, іли́ кого́ укори́х, іли́ оклевета́х, іли́ опеча́лих, іли́ в ні́чесом прогні́вах, іли́ окрадо́х, іли́ блу́дствовах, іли́ солга́х, іли́ та́йно ядо́х; іли́ друг дости́же ко мні, і презрі́х єго́, іли́ бра́та оскорби́х і преогорчи́х; іли́ стоя́щу мі на моли́тві і псалмопі́нії ум мой лука́вий на лука́вая обхожда́ше; іли́ па́че лі́паго наслади́хся, іли́ безу́мно смія́хся, іли́ кощу́нно глаго́лах, іли́ тщесла́вихся, іли́ горди́хся, іли́ добро́ту су́єтную ви́діх і от нея́ прельсти́хся, іли́ нелі́пая мні поглуми́хся; а́ще в чесо́м о моли́тві моє́й не ради́х; іли́ за́повідей духо́внаго моєго́ отця́ не сохрани́х, іли́ праздносло́вих, іли́ і́но что лука́воє сотвори́х; сія́ бо вся і вя́щшая сих соді́ях, ї́хже ніже́ по́мню; поми́луй, Го́споди, і прости́ мі вся, да в ми́рі усну́ і почи́ю, поя́, і благослов'я́, і сла́в'я Тя, со Безнача́льним Твої́м Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]}],"notes":["","","","<span class=''>[в си́лах]</span>"]},{"u":"Після завершення читання кількох кафизм або всього Псалтиря","e":"After reading several kathismas or the whole Psalter","secs":[{"ps":["Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего. Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм.","§Або:","О Тебі́ ра́дується, Благода́тная, вся́кая твар, / А́нгельський собо́р і челові́чеський род, / освяще́нний Хра́ме, і Раю́ слове́сний. Ді́вственная Похвало́, / із Нея́же Бог воплоти́ся, і Младе́нець бисть, / пре́жде вік сий Бог наш; / ложесна́ бо Твоя́ престо́л сотвори́, / і чре́во Твоє́ простра́нніє небе́с соді́ла. / О Тебі́ ра́дується, Благода́тная, вся́кая твар, сла́ва Тебі́.","Трисвято́є. І по О́тче наш:"]},{"h":"Тропарі, глас 6","ps":["Поми́луй нас, Го́споди, поми́луй нас, вся́каго бо отві́та недоумі́юще, сію́ Ті моли́тву я́ко Влади́ці грі́шнії прино́сим: поми́луй нас.","Сла́ва: Честно́є проро́ка Твоєго́ Го́споди торжество́, не́бо Це́рков показа́, с челові́ки лику́ють а́нгели. Того́ моли́твами, Христе́ Бо́же, в ми́рі упра́ви живо́т наш, да поє́м Ті: аллилу́я.","І ни́ні: Мно́гая мно́жества мої́х, Богоро́дице, прегріше́ній; к Тебі́ прибіго́х, Чи́стая, спасе́нія тре́буя. Посіти́ немощству́ющую мою́ ду́шу, і моли́ Си́на Твоєго́ і Бо́га на́шего да́ти мі оставле́ніє, я́же соді́ях лю́тих, єди́на Благослове́нная.","Потім, Го́споди, поми́луй. [40 разів.]"]},{"h":"І поклонів, скільки можливо, з молитвою святого Єфрема:","ps":["Го́споди і Влади́ко живота́ моєго́, дух пра́здности, уни́нія, любонача́лія і праздносло́вія не даждь мі. [Поклін]","Дух же цілому́дрія, смиренному́дрія, терпі́нія і любве́ да́руй мі, рабу́ Твоєму́. [Поклін]","Єй, Го́споди, Царю́, да́руй мі зрі́ти моя́ прегріше́нія і не осужда́ти бра́та моєго́, я́ко благослове́н єси́ во ві́ки віко́в. [Поклін]"]},{"h":"Після цього промовляй молитву цю з увагою:","ps":["Многоми́лостиве і преми́лостиве Го́споди, і всего́ добра́ Да́телю Человіколю́бче, і всея́ вселе́нния Царю́ многоімени́тий, Влади́ко і Го́споди, нищ і убо́г єсьм аз, дерза́ю призива́ти чу́дноє і стра́шноє і свято́є і́м'я Твоє́, єго́же вся твар Небе́сних Сил стра́хом трепе́щуть; ни́зу на землі́ неізрече́ннаго Твоєго́ человіколю́бія смотре́ніє удиви́л єси́, посла́нієм возлю́бленнаго Твоєго́ О́трока. Єго́же от безнача́льних нідр Твоєя́ Оте́чеськия сла́ви неразлу́чним Бо́жество́м отри́гнул єси́, да челові́ки со а́нгели во єди́н соста́в устро́їть. Пом'яни́, Го́споди, моєго́ уни́нія смире́ніє; кал сий і персть, Тебе́, неізглаго́ланнаго Сві́та призива́ю, не́мощію пло́ті обложе́н, ю́же ми́лостивні сло́во Твоє́ понесе́, і сме́ртію Своє́ю от рабо́ти вра́жия свободи́л єсть ду́ші на́ша, да о́бщники вся, і́же ві́рою яре́м рабо́ти Твоєя́ на ся взе́мшия, сла́ви Твоєя́ сподо́бить їх, от нея́же сатана́ льсти́вий отпаде́. Поми́луй м'я, омраче́ннаго гріхо́вними по́мисли, возведи́ ум мой уда́вленний те́рнієм лі́ности і ляди́ною непоко́рства; утверди́ се́рдце моє́ по Тебі́ горі́ти, очи́ма мої́ма істо́чник слез посли́ і на коне́ць ісхо́да душі́ моєя́ сотвори́ м'я безпоро́чна Твоєго́ уго́дника, наставля́я м'я к Тебі́ подвиза́тися усе́рдно. Пом'яни́, Го́споди, роди́телі моя́ милосе́рдієм Твої́м і вся бли́жнія моя́, і бра́тію, і дру́ги, і сосі́ди, і вся правосла́вния христия́ни, і спаси́ м'я моли́твами всіх святи́х; і прийми́ в честь сія́ псалми́ і моли́тви, я́же глаго́лах пред Тобо́ю за ся, і не ме́рзко Ті бу́ди с воздиха́нієм моле́ніє сіє́, я́ко ми́лостив сий і Человіколю́бець, і Тебе́, Безнача́льнаго Отця́, сла́вим, со Єдиноро́дним Твої́м Си́ном, і со Святи́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Після цього,","ps":["Честні́йшую Херуви́м, і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Го́споди, поми́луй. [Тричі] Благослови́.","§Якщо священик, то закінчує ієрейським чином.","Якщо ж чернець або мирянин, закінчує так: Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тере, си́лою Честна́го і Животворя́щаго Креста́, і святи́х Небе́сних Сил безпло́тних, і преподо́бних і богоно́сних оте́ць на́ших, і свята́го проро́ка Дави́да, і всіх святи́х поми́луй і спаси́ м'я, грі́шнаго, я́ко благ і Человіколю́бець."]}],"notes":[]},{"u":"Пісні Священного Писання","e":"Canticles of Holy Scripture","secs":[{"h":"Пісня перша","ps":["#Піснь Моїсе́йова о ісхо́ді. Вкýпі погрузи́в фарао́на Моїсе́й глаго́летъ:","#Го́сподеві поє́м, сла́вно бо просла́вися.","Поє́м Го́сподеві, сла́вно бо просла́вися; коня́ і вса́дника ве́рже в мо́ре.","Помо́щник і покрови́тель бисть мні во спасе́ніє; Сей мой Бог, і просла́влю Єго́, Бог Отця́ моєго́, і вознесу́ Єго́.","Госпо́дь сокруша́яй бра́ні, Госпо́дь і́м'я Єму́, колесни́ці фарао́нови, і си́лу єго́ ве́рже в мо́ре.","Ізбра́нния вса́дники триста́ти потопи́ в Чермні́м мо́рі.","Пучи́ною покри́ їх, погрязо́ша во глубині́, я́ко ка́мень.","Десни́ця Твоя́, Го́споди, просла́вися в крі́пості; десна́я Твоя́ рука́, Го́споди, сокруши́ враги́, і мно́жеством сла́ви Твоєя́ стерл єси́ сопроти́вних.","Посла́л єси́ гнів Твой, пояде́ я, я́ко сте́бліє, і ду́хом я́рости Твоєя́ разступи́ся вода́.","Огусті́ша, я́ко стіна́, во́ди, огусті́ша і во́лни посреді́ мо́ря.","Рече́ враг: гнав пости́гну, разділю́ кори́сть, іспо́лню ду́шу мою́, убію́ мече́м мої́м, госпо́дствовати бу́деть рука́ моя́.","Посла́л єси́ дух Твой, покри́ я мо́ре; погрязо́ша, я́ко о́лово в воді́ зі́льній.","Кто подо́бен Тебі́ в бозі́х, Го́споди, кто подо́бен Тебі́? Просла́влен во святи́х, ди́вен сла́вно, творя́й чудеса́;","Просте́рл єси́ десни́цю Твою́, пожре́ я земля́, наста́вил єси́ пра́вдою Твоє́ю лю́ди Твоя́ сія́, я́же ізба́вил єси́.","Уті́шил єси́ крі́постію Твоє́ю во оби́тель святу́ю Твою́. Сли́шаша язи́ци і прогні́вашася, болі́зні прия́ша живу́щії в Филисти́мі.","На 8: Тогда́ потща́шася влади́ки едо́мстії, і князе́й моаві́тських прия́т я тре́пет, раста́яша всі живу́щії в Ханая́ні.","Нападе́ть на ня страх і тре́пет, вели́чієм ми́шці Твоєя́ да ока́меняться.","На 6: До́ндеже про́йдуть лю́діє Твої́, Го́споди, до́ндеже про́йдуть лю́діє Твої́ сі́ї, я́же стяжа́л єси́.","Введ насади́ я в го́ру достоя́нія Твоєго́, в гото́воє жили́ще Твоє́, є́же соді́лал єси́, Го́споди, святи́ню, ю́же угото́васті ру́ці Твої́.","На 4: Госпо́дь Ца́рствуяй ві́ки і на вік, і єще́, єгда́ вни́де конь фарао́нов с колесни́цями і вса́дники в мо́ре.","І наведе́ на ня Госпо́дь во́ду морську́ю; си́нове же Ізра́їлеви пройдо́ша су́шею посреді́ мо́ря.","§Слава, і нині:"]},{"h":"Пісня друга","ps":["§Потрібно знати, що друга пісня ніколи не стихословиться, тільки один раз у вівторок Великого посту; читаємо ж її до кінця.","На тропарях промовляємо після кожного тропаря: Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","#Піснь Моїсе́йова о Второзако́нії. Зако́ну пи́сану па́ки, піснь Моїсе́йова.","Воньми́, не́бо, і возглаго́лю, і да сли́шить земля́ глаго́ли уст мої́х.","Да ча́єть, я́ко дождь, віща́ніє моє́, і да сни́дуть, я́ко роса́, глаго́ли мої́.","Я́ко ту́ча, на тро́скот, і я́ко і́ней, на сі́но, я́ко і́м'я Госпо́днє призва́х, даді́те вели́чіє Бо́гу на́шему.","Бог, і́стинна діла́ Єго́, і всі путіє́ Єго́ суд.","Бог ві́рен, і ність непра́вди в Нем; пра́веден і преподо́бен Госпо́дь.","Согріши́ша, не того́ ча́да поро́чная; ро́де стропти́вий і развраще́нний, сія́ ли Го́сподеві воздаєте́.","Сі́ї лю́діє бу́її і не му́дрі; не Сам ли Сей Оте́ць твой стяжа́ тя, і сотвори́ тя, і созда́ тя?","Пом'яні́те дні ві́чния, разумі́йте лі́та ро́да родо́в.","Вопроси́ отця́ твоєго́, і возвісти́ть тебі́, ста́рці твоя́, і реку́ть тебі́.","Єгда́ разділя́ше Ви́шній язи́ки, я́ко разсі́я си́ни Ада́мови.","Поста́ви преді́ли язи́ков по числу́ а́нгел Бо́жиїх, і бисть часть Госпо́дня, лю́діє Єго́ Іа́ков, у́же наслі́дія Єго́, Ізра́їль.","Удовли́ єго́ в пусти́ні, в жа́жді зно́я в безво́дні.","Оби́де єго́, і наказа́ єго́, і сохрани́ єго́, я́ко зі́ницю о́ка.","Я́ко оре́л покри́ гніздо́ своє́, і на птенці́ своя́ возжелі́.","Просте́р крилі́ свої́, і прия́т я, і под'я́т я на ра́му своє́ю.","Госпо́дь єди́н вожда́ше я, і не бі с ни́ми бог чужд.","Возведе́ я на си́лу землі́, наси́ти я жит се́льних.","Сса́ша мед із ка́мене, і єле́й от тве́рда ка́мене.","Ма́сло кра́віє, і млеко́ о́вчеє, с ту́ком а́гнчим і о́вним, сино́в ю́нчих і ко́злих, с ту́ком пшени́чним, і кров гро́здову пія́ху вино́.","І яде́ Іа́ков, і наси́тися, і отве́ржеся возлю́бленний.","Ути́, утолсті́, разширі́; і оста́ви Бо́га сотво́ршаго єго́, і отступи́ от Бо́га, Спа́са своєго́.","Прогні́ваша М'я о чужди́х, і в ме́рзостех свої́х преогорчи́ша М'я;","Пожро́ша бісово́м, а не Бо́гу, бого́м, ї́хже не ві́діша, но́ві і секра́ті⁽1⁾ прейдо́ша, ї́хже не ві́діша отці́ їх.","Бо́га ро́ждшаго Тя оста́вил єси́, і заби́л єси́ Бо́га пита́ющаго Тя.","І ви́ді Госпо́дь, і возревнова́, і раздражи́ся за гнів сино́в їх і дще́рей,","І рече́: отвращу́ лице́ Моє́ от них, і покажу́, что бу́деть їм напослі́док.","Я́ко род развраще́н єсть, си́нове ї́мже ність ві́ри в них.","Ті́ї раздражи́ша М'я не о Бо́зі, прогні́ваша М'я во і́доліх свої́х;","І Аз раздражу́ я не о язи́ці, о язи́ці же неразу́мливі прогні́ваю я.","Я́ко огнь возгори́ться от я́рости Моєя́, разжже́ться до а́да преіспо́дняго;","Сність зе́млю і жи́та єя́, попали́ть основа́нія гор.","Соберу́ на них зла́я, і стрі́ли Моя́ сконча́ю в них;","Та́юще гла́дом, і снідь птиць, і горб неісці́лен.","Зу́би звіре́й послю́ в ня, с я́ростію пресмика́ющихся по землі́.","От вні обезча́дить я меч, і от хра́мов їх страх; ю́ноша с ді́вою, ссу́щеє с соверше́нним ста́рцем.","Ріх: разсі́ю я, уста́влю же от челові́к па́м'ять їх.","А́ще не за гнів враго́в, да не долголі́тствують, і да не наля́гуть супоста́ти,","Да не реку́ть: рука́ на́ша висока́, і не Госпо́дь сотвори́ сія́ вся.","Я́ко язи́к погуби́вий сові́т єсть, і ність в них худо́жества.","Не сми́слиша разумі́ти; сія́ вся да при́ймуть во гряду́щеє лі́то.","Ка́ко пожене́ть єди́н ти́сящі, і два дви́гнета тьми,","А́ще не Бог отда́сть я, і Госпо́дь преда́сть я?","Не суть бо бо́зі їх, я́ко Бог наш; вразі́ же на́ші неразу́мливі.","От виногра́дов бо содо́мських виногра́д їх, і розга́ їх от Гомо́рри;","Грозд їх — грозд же́лчі, грозд го́рести їх.","Я́рость зміє́в — вино́ їх, і я́рость а́спідов неісці́льна.","Не сія́ ли вся собра́шася у Мене́, і запечатлі́шася в сокро́вищах Мої́х?","В день отмще́нія возда́м, во вре́м'я, внегда́ соблазни́ться нога́ їх.","Я́ко близ день поги́белі їх, і предстоя́ть гото́вая вам.","Я́ко су́дить і́мать Госпо́дь лю́дем Свої́м, і о рабі́х Свої́х умоле́н бу́деть.","Ви́ді бо я разсла́бленни, і іста́явша во вре́м'я, і ізнемо́гша.","І рече́ Госпо́дь: гді суть бо́зі їх, ї́хже упова́ша на ня? Ї́хже тук жертв їх ядя́сте, і пія́сте вино́ треб їх?","Да воскре́снуть і помо́гуть вам, і бу́дуть вам покрови́телі.","Ви́діте, ви́діте, я́ко Аз єсьм, і ність Бог ра́зві Мене́.","Аз убію́ і жи́ти сотворю́; поражу́ і Аз ісцілю́, і ність, і́же і́зметь от руку́ Моє́ю.","Я́ко воздви́гну на не́бо ру́ку Мою́, і клену́ся десни́цею Моє́ю, і реку́: живу́ Аз во ві́ки.","Я́ко поострю́, я́ко мо́лнію, меч Мой, і при́йметь суд рука́ Моя́;","І возда́м месть враго́м і ненави́дящим М'я возда́м.","Упою́ стрі́ли моя́ от кро́ве, і меч мой сність м'яса́;","От кро́ве я́звених і пліне́нія, от глав князе́й язи́чеських.","Возвеселі́теся небеса́ ку́пно с Ним, і да покло́няться Єму́ всі а́нгели Бо́жії.","Возвеселі́теся язи́ци с людьми́ Єго́, і да укріп'я́ться Єму́ всі си́нове Бо́жії.","Я́ко кров сино́в Свої́х отмща́єть, і отмсти́ть; і возда́сть месть враго́м, і ненави́дящим Єго́ возда́сть.","І очи́стить Госпо́дь зе́млю люде́й Свої́х.","§Слава, і нині:"]},{"h":"Пісня третя","ps":["#Моли́тва А́нни ма́тере Саму́їла пророка. Бо́га почита́єть непло́ди ражда́ющая стра́нно.","#Свят єси́, Го́споди, і Тя поє́ть дух мой.","Утверди́ся се́рдце моє́ во Го́споді, вознесе́ся рог мой о Бо́зі моє́м; разшири́шася уста́ моя́ на враги́ моя́, возвесели́хся о спасе́нії Твоє́м.","Я́ко ність свят, я́ко Госпо́дь, і ність пра́веден, я́ко Бог наш, і ність свят па́че Тебе́.","Не хвалі́теся і не глаго́літе висо́кая в горди́ні, ніже́ да ізи́деть велері́чіє із уст ва́ших;","Я́ко Бог ра́зумов Госпо́дь, і Бог уготовля́яй начина́нія Своя́.","Лук си́льних ізнемо́же, і немощству́ющії препоя́сашася си́лою.","Іспо́лненнії хлі́ба лиши́шася, і а́лчущії прише́льствоваша зе́млю.","Я́ко непло́ди роди́ седьм, і мно́гая в ча́діх ізнемо́же.","Госпо́дь мертви́ть і живи́ть, низво́дить во ад і возво́дить.","Госпо́дь убо́жить і богати́ть, смиря́єть і ви́сить; возставля́єть от землі́ убо́га і от гно́їща воздвиза́єть ни́ща.","Посади́ти єго́ с могу́щими люде́й, і престо́л сла́ви наслі́дуя єму́.","На 8: Дая́й моли́тву моля́щемуся, і благослови́ лі́та пра́веднаго.","Я́ко не укріпля́ється си́лен муж крі́постію своє́ю, Госпо́дь не́мощна сотвори́ сопоста́та єго́, Госпо́дь Свят.","На 6: Да не хва́литься прему́дрий прему́дростію своє́ю, і да не хва́литься си́льний си́лою своє́ю, і да не хва́литься бога́тий бога́тством свої́м.","Но о сем да хва́литься хваля́йся, є́же разумі́ти і зна́ти Го́спода, і твори́ти суд і пра́вду посреді́ землі́.","На 4: Госпо́дь взи́де на небеса́ і возгремі́, Той су́дить конце́м землі́, пра́веден сий.","І дасть крі́пость царю́ на́шему, і вознесе́ть рог христа́ Своєго́.","§Сла́ва, і ни́ні:"]},{"h":"Пісня четверта","ps":["#Моли́тва авваку́ма пророка. Сло́ва істоща́ніє Авваку́м сказу́єт:","#Сла́ва си́лі Твоє́й, Го́споди.","Го́споди, усли́шах слух Твой, і убоя́хся; Го́споди, разумі́х діла́ Твоя́, і ужасо́хся.","Посреді́ двою́ живо́тну позна́н бу́деши. Внегда́ прибли́житися лі́том, позна́єшися; внегда́ прийти́ вре́мені, яви́шися; внегда́ смути́тися душі́ моє́й во гні́ві, ми́лость Твою́ пом'яне́ши.","Бог от ю́га при́йдеть, і Святи́й із гори́ приосіне́нния ча́щі.","Покри́ небеса́ доброді́тель Єго́, і хвали́ Єго́ іспо́лнь земля́.","І сія́ніє Єго́, я́ко світ бу́деть, ро́зи в рука́х Єго́; і положи́ любо́в держа́вну крі́пості Своє́й.","Пред лице́м Єго́ преди́деть сло́во, і ізи́деть на по́ле за п'я́ту Єго́.","Ста, і подви́жеся земля́; призрі́, і раста́яша язи́ци.","Стри́шася го́ри ну́ждею, і раста́яша хо́лми ві́чнії, ше́ствія ві́чная їх.","За труд ви́діша селе́нія Ефіо́пськая, убоя́ться і кро́ви землі́ Мадіа́мськия.","Єда́ в ріка́х прогні́ваєшися, Го́споди? Єда́ в ріка́х я́рость Твоя́? Іли́ в мо́рі устремле́ніє Твоє́?","Я́ко вся́деши на ко́ні Твоя́, і яжде́ніє Твоє́ спасе́ніє.","Наляца́я наляче́ши лук Твой на ски́птри, глаго́леть Госпо́дь.","Ріка́ми разся́деться земля́, у́зрять Тя, і поболя́ть лю́діє.","Расточа́я во́ди ше́ствія; даде́ бе́здна глас свой, висота́ привиді́нія своя́.","Воздви́жеся со́лнце, і луна́ ста в чи́ні своє́м.","Во світ стрі́ли Твоя́ по́йдуть, в блиста́нії мо́лній ору́жій Твої́х.","Преще́нієм ума́лиши зе́млю, і я́ростію низложи́ши язи́ки.","Ізше́л єси́ на спасе́ніє люде́й Твої́х, спасти́ пома́занния Твоя́ прише́л єси́.","Вложи́л єси́ во глави́ беззако́нних смерть, воздви́гл єси́ у́зи да́же до ви́ї в коне́ць.","Разсі́кл єси́ во ізступле́нії глави́ си́льних, стрясу́ться в ней; разве́рзуть узди́ своя́, я́ко сніда́яй ни́щий тай.","І возве́л єси́ на мо́ре ко́ні Твої́, смуща́ющия во́ди мно́гі.","Сохрани́хся, і убоя́ся се́рдце моє́, от гла́са моли́тви усте́н мої́х.","І вни́де тре́пет в ко́сті моя́, і во мні см'яте́ся крі́пость моя́.","Почи́ю в день ско́рби моєя́, да взи́ду в лю́ди прише́льствія моєго́.","На 8: Зане́ смо́ков не плодопринесе́ть, і не бу́деть ро́да в лоза́х.","Солже́ть ді́ло ма́слинноє, і поля́ не сотворя́ть я́ді.","На 6: Оскуді́ша о́вці от пи́щі, і не бу́деть воло́в при я́слех.","Аз же о Го́споді возра́дуюся, возвеселю́ся о Бо́зі Спа́сі моє́м.","На 4: Госпо́дь Бог мой си́ла моя́; і учини́ть но́зі мої́ на соверше́ніє.","І на висо́кая возво́дить м'я, побіди́ти мі в пі́сні Єго́.","§Сла́ва, і ни́ні:"]},{"h":"Пісня п'ята","ps":["#Моли́тва іса́ії пророка. Іса́ії прорече́ніє, моли́тва в'я́щши:","#Го́споди, Бо́же наш, мир даждь нам.","От но́щі у́тренюєть дух мой к Тебі́, Бо́же, зане́ світ повелі́нія Твоя́ на землі́.","Пра́вді научі́теся, живу́щії на землі́; преста́ бо нечести́вий; всяк, і́же не научи́ться пра́вді на землі́, і́стини не сотвори́ть.","Да во́зьметься нечести́вий, да не ви́дить сла́ви Госпо́дні. Го́споди, висока́ Твоя́ ми́шця, і не ві́діша, разумі́вше же постидя́ться.","За́висть при́йметь лю́ди ненака́занния, і ни́ні огнь супоста́ти поя́сть.","Го́споди Бо́же наш, мир даждь нам, вся бо возда́л єси́ нам.","Го́споди Бо́же наш, стяжи́ ни; Го́споди, ра́зві Тебе́ іно́го не ві́ми; і́м'я Твоє́ імену́єм.","Ме́ртвії же живота́ не і́муть ви́діти, ніже́ вра́чеве воскреся́ть.","Сего́ ра́ди наве́л єси́ і погуби́л єси́, і взял єси́ всяк му́жеськ пол їх.","На 8: Приложи́ їм зла, Го́споди, приложи́ зла сла́вним землі́.","Го́споди, в ско́рбі пом'яну́хом Тя, в ско́рбі ма́лі наказа́ніє Твоє́ нам.","На 6: І я́ко боля́щая приближа́ється роди́ти і в болі́зні своє́й вопія́ше, та́ко би́хом возлю́бленному Твоєму́.","Стра́ха ра́ди Твоєго́, Го́споди, во чре́ві прия́хом і поболі́хом, і роди́хом дух спасе́нія Твоєго́, єго́же сотвори́хом на землі́; не паде́м, но паду́ть живу́щії на землі́.","На 4: Воскре́снуть ме́ртвії і воста́нуть, і́же во гробі́х, і возвеселя́ться, і́же на землі́.","Роса́ бо, я́же от Тебе́, ісціле́ніє їм єсть, земля́ же нечести́вих паде́ть.","§Сла́ва, і ни́ні:"]},{"h":"Пісня шоста","ps":["#Моли́тва Іо́ни проро́ка. Я́ко проро́ка Іо́ну спаси нас, Го́споди.","#От зві́ря воззва́ Іо́на глаго́ля:","Возопи́х в ско́рбі моє́й ко Го́споду Бо́гу моєму́, і усли́ша м'я.","Із чре́ва а́дова вопль мой, усли́шал єси́ глас мой.","Отве́ргл м'я єси́ во глубини́ се́рдця морська́го, і рі́ки обидо́ша м'я.","Вся висоти́ Твоя́ і во́лни Твоя́ на мні прейдо́ша.","І аз ріх: отри́нуся от о́чію Твоє́ю єда́ приложу́ призрі́ти мі ко хра́му свято́му Твоєму́?","Возлія́ся вода́ до душі́ моєя́, бе́здна оби́де м'я послі́дняя.","На 8: Понре́ глава́ моя́ в разсі́ли гор, снидо́х в зе́млю, єя́же вереї́ єя́ закле́пи ві́чнії.","І да взи́деть із істлі́нія живо́т мой к Тебі́, Го́споди Бо́же мой.","На 6: Внегда́ скончава́тися от мене́ душі́ моє́й, Го́спода пом'яну́х.","І да при́йдеть к Тебі́ моли́тва моя́ ко хра́му свято́му Твоєму́.","На 4: Храня́щії су́єтная і ло́жная ми́лость свою́ оста́виша.","Аз же со гла́сом хвале́нія і іспові́данія пожру́ Тебі́, єли́ка обіща́х, возда́м Тебі́ во спасе́ніє моє́ Го́сподеві.","§Сла́ва, і ни́ні:"]},{"h":"Пісня сьома","ps":["#Моли́тва святи́х тріє́х отроко́в; хвала́ пла́мень угаша́єть трех ю́нош.","#Оте́ць і наш Бо́же, благослове́н єси́.","Благослове́н єси́, Го́споди, Бо́же оте́ць на́ших, хва́льно і просла́влено і́м'я Твоє́ во ві́ки.","Я́ко пра́веден єси́ о всіх, я́же сотвори́л єси́ нам, і вся діла́ Твоя́ і́стинна, і пра́ві путіє́ Твої́, і всі суди́ Твої́ і́стинні.","І судьби́ і́стинни сотвори́л єси́ по всім, я́же наве́л єси́ на ни і на град святи́й оте́ць на́ших Ієрусали́м; я́ко і́стиною і судо́м наве́л єси́ сія́ вся на ни гріх ра́ди на́ших.","Я́ко согріши́хом і беззако́нновахом отступи́вше от Тебе́, і прегріши́хом во всіх.","І за́повідій Твої́х не послу́шахом, ніже́ соблюдо́хом, ніже́ сотвори́хом, я́коже запові́дал єси́ нам, да бла́го нам бу́деть.","І вся, я́же сотвори́л єси́ нам, і вся, єли́ка наве́л єси́ нам, і́стинним судо́м сотвори́л єси́.","І пре́дал єси́ нас в ру́ки враго́в беззако́нних, ме́рзьких отсту́пников, і царю́ непра́ведну і лука́внійшу па́че всея́ землі́.","І ни́ні ність нам отве́рсти уст, студ і поноше́ніє би́хом рабо́м Твої́м, і чту́щим Тя.","Не преда́ждь же нас до конця́ і́мене Твоєго́ ра́ди, і не разори́ заві́та Твоєго́,","І не отста́ви ми́лости Твоєя́ от нас, Авраа́ма ра́ди возлю́бленнаго от Тебе́, і за Ісаа́ка, раба́ Твоєго́, і Ізра́їля, свята́го Твоєго́;","І́мже глаго́лал єси́ умно́жити сі́м'я їх, я́ко зві́зди небе́сния, і я́ко песо́к при краї́ мо́ря.","Я́ко, Влади́ко, ума́лихомся па́че всіх язи́к, і єсьми́ смире́нні по всей землі́ днесь гріх ра́ди на́ших.","І ність во вре́м'я сіє́ нача́льника, і проро́ка, і вожда́; ніже́ всесожже́нія, ніже́ же́ртви, ніже́ приноше́нія, ніже́ кади́ла, ні мі́ста, є́же пожре́ти пред Тобо́ю і обрісти́ ми́лость;","Но душе́ю сокруше́нною, і ду́хом смире́нним, да прия́ті бу́дем.","Я́ко во всесожже́ніїх о́вних і ю́нчих і я́ко во тмах а́гнець ту́чних; та́ко да бу́деть же́ртва на́ша пред Тобо́ю днесь, і да соверши́ться по Тебі́, я́ко ність студа́ упова́ющим на Тя.","І ни́ні возслі́дуєм всім се́рдцем, і бої́мся Тебе́, і і́щем лиця́ Твоєго́.","Не посрами́ нас, но сотвори́ с на́ми по кро́тості Твоє́й, і по мно́жеству ми́лости Твоєя́.","І ізми́ нас по чудесе́м Твої́м, і даждь сла́ву і́мені Твоєму́, Го́споди.","І да посра́м'яться всі явля́ющії рабо́м Твої́м зла́я, і да постидя́ться от вся́кия си́ли, і крі́пость їх да сокруши́ться;","І да разумі́ють, я́ко Ти єси́ Госпо́дь Бог єди́н, і сла́вен по всей вселе́нній.","І не преста́ша влага́ющії я, слуги́ царе́ви, жгу́ще пещ на́ффою, і смоло́ю, і ізгре́бми, і ро́ждієм.","І разлива́щеся пла́мень над пе́щію на ла́ктій чети́редесять де́в'ять.","І оби́де, і пожже́, я́же обрі́те о пе́щі халде́йстій.","А́нгел же Госпо́день сни́де ку́пно с су́щими о Аза́рії в пещ;","І оттрясе́ пла́мень о́гненний от пе́щі,","І сотвори́ сре́днєє пе́щі, я́ко дух роси́ шум'я́щ; і не прикосну́ся їх отню́д огнь, і не оскорби́, ніже́ сту́жи їм.","Тогда́ тріє́ я́ко єди́німи усти́ поя́ху, і благословля́ху, і сла́вляху Бо́га в пещі́, глаго́люще:","#Росо́ю пе́щі, трех хвала́ ю́нош.","На 8: Благослове́н єси́, Го́споди, Бо́же оте́ць на́ших, і препі́тий і превозноси́мий во ві́ки.","І благслове́нно і́м'я сла́ви Твоєя́ свято́є, препі́тоє і превозноси́моє во ві́ки.","На 6: Благослове́н єси́ в хра́мі святи́я сла́ви Твоєя́, препі́тий і превозноси́мий во ві́ки.","Благослове́н єси́, ви́дяй бе́здни, сідя́й на Херуви́міх, препі́тий і превозноси́мий во ві́ки.","На 4: Благослове́н єси́ на престо́лі сла́ви Ца́рствія Твоєго́, препі́тий і превозноси́мий во ві́ки.","Благослове́н єси́ на тве́рді небе́сній, препі́тий і превозноси́мий во ві́ки.","§Сла́ва, і ни́ні:"]},{"h":"Пісня восьма","ps":["#Піснь святи́х тріє́х отроко́в. Влади́ку воспо́й созда́нних єстество́:","#Го́спода, по́йте діла́, і превозносі́те во вся ві́ки.","Благослові́те, вся діла́ Госпо́дня, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, а́нгели Госпо́дні, небеса́ Госпо́дня, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, во́ди вся, я́же преви́ше небе́с, вся си́ли Госпо́дні, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, со́лнце і мі́сяць, зві́зди небе́сния, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, всяк дождь і роса́, всі ду́сі, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, огнь і вар⁽2⁾, студь і зной, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, ро́си і і́ней, лед і мраз, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, сла́ни і сні́зі⁽3⁾, но́щі і дні́є, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, світ і тьма, мо́лнія і о́блаци, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, земля́, го́ри і хо́лми, і вся прозяба́ющая на ней, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, істо́чници, моря́ і рі́ки, ки́ти і вся дви́жущаяся в вода́х, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","На 8: Благослові́те, вся пти́ці небе́сния, зві́ріє і всі ско́ти, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, си́нове челові́честії, да благослови́ть Ізра́їль Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","На 6: Благослові́те, свяще́нници Госпо́дні, раби́ Госпо́дні, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, ду́сі і ду́ші пра́ведних, преподо́бнії і смире́ннії се́рдцем, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","На 4: Благослові́те Ана́нія, Аза́рія, Місаї́л, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","Благослові́те, апо́столи, проро́ци і му́ченици Госпо́дні, Го́спода, по́йте і превозносі́те Єго́ во ві́ки.","§Благослови́м Отця́, і Си́на, і Свята́го Ду́ха, Го́спода.","§Ни́ні, і при́сно, і во ві́ки віко́в, амі́нь.","§Хва́лим, благослови́м, покланя́ємся Го́сподеві, пою́ще і превознося́ще во вся ві́ки."]},{"h":"Пісня дев'ята","ps":["#Піснь Богоро́диці, от Луки́ свята́го Єва́нгелія. Си́на поє́ть і Ма́тер отрокови́ця.","#Богоро́дицу в пі́снех велича́єм.","Вели́чить душа́ Моя́ Го́спода, і возра́довася дух Мой о Бо́зі Спасі Моє́м.","Я́ко призрі́ на смире́ніє раби́ Своєя́, се бо от ни́ні ублажа́ть М'я всі ро́ди.","Я́ко сотвори́ Мні вели́чіє Си́льний, і свя́то і́м'я Єго́, і ми́лость Єго́ в ро́ди родо́в боя́щимся Єго́.","Сотвори́ держа́ву ми́шцею Своє́ю, расточи́ го́рдия ми́слію се́рдця їх.","Низложи́ си́льния со престо́л і вознесе́ смире́нния, а́лчущия іспо́лни благ і богатя́щияся отпусти́ тщи.","Восприя́т Ізра́їля, о́трока Своєго́, пом'яну́ти ми́лості, я́коже глаго́ла ко отце́м на́шим, Авраа́му і сі́мені єго́ да́же до ві́ка."]},{"h":"Молитва Захарії, отця Предтечі. Захарія благословляє народження отрочати.","ps":["Благослове́н Госпо́дь, Бог Ізра́їлев, я́ко посіти́ і сотвори́ ізбавле́ніє лю́дем Свої́м.","І воздви́же рог спасе́нія нам, в дому́ Дави́дові о́трока Своєго́;","Я́коже глаго́ла усти́ святи́х су́щих от ві́ка проро́к Єго́;","Спасе́ніє от враг на́ших, і із руки́ всіх ненави́дящих нас.","Сотвори́ти ми́лость со отци́ на́шими, і пом'яну́ти заві́т святи́й Свой.","На 8: Кля́тву, є́юже кля́тся ко Авраа́му, отцю́ на́шему, да́ти нам, без стра́ха, із руки́ враг на́ших ізба́вльшимся,","Служи́ти Єму́ преподо́бієм і пра́вдою пред Ним вся дні живота́ на́шего.","На 6: І ти, отроча́, проро́к Ви́шняго нарече́шися; преди́деши бо пред лице́м Госпо́днім, угото́вати путі́ Єго́,","Да́ти ра́зум спасе́нія лю́дем Єго́, во оставле́ніє гріх їх, милосе́рдія ра́ди ми́лості Бо́га на́шего.","На 4: В ни́хже посіти́ нас Восто́к с висоти́, яви́тися во тьмі і сі́ні сме́ртній сідя́щим.","Напра́вити но́ги на́ша на путь ми́рен.","§Сла́ва, і ни́ні:","§Коне́ць, і Бо́гу сла́ва."]}],"notes":["","","сла́ни і сні́зи — інії і сніги"]}];
/** Індекс кафизми k (1–20) у PSALTYR. */
export const kathIdx = (k: number) => k + 1;
